// Modular, thread-safe logging framework in C
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <pthread.h>
#include <unistd.h>
#include <syslog.h>

// Configuration
#define LOG_LEVEL_DEBUG 0
#define LOG_LEVEL_INFO 1
#define LOG_LEVEL_WARN 2
#define LOG_LEVEL_ERROR 3
#define DEFAULT_LOG_LEVEL LOG_LEVEL_INFO
#define DEFAULT_LOG_FORMAT "%s:%d - %s"

// Logging levels and formats
int log_level = DEFAULT_LOG_LEVEL;
char *log_format = NULL;

// Thread-safe logging mutex
pthread_mutex_t log_lock = PTHREAD_MUTEX_INITIALIZER;

// Dependency management
void *external_logger = NULL;

// Resource optimization
int log_batch_size = 100;
int log_batch_interval = 1000; // in milliseconds
struct timespec last_logged;
int log_throttle = 0;

// Concurrency handling
pthread_t log_thread;

// Error handling
void handle_error(const char *message) {
    perror(message);
}

// Performance monitoring
void profile() {
    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);

    // Logging code goes here

    clock_gettime(CLOCK_MONOTONIC, &end);
    double elapsed = (double)(end.tv_sec - start.tv_sec) + (double)(end.tv_nsec - start.tv_nsec) / 1000000000;
    printf("Logging time: %f ms\n", elapsed * 1000);
}

// Configuration flexibility
void set_log_level(int level) {
    log_level = level;
}

void set_log_format(char *fmt) {
    if (log_format != NULL) {
        free(log_format);
    }
    log_format = strdup(fmt);
}

// Scalability
void log_message(int level, char *msg) {
    pthread_mutex_lock(&log_lock);
    if (level >= log_level && external_logger != NULL) {
        // Log to external logger
        void (*external_log)(const char *) = external_logger;
        external_log(msg);
    } else {
        // Log locally
        printf("%s\n", msg);
    }
    pthread_mutex_unlock(&log_lock);
}

// Edge case management
void handle_network_failure() {
    log_message(LOG_LEVEL_WARN, "Network failure encountered while logging");
}

void handle_resource_limitation() {
    log_message(LOG_LEVEL_ERROR, "Resource limitation encountered while logging");
}

// Documentation and testing
/**
 * Logs a message at the specified level.
 *
 * @param level The logging level (DEBUG, INFO, WARN, ERROR)
 * @param msg The message to log
 */
void log(int level, char *msg) {
    // Check if logging is enabled for this level
    if (level >= log_level) {
        // Create log message
        char *log_message = NULL;
        asprintf(&log_message, log_format, msg);

        // Log the message
        log_message(level, log_message);

        // Free memory
        free(log_message);
    }
}

/**
 * Initializes the logging framework.
 */
void init_logging() {
    // Initialize external logger if specified
    if (external_logger != NULL) {
        void (*external_init)(void *) = external_logger;
        external_init(NULL);
    }
}

/**
 * Destroys the logging framework.
 */
void destroy_logging() {
    // Clean up resources
    free(log_format);
    pthread_mutex_destroy(&log_lock);

    // Deinitialize external logger if specified
    if (external_logger != NULL) {
        void (*external_deinit)(void *) = external_logger;
        external_deinit(NULL);
    }
}

int main() {
    init_logging();

    // Log at different levels
    log(LOG_LEVEL_DEBUG, "Debug message");
    log(LOG_LEVEL_INFO, "Info message");
    log(LOG_LEVEL_WARN, "Warning message");
    log(LOG_LEVEL_ERROR, "Error message");

    // Configure logging levels and formats at runtime
    set_log_level(LOG_LEVEL_DEBUG);
    set_log_format("%s - %d");

    // Log with new configuration
    log(LOG_LEVEL_INFO, "Info message");

    // Clean up resources
    destroy_logging();

    return 0;
}']

