from time import time

class HashService:
    def __init__(self):
        self.executor = ThreadPoolExecutor(max_workers=10)

    def hash_file(self, filepath, algorithm='MD5'):
        with open(filepath, 'rb') as f:
            hasher = getattr(hashlib, algorithm)(f.read())
            return hasher.hexdigest()

    def hash_files(self, filepaths, algorithms=['MD5', 'SHA256']):
        start_time = time()
        digests = {}
        for filepath in filepaths:
            for algorithm in algorithms:
                try:
                    digest = self.hash_file(filepath, algorithm)
                    digests[algorithm] = digest
                except Exception as e:
                    print(f'Error hashing {filepath} with {algorithm}: {e}')
        end_time = time()
        total_time = end_time - start_time
        return {
            'digests': digests,
            'total_time': total_time,
            'start_time': start_time,
            'end_time': end_time
        }

    def monitor(self):
        # Implement a monitoring function to display progress updates for the hashing process.
        pass
