* EDE3 (Triple-DES with 3 keys) in ECB mode
* CFB (Cipher Feedback) mode
* Null encryption for testing purposes
*/

typedef enum {
    DES_ECB = 0,
    EDE_ECB = 1,
    EDE3_ECB = 2,
    CFB_MODE = 3,
    NULL_ENCRYPTION = 4
} cipher_type;

/*
Cipher Modes:
--------------

The module provides the following cipher modes:

* ECB (Electronic Codebook) mode
* CFB (Cipher Feedback) mode
*/

typedef enum {
    ECB = 0,
    CFB = 1
} cipher_mode;

/*
Key Size:
---------

The module supports the following key sizes:

* DES: 64 bits (8 bytes)
* EDE: 192 bits (24 bytes)
* EDE3: 192 bits (24 bytes)
*/

typedef enum {
    DES_KEY_SIZE = 8,
    EDE_KEY_SIZE = 24,
    EDE3_KEY_SIZE = 24
} key_size;

/*
Encrypt and Decrypt Functions:
-------------------------------

The module provides the following encrypt and decrypt functions:

* Encrypt(unsigned char *plaintext, unsigned int plaintext_len, cipher_type type, const unsigned char *key, const unsigned char *iv)
* Decrypt(unsigned char *ciphertext, unsigned int ciphertext_len, cipher_type type, const unsigned char *key, const unsigned char *iv)
*/

void Encrypt(unsigned char *plaintext, unsigned int plaintext_len, cipher_type type, const unsigned char *key, const unsigned char *iv) {
    switch (type) {
        case DES_ECB:
            DES_ecb_encrypt(plaintext, plaintext, key, iv, DES_ENCRYPT);
            break;
        case EDE_ECB:
            EVP_EncryptInit(NULL, NULL, plaintext, key, iv, EVP_CIPH_MODE);
            break;
        case EDE3_ECB:
            EVP_EncryptInit(NULL, NULL, plaintext, key, iv, EVP_CIPH_MODE);
            break;
        case CFB_MODE:
            EVP_EncryptInit(NULL, NULL, plaintext, key, iv, EVP_CIPH_MODE);
            break;
        default:
            printf("Unsupported cipher type\n");
            return;
    }
}

void Decrypt(unsigned char *ciphertext, unsigned int ciphertext_len, cipher_type type, const unsigned char *key, const unsigned char *iv) {
    switch (type) {
        case DES_ECB:
            DES_ecb_encrypt(ciphertext, ciphertext, key, iv, DES_DECRYPT);
            break;
        case EDE_ECB:
            EVP_DecryptInit(NULL, NULL, ciphertext, key, iv, EVP_CIPH_MODE);
            break;
        case EDE3_ECB:
            EVP_DecryptInit(NULL, NULL, ciphertext, key, iv, EVP_CIPH_MODE);
            break;
        case CFB_MODE:
            EVP_DecryptInit(NULL, NULL, ciphertext, key, iv, EVP_CIPH_MODE);
            break;
        default:
            printf("Unsupported cipher type\n");
            return;
    }
