```
using System;
using System.Net.Http;
using System.Threading.Tasks;
using Newtonsoft.Json;

namespace LightingController
{
    public class WeatherServiceClient
    {
        private readonly string _baseUrl;
        private readonly string _apiKey;
        private readonly HttpClient _client;

        public WeatherServiceClient(string baseUrl, string apiKey)
        {
            _baseUrl = baseUrl;
            _apiKey = apiKey;
            _client = new HttpClient();
        }

        public async Task<WeatherData> GetCurrentWeatherAsync()
        {
            var url = $"{_baseUrl}/weather?key={_apiKey}";
            var response = await _client.GetAsync(url);
            var content = await response.Content.ReadAsStringAsync();
            return JsonConvert.DeserializeObject<WeatherData>(content);
        }
    }

    public class WeatherData
    {
        [JsonProperty("temperature")]
        public float Temperature { get; set; }

        [JsonProperty("humidity")]
        public float Humidity { get; set; }

        [JsonProperty("windSpeed")]
        public float WindSpeed { get; set; }
    }

    public class LightingController
    {
        private readonly WeatherServiceClient _weatherServiceClient;
        private readonly Dictionary<string, Light> _lights;
        private readonly int _updateInterval;

        public LightingController(WeatherServiceClient weatherServiceClient, Dictionary<string, Light> lights, int updateInterval)
        {
            _weatherServiceClient = weatherServiceClient;
            _lights = lights;
            _updateInterval = updateInterval;
        }

        public async Task UpdateLightingAsync()
        {
            var weatherData = await _weatherServiceClient.GetCurrentWeatherAsync();
            foreach (var light in _lights)
            {
                var currentTemperature = weatherData.Temperature;
                var currentHumidity = weatherData.Humidity;
                var currentWindSpeed = weatherData.WindSpeed;

                var temperatureThreshold = light.Value.TemperatureThreshold;
                var humidityThreshold = light.Value.HumidityThreshold;
                var windSpeedThreshold = light.Value.WindSpeedThreshold;

                if (currentTemperature > temperatureThreshold || currentHumidity > humidityThreshold || currentWindSpeed > windSpeedThreshold)
                {
                    light.Value.TurnOn();
                }
                else
                {
                    light.Value.TurnOff();
                }
            }
        }

        public async Task UpdateLightingAsync(int updateInterval)
        {
            while (true)
            {
                await UpdateLightingAsync();
                await Task.Delay(_updateInterval);
            }
        }
