// Modular JavaScript application architecture
class APIManager {
  constructor() {
    this.modules = [];
  }

  // Adds a new module to the manager
  addModule(module) {
    this.modules.push(module);
  }

  // Removes a module from the manager
  removeModule(module) {
    const index = this.modules.indexOf(module);
    if (index > -1) {
      this.modules.splice(index, 1);
    }
  }

  // Executes a module and returns its output
  executeModule(module, input) {
    const result = module.execute(input);
    return result;
  }
}

