        // Check for errors and log them if necessary
        if ($response->getStatusCode() !== 200) {
            $this->logger->error('Error authenticating user', [
                'username' => $username,
                'status_code' => $response->getStatusCode(),
            ]);

            return false;
        }

        // Return true if authentication was successful
        return true;
    }

    public function getUserProfile($accessToken): ?object {
        // Use the access token to make a request to retrieve user profile information
        $response = $this->client->get('https://example.com/api/user', [
            'headers' => [
                'Authorization' => 'Bearer ' . $accessToken,
            ],
        ]);

        // Check for errors and log them if necessary
        if ($response->getStatusCode() !== 200) {
            $this->logger->error('Error retrieving user profile', [
                'access_token' => $accessToken,
                'status_code' => $response->getStatusCode(),
            ]);

            return null;
        }

        // Return the user profile object if successful
        return json_decode($response->getBody());
    }

    public function refreshAccessToken($accessToken): ?string {
        // Use the access token to make a request to refresh it
        $response = $this->client->post('https://example.com/api/refresh-token', [
            'headers' => [
                'Authorization' => 'Bearer ' . $accessToken,
            ],
        ]);

        // Check for errors and log them if necessary
        if ($response->getStatusCode() !== 200) {
            $this->logger->error('Error refreshing access token', [
                'access_token' => $accessToken,
                'status_code' => $response->getStatusCode(),
            ]);

            return null;
        }

        // Return the new access token if successful
        return $response->getBody();
    }
}
