['```csharp
using System;
using System.Collections.Generic;
using System.Linq;

namespace DynamicRandomValueGenerator
{
    public class RandomValueGenerator : IRandomValueGenerator
    {
        private readonly List<IRandomDistribution> _distributions = new List<IRandomDistribution>();

        public void AddDistribution(IRandomDistribution distribution)
        {
            _distributions.Add(distribution);
        }

        public int GenerateIntegerValue(int min, int max, bool inclusive = true)
        {
            var random = new Random();
            var value = random.Next(min, max + (inclusive ? 1 : 0));
            return value;
        }

        public float GenerateFloatValue(float min, float max, bool inclusive = true)
        {
            var random = new Random();
            var value = random.NextDouble() * (max - min + (inclusive ? 1 : 0)) + min;
            return (float)value;
        }

        public void Seed(int seed)
        {
            foreach (var distribution in _distributions)
            {
                distribution.Seed(seed);
            }
        }
    }

    public interface IRandomValueGenerator
    {
        int GenerateIntegerValue(int min, int max, bool inclusive = true);
        float GenerateFloatValue(float min, float max, bool inclusive = true);
        void Seed(int seed);
    }

    public interface IRandomDistribution
    {
        int Next();
        void Seed(int seed);
    }

    public class RandomIntegerDistribution : IRandomDistribution
    {
        private readonly Random _random;

        public RandomIntegerDistribution()
        {
            _random = new Random();
        }

        public int Next()
        {
            return _random.Next();
        }

        public void Seed(int seed)
        {
            _random.Seed(seed);
        }
    }

    public class RandomFloatDistribution : IRandomDistribution
    {
        private readonly Random _random;

        public RandomFloatDistribution()
        {
            _random = new Random();
        }

        public float Next()
        {
            return (float)_random.NextDouble();
        }

        public void Seed(int seed)
        {
            _random.Seed(seed);
        }
    }
}
```
