    int num_fields;  // Number of fields in the XML data
    char **field_names;  // Names of the fields in the XML data
} xml_data;

// Function to validate the file format and fetch the resource bundle from the external API
int loadResourceBundle(const resource_bundle_config *config) {
    CURL *curl;
    CURLcode res;
    json_object *root = NULL;
    xmlDoc *doc = NULL;
    int num_fields = 0;
    char **field_names = NULL;

    // Initialize the CURL library and set up the URL and file name
