        curl_easy_setopt(curl, CURLOPT_USERAGENT, "libcurl-agent/1.0");
        curl_easy_setopt(curl, CURLOPT_VERBOSE, 1L);
    } else {
        // Handle error
        return -1;
    }

    // Perform the HTTP request and check for errors
    res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        // Handle error
        return -1;
    }

    // Check the HTTP response code and handle errors
    long http_code = 0;
    curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);
    if (http_code != 200) {
        fprintf(stderr, "HTTP response code: %ld\n", http_code);
        // Handle error
        return -1;
    }

    // Parse the JSON data and count the number of fields
    json_object *root = json_tokener_parse(curl_easy_strerror(res));
    if (!json_is_object(root)) {
        fprintf(stderr, "Error parsing JSON data\n");
        // Handle error
        return -1;
    }
    num_fields = json_object_get_size(root);

    // Parse the XML data and count the number of fields
    doc = xmlParseDoc(curl_easy_strerror(res));
    if (!doc) {
        fprintf(stderr, "Error parsing XML data\n");
        // Handle error
        return -1;
    }
    num_fields += xmlGetNsProp(doc->rootNode, NULL, "field-count");

    // Reduce the fields according to the specified reduction method and configuration
    json_data *json = (json_data *) malloc(sizeof(json_data));
    xml_data *xml = (xml_data *) malloc(sizeof(xml_data));
    json->root = root;
    json->num_fields = num_fields;
    json->field_names = field_names;
    xml->doc = doc;
    xml->num_fields = num_fields;
    xml->field_names = field_names;

    // Return the reduced data struct
    return 0;
}
