class TextParser {
    public function parseLine($line) {
        // Split the line into fields based on delimiter
        $fields = explode(',', $line);

        // Validate and validate fields
        if (count($fields) < 2 || !is_numeric($fields[1])) {
            return null;
        }

        // Compute the average of the last two numerical fields
        $average = ($fields[$count - 1] + $fields[$count - 2]) / 2;

        // Dynamically allocate memory for calculations
        $memory = $this->getMemorySize();

        // Perform computations and release memory
        return [$fields, $average, $memory];
    }

    private function getMemorySize() {
        // Determine the amount of available memory
        $free_memory = memory_get_free_size();

        // If there is not enough memory, release some and try again
        if ($free_memory < 100) {
            $this->releaseMemory($free_memory);
            return $this->getMemorySize();
        }

        return $free_memory;
    }

    private function releaseMemory($amount) {
        // Release the amount of memory requested
        gc_collect_cycles();
        unset($amount);
    }
}

// Define the PHP component for consuming processed data and initializing a web server environment
class WebServer {
    public function __construct() {
        $this->textParser = new TextParser();
    }

