        // Process the data and initialize the web server environment
        $parsedData = $this->textParser->parseLine($data);

        // Configure the application using the parsed data
        $this->configureApp($parsedData);
    }

    private function configureApp($data) {
        // Initialize the web server environment using the configuration from the YAML file
        $config = yaml_parse_file(__DIR__ . '/config/app.yaml');

        // Load dependencies using Composer's autoloader
        require_once __DIR__ . '/vendor/autoload.php';

        // Configure the application using the configuration from the YAML file
