    }

    private function configureAppDependencies($config) {
        // Set up the database connection using the configuration from the YAML file
        $dbConfig = $config['database'];
        $dsn = "mysql:host={$dbConfig['host']};port={$dbConfig['port']};dbname={$dbConfig['dbname']}";
        $username = $dbConfig['username'];
        $password = $dbConfig['password'];

        // Initialize the database connection and load dependencies using Composer's autoloader
        try {
            $pdo = new PDO($dsn, $username, $password);
            require_once __DIR__ . '/vendor/autoload.php';
        } catch (PDOException $e) {
            echo "Connection failed: " . $e->getMessage();
        }
    }
}

