// Define a structure to hold information about each background process
typedef struct {
  pid_t pid; // Process ID
  int status; // Exit status of the process
} bgProcess_t;

// Define a structure to hold information about each command being processed
typedef struct {
  char* cmd; // Command string
  char* args[]; // Array of arguments for the command
} cmdInfo_t;

// Semaphore for synchronizing access to the command queue
sem_t *cmdQueueSem;

// Queue of commands waiting to be processed
queue<cmdInfo_t> cmdQueue;

// Map of background processes and their corresponding PIDs
map<int, bgProcess_t*> bgProcs;

// Function to create a new background process for the given command
void createBgProc(cmdInfo_t *cmd) {
  // Create a new background process
  pid_t pid = fork();

  // Check if the fork was successful
  if (pid == 0) {
    // The child process will execute the command
    execvp(cmd->cmd, cmd->args);

    // If the exec call failed, exit with an error message
    perror("execvp");
    exit(-1);
  } else if (pid > 0) {
    // The parent process will monitor the child process
    bgProcs[pid] = new bgProcess_t();
    bgProcs[pid]->pid = pid;
  } else {
    // If the fork failed, print an error message and exit
    perror("fork");
    exit(-1);
  }
}

// Function to remove a background process from the map
void removeBgProc(int pid) {
  // Remove the process from the map
  bgProcs.erase(pid);

  // Wait for the process to exit and retrieve its status
  int status;
  waitpid(pid, &status, WNOHANG);
}

// Function to handle a command that has timed out
void handleTimeout() {
  // TODO: Implement logic for handling timed out commands
}

// Function to handle a command that has failed
void handleFailure() {
  // TODO: Implement logic for handling failed commands
}

// Main loop for processing background tasks
void processBgTasks() {
  while (true) {
    // Check if there are any commands in the queue
    if (cmdQueue.size() > 0) {
      // Retrieve the next command from the queue
      cmdInfo_t *cmd = cmdQueue.front();

      // Create a new background process for the command
      createBgProc(cmd);

      // Remove the command from the queue
      cmdQueue.pop();
    }

    // Check if there are any background processes that have exited
    if (bgProcs.size() > 0) {
      // Loop through each background process and check its status
      for (auto it = bgProcs.begin(); it != bgProcs.end(); ++it) {
        int pid = it->first;
        bgProcess_t *proc = it->second;

        // Check if the process has exited
        if (waitpid(pid, &proc->status, WNOHANG) == 0) {
          // Process has not exited yet, continue to next process
          continue;
        } else {
          // Process has exited, handle its status
          if (WIFEXITED(proc->status)) {
            // The process has successfully completed
            removeBgProc(pid);
          } else if (WIFSIGNALED(proc->status)) {
            // The process has been terminated by a signal
            handleFailure();
          } else if (WIFSTOPPED(proc->status)) {
            // The process has been stopped by a signal
            handleFailure();
          } else if (WIFCONTINUED(proc->status)) {
            // The process has been continued
            removeBgProc(pid);
          }
        }
      }
    }

    // Check for any timed out commands
    // TODO: Implement logic for handling timed out commands

    // Sleep for a short period of time before checking the queue again
    usleep(1000);
  }
}

int main() {
  // Initialize the semaphore for synchronizing access to the command queue
  cmdQueueSem = sem_open("/cmdQueue", O_CREAT, 0644, 1);

  // Start the background processing loop
  processBgTasks();
}
