```java
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

import com.jcraft.jsch.JSch;
import com.jcraft.jsch.JSchException;
import com.jcraft.jsch.Session;
import com.jcraft.jsch.SftpClient;

public class FileSyncUtility {
    private final List<String> hosts;
    private final Map<String, Session> sessions;
    private final ExecutorService executor;

    public FileSyncUtility(List<String> hosts) throws JSchException {
        this.hosts = hosts;
        this.sessions = new ConcurrentHashMap<>();
        this.executor = Executors.newFixedThreadPool(10);
    }

    public void executeCommand(String host, String command, long timeout) throws JSchException {
        Session session = sessions.get(host);
        if (session == null) {
            session = createSession(host);
            sessions.put(host, session);
        }

        executor.submit(() -> {
            SftpClient sftp = null;
            try {
                sftp = (SftpClient) session.openChannel("sftp");
                sftp.connect();
                sftp.execCommand(command);
            } catch (JSchException | SftpException e) {
                // handle exception
            } finally {
                if (sftp != null) {
                    sftp.disconnect();
                }
            }
        });
    }

    public void executeCommand(String host, String command, long timeout, Consumer<String> resultConsumer) throws JSchException {
        Session session = sessions.get(host);
        if (session == null) {
            session = createSession(host);
            sessions.put(host, session);
        }

        executor.submit(() -> {
            SftpClient sftp = null;
            try {
                sftp = (SftpClient) session.openChannel("sftp");
                sftp.connect();
                ByteArrayOutputStream outputStream = new ByteArrayOutputStream(1024);
                sftp.execCommand(command, outputStream);
                resultConsumer.accept(outputStream.toString());
            } catch (JSchException | SftpException e) {
                // handle exception
            } finally {
                if (sftp != null) {
                    sftp.disconnect();
                }
            }
        });
    }

    public void copyFile(String sourceHost, String destinationHost, String sourcePath, String destinationPath) throws JSchException {
        Session sourceSession = sessions.get(sourceHost);
        if (sourceSession == null) {
            sourceSession = createSession(sourceHost);
            sessions.put(sourceHost, sourceSession);
        }

        Session destinationSession = sessions.get(destinationHost);
        if (destinationSession == null) {
            destinationSession = createSession(destinationHost);
            sessions.put(destinationHost, destinationSession);
        }

        SftpClient sourceSftp = null;
        SftpClient destinationSftp = null;
        try {
            sourceSftp = (SftpClient) sourceSession.openChannel("sftp");
            sourceSftp.connect();
            destinationSftp = (SftpClient) destinationSession.openChannel("sftp");
            destinationSftp.connect();
            sourceSftp.get(sourcePath, destinationSftp.put(destinationPath));
        } catch (JSchException | SftpException e) {
            // handle exception
        } finally {
            if (sourceSftp != null) {
                sourceSftp.disconnect();
            }
            if (destinationSftp != null) {
                destinationSftp.disconnect();
            }
        }
    }

    public void deleteFile(String host, String path) throws JSchException {
        Session session = sessions.get(host);
        if (session == null) {
            session = createSession(host);
            sessions.put(host, session);
        }

        SftpClient sftp = null;
        try {
            sftp = (SftpClient) session.openChannel("sftp");
            sftp.connect();
            sftp.delete(path);
        } catch (JSchException | SftpException e) {
            // handle exception
        } finally {
            if (sftp != null) {
                sftp.disconnect();
            }
        }
    }

    private Session createSession(String host) throws JSchException {
        JSch jsch = new JSch();
        String user = "user"; // TODO: Replace with your SSH username
        String password = "password"; // TODO: Replace with your SSH password
        Session session = jsch.getSession(user, host);
        session.setPassword(password);
        return session;
    }
}
```
Note that this is just a sample implementation and may need to be modified based on specific requirements and constraints. It also assumes that the user has access to an SSH client library such as JSch for connecting to the remote servers.']

