#include <iostream>
#include <string>
#include <vector>
#include <chrono>
#include <thread>
#include <stdexcept>
#include <mutex>
#include <atomic>
#include <future>
#include <functional>

class DependencyManager {
public:
    // Initialize the dependency manager with a list of dependencies
    // The dependencies are passed as a vector of strings, each representing a dependency name
    DependencyManager(const std::vector<std::string>& dependencies) : dependencies_(dependencies), initialized_deps_(0) {}

    // Initialize all dependencies asynchronously using the given init function
    void initializeDependenciesAsync(std::function<void()> initFunction) {
        for (auto& dep : dependencies_) {
            initFunctions_.emplace_back(initFunction);
        }

        // Run each dependency initialization in a separate thread, with retry logic if necessary
        std::vector<std::future<void>> futures;
        for (auto& initFunction : initFunctions_) {
            futures.emplace_back(std::async([this, &initFunction]() {
                this->initializeDependency(initFunction);
            }));
        }

        // Wait for all dependencies to be initialized successfully or fail after 5 attempts with exponential backoff between retries
        for (auto& future : futures) {
            while (!future.wait_for(std::chrono::milliseconds(0))) {
                if (this->initialized_deps_.load() == dependencies_.size()) {
                    break;
                } else {
                    std::this_thread::sleep_for(std::chrono::milliseconds(100));
                }
            }
        }

        // Check if all dependencies were initialized successfully, and throw an exception otherwise
        if (this->initialized_deps_.load() != dependencies_.size()) {
            std::string errorMsg = "Failed to initialize dependencies: ";
            for (auto& initFunction : initFunctions_) {
                if (!initFunction.joinable()) {
                    errorMsg += initFunction.get_id();
                    errorMsg += " ";
                }
            }
            throw std::runtime_error(errorMsg);
        }
    }

private:
    // Initialize a single dependency using the given initialization function
    void initializeDependency(std::function<void()> initFunction) {
        for (int i = 0; i < 5; i++) {
            try {
                initFunction();
                this->initialized_deps_.fetch_add(1);
                break;
            } catch (const std::exception& e) {
                if (i == 4) {
                    std::cerr << "Dependency initialization failed: " << e.what() << std::endl;
                    this->initialized_deps_.fetch_add(1);
                } else {
                    // Exponential backoff
                    std::this_thread::sleep_for(std::chrono::milliseconds(50 * (i + 1)));
                }
            }
        }
    }

    // Vector of dependency names
    const std::vector<std::string>& dependencies_;

    // Number of initialized dependencies
    std::atomic_uint initialized_deps_;

    // Vector of initialization functions for each dependency
    std::vector<std::function<void()>> initFunctions_;
};

// Unit tests
void unitTests() {
    const std::vector<std::string> dependencies = {"dependency1", "dependency2", "dependency3"};
    DependencyManager manager(dependencies);

    // Initialize each dependency asynchronously with a separate initialization function
    manager.initializeDependenciesAsync([&]() { std::cout << "Initializing dependency 1" << std::endl; });
    manager.initializeDependenciesAsync([&]() { std::cout << "Initializing dependency 2" << std::endl; });
    manager.initializeDependenciesAsync([&]() { std::cout << "Initializing dependency 3" << std::endl; });

    // Wait for all dependencies to be initialized successfully or fail after 5 attempts with exponential backoff between retries
    while (manager.initialized_deps_.load() != dependencies.size()) {
        std::this_thread::sleep_for(std::chrono::milliseconds(100));
    }
}

int main() {
    // Run unit tests
    unitTests();
    return 0;
}']

