// Define the schema for the JSON data
struct TokenData {
    char* access_token;
    int expires_in;
    char* token_type;
    char* scope;
    char* issued_at;
};

// Function to validate the JSON data against the schema
bool ValidateTokenData(const struct TokenData* data) {
    if (data->access_token == NULL || strlen(data->access_token) == 0) {
        return false;
    }
    if (data->expires_in <= 0) {
        return false;
    }
    if (strcmp(data->token_type, "Bearer") != 0) {
        return false;
    }
    if (data->scope == NULL || strlen(data->scope) == 0) {
        return false;
    }
    if (!ValidateScopeString(data->scope)) {
        return false;
