public class WebSocketService : IDisposable
{
    private readonly WebSocket _socket;
    private readonly IKeyManagementService _keyManagementService;
    private readonly ILoggingService _loggingService;

    public WebSocketService(WebSocket socket, IKeyManagementService keyManagementService, ILoggingService loggingService)
    {
        _socket = socket;
        _keyManagementService = keyManagementService;
        _loggingService = loggingService;
    }

    public void Start()
    {
        // Start listening for incoming messages
        _socket.OnMessage += ProcessMessage;
    }

    private async Task ProcessMessage(object sender, WebSocketMessageEventArgs e)
    {
        try
        {
            var message = e.Data;

            // Decrypt the message using Triple DES and the client's provided key and IV
            var decryptedMessage = DecryptMessage(message);

            // Validate the integrity of the decrypted message
            if (!ValidateIntegrity(decryptedMessage))
            {
                _loggingService.LogError("Invalid message received");
                return;
            }

            // Extract the sequence of integers encoded within the message
            var integerSequence = GetIntegerSequence(decryptedMessage);

            // Determine the largest integer in the sequence
            var largestInteger = GetLargestInteger(integerSequence);

            // Respond to the client with both the decrypted message and the largest integer
            await _socket.SendAsync("Decrypted message: " + decryptedMessage + Environment.NewLine + "Largest integer: " + largestInteger, WebSocketMessageType.Text);
        }
        catch (Exception ex)
        {
            _loggingService.LogError(ex.ToString());
            await _socket.SendAsync("Error processing message", WebSocketMessageType.Text);
        }
    }

    private string DecryptMessage(string message)
    {
        // Retrieve the client's encryption key and IV from the secure key management service
        var encryptionKey = await _keyManagementService.GetEncryptionKeyAsync();
        var iv = await _keyManagementService.GetIVAsync();

        using (var tripleDes = new TripleDESCryptoServiceProvider())
        {
            // Set the decryption key and IV on the cryptographic service provider
            tripleDes.Key = Encoding.ASCII.GetBytes(encryptionKey);
            tripleDes.IV = iv;

            // Decrypt the message using Triple DES
            var plainText = tripleDes.CreateDecryptor().TransformFinalBlock(Convert.FromBase64String(message), 0, Convert.FromBase64String(message).Length);

            return Encoding.UTF8.GetString(plainText);
        }
    }

    private bool ValidateIntegrity(string message)
    {
        // Implement integrity validation here
        return true;
    }

    private int[] GetIntegerSequence(string message)
    {
        // Parse the sequence of integers from the decrypted message
        var integerSequence = new List<int>();

        foreach (var number in message.Split(' '))
        {
            if (!int.TryParse(number, out int result))
            {
                continue;
            }

            integerSequence.Add(result);
        }

        return integerSequence.ToArray();
    }

    private int GetLargestInteger(int[] integerSequence)
    {
        // Return the largest integer in the sequence
        return integerSequence.Max();
    }
}
