using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class SecureDataProcessor
{
    private readonly byte[] _encryptionKey;
    private readonly byte[] _initializationVector;
    private readonly Encoding _encoding;

    public SecureDataProcessor(byte[] encryptionKey, byte[] initializationVector, Encoding encoding = null)
    {
        _encryptionKey = encryptionKey ?? throw new ArgumentNullException(nameof(encryptionKey));
        _initializationVector = initializationVector ?? throw new ArgumentNullException(nameof(initializationVector));
        _encoding = encoding ?? Encoding.UTF8;
    }

    public async Task<T> ProcessAndLoadDataAsync<T>(byte[] encryptedData) where T : class
    {
        try
        {
            var decryptedData = Decrypt(encryptedData);
            return await DeserializeAsync<T>(decryptedData);
        }
        catch (Exception e)
        {
            Console.WriteLine($"Error processing and loading data: {e.Message}");
            throw;
        }
    }

    private byte[] Decrypt(byte[] encryptedData)
    {
        using var aes = AesCryptoServiceProvider.Create();
        aes.Key = _encryptionKey;
        aes.IV = _initializationVector;

        var decryptedData = new MemoryStream();
        using (var cryptor = aes.CreateDecryptor())
        {
            var inputBuffer = new byte[1024];
            var outputBuffer = new byte[1024];
            int readBytes, writtenBytes;

            while ((readBytes = encryptedData.Length) > 0)
            {
                cryptor.TransformBlock(encryptedData, 0, readBytes, outputBuffer, 0);
                decryptedData.Write(outputBuffer, 0, cryptor.OutputBlockSize);
                encryptedData = new byte[readBytes - cryptor.OutputBlockSize];
            }
        }

        return decryptedData.ToArray();
    }

    private async Task<T> DeserializeAsync<T>(byte[] data) where T : class
    {
        using var stream = new MemoryStream(data);
        var serializer = new CustomSerializer(_encoding);
        return await serializer.DeserializeAsync<T>(stream);
    }
}

public class CustomSerializer : ISerializer
{
    private readonly Encoding _encoding;

    public CustomSerializer(Encoding encoding)
    {
        _encoding = encoding ?? throw new ArgumentNullException(nameof(encoding));
    }

    public async Task<T> DeserializeAsync<T>(Stream stream) where T : class
    {
        try
        {
            using var reader = new StreamReader(stream, _encoding);
            var serializer = new CustomSerialization();
            return await serializer.DeserializeAsync<T>(reader);
        }
        catch (Exception e)
        {
            Console.WriteLine($"Error deserializing data: {e.Message}");
            throw;
        }
    }
}

public class CustomSerialization : ICustomSerialization
{
    public async Task<T> DeserializeAsync<T>(TextReader reader) where T : class
    {
        try
        {
            var serializer = new DataContractJsonSerializer(typeof(T));
            return (T)serializer.ReadObject(reader);
        }
        catch (Exception e)
        {
            Console.WriteLine($"Error deserializing data: {e.Message}");
            throw;
        }
    }
}
```
