int max_vertices = MAX_VERTICES;
int max_edges = MAX_EDGES;

// Define the size of the AES key in bytes
size_t aes_key_size = AES_KEY_SIZE;

// Define the AES key for encrypting and decrypting data
unsigned char aes_key[AES_KEY_SIZE];

// Define the Camellia key for encrypting and decrypting data
unsigned char camellia_key[CAMELLIA_KEY_SIZE];

// Define the SHA-256 hash function for generating hash values
SHA256_CTX sha256_ctx;

// Define the structure for storing vertex and edge information
