  int id;
  char label[100];
};

struct Edge {
  int src_id, dest_id;
  char label[100];
};

// Define the function for adding a variable number of vertices to the graph
int add_vertices(struct Vertex* vertices, int num_vertices) {
  if (num_vertices > max_vertices) {
    return -1;
  }

  // Encrypt and hash the vertices using AES-GCM and Camellia-GCM
  for (int i = 0; i < num_vertices; i++) {
    unsigned char iv[AES_BLOCK_SIZE];
    random_bytes(iv, sizeof(iv));

    int ret = aes_gcm_encrypt(aes_key, vertices[i].label, &sha256_ctx, iv);
    if (ret != 0) {
      return -1;
    }

    // Hash the encrypted vertex using SHA-256
    unsigned char hash[SHA256_DIGEST_LENGTH];
    sha256_hash(vertices[i].label, sizeof(vertices[i].label), &sha256_ctx, hash);

    // Set the random cryptographic properties for each vertex
    vertices[i].id = num_nodes++;
    memcpy(vertices[i].label, hash, SHA256_DIGEST_LENGTH);
  }

  return 0;
}

// Define the function for adding a variable number of edges to the graph
int add_edges(struct Edge* edges, int num_edges) {
  if (num_edges > max_edges) {
    return -1;
  }

  // Encrypt and hash the edges using AES-GCM and Camellia-GCM
  for (int i = 0; i < num_edges; i++) {
    unsigned char iv[AES_BLOCK_SIZE];
    random_bytes(iv, sizeof(iv));

    int ret = aes_gcm_encrypt(aes_key, edges[i].label, &sha256_ctx, iv);
    if (ret != 0) {
      return -1;
    }

    // Hash the encrypted edge using SHA-256
    unsigned char hash[SHA256_DIGEST_LENGTH];
    sha256_hash(edges[i].label, sizeof(edges[i].label), &sha256_ctx, hash);

    // Set the random cryptographic properties for each edge
    edges[i].src_id = num_nodes++;
    edges[i].dest_id = num_nodes++;
    memcpy(edges[i].label, hash, SHA256_DIGEST_LENGTH);
  }

  return 0;
}

