#include <condition_variable>
#include <future>
#include <chrono>
#include <thread>
#include <atomic>
#include <stdexcept>

// Define a struct to represent a packet buffer in the pool
struct PacketBuffer {
  // Use a vector of bytes as the payload for simplicity
  std::vector<char> payload;
  // Set the size of the payload to a fixed value (e.g., 1024)
  constexpr static size_t MAX_PAYLOAD_SIZE = 1024;
};

// Define a class to represent the packet buffer pool
class PacketBufferPool {
public:
  // Constructor
  PacketBufferPool() : available_buffers_(MAX_BUFFERS), used_buffers_(), next_available_buffer_idx_(0) {}

  // Function to allocate a new packet buffer from the pool
  std::shared_ptr<PacketBuffer> AllocateBuffer(const size_t payload_size = MAX_PAYLOAD_SIZE) {
    if (payload_size > MAX_PAYLOAD_SIZE) {
      throw std::invalid_argument("Payload size exceeds maximum value");
    }

    // Acquire a lock on the available buffers
    std::lock_guard<std::mutex> lock(available_buffers_mutex_);

    // Check if there are any available buffers in the pool
    if (available_buffers_.empty()) {
      return nullptr;
    }

    // Get the next available buffer index and allocate a new buffer
    size_t idx = next_available_buffer_idx_;
    std::shared_ptr<PacketBuffer> buffer = std::make_shared<PacketBuffer>(payload_size);
    next_available_buffer_idx_++;
    if (next_available_buffer_idx_ >= MAX_BUFFERS) {
      next_available_buffer_idx_ = 0;
    }
    available_buffers_.erase(idx);

    // Add the allocated buffer to the used buffers list and return it
    std::lock_guard<std::mutex> lock2(used_buffers_mutex_);
    used_buffers_.emplace_back(buffer);
    return buffer;
  }

  // Function to deallocate a packet buffer from the pool
  void DeallocateBuffer(const std::shared_ptr<PacketBuffer> &buffer) {
    if (!buffer) {
      throw std::invalid_argument("Buffer is null");
    }

    // Acquire locks on both lists of buffers
    std::lock_guard<std::mutex> lock(available_buffers_mutex_);
    std::lock_guard<std::mutex> lock2(used_buffers_mutex_);

    // Check if the buffer is in the used buffers list
    auto it = std::find(used_buffers_.begin(), used_buffers_.end(), buffer);
    if (it == used_buffers_.end()) {
      throw std::invalid_argument("Buffer not found");
    }

    // Move the buffer to the available buffers list and return it
    available_buffers_.emplace(next_available_buffer_idx_, *it);
    next_available_buffer_idx_++;
    if (next_available_buffer_idx_ >= MAX_BUFFERS) {
      next_available_buffer_idx_ = 0;
    }
    used_buffers_.erase(it);
  }

private:
  // Define constants for the maximum number of buffers and the payload size
  constexpr static size_t MAX_BUFFERS = 1024;
  constexpr static size_t MAX_PAYLOAD_SIZE = 1024;

  // Use an unordered map to store the available buffers as a hash table
  std::unordered_map<size_t, std::shared_ptr<PacketBuffer>> available_buffers_;

  // Use a vector to store the used buffers in the order they were allocated
  std::vector<std::shared_ptr<PacketBuffer>> used_buffers_;

  // Define variables to keep track of the next available buffer index and the mutexes for both lists of buffers
  size_t next_available_buffer_idx_;
  std::mutex available_buffers_mutex_;
  std::mutex used_buffers_mutex_;
};
