  private Map<String, MessageQueue> messageQueues = new HashMap<>();
  private MessageRouter messageRouter;
  private ErrorHandler errorHandler;

  public MessagingBroker() {
    this.messageQueues.put("rabbitmq", new RabbitMQMessageQueue());
    this.messageQueues.put("kafka", new KafkaMessageQueue());
    this.messageQueues.put("sqs", new AmazonSQSMessageQueue());

    this.messageRouter = new MessageRouter();
    this.errorHandler = new ErrorHandler();
  }

