    try {
      MessageQueue queue = this.messageQueues.get(queueName);
      if (queue == null) {
        throw new IllegalArgumentException("Invalid queue name: " + queueName);
      }
      return queue.receiveMessage();
    } catch (MessagingException e) {
      this.errorHandler.handleError(e);
      return null;
    }
  }

