// File: s3-storage.js
const AWS = require('aws-sdk');

class S3Storage {
  constructor(options) {
    this.bucketName = options.bucketName;
    this.keyPrefix = options.keyPrefix;
    this.s3Client = new AWS.S3({
      region: options.region,
      accessKeyId: options.accessKeyId,
      secretAccessKey: options.secretAccessKey,
    });
  }

  async storeHash(hash, filePath) {
    const key = `${this.keyPrefix}${filePath}`;
    try {
      await this.s3Client.putObject({ Bucket: this.bucketName, Key: key, Body: hash });
    } catch (err) {
      console.error(err);
      return Promise.reject(err);
    }
  }

  async getHash(filePath) {
    const key = `${this.keyPrefix}${filePath}`;
    try {
      const object = await this.s3Client.getObject({ Bucket: this.bucketName, Key: key });
      return object.Body;
    } catch (err) {
      console.error(err);
      return Promise.reject(err);
    }
  }
}
