const { Storage } = require('@google-cloud/storage');

class GCSStorage {
  constructor(options) {
    this.bucketName = options.bucketName;
    this.keyPrefix = options.keyPrefix;
    this.storageClient = new Storage({
      projectId: options.projectId,
      keyFilename: options.keyFilename,
    });
  }

  async storeHash(hash, filePath) {
    const key = `${this.keyPrefix}${filePath}`;
    try {
      await this.storageClient.bucket(this.bucketName).file(key).save(hash);
    } catch (err) {
      console.error(err);
      return Promise.reject(err);
    }
  }

  async getHash(filePath) {
    const key = `${this.keyPrefix}${filePath}`;
    try {
      const file = await this.storageClient.bucket(this.bucketName).file(key);
      const hash = await file.download();
      return hash[0];
    } catch (err) {
      console.error(err);
      return Promise.reject(err);
    }
  }
}
