#define MAX_ENCRYPTION_SIZE 256
#define HASH_ALGORITHM "sha256"
#define ENCRYPTION_ALGORITHM "aes-256-cbc"

// Global variables
EVP_MD_CTX *hash_ctx;
EVP_CIPHER_CTX *encryption_ctx;
unsigned char hash[MAX_HASH_SIZE];
unsigned char encryption_key[MAX_ENCRYPTION_SIZE];

void init_openssl() {
