void load_modules() {
  // Load the hash algorithm module
  if (!EVP_MD_CTX_init(&hash_ctx)) {
    printf("Error initializing hash algorithm context\n");
    exit(1);
  }
  EVP_MD_CTX_cleanup(&hash_ctx);

  // Load the encryption algorithm module
  if (!EVP_CIPHER_CTX_init(&encryption_ctx)) {
    printf("Error initializing encryption algorithm context\n");
    exit(1);
  }
  EVP_CIPHER_CTX_cleanup(&encryption_ctx);
}

void compute_hash() {
  // Set the hash algorithm and digest size
  const EVP_MD *md = EVP_get_digestbyname(HASH_ALGORITHM);
  if (!md) {
    printf("Invalid hash algorithm\n");
    exit(1);
  }

  // Hash the input data
  if (!EVP_DigestInit_ex(hash_ctx, md, NULL)) {
    printf("Error initializing hash algorithm\n");
    exit(1);
  }
  if (!EVP_DigestUpdate(hash_ctx, input_data, strlen(input_data))) {
    printf("Error updating hash algorithm\n");
    exit(1);
  }
  if (!EVP_DigestFinal_ex(hash_ctx, hash, NULL)) {
    printf("Error finalizing hash algorithm\n");
    exit(1);
  }
}

void generate_encryption_key() {
  // Generate a random encryption key of the appropriate size
  if (!RAND_bytes(encryption_key, MAX_ENCRYPTION_SIZE)) {
    printf("Error generating encryption key\n");
    exit(1);
  }
}

void encrypt_data() {
  // Set the encryption algorithm and block size
  const EVP_CIPHER *cipher = EVP_get_cipherbyname(ENCRYPTION_ALGORITHM);
  if (!cipher) {
    printf("Invalid encryption algorithm\n");
    exit(1);
  }

  // Initialize the encryption context
  if (!EVP_EncryptInit_ex(encryption_ctx, cipher, NULL, encryption_key, NULL)) {
    printf("Error initializing encryption algorithm\n");
    exit(1);
  }

  // Encrypt the input data
  int len = strlen(input_data);
  if (!EVP_EncryptUpdate(encryption_ctx, encrypted_data, &len, input_data, len)) {
    printf("Error encrypting data\n");
    exit(1);
  }
}

void free_openssl() {
  EVP_MD_CTX_cleanup(&hash_ctx);
  EVP_CIPHER_CTX_cleanup(&encryption_ctx);
}
