        // Create output file for writing
        ofstream outputFileStream(filePath + ".enc", ios::binary | ios::app);
        if (!outputFileStream.is_open()) {
            throw runtime_error("Failed to create output file: " + filePath + ".enc");
        }

        // Initialize encryption algorithm based on input parameter
        CryptoPP::SecByteBlock key = generateEncryptionKey(encryptionAlgorithm, rng);
        CryptoPP::SecureVector<byte> iv;
        CryptoPP::SymmetricCipher* cipher = getCipherInstance(encryptionAlgorithm, key, iv);

        // Encrypt file contents in chunks
        stringstream inputBuffer;
        stringstream outputBuffer;
        byte block[FILE_UPLOAD_CHUNK_SIZE];
        int bytesRead;
        while ((bytesRead = inputFileStream.readsome(block, FILE_UPLOAD_CHUNK_SIZE)) > 0) {
            cipher->Encrypt(outputBuffer, block, bytesRead);
            outputFileStream << outputBuffer.rdbuf();
            outputBuffer.clear();
        }

        // Close input and output files
        inputFileStream.close();
        outputFileStream.close();
    }

    CryptoPP::SecByteBlock generateEncryptionKey(string encryptionAlgorithm, CryptoPP::AutoSeededRandomPool& rng) {
        if (encryptionAlgorithm == AES_256_CBC) {
            return CryptoPP::SecByteBlock(AES_KEY_LENGTH);
        } else if (encryptionAlgorithm == RSA_ENCRYPTION_SCHEME) {
            // Generate a random key for the encryption algorithm
            SecureVector<byte> key = rng.GenerateRandom(RSA_KEY_LENGTH / 8);
            return CryptoPP::SecByteBlock(key.begin(), key.end());
        } else {
            throw runtime_error("Unsupported encryption algorithm: " + encryptionAlgorithm);
        }
    }

    CryptoPP::SymmetricCipher* getCipherInstance(string encryptionAlgorithm, CryptoPP::SecByteBlock key, SecureVector<byte>& iv) {
        if (encryptionAlgorithm == AES_256_CBC) {
            return new CryptoPP::AES(key);
        } else if (encryptionAlgorithm == RSA_ENCRYPTION_SCHEME) {
            // Generate a random initialization vector for the encryption algorithm
            iv = SecureVector<byte>(CryptoPP::AES::BLOCKSIZE, 0x0);
            return new CryptoPP::RSAES_OAEP_SHA_Decryptor(key);
        } else {
            throw runtime_error("Unsupported encryption algorithm: " + encryptionAlgorithm);
        }
    }
};
