// Semaphore class that manages concurrent access to shared resources across a dynamic cluster of nodes
class Semaphore {
public:
    // Constructor that takes in the initial value for the semaphore and the number of nodes in the cluster
    Semaphore(int init_val, int num_nodes) : sem_(init_val), num_nodes_(num_nodes) {}

    // Acquire function that blocks until the semaphore is available and then decrements it by 1
    void acquire() {
        std::unique_lock<std::mutex> lock(mtx_);
        while (sem_.load() <= 0) {
            cv_.wait(lock);
        }
        sem_--;
    }

    // Release function that increments the semaphore by 1 and notifies any waiting threads
    void release() {
        std::unique_lock<std::mutex> lock(mtx_);
        sem_++;
        cv_.notify_all();
    }

    // GetValue function that returns the current value of the semaphore
    int get_value() const {
        return sem_;
    }

private:
    std::atomic<int> sem_; // atomic integer for managing the semaphore value
    std::mutex mtx_;       // mutex to protect the critical section of the acquire and release functions
    std::condition_variable cv_; // condition variable to wait on the semaphore value becoming available
    int num_nodes_;        // number of nodes in the cluster
};

// ClusterManager class that manages node failures, dynamic load balancing, and seamless node addition/removal
class ClusterManager {
public:
    // Constructor that takes in the initial number of nodes in the cluster
    ClusterManager(int num_nodes) : num_nodes_(num_nodes) {}

    // AddNode function that adds a new node to the cluster and adjusts semaphore ownership accordingly
    void add_node() {
        std::unique_lock<std::mutex> lock(mtx_);
        num_nodes_++;
        semaphores_.insert({num_nodes_, Semaphore(0, num_nodes_)});
    }

    // RemoveNode function that removes a node from the cluster and adjusts semaphore ownership accordingly
    void remove_node() {
        std::unique_lock<std::mutex> lock(mtx_);
        if (num_nodes_ > 0) {
            num_nodes_--;
            semaphores_.erase(num_nodes_);
        }
    }

    // Acquire function that blocks until the semaphore is available on a specific node and then decrements it by 1
    void acquire(int node) {
        std::unique_lock<std::mutex> lock(mtx_);
        while (semaphores_.at(node).get_value() <= 0) {
            cv_.wait(lock);
        }
        semaphores_.at(node).acquire();
    }

    // Release function that increments the semaphore by 1 on a specific node and notifies any waiting threads
    void release(int node) {
        std::unique_lock<std::mutex> lock(mtx_);
        semaphores_.at(node).release();
    }

private:
    int num_nodes_;                 // number of nodes in the cluster
    std::unordered_map<int, Semaphore> semaphores_;   // map of node IDs to semaphore objects
    std::mutex mtx_;                // mutex to protect the critical section of the add and remove functions
    std::condition_variable cv_;   // condition variable to wait on the semaphore value becoming available
};

// SelfHealing class that redistributes semaphore ownership and reassigns tasks upon node failures, minimizing downtime
class SelfHealing {
public:
    // Constructor that takes in the cluster manager object and a vector of nodes
    SelfHealing(ClusterManager& cm, const std::vector<int>& nodes) : cm_(cm), nodes_(nodes) {}

    // NodeFailure function that handles a node failure and redistributes semaphore ownership accordingly
    void node_failure(int failed_node) {
        std::unique_lock<std::mutex> lock(mtx_);
        // Remove the failed node from the cluster manager object
        cm_.remove_node();
        // Redistribute the semaphore ownership across the remaining nodes
        for (auto& node : nodes_) {
            if (node != failed_node) {
                cm_.add_node(node);
            }
        }
    }

private:
    ClusterManager& cm_;                 // reference to the cluster manager object
    std::vector<int> nodes_;             // vector of node IDs
    std::mutex mtx_;                     // mutex to protect the critical section of the node failure function
};

// RetryLogic class that implements retry logic for semaphore operations with configurable backoff strategies
class RetryLogic {
public:
    // Constructor that takes in a vector of nodes, a backoff strategy, and a timeout period
    RetryLogic(const std::vector<int>& nodes, const BackoffStrategy& backoff_strategy, int timeout) : nodes_(nodes), backoff_strategy_(backoff_strategy), timeout_(timeout) {}

    // Acquire function that retries the acquire operation with a backoff strategy until it succeeds or times out
    void acquire() {
        std::unique_lock<std::mutex> lock(mtx_);
        for (int i = 0; i < nodes_.size(); i++) {
            if (!cm_.acquire(nodes_[i])) {
                // If the acquire operation fails, wait on the condition variable for the specified timeout period
                cv_.wait_for(lock, std::chrono::milliseconds(timeout_));
                // If the wait times out, throw a timeout exception
                if (!cm_.acquire(nodes_[i])) {
                    throw TimeoutException();
                }
            }
        }
    }

private:
    std::vector<int> nodes_;                     // vector of node IDs
    ClusterManager& cm_;                         // reference to the cluster manager object
    BackoffStrategy backoff_strategy_;           // backoff strategy for handling failures
    int timeout_;                                // timeout period in milliseconds
    std::mutex mtx_;                             // mutex to protect the critical section of the acquire function
    std::condition_variable cv_;                // condition variable to wait on the semaphore value becoming available
};
