// File: src/grammar_module.rs

use std::collections::HashMap;
use std::io::Read;

pub struct GrammarModule {
    rules: HashMap<String, String>,
}

impl GrammarModule {
    pub fn new() -> Self {
        Self {
            rules: HashMap::new(),
        }
    }

    // Parse the input file using this grammar module's rules and semantics
    pub fn parse_file(&self, input_file: &Path) -> Result<Vec<String>, String> {
        let mut rules = self.rules.clone();
        let mut parsed_input = vec![];

        // Read the input file line by line
        let mut f = match File::open(input_file) {
            Ok(f) => f,
            Err(_) => return Err("Failed to open input file".to_string()),
        };
        let mut buffer = String::new();
        while f.read_line(&mut buffer).unwrap() > 0 {
            // Apply the grammar rules to each line of the input file
            for rule in rules.keys() {
                let regex = Regex::new(rule);
                if let Some(captures) = regex.captures(&buffer) {
                    // Replace any matches with the corresponding value from the hash map
                    let replacement = rules[rule].to_string();
                    parsed_input.push(replacement);
                } else {
                    // If no match is found, append the line to the output
                    parsed_input.push(buffer.clone());
                }
            }
        }

        Ok(parsed_input)
    }
}

