use std::io::{self, Write};

pub struct LexerModule {
    tokenizer: Tokenizer,
}

impl LexerModule {
    pub fn new() -> Self {
        Self {
            tokenizer: Tokenizer::new(),
        }
    }

    // Parse the input file using this lexer module's rules and semantics
    pub fn parse_file(&self, input_file: &Path) -> Result<Vec<String>, String> {
        let mut tokens = vec![];

        // Open the input file in read-only mode
        let mut f = match File::open(input_file) {
            Ok(f) => f,
            Err(_) => return Err("Failed to open input file".to_string()),
        };

        // Read the entire file into memory
        let mut buffer = String::new();
        while f.read_line(&mut buffer).unwrap() > 0 {
            // Tokenize each line of the input file
            for token in self.tokenizer.tokenize(buffer) {
                tokens.push(token);
            }
        }

        Ok(tokens)
    }
}

