use std::collections::HashMap;
use std::io::{self, Write};

pub struct ParserModule {
    rules: HashMap<String, String>,
}

impl ParserModule {
    pub fn new() -> Self {
        Self {
            rules: HashMap::new(),
        }
    }

    // Parse the input file using this parser module's rules and semantics
    pub fn parse_file(&self, input_file: &Path) -> Result<Vec<String>, String> {
        let mut parsed_input = vec![];

        // Read the entire input file into memory
        let mut buffer = String::new();
        if let Ok(f) = File::open(input_file) {
            while f.read_line(&mut buffer).unwrap() > 0 {
                for rule in self.rules.keys() {
                    let regex = Regex::new(rule);
                    if let Some(captures) = regex.captures(&buffer) {
                        // Replace any matches with the corresponding value from the hash map
                        let replacement = self.rules[rule].to_string();
                        parsed_input.push(replacement);
                    } else {
                        // If no match is found, append the line to the output
                        parsed_input.push(buffer.clone());
                    }
                }
            }
        }

        Ok(parsed_input)
    }
}

