use std::io::Write;

pub struct LlvmIrModule {
    output_dir: Path,
}

impl LlvmIrModule {
    pub fn new(output_dir: &Path) -> Self {
        Self {
            output_dir: output_dir.to_path_buf(),
        }
    }

    // Generate LLVM IR code from the parsed input file
    pub fn generate(&self, parsed_input: &Vec<String>) -> Result<(), String> {
        let mut writer = File::create(self.output_dir.join("llvm_ir.txt"))?;
        for line in parsed_input {
            writer.write_all(line.as_bytes())?;
        }
        Ok(())
    }
