namespace RandomEngine {
    using namespace std;

    class MTGenerator {
    private:
        mt19937 eng;
        mutex mtx;
        condition_variable cv;

    public:
        MTGenerator(uint64_t seed) : eng(seed), mtx(), cv() {}

        uint64_t getSeed() { return eng.getSeed(); }

        void setSeed(uint64_t seed) {
            lock_guard<mutex> lck(mtx);
            eng.seed(seed);
        }

        int32_t generateInt32() {
            int32_t result;
            mtx.lock();
            try {
                result = eng.operator()();
            } catch (exception &e) {
                cerr << "Error generating random integer: " << e.what() << endl;
            }
            mtx.unlock();
            return result;
        }

        double generateDouble() {
            double result;
            mtx.lock();
            try {
                result = eng.operator()();
            } catch (exception &e) {
                cerr << "Error generating random double: " << e.what() << endl;
            }
            mtx.unlock();
            return result;
        }

        float generateFloat() {
            float result;
            mtx.lock();
            try {
                result = eng.operator()();
            } catch (exception &e) {
                cerr << "Error generating random float: " << e.what() << endl;
            }
            mtx.unlock();
            return result;
        }
    };
}
