    public class XMLParser
    {
        private readonly string _configurationPath;
        private readonly string _schemaRegistryUrl;
        private readonly string _authServiceUrl;
        private readonly ConcurrentDictionary<string, XDocument> _cachedDocuments;
        private readonly ObjectPool<XmlReader> _xmlReaderPool;
        private readonly ObjectPool<XElement> _xElementPool;

        public XMLParser(string configurationPath, string schemaRegistryUrl, string authServiceUrl)
        {
            _configurationPath = configurationPath;
            _schemaRegistryUrl = schemaRegistryUrl;
            _authServiceUrl = authServiceUrl;
            _cachedDocuments = new ConcurrentDictionary<string, XDocument>();
            _xmlReaderPool = new ObjectPool<XmlReader>(() => XmlReader.Create(new StringReader("")), 10);
            _xElementPool = new ObjectPool<XElement>(() => new XElement(""), 10);
        }

        public async Task ParseAsync(string xmlFilePath, string xsdSchemaPath = null)
        {
            var document = await LoadDocumentAsync(xmlFilePath);
            if (xsdSchemaPath != null)
            {
                ValidateAgainstSchema(document, xsdSchemaPath);
            }
        }

        public async Task<XElement> ParseSingleNodeAsync(string xmlFilePath, string xpathExpression)
        {
            var document = await LoadDocumentAsync(xmlFilePath);
            return GetSingleNode(document, xpathExpression);
        }

        public async Task<IEnumerable<XElement>> ParseMultipleNodesAsync(string xmlFilePath, string xpathExpression)
        {
            var document = await LoadDocumentAsync(xmlFilePath);
            return GetMultipleNodes(document, xpathExpression);
        }

        private async Task<XDocument> LoadDocumentAsync(string xmlFilePath)
        {
            if (_cachedDocuments.TryGetValue(xmlFilePath, out var document))
            {
                return document;
            }

            using (var stream = new FileStream(xmlFilePath, FileMode.Open))
            {
                using (var xmlReader = _xmlReaderPool.GetObject())
                {
                    xmlReader.ReadState = ReadState.Interactive;
                    document = await XDocument.LoadAsync(stream, LoadOptions.None, CancellationToken.None);
                    _cachedDocuments[xmlFilePath] = document;
                }
            }
        }

        private void ValidateAgainstSchema(XDocument document, string xsdSchemaPath)
        {
            // TODO: Implement schema validation using the XSD schema provided in xsdSchemaPath
        }

        private XElement GetSingleNode(XDocument document, string xpathExpression)
        {
            var node = document.SelectSingleNode(xpathExpression);
            return _xElementPool.GetObject(() => new XElement(node));
        }

        private IEnumerable<XElement> GetMultipleNodes(XDocument document, string xpathExpression)
        {
            var nodes = document.SelectNodes(xpathExpression);
            if (nodes == null || !nodes.Any())
            {
                return Enumerable.Empty<XElement>();
            }

            using (var enumerator = _xElementPool.GetEnumerator())
            {
                foreach (XmlNode node in nodes)
                {
                    var element = new XElement(node);
                    enumerator.PushObject(element);
                }

                return enumerator;
            }
        }

