Here is a sample code for the given programming task:
```javascript
const express = require('express');
const app = express();
const multer = require('multer');
const path = require('path');
const fs = require('fs');
const request = require('request');
const axios = require('axios');

// Set up Multer for file uploads
app.use(multer({ dest: 'uploads/' }).single('file'));

// Set up API endpoint for file processing
app.post('/process-file', (req, res) => {
  const file = req.files.file;

  // Validate the file type and size
  if (!validateFile(file)) {
    return res.status(400).send('Invalid file');
  }

  // Store the file in a temporary directory
  const tempPath = path.join(__dirname, 'uploads', file.originalname);
  fs.writeFileSync(tempPath, file.buffer);

  // Make a request to the third-party API for validation and authentication
  const apiUrl = 'https://api.example.com/validate';
  const data = { file: tempPath };
  axios.post(apiUrl, data)
    .then((response) => {
      // Check if the validation was successful
      if (response.data.successful) {
        // Log the request in a separate log file
        fs.appendFileSync('access.log', JSON.stringify(req.body));

        // Delete the temporary file
        fs.unlinkSync(tempPath);

        // Send the response back to the client
        res.send({ message: 'File uploaded successfully' });
      } else {
        // If the validation failed, delete the temporary file and send an error response
        fs.unlinkSync(tempPath);
        res.status(400).send('File upload failed');
      }
    })
    .catch((error) => {
      // If there was an error making the request to the API, delete the temporary file and send an error response
      fs.unlinkSync(tempPath);
      res.status(500).send('Error processing file');
    });
});

// Validate the file type and size
function validateFile(file) {
  const validTypes = ['image/jpeg', 'image/png'];
  const maxSize = 1 * 1024 * 1024; // 1 MB
  if (!validTypes.includes(file.mimetype)) {
    return false;
  }
  if (file.size > maxSize) {
    return false;
  }
  return true;
}
```
