const express = require('express');
const app = express();
const bodyParser = require('body-parser');
const axios = require('axios');
const mongoose = require('mongoose');
const cache = require('cache-level');
const rateLimit = require('express-rate-limit');
const helmet = require('helmet');

// Connect to the MongoDB database
mongoose.connect(process.env.MONGO_URI, { useNewUrlParser: true });

// Set up the Express app
app.use(bodyParser.json());
app.use(helmet());
app.set('trust proxy', 1); // trust first proxy
app.use(rateLimit({
  windowMs: 60 * 1000, // 1 minute window
  max: 50, // limit each IP to 50 requests per windowMs
}));

// Set up the caching layer
const cacheStore = new cache.MemoryCache();

// Set up the MongoDB model
const StockSchema = new mongoose.Schema({
  symbol: String,
  price: Number,
  timestamp: Date,
});

const StockModel = mongoose.model('Stock', StockSchema);

// Define the API endpoints
app.post('/stocks', (req, res) => {
  const stockData = req.body; // retrieve the stock data from the request body
  const symbol = stockData.symbol; // extract the stock symbol

  // Check if the stock is already in the cache
  const cachedStock = cacheStore.get(symbol);
  if (cachedStock) {
    res.send(cachedStock); // return the cached stock data
    return;
  }

  // If the stock is not in the cache, fetch it from the API
  axios.get(`https://api.example.com/stocks/${symbol}`)
    .then((response) => {
      const stock = response.data; // extract the stock data from the API response
      const newStock = new StockModel(stock); // create a new Stock model instance
      newStock.save().then(() => {
        cacheStore.set(symbol, stock); // cache the stock data
        res.send(stock); // return the stock data
      });
    })
    .catch((error) => {
      console.error(`Error fetching stock data for ${symbol}:`, error);
      res.status(500).send('Internal server error');
    });
});

app.get('/stocks', (req, res) => {
  const symbol = req.query.symbol; // extract the stock symbol from the query parameters
  if (!symbol) {
    res.status(400).send('Missing stock symbol');
    return;
  }

  const cachedStock = cacheStore.get(symbol);
  if (cachedStock) {
    res.send(cachedStock); // return the cached stock data
    return;
  }

  StockModel.findOne({ symbol })
    .then((stock) => {
      if (!stock) {
        res.status(404).send('Stock not found');
        return;
      }
      cacheStore.set(symbol, stock); // cache the stock data
      res.send(stock); // return the stock data
    })
    .catch((error) => {
      console.error(`Error fetching stock data for ${symbol}:`, error);
      res.status(500).send('Internal server error');
    });
});

// Start the Express app
const port = process.env.PORT || 3000;
app.listen(port, () => {
  console.log(`Server started on port ${port}`);
});
```
Note that this is just a sample code and may need to be modified based on your specific requirements. Additionally, you will need to set up the MongoDB database and the third-party APIs for market indices and news feeds."]

