public class DynamicRandomValueGenerator {
  // Initialize a random number generator and seed it with a fixed value for reproducibility
  private static readonly Random _random = new Random(0);

  // Function to generate random values within specified ranges, supporting integers and floats
  public static object GenerateRandomValue(Type type, int min, int max) {
    if (type == typeof(int)) {
      return _random.Next(min, max + 1);
    } else if (type == typeof(float)) {
      return (float)_random.NextDouble() * (max - min) + min;
    } else {
      throw new NotSupportedException($"Unsupported type: {type}");
    }
  }
}
