function makeApiCall($url, $method = 'GET', $data = []) {
  // Handle rate limits and connection failures gracefully
  try {
    $response = \Httpful\Request::$method($url)
      ->addHeaders([
        'Content-Type' => 'application/json',
      ])
      ->send();
    return json_decode($response->body, true);
  } catch (Exception $e) {
    // Log error and return empty response
    logError('API call failed: ' . $e->getMessage());
    return [];
  }
}

function makeDbQuery($query, $params = []) {
  try {
    $db = new PDO(DB_HOST . ';dbname=' . DB_NAME, DB_USER, DB_PASS);
    $stmt = $db->prepare($query);
    $stmt->execute($params);
    return $stmt->fetchAll();
  } catch (Exception $e) {
    // Log error and return empty response
    logError('Database query failed: ' . $e->getMessage());
    return [];
  }
}

