  // Check if ID is present and valid
  if (!is_numeric($id) || !$id) {
    throw new \Exception('Invalid employee ID');
  }

  // Build query to update employee record
  $query = 'UPDATE employees SET name = :name, email = :email, password = :password, role = :role, status = :status WHERE id = :id';
  $params = [
    ':id' => $id,
    ':name' => $name,
    ':email' => $email,
    ':password' => $password,
    ':role' => $role,
    ':status' => $status,
