  // Make API call to update employee record
  $response = makeApiCall(API_URL . '/' . $id, 'PUT', json_encode($params));
  if ($response['success']) {
    logInfo('Employee updated successfully');
    return true;
  } else {
    logError('Failed to update employee record: ' . $response['error']);
    throw new \Exception('Failed to update employee record');
  }
