  // Check if ID is present and valid
  if (!is_numeric($id) || !$id) {
    throw new \Exception('Invalid employee ID');
  }

  // Build query to delete employee record
  $query = 'DELETE FROM employees WHERE id = :id';
  $params = [':id' => $id];

  // Make API call to delete employee record
  $response = makeApiCall(API_URL . '/' . $id, 'DELETE', json_encode($params));
  if ($response['success']) {
    logInfo('Employee deleted successfully');
    return true;
  } else {
    logError('Failed to delete employee record: ' . $response['error']);
    throw new \Exception('Failed to delete employee record');
  }
