  $params = [
    ':name' => $name,
    ':email' => $email,
    ':password' => $password,
    ':role' => $role,
    ':status' => $status,
  ];

  // Make API call to create employee record
  $response = makeApiCall(API_URL, 'POST', json_encode($params));
  if ($response['success']) {
    logInfo('Employee created successfully');
    return true;
  } else {
    logError('Failed to create employee record: ' . $response['error']);
    throw new \Exception('Failed to create employee record');
  }
}

// Define function for approving employee changes
