package OAuthKeyManager;

use crate::{cache::RedisCache, config::Config};
use async_std::task;
use futures::future::join_all;
use std::collections::HashMap;
use tokio::sync::Mutex;

// External Services
const AWS_S3: &str = "AWS S3";
const AZURE_BLOB_STORAGE: &str = "Azure Blob Storage";
const GOOGLE_CLOUD_STORAGE: &str = "Google Cloud Storage";

// Dependency Crates
const HTTP_CLIENT: &str = "http-client";
const FILE_IO: &str = "file-io";
const BASE64_ENCODING: &str = "base64-encoding";
const CACHING: &str = "caching";

// Error Types
type Result<T> = std::result::Result<T, OAuthKeyManagerError>;

#[derive(Debug)]
enum OAuthKeyManagerError {
    ExternalServiceError(String),
    DependencyLoadingError(String),
    EncryptionError(String),
    KeyValidationError(String),
}

// Structs and Enums
struct KeyInfo {
    key_id: String,
    key_type: String,
    algorithm: String,
    key: String,
    expires_at: u64,
}

enum KeySource {
    Internal(String),
    External(String),
}

// Service Functions
struct OAuthKeyManager {
    config: Config,
    cache: Mutex<RedisCache>,
    key_info: HashMap<String, KeyInfo>,
}

impl OAuthKeyManager {
    fn new() -> Self {
        Self {
            config: Config::new(),
            cache: Mutex::new(RedisCache::new()),
            key_info: HashMap::new(),
        }
    }

    async fn load_dependencies(&mut self) -> Result<()> {
        let mut dependencies = vec![];

        if self.config.load_internal_keys {
            dependencies.push(HTTP_CLIENT);
            dependencies.push(FILE_IO);
        } else {
            dependencies.push(AWS_S3);
            dependencies.push(AZURE_BLOB_STORAGE);
            dependencies.push(GOOGLE_CLOUD_STORAGE);
        }

        if self.config.load_caching {
            dependencies.push(CACHING);
        }

        for dependency in dependencies {
            let result = crate::dependencies::load(dependency).await;

            match result {
                Ok(_) => (),
                Err(error) => return Err(OAuthKeyManagerError::DependencyLoadingError(format!(
                    "Failed to load dependency: {}",
                    error
                ))),
            }
        }

        Ok(())
    }

    async fn fetch_keys(&mut self, key_source: KeySource) -> Result<Vec<KeyInfo>> {
        match key_source {
            KeySource::Internal => {
                let mut keys = vec![];

                if self.config.load_internal_keys {
                    for key in crate::http_client::get_keys(
                        &self.config.internal_key_server,
                        &self.config.internal_key_path,
                    ) {
                        keys.push(KeyInfo {
                            key_id: key.key_id.clone(),
                            key_type: key.key_type.clone(),
                            algorithm: key.algorithm.clone(),
                            key: key.key,
                            expires_at: 0,
                        });
                    }
                } else {
                    return Err(OAuthKeyManagerError::ExternalServiceError(format!(
                        "Unable to fetch keys from internal key server"
                    )));
                }

                Ok(keys)
            }
            KeySource::External => {
                let mut keys = vec![];

                if self.config.load_external_keys {
                    for key in crate::aws_s3::get_keys(&self.config.external_key_server) {
                        keys.push(KeyInfo {
                            key_id: key.key_id.clone(),
                            key_type: key.key_type.clone(),
                            algorithm: key.algorithm.clone(),
                            key: key.key,
                            expires_at: 0,
                        });
                    }
                } else {
                    return Err(OAuthKeyManagerError::ExternalServiceError(format!(
                        "Unable to fetch keys from external storage"
                    )));
                }

                Ok(keys)
            }
        }
    }

    async fn validate_key(&mut self, key: &String) -> Result<()> {
        let key_info = crate::base64_encoding::decode(&key)?;

        if !crate::crypto::verify(
            &key_info.algorithm,
            &key_info.key,
            &self.config.client_id,
            &self.config.shared_secret,
        ) {
            return Err(OAuthKeyManagerError::KeyValidationError(format!(
                "Invalid key: {}",
                key_info.algorithm
            )));
        }

        Ok(())
    }

    async fn get_key(&mut self, key_id: &String) -> Result<String> {
        let mut cache = self.cache.lock().await;

        if cache.contains_key(key_id) {
            return Ok(cache.get(key_id).unwrap().clone());
        }

        for key in self.fetch_keys(KeySource::Internal).await? {
            if &key.key_id == key_id {
                cache.insert(key_id.clone(), key.clone());
                return Ok(key.key);
            }
        }

        for key in self.fetch_keys(KeySource::External).await? {
            if &key.key_id == key_id {
                cache.insert(key_id.clone(), key.clone());
                return Ok(key.key);
            }
        }

        Err(OAuthKeyManagerError::KeyNotFound(format!(
            "Failed to find key: {}",
            key_id
        )))
    }
}
```

