```rust
use std::fs;
use std::io::{Error, ErrorKind};

struct OctreeConfig {
    pub node_size: u32,
    pub max_children_nodes: u8,
}

impl OctreeConfig {
    fn new() -> Self {
        Self {
            node_size: 0,
            max_children_nodes: 0,
        }
    }
}

fn parse_config(filepath: &str) -> Result<OctreeConfig, Error> {
    let contents = fs::read_to_string(filepath).unwrap();
    let mut config = OctreeConfig::new();
    for line in contents.lines() {
        if line.starts_with("node_size") {
            let tokens: Vec<&str> = line.split('=').collect();
            config.node_size = tokens[1].parse().unwrap();
        } else if line.starts_with("max_children_nodes") {
            let tokens: Vec<&str> = line.split('=').collect();
            config.max_children_nodes = tokens[1].parse().unwrap();
        }
    }
    Ok(config)
}
