// Define the function signature
void fetchAndProcessResourceBundle(const char* resourceUrl, const char* fileFormat, int fieldsToReduce[], int aggregationMethod);

// Define the function implementation
void fetchAndProcessResourceBundle(const char* resourceUrl, const char* fileFormat, int fieldsToReduce[], int aggregationMethod) {
    // Initialize curl and openssl
    CURL *curl;
    CURLcode res;
    SSL_CTX *ssl_ctx = NULL;

    // Configure curl to use https protocol
    curl_global_init(CURL_GLOBAL_ALL);
    curl = curl_easy_init();
    if(!curl) {
        printf("Failed to initialize curl\n");
        return;
    }

    // Set the URL, file format, and fields to reduce
    curl_easy_setopt(curl, CURLOPT_URL, resourceUrl);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, "Accept: application/json");
    curl_easy_setopt(curl, CURLOPT_SSL_CTX, ssl_ctx);
    curl_easy_setopt(curl, CURLOPT_USERAGENT, "libcurl-agent/1.0");

    // Set the aggregation method
    if(aggregationMethod == SUM) {
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, "sum=true");
    } else if(aggregationMethod == AVERAGE) {
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, "average=true");
    } else if(aggregationMethod == MEDIAN) {
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, "median=true");
    }

    // Set the fields to reduce
    char* fieldsToReduceStr = "";
    for(int i = 0; i < fieldsToReduce.length(); i++) {
        fieldsToReduceStr += fieldsToReduce[i];
        if(i != fieldsToReduce.length() - 1) {
            fieldsToReduceStr += ",";
        }
    }
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, "fieldsToReduce=" + fieldsToReduceStr);

    // Set the file format
    if(fileFormat == JSON) {
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, "json=true");
    } else if(fileFormat == XML) {
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, "xml=true");
    } else if(fileFormat == YAML) {
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, "yaml=true");
    }

    // Set the output file path
    FILE* fp;
    char outputFilePath[1024];
    snprintf(outputFilePath, sizeof(outputFilePath), "/tmp/resource-bundle-%d.json", getpid());
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, NULL);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, fp);

    // Perform the request and handle errors
    res = curl_easy_perform(curl);
    if(res != CURLE_OK) {
        printf("Failed to perform request: %s\n", curl_easy_strerror(res));
        return;
    }

    // Close the connection and clean up
    curl_easy_cleanup(curl);
    curl_global_cleanup();
}
