    if (ret != 1) {
        return -1;
    }

    // Reset the nonce and sequence number for each new session.
    memset(key->nonce, 0, 16);
    key->sequence_number = 0;

    return 0;
}

int encrypt(struct session_info *session, const uint8_t *plaintext, uint8_t *ciphertext) {
    // Check if the session is valid.
    if (!session->valid) {
        return -1;
    }

    // Initialize the AES-256-CBC context with the derived key and nonce.
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (EVP_EncryptInit(ctx, EVP_aes_256_cbc(), session->key.key, session->nonce) != 1) {
        return -1;
    }

    // Set the encryption mode to CFB or GCM.
    if (EVP_CIPHER_CTX_set_cipher(ctx, EVP_aes_256_cbc()) != 1) {
