    }

    // Increment the sequence number for each new block.
    session->sequence_number++;

    // Free the context and return.
    EVP_CIPHER_CTX_free(ctx);

    return 0;
}

int decrypt(struct session_info *session, const uint8_t *ciphertext, uint8_t *plaintext) {
