```csharp
using System;
using System.Data.SqlClient;
using System.Security.Cryptography;
using System.Threading;
using System.Threading.Tasks;

namespace HashLibrary
{
    public class Hasher
    {
        private readonly string _connectionString;
        private readonly SqlConnection _connection;
        private readonly object _lock = new object();

        public Hasher(string connectionString)
        {
            _connectionString = connectionString;
            _connection = new SqlConnection(_connectionString);
        }

        public async Task<bool> AddHashAsync(string input, string hashAlgorithm, CancellationToken cancellationToken = default)
        {
            using (var transaction = _connection.BeginTransaction())
            {
                try
                {
                    // Hash the input and store it in the database
                    byte[] hash = await GetHashAsync(input, hashAlgorithm, cancellationToken);
                    var command = new SqlCommand("INSERT INTO [Hashes] (Input, Hash) VALUES (@input, @hash)", transaction);
                    command.Parameters.AddWithValue("@input", input);
                    command.Parameters.AddWithValue("@hash", hash);
                    await command.ExecuteNonQueryAsync();

                    // Commit the transaction and return true
                    transaction.Commit();
                    return true;
                }
                catch (Exception ex)
                {
                    // Rollback the transaction and return false if an error occurs
                    transaction.Rollback();
                    Console.WriteLine(ex);
                    return false;
                }
            }
        }

        public async Task<bool> CheckHashAsync(string input, string hash, CancellationToken cancellationToken = default)
        {
            using (var transaction = _connection.BeginTransaction())
            {
                try
                {
                    // Get the stored hash for the input from the database
                    var command = new SqlCommand("SELECT [Hash] FROM [Hashes] WHERE [Input] = @input", transaction);
                    command.Parameters.AddWithValue("@input", input);
                    byte[] storedHash = await command.ExecuteScalarAsync<byte[]>();

                    // Compare the stored hash with the expected hash
                    bool match = Hasher.CompareHash(storedHash, hash);
                    if (match)
                    {
                        // Commit the transaction and return true
                        transaction.Commit();
                        return true;
                    }
                    else
                    {
                        // Rollback the transaction and return false if there is a mismatch
                        transaction.Rollback();
                        return false;
                    }
                }
                catch (Exception ex)
                {
                    // Rollback the transaction and return false if an error occurs
                    transaction.Rollback();
                    Console.WriteLine(ex);
                    return false;
                }
            }
        }

        private static async Task<byte[]> GetHashAsync(string input, string hashAlgorithm, CancellationToken cancellationToken = default)
        {
            using (var algorithm = Hasher.GetHashAlgorithm(hashAlgorithm))
            {
                byte[] hash = await algorithm.ComputeHashAsync(Encoding.UTF8.GetBytes(input), cancellationToken);
                return hash;
            }
        }

        private static HashAlgorithm GetHashAlgorithm(string name)
        {
            switch (name)
            {
                case "MD5":
                    return MD5.Create();
                case "SHA-256":
                    return SHA256.Create();
                default:
                    throw new ArgumentException("Invalid hash algorithm name", nameof(name));
            }
        }

        private static bool CompareHash(byte[] storedHash, string expectedHash)
        {
            // Convert the expected hash to a byte array
            byte[] expectedBytes = Encoding.UTF8.GetBytes(expectedHash);

            // Compare the stored hash with the expected hash
            return storedHash.SequenceEqual(expectedBytes);
        }
    }
}
