```csharp
using System;
using System.Text;
using Newtonsoft.Json;

namespace HashLibrary
{
    public class TokenValidator
    {
        private static readonly JsonSerializerSettings _settings = new JsonSerializerSettings
        {
            MissingMemberHandling = MissingMemberHandling.Error,
            NullValueHandling = NullValueHandling.Include,
            DefaultValueHandling = DefaultValueHandling.Ignore
        };

        public static bool ValidateToken(string jsonString)
        {
            try
            {
                // Deserialize the JSON string to a TokenResponse object
                var tokenResponse = JsonConvert.DeserializeObject<TokenResponse>(jsonString, _settings);

                // Check that all mandatory fields are present in the response
                if (tokenResponse.access_token == null || tokenResponse.expires_in < 0 || tokenResponse.token_type != "Bearer")
                {
                    return false;
                }

                // Optionally check that a refresh_token is present if one was requested
                if (tokenResponse.refresh_token == null && tokenResponse.requested)
                {
                    return false;
                }

                // Return true if all conditions are met
                return true;
            }
            catch (JsonException ex)
            {
                Console.WriteLine(ex);
                return false;
            }
        }

        private class TokenResponse
        {
            [JsonProperty("access_token")]
            public string access_token { get; set; }

            [JsonProperty("expires_in")]
            public int expires_in { get; set; }

            [JsonProperty("token_type")]
            public string token_type { get; set; }

            [JsonProperty("refresh_token", DefaultValueHandling = DefaultValueHandling.Ignore)]
            public string refresh_token { get; set; }

            [JsonProperty("requested", DefaultValueHandling = DefaultValueHandling.Include)]
            public bool requested { get; set; }
        }
    }
}
