using Amazon.S3;
using Amazon.S3.Model;

namespace SecureDataProcessor
{
    public class UtilityClass
    {
        private const string SerializationFrameworkKey = "SerializationFramework";
        private const string EncryptionProviderKey = "EncryptionProvider";
        private const string S3BucketNameKey = "S3BucketName";
        private const string S3RegionKey = "S3Region";
        private const string S3AccessKeyIdKey = "S3AccessKeyId";
        private const string S3SecretAccessKeyKey = "S3SecretAccessKey";
        private const string EncryptionAlgorithmAESCBC = "AES-CBC";
        private const string EncryptionAlgorithmRSAOAEP = "RSA-OAEP";

        private readonly IConfiguration _configuration;
        private readonly AmazonS3Client _s3Client;
        private readonly Dictionary<string, SerializationFramework> _serializationFrameworks = new Dictionary<string, SerializationFramework>();
        private readonly Dictionary<string, EncryptionProvider> _encryptionProviders = new Dictionary<string, EncryptionProvider>();
        private readonly object _lockObject = new object();

        public UtilityClass(IConfiguration configuration)
        {
            _configuration = configuration;
            InitializeSerializationFrameworks();
            InitializeEncryptionProviders();
            InitializeS3Client();
        }

        private void InitializeSerializationFrameworks()
        {
            _serializationFrameworks.Add("Json", new JsonSerializationFramework());
            _serializationFrameworks.Add("MessagePack", new MessagePackSerializationFramework());
        }

        private void InitializeEncryptionProviders()
        {
            _encryptionProviders.Add(EncryptionAlgorithmAESCBC, new AESEncryptionProvider());
            _encryptionProviders.Add(EncryptionAlgorithmRSAOAEP, new RSAOAEPEncryptionProvider());
        }

        private void InitializeS3Client()
        {
            var s3AccessKeyId = _configuration[S3AccessKeyIdKey];
            var s3SecretAccessKey = _configuration[S3SecretAccessKeyKey];
            var s3Region = _configuration[S3RegionKey];
            var s3BucketName = _configuration[S3BucketNameKey];
            if (s3AccessKeyId != null && s3SecretAccessKey != null && s3Region != null && s3BucketName != null)
            {
                _s3Client = new AmazonS3Client(s3AccessKeyId, s3SecretAccessKey, RegionEndpoint.GetBySystemName(s3Region));
            }
        }

        public void ProcessData(string data, string serializationFramework, string encryptionProvider)
        {
            var serializationFramework = GetSerializationFramework(serializationFramework);
            var encryptionProvider = GetEncryptionProvider(encryptionProvider);

            // Encrypt and serialize the data
            var encryptedData = encryptionProvider.Encrypt(data);
            var serializedData = serializationFramework.Serialize(encryptedData);

            // Upload the data to S3
            if (_s3Client != null)
            {
                var s3BucketName = _configuration[S3BucketNameKey];
                var s3Object = new PutObjectRequest()
                {
                    BucketName = s3BucketName,
                    Key = "data.json",
                    ContentBody = serializedData
                };
                _s3Client.PutObject(s3Object);
            }
        }

        private SerializationFramework GetSerializationFramework(string name)
        {
            if (!_serializationFrameworks.ContainsKey(name))
            {
                throw new ArgumentException($"Invalid serialization framework: {name}");
            }
            return _serializationFrameworks[name];
        }

        private EncryptionProvider GetEncryptionProvider(string name)
        {
            if (!_encryptionProviders.ContainsKey(name))
            {
                throw new ArgumentException($"Invalid encryption provider: {name}");
            }
            return _encryptionProviders[name];
        }
    }

    public interface SerializationFramework
    {
        string Serialize(object data);
    }

    public class JsonSerializationFramework : SerializationFramework
    {
        public string Serialize(object data)
        {
            return JsonConvert.SerializeObject(data);
        }
    }

    public class MessagePackSerializationFramework : SerializationFramework
    {
        public string Serialize(object data)
        {
            var serializedData = MessagePackSerializer.Serialize(data);
            return Convert.ToBase64String(serializedData);
        }
    }

    public interface EncryptionProvider
    {
        byte[] Encrypt(string data);
    }

    public class AESEncryptionProvider : EncryptionProvider
    {
        private readonly byte[] _key;
        private readonly byte[] _iv;

        public AESEncryptionProvider()
        {
            var key = new byte[32];
            var iv = new byte[16];
            var random = new Random();
            random.NextBytes(key);
            random.NextBytes(iv);
            _key = key;
            _iv = iv;
        }

        public byte[] Encrypt(string data)
        {
            using (var aes = Aes.Create())
            {
                var encryptedData = new List<byte>();
                aes.Key = _key;
                aes.IV = _iv;
                aes.Mode = CipherMode.CBC;
                using (var encryptor = aes.CreateEncryptor())
                {
                    var dataBytes = Encoding.UTF8.GetBytes(data);
                    var encryptedDataBytes = encryptor.TransformFinalBlock(dataBytes, 0, dataBytes.Length);
                    encryptedData.AddRange(encryptedDataBytes);
                }
                return encryptedData.ToArray();
            }
        }
    }

    public class RSAOAEPEncryptionProvider : EncryptionProvider
    {
        private readonly byte[] _modulus;
        private readonly byte[] _exponent;

        public RSAOAEPEncryptionProvider()
        {
            var key = new byte[32];
            var random = new Random();
            random.NextBytes(key);
            _modulus = key;

            var exponent = new byte[4];
            random.NextBytes(exponent);
            _exponent = exponent;
        }

        public byte[] Encrypt(string data)
        {
            using (var rsa = RSACryptoServiceProvider.Create())
            {
                var encryptedData = new List<byte>();
                rsa.KeySize = 2048;
                rsa.ImportParameters(new RSAParameters()
                {
                    Modulus = _modulus,
                    Exponent = _exponent
                });
                using (var encryptor = rsa.CreateEncryptor())
                {
                    var dataBytes = Encoding.UTF8.GetBytes(data);
                    var encryptedDataBytes = encryptor.TransformFinalBlock(dataBytes, 0, dataBytes.Length);
                    encryptedData.AddRange(encryptedDataBytes);
                }
                return encryptedData.ToArray();
            }
        }
    }
}
