```c++
#include <iostream>
#include <string>
#include <vector>
#include <queue>
#include <map>
#include <set>
#include <unordered_map>
#include <algorithm>
#include <chrono>
#include <thread>
#include <mutex>
#include <condition_variable>

using namespace std;

class DataProcessor {
private:
    // Variables for data ingestion and processing
    queue<string> messageQueue;
    map<string, vector<string>> schemaCache;
    unordered_map<string, int> versionMap;
    mutex lock;
    condition_variable cv;
    bool running = true;

    // Function for handling data ingestion and processing
    void processMessage(const string& message) {
        unique_lock<mutex> lk(lock);
        auto start = chrono::high_resolution_clock::now();

        // Check if the message is a schema update
        if (message.starts_with("SCHEMA:")) {
            string schemaUpdate = message.substr(7);
            vector<string> schemaFields;
            split(schemaUpdate, ',', schemaFields);

            // Update the schema cache
            for (const auto& field : schemaFields) {
                int version = stoi(field.substr(0, 2));
                string fieldName = field.substr(3);
                schemaCache[fieldName] = vector<string>({"", ""});
                versionMap[fieldName] = version;
            }
        } else {
            // Process the message using the schema cache
            auto end = chrono::high_resolution_clock::now();
            long duration = chrono::duration_cast<chrono::milliseconds>(end - start).count();
            cout << "Processed message in: " << duration << " ms" << endl;
        }
    }

    // Function for handling schema updates and data processing
    void run() {
        while (running) {
            unique_lock<mutex> lk(lock);
            cv.wait(lk, [this] { return !messageQueue.empty(); });
            while (!messageQueue.empty()) {
                processMessage(messageQueue.front());
                messageQueue.pop();
            }
        }
    }

public:
    DataProcessor() : messageQueue(), schemaCache(), versionMap(), lock(), cv(), running() {}

    // Function for adding messages to the queue
    void addMessage(const string& message) {
        unique_lock<mutex> lk(lock);
        messageQueue.push(message);
        cv.notify_all();
    }

    // Function for stopping the data processor
    void stop() {
        running = false;
    }
};
```
This code implements a C++ class called `DataProcessor` that is responsible for handling data ingestion and processing. The class has several private variables, such as `messageQueue`, `schemaCache`, and `versionMap`, which are used to store the incoming messages and maintain state across multiple threads. The `processMessage()` function is where most of the logic for handling messages resides. It checks if the message is a schema update, and if so, it updates the schema cache and version map accordingly. If not, it processes the message using the schema cache and prints out some information about how long it took to process the message. The `run()` function is where most of the data processing takes place. It loops indefinitely, waiting for new messages to arrive on the queue and then processing them using the `processMessage()` function.

The `addMessage()` function is used to add new messages to the queue for processing. The `stop()` function is used to stop the data processor from running.']

