#include <iostream>
#include <string>
#include <vector>
#include <cstdlib>
#include <openssl/des.h>
#include <openssl/modes.h>
#include <openssl/aes.h>
#include <openssl/evp.h>
#include <openssl/err.h>

using namespace std;

const int DEFAULT_BLOCK_SIZE = 1024; // in bytes

// Encryption and decryption functions using OpenSSL
int encrypt(string data, string key) {
    // Set up the encryption parameters
    const EVP_CIPHER *cipher;
    const EVP_MD *digest;
    int ciphertext_len, digest_len;
    unsigned char *ciphertext, *digest;

    // Select the appropriate cipher mode based on workload characteristics
    if (data.size() < DEFAULT_BLOCK_SIZE) {
        // Use DES in ECB mode for small messages to minimize latency and improve throughput
        cipher = EVP_des_ecb();
    } else {
        // Use AES in CTR mode for large messages to balance security with performance
        cipher = EVP_aes_128_ctr();
    }

    // Set up the encryption parameters
    EVP_CIPHER_CTX *ctx;
    ctx = EVP_CIPHER_CTX_new();
    int iv_len = EVP_CIPHER_iv_length(cipher);
    unsigned char iv[iv_len];
    memset(iv, 0, iv_len);
    if (EVP_EncryptInit_ex(ctx, cipher, NULL, key.c_str(), iv) != 1) {
        cout << "Error initializing encryption" << endl;
        return -1;
    }

    // Encrypt the data
    int plaintext_len = data.size();
    unsigned char *plaintext = (unsigned char *)data.c_str();
    ciphertext_len = plaintext_len + EVP_CIPHER_block_size(cipher);
    ciphertext = new unsigned char[ciphertext_len];
    int final_len;
    if (EVP_EncryptUpdate(ctx, ciphertext, &final_len, plaintext, plaintext_len) != 1) {
        cout << "Error encrypting data" << endl;
        return -1;
    }

    // Finalize the encryption
    if (EVP_EncryptFinal_ex(ctx, ciphertext + final_len, &ciphertext_len) != 1) {
        cout << "Error finalizing encryption" << endl;
        return -1;
    }

    // Clean up
    EVP_CIPHER_CTX_free(ctx);

    // Return the encrypted data
    return ciphertext_len;
}

int decrypt(string data, string key) {
    // Set up the encryption parameters
    const EVP_CIPHER *cipher;
    const EVP_MD *digest;
    int plaintext_len, digest_len;
    unsigned char *plaintext, *digest;

    // Select the appropriate cipher mode based on workload characteristics
    if (data.size() < DEFAULT_BLOCK_SIZE) {
        // Use DES in ECB mode for small messages to minimize latency and improve throughput
        cipher = EVP_des_ecb();
    } else {
        // Use AES in CTR mode for large messages to balance security with performance
        cipher = EVP_aes_128_ctr();
    }

    // Set up the encryption parameters
    EVP_CIPHER_CTX *ctx;
    ctx = EVP_CIPHER_CTX_new();
    int iv_len = EVP_CIPHER_iv_length(cipher);
    unsigned char iv[iv_len];
    memset(iv, 0, iv_len);
    if (EVP_DecryptInit_ex(ctx, cipher, NULL, key.c_str(), iv) != 1) {
        cout << "Error initializing decryption" << endl;
        return -1;
    }

    // Decrypt the data
    int ciphertext_len = data.size();
    unsigned char *ciphertext = (unsigned char *)data.c_str();
    plaintext_len = ciphertext_len + EVP_CIPHER_block_size(cipher);
    plaintext = new unsigned char[plaintext_len];
    int final_len;
    if (EVP_DecryptUpdate(ctx, plaintext, &final_len, ciphertext, ciphertext_len) != 1) {
        cout << "Error decrypting data" << endl;
        return -1;
    }

    // Finalize the decryption
    if (EVP_DecryptFinal_ex(ctx, plaintext + final_len, &plaintext_len) != 1) {
        cout << "Error finalizing decryption" << endl;
        return -1;
    }

    // Clean up
    EVP_CIPHER_CTX_free(ctx);

    // Return the decrypted data
    return plaintext_len;
}
