      dataStore_.insert({deviceId, make_shared<IoTDevice>(device)});
    } else {
      cout << "Invalid device ID: " << deviceId << endl;
    }
  }

 private:
  map<string, shared_ptr<DataStore>> dataStore_;

  double calculateAverage(const string& deviceId) {
    IoTDevice device = *dataStore_.at(deviceId);
    int numDataPoints = device.getNumDataPoints();
    double sum = 0;
    for (int i = 0; i < numDataPoints; ++i) {
      sum += device.getDataPoint(i);
    }
    return sum / numDataPoints;
  }
};
```
