#include <iostream>
#include <vector>
#include <unordered_map>
#include <string>
#include <chrono>
#include <memory>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <fstream>
#include <iomanip>

using namespace std;

// Define a struct to store data for each device
struct DeviceData {
    string deviceId;
    double temperature;
    double humidity;
    double pressure;
};

// Define a class to handle the middleware layer
class Middleware {
public:
    // Constructor to initialize the middleware layer
    Middleware() {
        // Initialize the dependency manager with the available services
        dependencies = new vector<string>({"cloud1", "cloud2", "iot_gateway", "analytics_tool1"});
        // Initialize the priority queue for data processing tasks
        taskQueue = new priority_queue<Task, TaskComparator>;
    }

    // Destructor to clean up resources
    ~Middleware() {
        delete dependencies;
        delete taskQueue;
    }

    // Method to process incoming data streams asynchronously and in parallel
    void processData(vector<DeviceData> data) {
        // Iterate over the data from each device
        for (auto &deviceData : data) {
            // Check if the device is registered with the middleware layer
            if (!isRegistered(deviceData.deviceId)) {
                registerDevice(deviceData.deviceId);
            }

            // Add the data to the task queue for processing
            addTask(deviceData);
        }
    }

    // Method to handle incoming data from a device
    void handleIncomingData(DeviceData &data) {
        // Check if the device is registered with the middleware layer
        if (!isRegistered(data.deviceId)) {
            registerDevice(data.deviceId);
        }

        // Add the data to the task queue for processing
        addTask(data);
    }

    // Method to register a device with the middleware layer
    void registerDevice(string deviceId) {
        // Check if the device is already registered
        if (!isRegistered(deviceId)) {
            // Register the device with the middleware layer
            devices.push_back(deviceId);
        }
    }

    // Method to check if a device is registered with the middleware layer
    bool isRegistered(string deviceId) {
        return std::find(devices.begin(), devices.end(), deviceId) != devices.end();
    }

    // Method to add a task for processing data from a device
    void addTask(DeviceData &data) {
        // Create a new task object
        Task task = {data.deviceId, data};

        // Add the task to the priority queue
        taskQueue->push(task);
    }

    // Method to retrieve the next available task from the priority queue
    Task getNextTask() {
        // Lock the mutex to prevent concurrent access to the queue
        std::lock_guard<std::mutex> lock(mutex);

        // Check if there are any tasks available in the queue
        if (!taskQueue->empty()) {
            // Retrieve the next available task from the priority queue
            Task task = *taskQueue->top();

            // Remove the task from the queue
            taskQueue->pop();

            return task;
        }
    }

private:
    // Vector to store the registered devices
    vector<string> devices;

    // Priority queue for data processing tasks
    priority_queue<Task, TaskComparator> *taskQueue;

    // Mutex to prevent concurrent access to the priority queue
    std::mutex mutex;

    // Condition variable to signal when a new task is available
    std::condition_variable cv;
};
```
Note that this is just one possible implementation of the middleware layer, and there may be variations depending on the specific requirements of your application. Additionally, this code uses C++14 features such as `std::chrono`, `std::thread`, `std::mutex`, `std::condition_variable`, etc., which are not available in earlier versions of the language.']

