// Define constants for error handling and logging
#define ERROR_INVALID_INPUT -1
#define LOG_SUCCESS 0
#define LOG_FAILURE 1
#define LOG_LEVEL_MIN 2 // Minimum log level (only critical errors)
#define LOG_LEVEL_MAX 5 // Maximum log level (all messages)

// Define a fixed-size pool of memory for NFAPI_CRC_INDICATION_PDU_T structures
#define POOL_SIZE 1024 * 1024 // Size in bytes
static char pool[POOL_SIZE]; // Array of structures in the pool
static size_t pool_size = 0; // Current number of allocated structures
static size_t pool_offset = 0; // Current offset for structure allocation

// Define a function to create and log NFAPI_CRC_INDICATION_PDU_T structures
int createAndLogNFapiCrcIndications(int N, RX_UE_INFORMATION_TAG *rx_ue_information) {
    // Check input parameters for validity
    if (N < 0 || rx_ue_information == NULL) {
        return ERROR_INVALID_INPUT;
    }

    // Initialize variables for logging and error handling
    int log_level = LOG_LEVEL_MIN;
    size_t num_created = 0;
    int err = 0;

    // Allocate memory for the structures in the pool
    for (int i = 0; i < N && err == 0; ++i) {
        if (pool_offset >= POOL_SIZE || pool_size + sizeof(NFAPI_CRC_INDICATION_PDU_T) > POOL_SIZE) {
            log_level = LOG_LEVEL_MAX; // Print all messages for error handling
            err = ERROR_INVALID_INPUT;
        } else {
            NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T *)(pool + pool_offset);
            memset(pdu, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));

            // Set random values for CRCFLAG and RNTI
            pdu->crcFlag = rand() % 2; // Controlled randomization mechanism for CRCFLAG
            pdu->rnti = rand() % INT_MAX; // Randomly set RNTI

            // Set valid values for RX_UE_INFORMATION_TAG and CRC_INDICATION_REL8_TAG
            pdu->rx_ue_information_tag.tl.tag = 0x1;
            pdu->rx_ue_information_tag.length = sizeof(RX_UE_INFORMATION_TAG);
            memcpy(&pdu->rx_ue_information, rx_ue_information, sizeof(RX_UE_INFORMATION_TAG));

            pdu->crcIndicationRel8.tl.tag = 0x2;
            pdu->crcIndicationRel8.length = sizeof(CRC_INDICATION_REL8_TAG);
            pdu->crcIndicationRel8.crcFlag = pdu->crcFlag; // CRCFLAG is set based on random values

            pool_offset += sizeof(NFAPI_CRC_INDICATION_PDU_T);
            ++num_created;
        }
    }

    // Log the result of the operation
    if (err == 0) {
        printf("createAndLogNFapiCrcIndications: %zu structures created successfully\n", num_created);
        log_level = LOG_LEVEL_MAX;
    } else {
        printf("createAndLogNFapiCrcIndications: %s\n", err == ERROR_INVALID_INPUT ? "Invalid input" : "Memory allocation failed");
    }
    return log_level;
}
