// TCPConnectionManager.h
#ifndef TCP_CONNECTION_MANAGER_H
#define TCP_CONNECTION_MANAGER_H

#include <vector>
#include <unordered_map>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <chrono>
#include <functional>

// Forward declaration for the TCPConnection class
class TCPConnection;

// Define the connection handle type
typedef std::shared_ptr<TCPConnection> ConnectionHandle;

// Define the callback function signature for connecting to a remote host
using ConnectCallback = std::function<void(const ConnectionHandle&)>;

// Define the callback function signature for disconnecting from a remote host
using DisconnectCallback = std::function<void(const ConnectionHandle&)>;

// Define the callback function signature for receiving data from a remote host
using ReceiveCallback = std::function<void(const ConnectionHandle&, const void*, size_t)>;

class TCPConnectionManager {
public:
    // Constructor and destructor
    TCPConnectionManager();
    ~TCPConnectionManager();

    // Methods for connecting to a remote host
    void connect(const std::string& hostname, int port, const ConnectCallback& callback);
    bool isConnected(const ConnectionHandle& handle) const;
    void disconnect(const ConnectionHandle& handle, const DisconnectCallback& callback);

    // Methods for sending data to a remote host
    size_t send(const ConnectionHandle& handle, const void* buffer, size_t size);

    // Methods for receiving data from a remote host
    size_t receive(const ConnectionHandle& handle, void* buffer, size_t size);

    // Methods for configuring the connection manager
    void setReceiveCallback(const ReceiveCallback& callback);
    const ReceiveCallback& getReceiveCallback() const;

private:
    // Private methods for managing connections
    void manageConnections();
    void addConnection(const ConnectionHandle& handle);
    bool removeConnection(const ConnectionHandle& handle);
    void updateConnection(const ConnectionHandle& handle, std::chrono::steady_clock::time_point& expiryTime);
    size_t sendToConnections(const void* buffer, size_t size);
    size_t receiveFromConnections(void* buffer, size_t size);

    // Private data members for the connection manager
    std::unordered_map<ConnectionHandle, std::chrono::steady_clock::time_point> connections_;
    std::mutex connectionsMutex_;
    std::condition_variable connectionsConditionVariable_;
    ReceiveCallback receiveCallback_;

    // Private data members for the connection threads
    bool stopThreads_;
    std::vector<std::thread> threads_;
};

#endif // TCP_CONNECTION_MANAGER_H

// TCPConnectionManager.cpp
#include "TCPConnectionManager.h"

#include <iostream>
#include <fstream>
#include <string>

// Define the TCP connection class
class TCPConnection {
public:
    // Constructor and destructor
    TCPConnection(const std::string& hostname, int port);
    ~TCPConnection();

    // Methods for managing the connection
    void connect();
    bool isConnected() const;
    void disconnect();

    // Methods for sending and receiving data on the connection
    size_t send(const void* buffer, size_t size);
    size_t receive(void* buffer, size_t size);

private:
    // Private data members for the TCP connection
    std::string hostname_;
    int port_;
    int socketFd_;
};

// Implementation of the TCPConnectionManager class methods
TCPConnectionManager::TCPConnectionManager() : stopThreads_(false) {
    // Start the connection threads
    for (int i = 0; i < 4; ++i) {
        threads_.push_back(std::thread(&TCPConnectionManager::manageConnections, this));
    }
}

TCPConnectionManager::~TCPConnectionManager() {
    // Stop the connection threads
    stopThreads_ = true;
    for (auto& thread : threads_) {
        if (thread.joinable()) {
            thread.join();
        }
    }
}

void TCPConnectionManager::connect(const std::string& hostname, int port, const ConnectCallback& callback) {
    // Create a new connection handle
    ConnectionHandle handle = std::make_shared<TCPConnection>(hostname, port);

    // Add the connection to the list of managed connections
    addConnection(handle);

    // Call the connect callback if provided
    if (callback) {
        callback(handle);
    }
}

bool TCPConnectionManager::isConnected(const ConnectionHandle& handle) const {
    std::lock_guard<std::mutex> lock(connectionsMutex_);
    return connections_.find(handle) != connections_.end();
}

void TCPConnectionManager::disconnect(const ConnectionHandle& handle, const DisconnectCallback& callback) {
    // Remove the connection from the list of managed connections
    removeConnection(handle);

    // Call the disconnect callback if provided
    if (callback) {
        callback(handle);
    }
}

size_t TCPConnectionManager::send(const ConnectionHandle& handle, const void* buffer, size_t size) {
    std::lock_guard<std::mutex> lock(connectionsMutex_);
    if (connections_.find(handle) == connections_.end()) {
        return 0;
    }
    return handle->send(buffer, size);
}

size_t TCPConnectionManager::receive(const ConnectionHandle& handle, void* buffer, size_t size) {
    std::lock_guard<std::mutex> lock(connectionsMutex_);
    if (connections_.find(handle) == connections_.end()) {
        return 0;
    }
    return handle->receive(buffer, size);
}

void TCPConnectionManager::setReceiveCallback(const ReceiveCallback& callback) {
    receiveCallback_ = callback;
}

const TCPConnectionManager::ReceiveCallback& TCPConnectionManager::getReceiveCallback() const {
    return receiveCallback_;
}

// Implementation of the TCP connection class methods
TCPConnection::TCPConnection(const std::string& hostname, int port) : hostname_(hostname), port_(port) {
    // Create a new socket and connect to the server
    socketFd_ = ::socket(AF_INET, SOCK_STREAM, 0);
    if (socketFd_ == -1) {
        std::cerr << "Failed to create socket" << std::endl;
    } else {
        struct sockaddr_in serverAddr;
        memset(&serverAddr, 0, sizeof(serverAddr));
        serverAddr.sin_family = AF_INET;
        serverAddr.sin_port = htons(port);
        inet_pton(AF_INET, hostname_.c_str(), &serverAddr.sin_addr);
        if (connect(socketFd_, reinterpret_cast<struct sockaddr*>(&serverAddr), sizeof(serverAddr)) < 0) {
            std::cerr << "Failed to connect socket" << std::endl;
        }
    }
}

TCPConnection::~TCPConnection() {
    if (socketFd_ != -1) {
        close(socketFd_);
    }
}

void TCPConnection::connect() {
    // Connect to the server using the socket file descriptor
    struct sockaddr_in serverAddr;
    memset(&serverAddr, 0, sizeof(serverAddr));
    serverAddr.sin_family = AF_INET;
    serverAddr.sin_port = htons(port_);
    inet_pton(AF_INET, hostname_.c_str(), &serverAddr.sin_addr);
    if (connect(socketFd_, reinterpret_cast<struct sockaddr*>(&serverAddr), sizeof(serverAddr)) < 0) {
        std::cerr << "Failed to connect socket" << std::endl;
    }
}

bool TCPConnection::isConnected() const {
    return socketFd_ != -1 && socketFd_ != -1;
}

void TCPConnection::disconnect() {
    if (socketFd_ != -1) {
        close(socketFd_);
        socketFd_ = -1;
    }
}

size_t TCPConnection::send(const void* buffer, size_t size) {
    // Send data to the server using the socket file descriptor
    return ::write(socketFd_, buffer, size);
}

size_t TCPConnection::receive(void* buffer, size_t size) {
    // Receive data from the server using the socket file descriptor
    return ::read(socketFd_, buffer, size);
}

// Implementation of the connection thread methods
void TCPConnectionManager::manageConnections() {
    while (!stopThreads_) {
        std::unique_lock<std::mutex> lock(connectionsMutex_);
        connectionsConditionVariable_.wait(lock);
        if (stopThreads_) {
            break;
        }
        auto expiredIter = connections_.begin();
        while (expiredIter != connections_.end()) {
            // Check if the connection has expired and remove it if necessary
            if (std::chrono::steady_clock::now() > expiredIter->second) {
                removeConnection(expiredIter->first);
                expiredIter = connections_.begin();
            } else {
                ++expiredIter;
            }
        }
    }
}

void TCPConnectionManager::addConnection(const Connection::Ptr& connection) {
    std::lock_guard<std::mutex> lock(connectionsMutex_);
    connections_.insert({connection, std::chrono::steady_clock::now() + std::chrono::milliseconds(5000)});
    connectionsConditionVariable_.notify_one();
}

void TCPConnectionManager::removeConnection(const Connection::Ptr& connection) {
    std::lock_guard<std::mutex> lock(connectionsMutex_);
    auto iter = connections_.find(connection);
    if (iter != connections_.end()) {
        connections_.erase(iter);
        connectionsConditionVariable_.notify_one();
    }
}

void TCPConnectionManager::updateExpiryTime(const Connection::Ptr& connection) {
    std::lock_guard<std::mutex> lock(connectionsMutex_);
    auto iter = connections_.find(connection);
    if (iter != connections_.end()) {
        iter->second = std::chrono::steady_clock::now() + std::chrono::milliseconds(5000);
    }
}

void TCPConnectionManager::clearExpiredConnections() {
    std::lock_guard<std::mutex> lock(connectionsMutex_);
    auto expiredIter = connections_.begin();
    while (expiredIter != connections_.end()) {
        // Check if the connection has expired and remove it if necessary
        if (std::chrono::steady_clock::now() > expiredIter->second) {
            removeConnection(expiredIter->first);
            expiredIter = connections_.begin();
        } else {
            ++expiredIter;
        }
    }
}']

