// TCPConnectionPool.h
#ifndef TCPCONNECTIONPOOL_H
#define TCPCONNECTIONPOOL_H

#include <vector>
#include <unordered_map>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <chrono>
#include <iostream>
#include <string>
#include <functional>

class TCPConnectionPool {
 public:
  explicit TCPConnectionPool(size_t maxConnections = 0);

  // Add a new connection to the pool, or retrieve an existing one if available.
  // Returns true on success, false otherwise.
  bool addConnection(const std::string& hostname, uint16_t port,
                    size_t maxConnections = 0);

  // Remove a connection from the pool, closing it if necessary.
  // Returns true on success, false otherwise.
  bool removeConnection(const std::string& hostname, uint16_t port);

  // Get an available connection from the pool, or create a new one if none are available.
  // The connection is marked as in use by this thread until it is returned to the pool.
  TCPConnection* getConnection(const std::string& hostname, uint16_t port);

  // Return an in-use connection to the pool.
  void returnConnection(TCPConnection* conn);

 private:
  size_t maxConnections_;
  std::vector<TCPConnection*> connections_;
  std::unordered_map<std::string, TCPConnection*> hostnameMap_;
  std::mutex connectionsMutex_;
  std::condition_variable connectionsCondVar_;
  std::thread connectionThread_;

  void connectionThreadFunc();
};

#endif // TCPCONNECTIONPOOL_H
