```
// TCPConnectionPool.cpp
#include "TCPConnectionPool.h"
#include <iostream>

TCPConnectionPool::TCPConnectionPool(size_t maxConnections) :
  maxConnections_(maxConnections), connectionsMutex_(), connectionsCondVar_() {}

bool TCPConnectionPool::addConnection(const std::string& hostname, uint16_t port, size_t maxConnections) {
  // Check if the connection already exists in the pool.
  std::lock_guard<std::mutex> lock(connectionsMutex_);
  auto it = hostnameMap_.find(hostname);
  if (it != hostnameMap_.end()) return false;

  // Create a new connection and add it to the pool.
  TCPConnection* conn = new TCPConnection(hostname, port);
  connections_.push_back(conn);
  hostnameMap_[hostname] = conn;

  // Start the connection thread if this is the first connection added.
  if (connections_.size() == 1) {
    connectionThread_ = std::thread(&TCPConnectionPool::connectionThreadFunc, this);
  }

  return true;
}

bool TCPConnectionPool::removeConnection(const std::string& hostname, uint16_t port) {
  // Check if the connection exists in the pool.
  std::lock_guard<std::mutex> lock(connectionsMutex_);
  auto it = hostnameMap_.find(hostname);
  if (it == hostnameMap_.end()) return false;

  // Remove the connection from the pool and delete it.
  TCPConnection* conn = it->second;
  connections_.erase(std::remove(connections_.begin(), connections_.end(), conn), connections_.end());
  hostnameMap_.erase(it);
  delete conn;

  return true;
}

TCPConnection* TCPConnectionPool::getConnection(const std::string& hostname, uint16_t port) {
  // Check if the connection already exists in the pool.
  std::lock_guard<std::mutex> lock(connectionsMutex_);
  auto it = hostnameMap_.find(hostname);
  if (it != hostnameMap_.end()) return it->second;

  // If not, create a new connection and add it to the pool.
  TCPConnection* conn = new TCPConnection(hostname, port);
  connections_.push_back(conn);
  hostnameMap_[hostname] = conn;

  // Start the connection thread if this is the first connection added.
  if (connections_.size() == 1) {
    connectionThread_ = std::thread(&TCPConnectionPool::connectionThreadFunc, this);
  }

  return conn;
}

void TCPConnectionPool::returnConnection(TCPConnection* conn) {
  // Check if the connection exists in the pool.
  std::lock_guard<std::mutex> lock(connectionsMutex_);
  auto it = std::find(connections_.begin(), connections_.end(), conn);
  if (it == connections_.end()) return;

  // Remove the connection from the pool and delete it.
  connections_.erase(std::remove(connections_.begin(), connections_.end(), conn), connections_.end());
  hostnameMap_.erase(conn->hostname_);
}

void TCPConnectionPool::connectionThreadFunc() {
  while (true) {
    // Wait for a connection to become available.
    std::unique_lock<std::mutex> lock(connectionsMutex_);
    connectionsCondVar_.wait(lock, [this] { return !connections_.empty(); });

    // Check if the thread should exit.
    if (connections_.empty()) break;

    // Get the next connection in the queue.
    TCPConnection* conn = connections_[0];
    connections_.erase(connections_.begin());

    // Open the connection and initiate any necessary handshaking.
    if (!conn->open()) {
      std::cout << "Error opening connection to " << conn->hostname_ << ":" << conn->port_ << std::endl;
      continue;
    }

    // Add the connection back to the pool once it has been opened successfully.
    hostnameMap_[conn->hostname_] = conn;
    connections_.push_back(conn);
  }
}
