// C Header File
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <ctype.h>

// Kafka and RabbitMQ Libraries
#include <librdkafka/rdkafka.h>
#include <rabbitmq-c/amqp.h>

// PostgreSQL Library
#include <libpq-fe.h>

// JSON Parser Library
#include "json.h"

// Structures for Data Processing
struct Transaction {
    char* id;
    int timestamp;
    float amount;
    char* currency;
};

struct Account {
    char* account_id;
    float balance;
};

// Function Declarations
void processTransaction(struct Transaction* transaction);
void updateAccountBalance(struct Account* account, struct Transaction* transaction);

int main() {
    // Initialize Kafka and RabbitMQ Consumers
    rd_kafka_t* kafkaConsumer = NULL;
    amqp_connection_state_t rabbitmqConnection = NULL;
    amqp_channel_open(rabbitmqConnection);
    amqp_queue_declare(rabbitmqConnection, 0, AMQP_EXCHANGE_TYPE_DIRECT, "transactions", 0, 0, 0, 0, NULL);
    amqp_basic_consume(rabbitmqConnection, amqp_cstring_bytes("transactions"), 1, false, true, false, false, NULL);

    // Initialize PostgreSQL Connection
    PGconn* dbConnection = NULL;
    dbConnection = PQconnectdb("postgresql://user:password@host:port/database");

    if (PQstatus(dbConnection) != CONNECTION_OK) {
        fprintf(stderr, "Connection to PostgreSQL failed\n");
        PQfinish(dbConnection);
        exit(1);
    }

    // Initialize JSON Parser
    json_error_t error;
    char* jsonString = NULL;

    while (true) {
        // Consume Kafka Message
        rd_kafka_message_t* message = rd_kafka_consumer_poll(kafkaConsumer, 100);
        if (message->err == RD_KAFKA_RESP_ERR__PARTITION_EOF) {
            continue;
        } else if (message->err != RD_KAFKA_RESP_ERR_NO_ERROR) {
            fprintf(stderr, "Error while consuming Kafka message\n");
            rd_kafka_message_destroy(message);
            continue;
        }

        // Parse JSON from Kafka Message
        jsonString = (char*)message->payload;
        struct Transaction transaction;
        json_t* root = json_loads(jsonString, 0, &error);
        if (!root) {
            fprintf(stderr, "Error while parsing JSON: %s\n", error.text);
            rd_kafka_message_destroy(message);
            continue;
        }
        transaction.id = json_string_value(json_object_get(root, "id"));
        transaction.timestamp = (int)json_integer_value(json_object_get(root, "timestamp"));
        transaction.amount = (float)json_number_value(json_object_get(root, "amount"));
        transaction.currency = json_string_value(json_object_get(root, "currency"));
        rd_kafka_message_destroy(message);

        // Process Transaction
        processTransaction(&transaction);
    }

    return 0;
}

void processTransaction(struct Transaction* transaction) {
    // Insert Transaction into PostgreSQL Database
    char* sql = "INSERT INTO transactions (id, timestamp, amount, currency) VALUES ($1, $2, $3, $4);";
    PGresult* dbResult = NULL;
    int params[5];
    params[0] = transaction->id;
    params[1] = transaction->timestamp;
    params[2] = transaction->amount;
    params[3] = transaction->currency;
    dbConnection = PQexecParams(dbConnection, sql, 4, NULL, (const char**)params, NULL, NULL, 0);
    if (PQresultStatus(dbResult) != PGRES_COMMAND_OK) {
        fprintf(stderr, "Error while inserting transaction into PostgreSQL database\n");
    }

    // Update Account Balance
    updateAccountBalance(&transaction->account_id, &transaction);
}

void updateAccountBalance(struct Account* account, struct Transaction* transaction) {
    // Query for Account Balance
    char* sql = "SELECT balance FROM accounts WHERE id = $1;";
    PGresult* dbResult = NULL;
    int params[1];
    params[0] = account->id;
    dbConnection = PQexecParams(dbConnection, sql, 1, NULL, (const char**)params, NULL, NULL, 0);
    if (PQresultStatus(dbResult) != PGRES_TUPLES_OK) {
        fprintf(stderr, "Error while querying account balance\n");
    }

    // Update Account Balance
    int balance = atoi(PQgetvalue(dbResult, 0, 0));
    if (transaction->amount < 0) {
        balance -= transaction->amount;
    } else {
        balance += transaction->amount;
    }

    // Insert Updated Balance into PostgreSQL Database
    char* sql = "UPDATE accounts SET balance = $1 WHERE id = $2;";
    PGresult* dbResult = NULL;
    int params[2];
    params[0] = balance;
    params[1] = account->id;
    dbConnection = PQexecParams(dbConnection, sql, 2, NULL, (const char**)params, NULL, NULL, 0);
    if (PQresultStatus(dbResult) != PGRES_COMMAND_OK) {
        fprintf(stderr, "Error while updating account balance\n");
    }
}']

