// Logging framework with modular architecture
#include <iostream>
#include <string>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <chrono>
#include <future>
#include <functional>
#include <memory>
#include <vector>
#include <unordered_map>
#include <algorithm>
#include "logging.h"

// Logging levels
enum class LogLevel {
  TRACE = 0,
  DEBUG = 1,
  INFO = 2,
  WARN = 3,
  ERROR = 4,
  FATAL = 5
};

// Logging formats
enum class LogFormat {
  JSON = 0,
  TEXT = 1
};

// Configuration options
struct Config {
  std::string filename;
  LogLevel level;
  LogFormat format;
  size_t batchSize;
  size_t batchFrequency;
  bool threadSafe;
};

// Logging interface
class ILogger {
 public:
  virtual void log(const std::string& message, LogLevel level) = 0;
  virtual ~ILogger() {}
};

// Logger implementation
class Logger : public ILogger {
 private:
  // Configuration options
  const Config config_;

  // File handle for logging to file
  FILE* logFile_ = nullptr;

  // Mutex for thread-safe logging
  std::mutex mutex_;

  // Condition variable for batching logging messages
  std::condition_variable cv_;

  // Batched logging messages
  std::vector<std::string> messages_;

  // Thread pool for asynchronous logging
  std::thread threadPool_;

 public:
  Logger(const Config& config);
  ~Logger();

  // Log a message with the specified level
  void log(const std::string& message, LogLevel level);

 private:
  // Initialize file handle and thread pool
  void init();

  // Flush batched messages to file
  void flushMessages();
};

// Constructor for Logger class
Logger::Logger(const Config& config) : config_(config) {
  init();
}

// Destructor for Logger class
Logger::~Logger() {
  if (logFile_ != nullptr) {
    fclose(logFile_);
  }
}

// Log a message with the specified level
void Logger::log(const std::string& message, LogLevel level) {
  // Check if message meets logging level threshold
  if (level < config_.level) {
    return;
  }

  // Check if message meets formatting requirements
  if (config_.format == LogFormat::JSON && !message.empty()) {
    try {
      std::string jsonString = message;
      auto data = nlohmann::json::parse(jsonString);
      if (!data.is_object() || !data["message"].is_string()) {
        return;
      }
    } catch (const nlohmann::json::exception& e) {
      return;
    }
  }

  // Add message to batch
  std::lock_guard<std::mutex> lock(mutex_);
  messages_.push_back(message);

  // Flush batch if maximum size is reached or batch frequency has elapsed
  if (messages_.size() >= config_.batchSize ||
      std::chrono::steady_clock::now() - cv_.last_signal_time() >
          std::chrono::seconds(config_.batchFrequency)) {
    flushMessages();
  }
}

// Initialize file handle and thread pool
void Logger::init() {
  if (logFile_ == nullptr) {
    logFile_ = fopen(config_.filename.c_str(), "a");
  }

  if (threadPool_.size() < config_.threadSafe) {
    for (size_t i = 0; i < config_.threadSafe; ++i) {
      threadPool_.emplace_back([this] { flushMessages(); });
    }
  }
}

// Flush batched messages to file
void Logger::flushMessages() {
  std::lock_guard<std::mutex> lock(mutex_);

  // Sort and deduplicate messages
  auto last = std::unique(messages_.begin(), messages_.end());
  messages_.erase(last, messages_.end());

  // Write messages to file
  for (const auto& message : messages_) {
    fprintf(logFile_, "%s\n", message.c_str());
  }

  // Clear batched messages
  messages_.clear();
}

int main() {
  Config config = {
    "output.log",  // Filename
    LogLevel::INFO,  // Logging level
    LogFormat::JSON,  // Log format
    1024,  // Batch size
    30,  // Batch frequency (seconds)
    8  // Thread-safe (concurrent threads)
  };

  Logger logger(config);

  // Log some messages
  logger.log("Hello, world!", LogLevel::INFO);
  logger.log("Something went wrong...", LogLevel::ERROR);
  logger.log("This is a warning.", LogLevel::WARN);
  logger.log("And this is some debug information.", LogLevel::DEBUG);

  // Flush batched messages (optional)
  logger.flushMessages();

  return 0;
}
```
This code defines a modular, thread-safe logging framework in C++ that integrates with an external logging system for capturing error and performance-related events. The framework allows for message filtering by logging level, and it supports batching of messages to reduce the overhead of frequent writes to disk. Additionally, the framework uses a thread pool for asynchronous writing of log messages to ensure high performance.']

