import json
from datetime import datetime

class JobScheduler:
    def __init__(self):
        self.jobs = {}
        self.queued_jobs = []
        self.running_jobs = set()
        self.completed_jobs = {}

    def submit_job(self, job):
        # Check if the job is already running or completed
        if job.id in self.running_jobs or job.id in self.completed_jobs:
            return "Job with ID %d is already running or completed" % (job.id)

        # Add the job to the queued jobs list
        self.queued_jobs.append(job)

        return "Job with ID %d submitted successfully" % (job.id)

    def cancel_job(self, job_id):
        # Check if the job is already running or completed
        if job_id not in self.running_jobs and job_id not in self.completed_jobs:
            return "Job with ID %d does not exist" % (job_id)

        # Cancel the job and remove it from the queued jobs list
        for job in self.queued_jobs:
            if job.id == job_id:
                self.queued_jobs.remove(job)
                break

        return "Job with ID %d cancelled successfully" % (job_id)

    def update_job(self, job):
        # Check if the job is already running or completed
        if job.id not in self.running_jobs and job.id not in self.completed_jobs:
            return "Job with ID %d does not exist" % (job.id)

        # Update the job and remove it from the queued jobs list
        for job in self.queued_jobs:
            if job.id == job_id:
                job = job._replace(**job.__dict__)
                self.queued_jobs.remove(job)
                break

        return "Job with ID %d updated successfully" % (job_id)

    def run_job(self, job):
        # Check if the job is already running or completed
        if job.id in self.running_jobs or job.id in self.completed_jobs:
            return "Job with ID %d is already running or completed" % (job.id)

        # Add the job to the running jobs set and remove it from the queued jobs list
        self.running_jobs.add(job.id)
        for job in self.queued_jobs:
            if job.id == job_id:
                self.queued_jobs.remove(job)
                break

        # Start the job execution and update the status
        try:
            start = datetime.now()
            job.execute()
            end = datetime.now()
            duration = (end - start).total_seconds() * 1000

            self.completed_jobs[job.id] = {
                "start": str(start),
                "end": str(end),
                "duration": duration,
                "success": True
            }
        except Exception as e:
            # Handle job failure and update the status
            self.running_jobs.remove(job.id)

            self.completed_jobs[job.id] = {
                "start": str(start),
                "end": str(end),
                "duration": duration,
                "success": False,
                "error": str(e)
            }

    def get_job_status(self, job_id):
        # Check if the job exists
        if job_id not in self.running_jobs and job_id not in self.completed_jobs:
            return "Job with ID %d does not exist" % (job_id)

        # Return the status of the job
        if job_id in self.running_jobs:
            return "Job with ID %d is running" % (job_id)
        else:
            return "Job with ID %d completed successfully" % (job_id)

    def get_jobs(self):
        # Return a list of all the jobs in the system
        return self.queued_jobs + list(self.running_jobs.keys())
