4. Implement a distributed lock system that allows multiple nodes to coordinate access to a shared resource. The system should be able to handle multiple requests for the same resource and should ensure that only one node can acquire the lock at a time.
```c++
class DistributedLock {
    private:
        std::mutex mutex; // mutex for synchronizing access to the lock
        bool is_locked = false; // flag indicating whether the lock is currently held by another node
        int next_node_id = 0; // next available node ID
        std::unordered_set<int> locked_nodes; // set of nodes that have acquired the lock
    public:
        DistributedLock() {}
        ~DistributedLock() {
            if (!is_destroyed) {
                std::lock_guard<std::mutex> lock(mutex);
                cv.notify_all();
                is_destroyed = true;
            }
        }
        void destroy() {
            std::lock_guard<std::mutex> lock(mutex);
            if (!is_destroyed) {
                cv.notify_all();
                is_destroyed = true;
            }
        }
        bool acquireLock(int node_id) {
            std::unique_lock<std::mutex> lock(mutex);
            while (is_locked && locked_nodes.find(node_id) == locked_nodes.end()) {
                cv.wait(lock);
            }
            if (is_locked) {
                return false;
            } else {
                is_locked = true;
                locked_nodes.insert(node_id);
                return true;
            }
        }
        void releaseLock(int node_id) {
            std::lock_guard<std::mutex> lock(mutex);
            if (is_locked && locked_nodes.find(node_id) != locked_nodes.end()) {
                is_locked = false;
                locked_nodes.erase(node_id);
                cv.notify_all();
            }
        }
};
```
