        int count = 0; // current count of available resources
        bool is_destroyed = false; // flag indicating whether the semaphore has been destroyed
    public:
        DistributedSemaphore() {}
        ~DistributedSemaphore() {
            if (!is_destroyed) {
                std::lock_guard<std::mutex> lock(mutex);
                cv.notify_all();
                is_destroyed = true;
            }
        }
        void destroy() {
            std::lock_guard<std::mutex> lock(mutex);
            if (!is_destroyed) {
                cv.notify_all();
                is_destroyed = true;
            }
        }
        bool acquire(int node_id, int amount) {
            std::unique_lock<std::mutex> lock(mutex);
            while (count < amount) {
                cv.wait(lock);
            }
            if (is_destroyed) {
                return false;
            } else {
                count -= amount;
                return true;
            }
        }
        void release(int node_id, int amount) {
            std::lock_guard<std::mutex> lock(mutex);
            if (!is_destroyed) {
                count += amount;
                cv.notify_all();
            }
        }
};
