namespace FinancialEngine {
    class MTGenerator {
        private:
            // Define the internal state of the generator
            std::vector<int> mt;
            int mti = 0;

            // Define the global seed for all instances
            static constexpr unsigned int SEED = 42;

            // Define the maximum number of concurrent threads
            static constexpr int MAX_CONCURRENCY = 16;

            // Define a mutex to ensure thread safety
            std::mutex mtx;

        public:
            MTGenerator() {
                // Initialize the generator with the global seed
                this->mt.resize(MT_SIZE);
                initialize();
            }

            ~MTGenerator() = default;

            // Generate a random integer between [0, 2^31 - 1]
            int nextInt() {
                return static_cast<int>(this->generate() >> MT_SIZE);
            }

            // Generate a random float between [0.0, 1.0)
            double nextFloat() {
                return (this->generate() & MT_MASK) / MT_MAX;
            }

            // Generate a random double between [0.0, 1.0)
            double nextDouble() {
                return (this->generate() & MT_MASK) / MT_MAX;
            }

            // Set the global seed for all instances
            void setSeed(unsigned int seed) {
                SEED = seed;
            }

        private:
            // Generate a random number using the Mersenne Twister algorithm
            unsigned long generate() {
                if (mti >= MT_SIZE) {
                    mt = this->twist();
                    mti = 0;
                }

                unsigned long y = (mt[mti] & UPPER_MASK) | (mt[mti + 1] & LOWER_MASK);
                ++mti;

                return y ^ (y >> 11);
            }

            // Initialize the generator with the global seed
            void initialize() {
                mt[0] = SEED;

                for (int i = 1; i < MT_SIZE; ++i) {
                    mt[i] = 0x8b695e73UL * (mt[i - 1] ^ (mt[i - 1] >> 2)) + i;
                }
            }

            // Twist the generator state using the Mersenne Twister algorithm
            std::vector<int> twist() {
                std::vector<int> new_mt(MT_SIZE);

                for (int i = 0; i < MT_SIZE; ++i) {
                    new_mt[i] = mt[i] & UPPER_MASK;

                    if ((i & 1) == 0) {
                        new_mt[i] ^= (mt[i + MT_SIZE - MT_N] >> 1);
                    } else {
                        new_mt[i] ^= (mt[i + MT_SIZE - MT_N] << 1);
                    }
                }

                return new_mt;
            }
    };
}
```
