        private readonly HttpClient _httpClient;
        private readonly Dictionary<string, string> _cache = new();
        private readonly List<(string, string)> _pendingUpdates = new();
        private readonly JsonSerializerOptions _jsonOptions = new() { WriteIndented = true };
        private readonly RijndaelManaged _rijndael = new() { KeySize = 256, BlockSize = 128, Padding = PaddingMode.PKCS7 };

        public ActivityStreamService(HttpClient httpClient)
        {
            _httpClient = httpClient;
        }

        public async Task<IEnumerable<Activity>> FetchUserActivityStreamAsync(string userId)
        {
            var cachedActivities = GetCachedActivities(userId);
            if (cachedActivities.Any()) return cachedActivities;

            try
            {
                var externalApiUrl = $"https://external-api.example.com/users/{userId}/activities";
                var response = await _httpClient.GetAsync(externalApiUrl);
                if (response.IsSuccessStatusCode)
                {
                    var jsonResponse = await response.Content.ReadAsStringAsync();
                    var activities = JsonSerializer.Deserialize<IEnumerable<Activity>>(jsonResponse, _jsonOptions);
                    UpdateCache(userId, activities);
                    return activities;
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error fetching activity stream for user {userId}: {ex.Message}");
            }

            return Enumerable.Empty<Activity>();
        }

        private IEnumerable<Activity> GetCachedActivities(string userId)
        {
            if (!_cache.ContainsKey(userId)) return Enumerable.Empty<Activity>();
            var cachedData = _rijndael.Decrypt(_cache[userId], "secret-key");
            return JsonSerializer.Deserialize<IEnumerable<Activity>>(cachedData, _jsonOptions);
        }

        private void UpdateCache(string userId, IEnumerable<Activity> activities)
        {
            var encryptedData = _rijndael.Encrypt(JsonSerializer.SerializeToUtf8Bytes(activities, _jsonOptions), "secret-key");
            _cache[userId] = encryptedData;
        }
    }
}
