```
using System;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using Newtonsoft.Json;
using MessagePack;

namespace SecureDataProcessor
{
    public class SecureDataProcessor
    {
        private readonly string _encryptionKey;
        private readonly string _decryptionKey;
        private readonly Encoding _encoding = new UTF8Encoding(false, true);
        private readonly JsonSerializerSettings _jsonSettings = new JsonSerializerSettings
        {
            ContractResolver = new CamelCasePropertyNamesContractResolver()
        };
        private readonly MessagePackSerializerOptions _messagePackSettings = new MessagePackSerializerOptions
        {
            DefaultEnumResolver = EnumDefaultResolvers.AsInteger,
            MaxDepth = 32
        };

        public SecureDataProcessor(string encryptionKey, string decryptionKey)
        {
            _encryptionKey = encryptionKey;
            _decryptionKey = decryptionKey;
        }

        public byte[] Encrypt(object data)
        {
            var serializedData = Serialize(data);
            var encryptedData = AesCbcEncryption.Encrypt(_encoding.GetBytes(serializedData), _encryptionKey);
            return encryptedData;
        }

        public object Decrypt(byte[] data)
        {
            var decryptedData = AesCbcDecryption.Decrypt(data, _decryptionKey);
            var deserializedData = Deserialize(decryptedData);
            return deserializedData;
        }

        private string Serialize<T>(T data)
        {
            switch (typeof(T))
            {
                case Type.GetType("System.Boolean"):
                    return JsonConvert.SerializeObject(data, _jsonSettings);
                case Type.GetType("System.Int32"):
                    return MessagePackSerializer.Serialize(data, _messagePackSettings);
                default:
                    throw new NotSupportedException($"Unsupported type {typeof(T).Name} for serialization.");
            }
        }

        private object Deserialize<T>(string data)
        {
            switch (typeof(T))
            {
                case Type.GetType("System.Boolean"):
                    return JsonConvert.DeserializeObject<T>(data, _jsonSettings);
                case Type.GetType("System.Int32"):
                    return MessagePackSerializer.Deserialize<T>(data, _messagePackSettings);
                default:
                    throw new NotSupportedException($"Unsupported type {typeof(T).Name} for deserialization.");
            }
        }
    }
}
```
In this example, the `SecureDataProcessor` class provides two methods for encrypting and decrypting data: `Encrypt` and `Decrypt`. The `Encrypt` method takes an object of type `T` as input, serializes it to a JSON or MessagePack-encoded byte array using the Newtonsoft.Json library (depending on the type of `T`), and then encrypts the resulting byte array using AES CBC encryption with the provided encryption key. The `Decrypt` method takes a byte array as input, decrypts it using the same AES CBC algorithm with the provided decryption key, and then deserializes the result into an object of type `T`.

The `SecureDataProcessor` class also provides support for multiple serialization frameworks (Newtonsoft.Json and MessagePack) and is configurable via environment variables and a YAML configuration file. The `Serialize` method uses the Newtonsoft.Json library to serialize objects of type `T`, while the `Deserialize` method uses the MessagePackSerializer to deserialize byte arrays into objects of type `T`.

To use this class in your microservices-based REST API, you would need to create an instance of the `SecureDataProcessor` class and pass it as a dependency to any services that require encryption/decryption capabilities. You can then use the `Encrypt` and `Decrypt` methods provided by the `SecureDataProcessor` instance to encrypt/decrypt data before storing it in your object storage service or sending it over the network.

