        'url' => $external_system . $path,
        'content-type' => 'application/json',
        'body' => json_encode($data)
    );

    // Set up the HTTP client parameters
    $client = new GuzzleHttp\Client();
    $response = $client->request($params['method'], $params['url'], [
        'headers' => [
            'Content-Type' => 'application/json',
        ],
        'body' => json_encode($data),
        'http_errors' => false,
