    for crate_name in external_crates {
        info!(%crate_name, "Loading crate");
        match client.get(&format!("https://crates.io/api/v1/crates/{}/", crate_name)).send() {
            Ok(response) => {
                let crate_data = response.json::<Value>()?;
                loaded_crates.push(crate_data);
                info!(%crate_name, %loaded_crates.len(), "Crate loaded");
            }
            Err(error) => {
                warn!(%error, %crate_name, "Failed to load crate");
                return Err(Box::new(error));
            }
        }
    }
    Ok(loaded_crates)
}

fn handle_authentication_failures(response: Response, error: &'static str) -> Result<(), Box<dyn Error>> {
    match response.status() {
        401 | 403 => {
            error!(%error);
            return Err(Box::new(error));
        }
        _ => (),
    }
}

fn handle_network_failures(response: Response, error: &'static str) -> Result<(), Box<dyn Error>> {
    match response.status() {
        408 | 500..=599 => {
            warn!(%error);
        }
        _ => (),
    }
}

fn get_metadata(
    file_path: &str,
    storage_type: StorageType,
) -> Result<Vec<Value>, Box<dyn Error>> {
    let mut response = None;
    match storage_type {
        StorageType::S3 => {
            // ...
        }
        StorageType::GCS => {
            // ...
        }
        StorageType::AzureBlobStorage => {
            // ...
        }
        StorageType::Dropbox => {
            // ...
        }
    }

    if response.is_none() {
        return Err(Box::new("Failed to retrieve metadata".to_string()));
    }
    let response = response.unwrap();

    match response.text() {
        Ok(metadata) => Ok(serde_json::from_str(&metadata)?),
        Err(error) => {
            error!(%error);
            return Err(Box::new(error));
        }
    }
}

fn aggregate_metadata(file_path: &str, storage_types: &[StorageType]) -> Result<(), Box<dyn Error>> {
    let mut metadata_map = HashMap::new();
    for storage_type in storage_types {
        match get_metadata(file_path, *storage_type) {
            Ok(metadata) => {
                metadata_map.insert(*storage_type, metadata);
            }
            Err(error) => {
                error!(%error);
                return Err(Box::new(error));
            }
        }
    }

    let mut aggregated_metadata = vec![];
    for (storage_type, metadata) in &metadata_map {
        match storage_type {
            StorageType::S3 => {
                // ...
            }
            StorageType::GCS => {
                // ...
            }
            StorageType::AzureBlobStorage => {
                // ...
            }
            StorageType::Dropbox => {
                // ...
            }
        }
    }

    Ok(())
}

fn handle_metadata_aggregation(file_path: &str) -> Result<(), Box<dyn Error>> {
    let storage_types = vec![StorageType::S3, StorageType::GCS];
    aggregate_metadata(file_path, &storage_types)?;
    Ok(())
}

fn handle_request(request: Request) -> Result<Response, Box<dyn Error>> {
    match request.uri().path() {
        "/files" => {
            let files = vec![
                "file1",
                "file2",
                "file3",
            ];
            Ok(json(&files))
        }
        "/files/{file}" => {
            // ...
        }
        _ => Err(Box::new("Invalid request".to_string())),
    }
}

fn handle_requests() -> Result<(), Box<dyn Error>> {
    loop {
        match listener.accept()? {
            (socket, address) => {
                println!("Accepted connection from {}", address);
                let request = match Request::from_socket(&socket)? {
                    Some(request) => request,
                    None => continue,
                };
                handle_request(request)?;
            }
        }
    }
}
