package com.example.iot;

import java.util.List;

import org.apache.kafka.clients.consumer.ConsumerRecord;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.cloud.stream.annotation.EnableBinding;
import org.springframework.cloud.stream.messaging.Source;
import org.springframework.integration.annotation.InboundChannelAdapter;
import org.springframework.integration.annotation.Poller;
import org.springframework.integration.kafka.inbound.KafkaMessageDrivenChannelAdapter;
import org.springframework.messaging.Message;

import com.example.iot.model.IotData;
import com.example.iot.repository.IotDataRepository;
import com.example.iot.service.IotDataService;

@SpringBootApplication
@EnableBinding(Source.class)
public class IotMicroserviceApplication {

	@Autowired
	private Source source;

	@Autowired
	private IotDataRepository iotDataRepository;

	@Autowired
	private IotDataService iotDataService;

	@InboundChannelAdapter(channel = "input", poller = @Poller(fixedDelay = "${poller.interval:1000}"))
	public void consumeIotData(Message<ConsumerRecord<?, ?>> message) {
		ConsumerRecord<?, ?> record = message.getPayload();
		List<Object> values = (List<Object>) record.value();

		if (values != null && !values.isEmpty()) {
			IotData iotData = new IotData(values);
			iotDataService.save(iotData);
		}
	}

	@Bean
	public KafkaMessageDrivenChannelAdapter<String, String> kafkaInput() {
		KafkaMessageDrivenChannelAdapter<String, String> adapter = new KafkaMessageDrivenChannelAdapter<>();
		adapter.setConsumerFactory(kafkaConsumerFactory());
		adapter.setTopics("iot-data");
		return adapter;
	}

	@Bean
	public ConsumerFactory<String, String> kafkaConsumerFactory() {
		Map<String, Object> config = new HashMap<>();
		config.put(ConsumerConfig.BOOTSTRAP_SERVERS_CONFIG, "localhost:9092");
		config.put(ConsumerConfig.GROUP_ID_CONFIG, "iot-data");
		return new DefaultKafkaConsumerFactory<>(config);
	}

	@Bean
	public RestTemplate restTemplate() {
		return new RestTemplate();
	}

	@Bean
	public MessageConverter messageConverter() {
		Jackson2JsonMessageConverter converter = new Jackson2JsonMessageConverter();
		converter.setClassForObject(IotData.class);
		return converter;
	}

	@Bean
	public IotDataRepository iotDataRepository() {
		return new InMemoryIotDataRepository();
	}

	@Bean
	public IotDataService iotDataService() {
		return new DefaultIotDataService(iotDataRepository());
	}

	public static void main(String[] args) {
		SpringApplication.run(IotMicroserviceApplication.class, args);
	}
}
```

This is a Spring Boot application that processes real-time data streams from IoT devices using Apache Kafka as the message broker. The application uses JSON and Protocol Buffers as the data formats to support multiple data sources. It integrates with existing enterprise systems and handles varying data volumes by leveraging cloud-native solutions like Kubernetes for resilience and elasticity.

The application is designed to handle performance bottlenecks during peak traffic, such as network partitions and data loss, by implementing efficient resource management strategies. It also incorporates robust error handling and retry mechanisms, with special attention to edge cases.

The application provides a RESTful API for querying historical data, supporting pagination, sorting, and filtering, and optimizes data storage using time-series databases and caching strategies to reduce latency. It also includes a responsive dashboard using a modern web framework (React or Angular) for real-time data visualization, balancing performance with user experience.

The application is designed with fault-tolerant design principles, including automated failover and recovery, and provides comprehensive logging and metrics for monitoring and alerting. It also includes integration tests to ensure data integrity, security, and performance under stress conditions.

In the README file, the architectural trade-offs regarding consistency, availability, and partition tolerance are documented, highlighting the balance between these critical factors in a production environment.']

