class TransactionProcessor:
    def __init__(self, frequency_threshold=3, weighted_sum_threshold=50, age_threshold=3):
        self.frequency_threshold = frequency_threshold
        self.weighted_sum_threshold = weighted_sum_threshold
        self.age_threshold = age_threshold
        self.transactions = {}
        self.last_transaction_time = time.time()
        self.thread_pool = ThreadPoolExecutor(max_workers=10)

    def process_transaction(self, transaction):
        if self.is_duplicate(transaction):
            return False
        else:
            self.transactions[transaction] = time.time()
            self.last_transaction_time = time.time()
            return True

    def is_duplicate(self, transaction):
        if transaction in self.transactions:
            timestamp = self.transactions[transaction]
            if (time.time() - timestamp) < self.age_threshold:
                return True
            else:
                del self.transactions[transaction]
                return False
        else:
            return False

    def filter_transactions(self, transactions):
        filtered_transactions = []
        for transaction in transactions:
            if self.process_transaction(transaction):
                filtered_transactions.append(transaction)
        return filtered_transactions

    def get_statistics(self):
