using namespace std;

struct Transaction {
    int age;
    int count;
    double sum;
};

struct Metrics {
    int max_sum;
    string max_id;
};

Metrics calculateMetrics(vector<Transaction> transactions) {
    Metrics metrics = {};

    for (auto transaction : transactions) {
        if (transaction.age >= 3 && transaction.count >= 2) {
            metrics.max_sum = max(metrics.max_sum, transaction.sum);
            metrics.max_id = transaction.id;
        }
    }

    return metrics;
}

int main() {
    vector<Transaction> transactions = {
        {"1", 30, 100},
        {"2", 5, 50},
        {"3", 10, 75},
        {"4", 8, 60},
        {"5", 15, 90}
    };

    Metrics metrics = calculateMetrics(transactions);

    cout << "Maximum weighted sum: " << metrics.max_sum << endl;
    cout << "Corresponding transaction ID: " << metrics.max_id << endl;

    return 0;
}
