public class TransactionProcessor {
  private static final int MAX_BATCH_SIZE = 1000;
  private static final int MAX_RETRIES = 5;
  private static final long FILTERING_TIMEOUT = 3 * 1000L; // 3 seconds in milliseconds

  private final Map<String, Integer> filterCriteria = new HashMap<>();
  private final Map<String, Long> filterTimestamps = new HashMap<>();

  public void processTransactions(List<Transaction> transactions) {
    for (Transaction transaction : transactions) {
      if (filterTransaction(transaction)) {
        // Serialize the transaction into a compact binary format.
        byte[] serializedTransaction = serializeTransaction(transaction);

        // Send the serialized transaction to downstream processing.
        sendSerializedTransaction(serializedTransaction);
      }
    }
  }

  private boolean filterTransaction(Transaction transaction) {
    String transactionId = transaction.getTransactionId();

    // Check if the transaction is within the filtering timeout.
    long currentTime = System.currentTimeMillis();
    Long lastSeenTimestamp = filterTimestamps.get(transactionId);
    if (lastSeenTimestamp != null && currentTime - lastSeenTimestamp <= FILTERING_TIMEOUT) {
      return false;
    }

    // Check the transaction frequency and weighted sum threshold.
    Integer count = filterCriteria.get(transactionId);
    if (count == null || count < MAX_RETRIES) {
      filterTimestamps.put(transactionId, currentTime);
      return true;
    } else {
      return false;
    }
  }

  private byte[] serializeTransaction(Transaction transaction) {
    // Serialize the transaction into a compact binary format using Java's serialization mechanism.
    ByteArrayOutputStream baos = new ByteArrayOutputStream();
    ObjectOutputStream oos = new ObjectOutputStream(baos);
    try {
      oos.writeObject(transaction);
      oos.flush();
    } catch (IOException e) {
      throw new RuntimeException("Error serializing transaction", e);
    } finally {
      try {
        baos.close();
        oos.close();
      } catch (IOException e) {
        // Ignore, nothing to be done here.
      }
    }
    return baos.toByteArray();
  }

  private void sendSerializedTransaction(byte[] serializedTransaction) {
    // Send the serialized transaction to downstream processing using a separate thread or an async API call.
    // This will ensure that the service can process multiple transactions simultaneously without overloading the system.
  }
}
