        return cv.cvtColor(frame, cv.COLOR_BGR2YCrCb)

    def effect_grayscale(frame):
        return cv.cvtColor(frame, cv.COLOR_BGR2GRAY)

    def effect_negative(frame):
        return cv.bitwise_not(frame)

