import java.io.*;
import java.net.Socket;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.apache.commons.math3.util.Pair;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import com.google.common.cache.CacheBuilder;
import com.google.common.cache.CacheLoader;
import com.google.common.cache.LoadingCache;
import com.google.common.collect.ImmutableSet;
import com.google.common.hash.HashFunction;
import com.google.common.hash.Hashing;

public class FileSyncUtility {
    private static final Logger LOGGER = LoggerFactory.getLogger(FileSyncUtility.class);
    private static final int CONNECTION_TIMEOUT = 10000; // milliseconds
    private static final int COMMAND_TIMEOUT = 60000; // milliseconds
    private static final int RETRY_COUNT = 3;
    private static final ImmutableSet<String> IGNORED_COMMANDS = ImmutableSet.of("rm -rf", "cp -r");
    private static final HashFunction HASH_FUNCTION = Hashing.md5();

    // Loading cache for SSH connections
    private static final LoadingCache<String, Socket> SOCKET_CACHE = CacheBuilder.newBuilder()
            .expireAfterWrite(10, TimeUnit.MINUTES)
            .build(new CacheLoader<String, Socket>() {
                @Override
                public Socket load(String host) throws Exception {
                    return new Socket(host, 22);
                }
            });

    // Command queue for executing commands concurrently
    private static final Queue<Pair<String, String>> COMMAND_QUEUE = new ConcurrentLinkedQueue<>();

    // Container for storing command outputs and their corresponding statuses
    private static final Map<String, Pair<String, Boolean>> COMMAND_OUTPUTS = new HashMap<>();

    /**
     * Establishes an SSH connection to the given host.
     * @param host the hostname or IP address of the remote server
     * @return a Socket object representing the established connection
     */
    public static Socket connect(String host) {
        try {
            LOGGER.info("Establishing SSH connection to {}...", host);
            return SOCKET_CACHE.get(host);
        } catch (Exception e) {
            throw new IllegalStateException("Failed to establish SSH connection to " + host, e);
        }
    }

    /**
     * Closes an established SSH connection.
     * @param socket the Socket object representing the connection to be closed
     */
    public static void disconnect(Socket socket) {
        try {
            LOGGER.info("Closing SSH connection...");
            socket.close();
        } catch (Exception e) {
            throw new IllegalStateException("Failed to close SSH connection", e);
        }
    }

    /**
     * Executes the given command on the given host.
     * @param host the hostname or IP address of the remote server
     * @param command the command to be executed
     */
    public static void execute(String host, String command) {
        // Check if the command is ignored
        if (IGNORED_COMMANDS.contains(command)) {
            LOGGER.warn("Ignoring command '{}' on host {}", command, host);
            return;
        }

        // Generate a unique ID for the command
        String id = HASH_FUNCTION.hashString(host + command).toString();

        // Add the command to the queue with its corresponding ID
        COMMAND_QUEUE.add(new Pair<>(id, command));

        // Start executing the command if there are no other commands in progress
        if (COMMAND_QUEUE.size() == 1) {
            executeNextCommand();
        }
    }

    /**
     * Executes the next command in the queue.
     */
    private static void executeNextCommand() {
        // Get the next command from the queue
        Pair<String, String> command = COMMAND_QUEUE.peek();
        if (command == null) {
            return;
        }

        // Execute the command on a new thread to avoid blocking the main thread
        Thread executorThread = new Thread(() -> {
            try {
                LOGGER.info("Executing command '{}' on host {}...", command.getSecond(), command.getFirst());
                Socket socket = connect(command.getFirst());
                PrintWriter out = new PrintWriter(socket.getOutputStream(), true);
                BufferedReader in = new BufferedReader(new InputStreamReader(socket.getInputStream()));
                String output;

                // Send the command to the remote server
                out.println(command.getSecond());

                // Read the output from the remote server
                while ((output = in.readLine()) != null) {
                    LOGGER.info("Command output: {}", output);
                }

                // Close the socket connection
                disconnect(socket);
            } catch (Exception e) {
                LOGGER.error("Failed to execute command '{}' on host {}", command.getSecond(), command.getFirst(), e);
                COMMAND_OUTPUTS.put(command.getFirst(), new Pair<>(command.getSecond(), false));
            } finally {
                // Remove the command from the queue after it has been executed or failed
                COMMAND_QUEUE.remove();

                // Execute the next command if there are any in the queue
                executeNextCommand();
            }
        });

        // Start executing the command on a new thread
        executorThread.start();
    }
}']

