    private readonly ILogger<CryptoMessageProcessor> _logger;
    private readonly IPaymentGateway _paymentGateway;
    private readonly RabbitMQClient _rabbitMQClient;
    private readonly OAuth2Client _oauth2Client;
    private readonly CryptographyService _cryptographyService;
    private readonly MachineLearningService _machineLearningService;
    private readonly GeoDatabaseReplicator _geoDatabaseReplicator;
    private readonly TimeSpan _webSocketTimeout;
    private readonly TimeSpan _paymentGatewayDelay;
    private readonly int _complianceRetentionPeriod;
    private readonly bool _enableMachineLearningDetection;

    public CryptoMessageProcessor(ILogger<CryptoMessageProcessor> logger, IPaymentGateway paymentGateway, RabbitMQClient rabbitMQClient, OAuth2Client oauth2Client, CryptographyService cryptographyService, MachineLearningService machineLearningService, GeoDatabaseReplicator geoDatabaseReplicator, TimeSpan webSocketTimeout, TimeSpan paymentGatewayDelay, int complianceRetentionPeriod, bool enableMachineLearningDetection) {
      _logger = logger;
      _paymentGateway = paymentGateway;
      _rabbitMQClient = rabbitMQClient;
      _oauth2Client = oauth2Client;
      _cryptographyService = cryptographyService;
      _machineLearningService = machineLearningService;
      _geoDatabaseReplicator = geoDatabaseReplicator;
      _webSocketTimeout = webSocketTimeout;
      _paymentGatewayDelay = paymentGatewayDelay;
      _complianceRetentionPeriod = complianceRetentionPeriod;
      _enableMachineLearningDetection = enableMachineLearningDetection;
    }

    public async Task ProcessMessage(WebSocket webSocket, string message) {
      try {
        var clientId = webSocket.SubProtocol;
        var userId = await GetUserIdFromClientId(clientId);
        var accessToken = await GetAccessTokenForUserId(userId);
        var decryptedMessage = DecryptMessage(message, accessToken);
        var sequenceOfIntegers = ExtractSequenceOfIntegers(decryptedMessage);
        var largestInteger = sequenceOfIntegers.Max();
        var response = $"<clientId>{clientId}</clientId><largestInteger>{largestInteger}</largestInteger>";

        await _rabbitMQClient.SendMessageAsync("crypto-service", response);
      } catch (Exception ex) {
        _logger.LogError(ex, "Failed to process message");
      }
    }

    private async Task<string> GetUserIdFromClientId(string clientId) {
      var userId = await _oauth2Client.GetUserIdAsync(clientId);
      return userId;
    }

    private async Task<string> GetAccessTokenForUserId(string userId) {
      var accessToken = await _oauth2Client.GetAccessTokenAsync(userId);
      return accessToken;
    }

    private string DecryptMessage(string message, string accessToken) {
      var decryptedMessage = _cryptographyService.Decrypt(message, accessToken);
      return decryptedMessage;
    }

    private List<int> ExtractSequenceOfIntegers(string message) {
      var sequenceOfIntegers = new List<int>();
      foreach (var integer in message.Split(",")) {
        if (int.TryParse(integer, out int parsedInteger)) {
          sequenceOfIntegers.Add(parsedInteger);
        }
      }
      return sequenceOfIntegers;
    }

    private async Task<bool> VerifyMessageIntegrityAsync(string message) {
      var integrity = await _cryptographyService.VerifyIntegrityAsync(message);
      return integrity;
    }

    private async Task<bool> IsClientAllowedAsync(string clientId, string userId) {
      var isAllowed = await _oauth2Client.IsClientAllowedAsync(clientId, userId);
      return isAllowed;
    }

    private async Task<bool> HasEnoughBalanceAsync(string userId) {
      var balance = await _paymentGateway.GetBalanceAsync(userId);
      if (balance < 0) {
        return false;
      }
      return true;
    }

    private async Task<bool> HasEnoughPriorityAsync(string userId) {
      var priority = await _rabbitMQClient.GetQueuePriorityAsync("crypto-service", userId);
      if (priority < 0) {
        return false;
      }
      return true;
    }

    private async Task<bool> IsMessageProcessingAllowedAsync(string clientId, string userId, string message) {
      var isAllowed = await _oauth2Client.IsClientAllowedAsync(clientId, userId);
      if (!isAllowed) {
        return false;
      }
      var balance = await _paymentGateway.GetBalanceAsync(userId);
      if (balance < 0) {
        return false;
      }
      var priority = await _rabbitMQClient.GetQueuePriorityAsync("crypto-service", userId);
      if (priority < 0) {
        return false;
      }
      return true;
    }
  }
}
```

