```scss
// Import necessary libraries and dependencies
const { Client } = require('messaging-broker');
const { PresenceService } = require('presence-service');
const { AuthAPI } = require('authentication-api');

// Define the main application class
class ChatApplication {
  constructor() {
    this.client = new Client();
    this.presenceService = new PresenceService();
    this.authAPI = new AuthAPI();
  }

  // Initialize the application and connect to external services
  async initialize() {
    await this.client.connect();
    await this.presenceService.connect();
    await this.authAPI.authenticate();
  }

  // Send a message to a specific user or room
  async sendMessage(message, recipient) {
    const sender = await this.authAPI.getUser();
    const recipientUser = await this.presenceService.getUser(recipient);
    if (sender && recipientUser) {
      // Send the message using the messaging broker client
      await this.client.sendMessage(message, sender, recipientUser);
    } else {
      throw new Error('Failed to send message: invalid recipient or user not found');
    }
  }

  // Handle incoming messages from the messaging broker
  async handleMessage(message) {
    try {
      const sender = await this.authAPI.getUser();
      const recipient = message.recipient;
      if (sender && recipient) {
        // Check for urgent messages and prioritize delivery
        const isUrgent = this.checkUrgency(message);
        if (isUrgent) {
          // Degrade gracefully in case of high latency from any service
          await this.client.sendMessage(message, sender, recipient, {
            degraded: true,
            onError: (error) => console.log(`Error sending message: ${error}`)
          });
        } else {
          // Send the message using the messaging broker client
          await this.client.sendMessage(message, sender, recipient);
        }
      } else {
        throw new Error('Failed to send message: invalid recipient or user not found');
      }
    } catch (error) {
      console.log(`Error handling message: ${error}`);
    }
  }

  // Check for urgent messages and prioritize delivery
  checkUrgency(message) {
    const isUrgent = false;
    if (message.urgent) {
      isUrgent = true;
    }
    return isUrgent;
  }
}

// Initialize the application and connect to external services
const app = new ChatApplication();
await app.initialize();

// Send a message to a specific user or room
app.sendMessage('Hello, world!', 'user@example.com');

// Handle incoming messages from the messaging broker
app.handleMessage({
  sender: 'user@example.com',
  recipient: 'other-user@example.com',
  message: 'Hi there!'
});
```
