    data: Vec<u8>,
}

struct Session {
    user_id: String,
    token: String,
    tasks: Vec<Task>,
}

enum CipherMode {
    AES_CBC,
    CFB,
    GCM,
}

impl Session {
    fn new(user_id: &str) -> Self {
        Self {
            user_id: String::from(user_id),
            token: String::new(),
            tasks: Vec::new(),
        }
    }

