        if (strlen(line) > 0 && line[0] != '#') {
            char* key = strtok(line, "=");
            char* value = strtok(NULL, "\n");
            if (strcmp(key, "url") == 0) {
                config.url = strdup(value);
            } else if (strcmp(key, "timeout") == 0) {
                config.timeout = atoi(value);
            } else if (strcmp(key, "concurrency") == 0) {
                config.concurrency = atoi(value);
            }
        }
    }

    fclose(file);
    return config;
}

// Define the session creation function
session_t* create_session(const char* url, int timeout, int concurrency) {
    CURL* curl = curl_easy_init();
    if (curl == NULL) {
        log("Failed to initialize cURL.");
        return ERROR_THREAD_CREATION;
    }

    session_t* session = malloc(sizeof(session_t));
    session->curl = curl;
    session->config = parse_config(url);
    if (session->config == ERROR_CONFIG_PARSING) {
        log("Failed to parse configuration file.");
        return NULL;
    }

    // Set the cURL options
    curl_easy_setopt(curl, CURLOPT_URL, session->config.url);
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, timeout);
    curl_easy_setopt(curl, CURLOPT_CONNECTTIMEOUT, concurrency);

    return session;
}

// Define the work queue creation function
work_queue_t* create_work_queue() {
    pthread_mutex_init(&mutex, NULL);
    work_queue_t* queue = malloc(sizeof(work_queue_t));
    queue->size = 10;
    queue->count = 0;
    queue->tasks[0] = create_session("https://example.com/api", 30, 5);
    return queue;
}

// Define the work queue execution function
void execute_work_queue(work_queue_t* queue) {
    pthread_mutex_lock(&queue->mutex);
    while (queue->count > 0) {
        session_t* task = queue->tasks[queue->count - 1];
        curl_easy_perform(task->curl);
        free(task->curl);
        queue->count--;
        pthread_mutex_unlock(&queue->mutex);
    }
}

// Define the main function
int main(int argc, char* argv[]) {
    // Parse the command-line arguments
    if (argc < 2) {
        log("Usage: %s [options]", argv[0]);
        return SUCCESS;
    }

    // Create a work queue
    work_queue_t* queue = create_work_queue();

    // Execute the work queue
    execute_work_queue(queue);

    // Free the work queue
    free(queue->tasks[0]);
    free(queue);

    return SUCCESS;
}
