import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.scheduling.annotation.EnableAsync;
import org.springframework.scheduling.annotation.EnableScheduling;
import org.springframework.scheduling.concurrent.ThreadPoolTaskExecutor;

@SpringBootApplication
@EnableAsync
@EnableScheduling
public class DataProcessor {

	private static final int THREAD_POOL_SIZE = 10;
	private static final long RETRY_DELAY = 5000; // 5 seconds
	private static final int MAX_RETRIES = 3;

	public static void main(String[] args) {
		SpringApplication.run(DataProcessor.class, args);
	}

	@Bean
	public ThreadPoolTaskExecutor threadPoolTaskExecutor() {
		ThreadPoolTaskExecutor executor = new ThreadPoolTaskExecutor();
		executor.setCorePoolSize(THREAD_POOL_SIZE);
		executor.setMaxPoolSize(THREAD_POOL_SIZE);
		executor.setKeepAliveSeconds(60);
		return executor;
	}

	@Bean
	public ScheduledExecutorService scheduledExecutorService() {
		ScheduledExecutorService executor = Executors.newSingleThreadScheduledExecutor();
		return executor;
	}

	private static class RetryableTask implements Runnable {
		private final Runnable task;
		private final int retries;

		public RetryableTask(Runnable task, int retries) {
			this.task = task;
			this.retries = retries;
		}

		@Override
		public void run() {
			int retryCount = 0;
			while (retryCount < retries) {
				try {
					task.run();
					break; // successful execution, break out of loop
				} catch (Exception e) {
					if (retryCount >= retries - 1) {
						throw new RuntimeException("Retry limit exceeded", e);
					}
					// exponential backoff
					long delay = (long) Math.scalb(RETRY_DELAY, retryCount);
					retryCount++;
					System.out.println("Retrying in " + delay + " milliseconds");
					Thread.sleep(delay); // sleep before attempting again
				}
			}
		}
	}

	private void scheduleTaskWithRetries() {
		// scheduling task with retry mechanism
		Runnable task = () -> {
			// task code here
		};
		ScheduledExecutorService executor = scheduledExecutorService();
		executor.scheduleWithFixedDelay(new RetryableTask(task, MAX_RETRIES), 0, RETRY_DELAY, TimeUnit.MILLISECONDS);
	}

	private void processData() {
		// process data code here
	}

	@Async
	public void handleRequest() {
		// handle request code here
		processData();
	}
}']

