// Define dynamic array of NFAPI_CRC_INDICATION_PDU_T structures
class DynamicArray {
public:
    // Constructor
    DynamicArray() : size_(0), capacity_(MAX_SIZE) {}

    // Destructor
    ~DynamicArray() {
        delete[] data_;
    }

    // Add element to the end of the array
    void push(const NFAPI_CRC_INDICATION_PDU_T& element) {
        std::unique_lock<std::mutex> lock(mutex_);
        while (size_ == capacity_) {
            cv_.wait(lock, [this]() { return size_ < capacity_; });
        }
        data_[size_++] = element;
        lock.unlock();
        cv_.notify_all();
    }

    // Remove element from the end of the array
    void pop() {
        std::unique_lock<std::mutex> lock(mutex_);
        while (size_ == 0) {
            cv_.wait(lock, [this]() { return size_ > 0; });
        }
        --size_;
        lock.unlock();
        cv_.notify_all();
    }

    // Get element at the specified index
    NFAPI_CRC_INDICATION_PDU_T& get(int index) {
        std::unique_lock<std::mutex> lock(mutex_);
        while (index >= size_) {
            cv_.wait(lock, [this]() { return index < size_; });
        }
        return data_[index];
    }

    // Set element at the specified index
    void set(int index, const NFAPI_CRC_INDICATION_PDU_T& element) {
        std::unique_lock<std::mutex> lock(mutex_);
        while (index >= size_) {
            cv_.wait(lock, [this]() { return index < size_; });
        }
        data_[index] = element;
    }

private:
    // Size of the dynamic array
    int size_;

    // Capacity of the dynamic array
    int capacity_;

    // Data array of NFAPI_CRC_INDICATION_PDU_T structures
    std::atomic<NFAPI_CRC_INDICATION_PDU_T*> data_;

    // Mutex for synchronizing access to the dynamic array
    std::mutex mutex_;

    // Condition variable for waiting on changes to the size of the dynamic array
    std::condition_variable cv_;
};

// Define class for managing a pool of custom allocators
class AllocatorPool {
public:
    // Constructor
    AllocatorPool() : allocators_(MAX_SIZE) {}

    // Destructor
    ~AllocatorPool() {
        delete[] allocators_;
    }

    // Add a custom allocator to the pool
    void add(std::function<void* (size_t)> allocator) {
        std::unique_lock<std::mutex> lock(mutex_);
        while (count_ == MAX_SIZE) {
            cv_.wait(lock, [this]() { return count_ < MAX_SIZE; });
        }
        allocators_[count_++] = allocator;
        lock.unlock();
        cv_.notify_all();
    }

    // Remove a custom allocator from the pool
    void remove(std::function<void* (size_t)> allocator) {
        std::unique_lock<std::mutex> lock(mutex_);
        while (count_ == 0) {
            cv_.wait(lock, [this]() { return count_ > 0; });
        }
        for (int i = 0; i < count_; ++i) {
            if (allocators_[i] == allocator) {
                --count_;
                std::swap(allocators_[i], allocators_[count_]);
                break;
            }
        }
        lock.unlock();
        cv_.notify_all();
    }

    // Get a custom allocator from the pool
    std::function<void* (size_t)> get() {
        std::unique_lock<std::mutex> lock(mutex_);
        while (count_ == 0) {
            cv_.wait(lock, [this]() { return count_ > 0; });
        }
        return allocators_[--count_];
    }

private:
    // Count of custom allocators in the pool
    int count_;

    // Array of custom allocators
    std::function<void* (size_t)>* allocators_;

    // Mutex for synchronizing access to the pool
    std::mutex mutex_;

    // Condition variable for waiting on changes to the size of the pool
    std::condition_variable cv_;
};

