// File renaming module

#define MAX_FILENAME_LENGTH 256
#define EXTENSION_MAX_LENGTH 8
#define INVALID_EXTENSION "invalid"

struct file_renaming_data {
    char* filename;
    size_t filename_length;
    char* extension;
    size_t extension_length;
};

void parse_filename(const char* filename, struct file_renaming_data* data) {
    assert(filename != NULL && data != NULL);

    // Get the length of the filename and check if it's too long
    size_t filename_length = strlen(filename);
    if (filename_length > MAX_FILENAME_LENGTH) {
        fprintf(stderr, "Error: Filename is too long\n");
        exit(EXIT_FAILURE);
    }

    // Get the extension of the filename and check if it's invalid
    const char* dot = strrchr(filename, '.');
    size_t extension_length;
    if (dot == NULL) {
        extension_length = 0;
    } else {
        extension_length = MAX_FILENAME_LENGTH - (dot - filename + 1);
    }
    if (extension_length > EXTENSION_MAX_LENGTH) {
        fprintf(stderr, "Error: Extension is too long\n");
        exit(EXIT_FAILURE);
    }

    // Copy the filename and extension to the data structure
    size_t max_filename_length = MAX_FILENAME_LENGTH - (extension_length + 1);
    if (max_filename_length > filename_length) {
        max_filename_length = filename_length;
    }
    data->filename_length = max_filename_length;
    memcpy(data->filename, filename, data->filename_length);
    data->extension = dot + 1;
    data->extension_length = extension_length;
}

void rename_file(const char* filename, const char* new_name) {
    assert(filename != NULL && new_name != NULL);

    // Create a temporary buffer for the new name and parse it
    struct file_renaming_data data = {0};
    parse_filename(new_name, &data);

    // Build the new filename with the parsed extension
    char new_filename[MAX_FILENAME_LENGTH] = {0};
    memcpy(new_filename, data.filename, data.filename_length);
    if (data.extension_length > 0) {
        strncat(new_filename, ".", MAX_FILENAME_LENGTH - data.filename_length);
        strncat(new_filename, data.extension, EXTENSION_MAX_LENGTH);
    }

    // Rename the file and log the renaming event
    int result = rename(filename, new_filename);
    if (result == -1) {
        fprintf(stderr, "Error: Failed to rename file %s to %s\n", filename, new_name);
    } else {
        printf("Renamed file %s to %s\n", filename, new_name);
    }
}

// Graph database integration module

#define GRAPH_DATABASE_URL "http://localhost:8080/graph"
#define FILE_METADATA_PROPERTY "fileMetadata"
#define FILE_NAME_PROPERTY "fileName"
#define FILE_SIZE_PROPERTY "fileSize"
#define FILE_TYPE_PROPERTY "fileType"
#define GRAPH_UPDATE_LIMIT 100

struct file_metadata {
    char* filename;
    size_t filename_length;
    long file_size;
    const char* file_type;
};

void parse_file_metadata(const char* metadata, struct file_metadata* data) {
    assert(metadata != NULL && data != NULL);

    // Get the length of the metadata and check if it's too long
    size_t metadata_length = strlen(metadata);
    if (metadata_length > MAX_FILENAME_LENGTH) {
        fprintf(stderr, "Error: Metadata is too long\n");
        exit(EXIT_FAILURE);
    }

    // Parse the metadata and fill in the struct
    const char* comma = strchr(metadata, ',');
    if (comma == NULL) {
        fprintf(stderr, "Error: Invalid metadata format\n");
        exit(EXIT_FAILURE);
    }
    size_t filename_length = comma - metadata;
    memcpy(data->filename, metadata, filename_length);
    data->filename[filename_length] = '\0';
    long file_size = atol(comma + 1);
    if (file_size == 0) {
        fprintf(stderr, "Error: Invalid file size\n");
        exit(EXIT_FAILURE);
    }
    data->file_size = file_size;
    const char* slash = strrchr(metadata, '/');
    if (slash == NULL) {
        fprintf(stderr, "Error: Invalid file type\n");
        exit(EXIT_FAILURE);
    }
    size_t file_type_length = metadata_length - (slash - metadata + 1);
    memcpy(data->file_type, slash + 1, file_type_length);
    data->file_type[file_type_length] = '\0';
}

void extract_file_metadata(const char* filename, struct file_metadata* data) {
    assert(filename != NULL && data != NULL);

    // Open the file and parse its metadata
    FILE* fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open file %s\n", filename);
        return;
    }
    char buffer[MAX_FILENAME_LENGTH] = {0};
    size_t bytes_read = fread(buffer, 1, MAX_FILENAME_LENGTH - 1, fp);
    if (bytes_read == 0) {
        fprintf(stderr, "Error: Failed to read from file %s\n", filename);
        return;
    }
    buffer[bytes_read] = '\0';
    parse_file_metadata(buffer, data);
}

void update_graph(const char* filename) {
    assert(filename != NULL);

    // Extract the file metadata and build the graph update request
    struct file_metadata metadata;
    extract_file_metadata(filename, &metadata);
    char update[MAX_FILENAME_LENGTH] = {0};
    snprintf(update, MAX_FILENAME_LENGTH - 1, "%s|%ld|%s", FILE_METADATA_PROPERTY, metadata.filename_length, metadata.file_type);

    // Send the update request to the graph database and log the result
    CURL* curl = curl_easy_init();
    if (curl) {
        char url[MAX_FILENAME_LENGTH] = {0};
        snprintf(url, MAX_FILENAME_LENGTH - 1, "%s/%s", GRAPH_DATABASE_URL, filename);
        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, update);
        CURLcode result = curl_easy_perform(curl);
        if (result == CURLE_OK) {
            printf("Updated graph with file %s\n", filename);
        } else {
            fprintf(stderr, "Error: Failed to update graph with file %s\n", filename);
        }
    } else {
        fprintf(stderr, "Error: Failed to initialize curl for updating graph\n");
    }
}

// System module

#define TASK_QUEUE_SIZE 100
#define THREAD_COUNT 4

struct task {
    char* filename;
};

void run_task(void* arg) {
    struct task* task = (struct task*)arg;
    rename_file(task->filename, "renamed");
}

void start_system() {
    printf("Starting system...\n");

    // Create a queue for tasks and start the worker threads
    struct task task_queue[TASK_QUEUE_SIZE] = {0};
    pthread_t thread[THREAD_COUNT];
    for (int i = 0; i < THREAD_COUNT; i++) {
        int result = pthread_create(&thread[i], NULL, run_task, &task_queue[i]);
        if (result != 0) {
            fprintf(stderr, "Error: Failed to start worker thread %d\n", i);
        }
    }

    // Start the file monitoring loop
    while (1) {
        char filename[MAX_FILENAME_LENGTH] = {0};
        printf("Monitoring for new files...\n");
        sleep(1);
        if (readline(filename, MAX_FILENAME_LENGTH) == 0) {
            continue;
        }
        if (!strcmp(filename, "exit")) {
            break;
        }

        // Add the new file to the task queue and update the graph database
        strcpy(task_queue[i].filename, filename);
        update_graph(filename);
    }

    // Wait for all worker threads to finish
    for (int i = 0; i < THREAD_COUNT; i++) {
        int result = pthread_join(thread[i], NULL);
        if (result != 0) {
            fprintf(stderr, "Error: Failed to join worker thread %d\n", i);
        }
    }

    printf("System shutting down...\n");
}

int main() {
    start_system();
    return 0;
}
```

This code uses several libraries and frameworks:

* `stdio.h` for input/output operations
* `string.h` for string manipulation functions
* `stdlib.h` for memory management and other general-purpose functions
* `pthread.h` for thread creation and synchronization
* `readline` for reading lines from the terminal
* `curl` for sending HTTP requests to update the graph database

The program starts by defining several constants and arrays to hold data:

* `TASK_QUEUE_SIZE` is the maximum number of tasks that can be in the task queue at any given time.
* `THREAD_COUNT` is the number of worker threads that will be created.
* `task_queue` is an array of `struct task` objects, where each object holds a file name.
* `thread` is an array of thread IDs, which are used to join the threads later.

The program then starts by creating the worker threads and starting the file monitoring loop. The loop reads lines from the terminal and adds them to the task queue if they are not empty. If the line contains "exit", the loop breaks and the worker threads are joined.

After that, the program updates the graph database for each new file in the task queue using `update_graph`. This function sends an HTTP POST request to the graph database with the updated data. The response is printed to the terminal.

The main function starts the system by calling `start_system`, which starts the worker threads and enters the file monitoring loop.']

