namespace CryptographicLibrary {

    // Enumerations for supported algorithms and key sizes
    enum Algorithm {
        AES,
        Camellia,
        MD5,
        SHA256,
        RSAWithSHA256
    };

    enum KeySize {
        128,
        192,
        256
    };

    // Struct for holding cryptographic parameters and data
    struct CryptoParams {
        Algorithm algorithm;
        KeySize keySize;
        std::string key;
        std::vector<std::string> iv;
        std::string data;
    };

    // Function to perform encryption
    void Encrypt(const CryptoParams& params);

    // Function to perform decryption
    void Decrypt(const CryptoParams& params);

}

