#include <string>
#include <vector>

void CryptographicLibrary::Encrypt(const CryptoParams& params) {
    // Check for valid parameters
    if (params.algorithm == Algorithm::Invalid || params.keySize == KeySize::Invalid) {
        std::cout << "Error: Invalid encryption parameters" << std::endl;
        return;
    }

    // Generate a random key and IV for the selected algorithm
    switch (params.algorithm) {
        case Algorithm::AES:
            params.key = generateRandomKey(16, 32);
            params.iv = generateRandomIV(16, 32);
            break;
        case Algorithm::Camellia:
            params.key = generateRandomKey(32, 48);
            params.iv = generateRandomIV(16, 32);
            break;
        case Algorithm::MD5:
            params.key = generateRandomKey(16, 32);
            break;
        case Algorithm::SHA256:
            params.key = generateRandomKey(32, 48);
            break;
        case Algorithm::RSAWithSHA256:
            params.key = generateRandomKey(1024, 2048);
            break;
    }

    // Encrypt the data using the selected algorithm and key size
    switch (params.algorithm) {
        case Algorithm::AES:
            params.data = aesEncrypt(params.key, params.iv, params.data);
            break;
        case Algorithm::Camellia:
            params.data = camelliaEncrypt(params.key, params.iv, params.data);
            break;
