            params.data = md5Hash(params.key, params.data);
            break;
        case Algorithm::SHA256:
            params.data = sha256Hash(params.key, params.data);
            break;
        case Algorithm::RSAWithSHA256:
            params.data = rsaEncrypt(params.key, params.data);
            break;
    }
}

void CryptographicLibrary::Decrypt(const CryptoParams& params) {
    // Check for valid parameters
    if (params.algorithm == Algorithm::Invalid || params.keySize == KeySize::Invalid) {
        std::cout << "Error: Invalid decryption parameters" << std::endl;
        return;
    }

    // Decrypt the data using the selected algorithm and key size
    switch (params.algorithm) {
        case Algorithm::AES:
            params.data = aesDecrypt(params.key, params.iv, params.data);
            break;
        case Algorithm::Camellia:
            params.data = camelliaDecrypt(params.key, params.iv, params.data);
