using namespace std;

// Define the HTTP request message structure
struct HTTPRequestMessage {
  string method;
  string url;
  string body;
  unordered_map<string, string> headers;
};

// Define the REST API client class
class RESTAPIClient {
public:
  // Constructor to initialize the client with a given endpoint URL
  RESTAPIClient(const string& endpoint) : _endpoint(endpoint) {}

  // Function to send an HTTP request and return the response
  unique_ptr<HTTPResponseMessage> sendRequest(const HTTPRequestMessage& request);

private:
  // Endpoint URL for the REST API
  const string _endpoint;
};

// Define the request queue data structure
struct RequestQueue {
  vector<HTTPRequestMessage> requests;
  mutex mtx;
};

// Define the component class that manages the dynamic collection of HTTP_REQUEST_MESSAGE objects within a microservices architecture
class HTTPRequestManager {
public:
  // Constructor to initialize the component with a given configuration and external REST API clients
  HTTPRequestManager(const Configuration& config, const vector<unique_ptr<RESTAPIClient>>& clients);

  // Function to add an HTTP request message to the queue
  void addRequest(const HTTPRequestMessage& request);

  // Function to remove an HTTP request message from the queue
  unique_ptr<HTTPResponseMessage> removeRequest();

private:
  // Configuration for the component
  const Configuration _config;

  // Vector of external REST API clients
  const vector<unique_ptr<RESTAPIClient>> _clients;

  // Request queue data structure
  RequestQueue _requestQueue;

  // Mutex to protect the request queue from concurrent access
  mutex _mtx;
};

// Implementation of the component class
HTTPRequestManager::HTTPRequestManager(const Configuration& config, const vector<unique_ptr<RESTAPIClient>>& clients)
    : _config(config), _clients(clients) {}

void HTTPRequestManager::addRequest(const HTTPRequestMessage& request) {
  unique_lock<mutex> lock(_mtx);
  _requestQueue.requests.push_back(request);
}

unique_ptr<HTTPResponseMessage> HTTPRequestManager::removeRequest() {
  unique_lock<mutex> lock(_mtx);

  // Check if there are any requests in the queue
  if (_requestQueue.requests.empty()) {
    return nullptr;
  }

  // Remove the first request from the queue and send it to the REST API client
  HTTPRequestMessage request = _requestQueue.requests.front();
  _requestQueue.requests.pop_front();
  unique_ptr<HTTPResponseMessage> response = _clients[0]->sendRequest(request);

  // Return the response to the caller
  return response;
}
