['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <limits.h>
#include <time.h>
#include <pthread.h>
#include "metadata_service.h"

// Maximum length of a website name and version string
#define MAX_SITE_NAME_LEN 255

// Maximum number of concurrently handled websites
#define MAX_WEBSITES 10000

// Directory where website configurations are stored
const char* config_dir = "/path/to/configs";

// Lock to ensure thread-safe access to the metadata service
pthread_mutex_t metadata_lock;

// Map of website names and their corresponding versions
struct WebsiteVersion {
    char name[MAX_SITE_NAME_LEN];
    int version;
};

// Map of website names and their corresponding configurations
struct WebsiteConfig {
    char name[MAX_SITE_NAME_LEN];
    char* config;
};

// Function to add a new website configuration with the specified version
int addWebsiteWithVersion(const char* site_name, int version) {
    // Check if the website already exists
    struct WebsiteConfig* existing_config = get_website_config(site_name);
    if (existing_config != NULL) {
        return -1;
    }

    // Create a new configuration file for the website
    char config_file[MAX_SITE_NAME_LEN + 20];
    sprintf(config_file, "%s/%s-%d.conf", config_dir, site_name, version);
    FILE* fp = fopen(config_file, "w");
    if (fp == NULL) {
        return -1;
    }

    // Write the configuration to the file
    fprintf(fp, "%s-%d", site_name, version);
    fclose(fp);

    // Add the new website to the metadata service
    add_website_to_metadata_service(site_name, version);

    return 0;
}

// Function to retrieve a website configuration by name and version
char* get_website_config(const char* site_name) {
    // Check if the website exists in the metadata service
    struct WebsiteConfig* config = get_website_config_from_metadata_service(site_name);
    if (config == NULL) {
        return NULL;
    }

    // Open the configuration file
    char config_file[MAX_SITE_NAME_LEN + 20];
    sprintf(config_file, "%s/%s-%d.conf", config_dir, site_name, config->version);
    FILE* fp = fopen(config_file, "r");
    if (fp == NULL) {
        return NULL;
    }

    // Read the configuration from the file
    char* config_data = malloc(sizeof(char)*MAX_SITE_NAME_LEN);
    fread(config_data, sizeof(char), MAX_SITE_NAME_LEN, fp);
    fclose(fp);

    return config_data;
}

// Function to delete a website configuration by name and version
int delete_website_config(const char* site_name) {
    // Check if the website exists in the metadata service
    struct WebsiteConfig* config = get_website_config_from_metadata_service(site_name);
    if (config == NULL) {
        return -1;
    }

    // Delete the configuration file
    char config_file[MAX_SITE_NAME_LEN + 20];
    sprintf(config_file, "%s/%s-%d.conf", config_dir, site_name, config->version);
    int ret = remove(config_file);
    if (ret != 0) {
        return -1;
    }

    // Delete the website from the metadata service
    delete_website_from_metadata_service(site_name);

    return 0;
}

// Function to handle conflicts by appending timestamps or counters
int conflict_resolution(const char* site_name, int version) {
    // Check if the website already exists in the metadata service
    struct WebsiteConfig* existing_config = get_website_config_from_metadata_service(site_name);
    if (existing_config == NULL) {
        return -1;
    }

    // If the version is different from the existing configuration, append a timestamp or counter
    if (version != existing_config->version) {
        // Append a timestamp to the website name
        struct tm current_time = *localtime(&time(NULL));
        char* timestamp_str = asctime(&current_time);
        char new_name[MAX_SITE_NAME_LEN + 20];
        sprintf(new_name, "%s-%s", site_name, timestamp_str);

        // Create a new configuration file for the website
        char config_file[MAX_SITE_NAME_LEN + 20];
        sprintf(config_file, "%s/%s.conf", config_dir, new_name);
        FILE* fp = fopen(config_file, "w");
        if (fp == NULL) {
            return -1;
        }

        // Write the configuration to the file
        fprintf(fp, "%s-%d", site_name, version);
        fclose(fp);

        // Add the new website to the metadata service
        add_website_to_metadata_service(new_name, version);
    }

    return 0;
}

// Function to check if a website exists in the metadata service
struct WebsiteConfig* get_website_config_from_metadata_service(const char* site_name) {
    // Lock the metadata service
    lock(&metadata_lock);

    // Check if the website exists in the metadata service
    struct WebsiteConfig* config = NULL;
    for (struct WebsiteConfig* current = metadata_head; current != NULL; current = current->next) {
        if (strcmp(current->site_name, site_name) == 0) {
            config = current;
            break;
        }
    }

    // Unlock the metadata service
    unlock(&metadata_lock);

    return config;
}

// Function to add a website to the metadata service
void add_website_to_metadata_service(const char* site_name, int version) {
    // Lock the metadata service
    lock(&metadata_lock);

    // Create a new website configuration entry
    struct WebsiteConfig* config = malloc(sizeof(struct WebsiteConfig));
    config->site_name = site_name;
    config->version = version;

    // Add the website to the metadata service
    if (metadata_head == NULL) {
        metadata_head = config;
    } else {
        struct WebsiteConfig* current = metadata_head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = config;
    }

    // Unlock the metadata service
    unlock(&metadata_lock);
}

// Function to delete a website from the metadata service
void delete_website_from_metadata_service(const char* site_name) {
    // Lock the metadata service
    lock(&metadata_lock);

    // Check if the website exists in the metadata service
    struct WebsiteConfig* config = get_website_config_from_metadata_service(site_name);
    if (config == NULL) {
        unlock(&metadata_lock);
        return;
    }

    // Remove the website from the metadata service
    if (metadata_head == config) {
        metadata_head = config->next;
    } else {
        struct WebsiteConfig* current = metadata_head;
        while (current != NULL && current->next != config) {
            current = current->next;
        }
        if (current != NULL) {
            current->next = config->next;
        }
    }

    // Unlock the metadata service
    unlock(&metadata_lock);
}
```

