public class TransactionProcessor {
  private static final Logger logger = Logger.getLogger(TransactionProcessor.class);

  // Configuration properties
  private static final String KAFKA_BOOTSTRAP_SERVERS = "localhost:9092";
  private static final String KAFKA_TOPIC = "transactions";
  private static final String CONSUMER_GROUP_ID = "transaction-processor";
  private static final String PRODUCER_CLIENT_ID = "transaction-producer";
  private static final String JSON_FORMAT = "json";
  private static final String XML_FORMAT = "xml";
  private static final String AVRO_FORMAT = "avro";

  // Data formats
  private static final Pattern JSON_PATTERN = Pattern.compile("\\{\\s*\"amount\":([0-9.]+)\\s*,\\s*\"currency\":\\s*\".+\"\\s*\\}");
  private static final Pattern XML_PATTERN = Pattern.compile("<transaction>\\s*<amount>([0-9.]+)</amount>\\s*<currency>\\s*[^<]+\\s*</currency>\\s*</transaction>");
  private static final Schema AVRO_SCHEMA = new Schema.Parser().parse("{\"type\":\"record\", \"name\":\"Transaction\", \"fields\":[{\"name\":\"amount\",\"type\":\"double\"}, {\"name\":\"currency\",\"type\":\"string\"}]}");
  private static final int TRANSACTION_AMOUNT_THRESHOLD = 100;
  private static final long TRANSACTION_TIMEOUT = TimeUnit.SECONDS.toMillis(3);

  // Statistics
  private static final AtomicInteger transactionCount = new AtomicInteger();
  private static final AtomicInteger filteredTransactionCount = new AtomicInteger();
  private static final AtomicInteger successfulProcessingTime = new AtomicInteger();
  private static final AtomicInteger failedProcessingTime = new AtomicInteger();

  public static void main(String[] args) {
    // Initialize Kafka consumer and producer
    Properties props = new Properties();
    props.put(ConsumerConfig.BOOTSTRAP_SERVERS_CONFIG, KAFKA_BOOTSTRAP_SERVERS);
    props.put(ConsumerConfig.GROUP_ID_CONFIG, CONSUMER_GROUP_ID);
    props.put(ConsumerConfig.CLIENT_ID_CONFIG, PRODUCER_CLIENT_ID);
    KafkaConsumer<String, String> consumer = new KafkaConsumer<>(props);

    // Subscribe to Kafka topic
    consumer.subscribe(Collections.singletonList(KAFKA_TOPIC));

    // Initialize C# function for computing MD5 hashes
    CSharpFunction csharpFunction = new CSharpFunction();

    // Run the main loop
    while (true) {
      ConsumerRecords<String, String> records = consumer.poll(Duration.ofMillis(100));
      for (ConsumerRecord<String, String> record : records) {
        processTransaction(record.value(), csharpFunction);
      }
    }
  }

  private static void processTransaction(String transaction, CSharpFunction csharpFunction) {
    // Filter transactions based on age, frequency within the last 3 seconds, a weighted sum threshold, and geolocation, with parameters adjustable in real-time through a secure administrative interface.
    if (isOldTransaction(transaction)) {
      logger.info("Skipping old transaction: " + transaction);
      return;
    }
    if (!meetsFrequencyThreshold(transaction)) {
      logger.info("Skipping transaction with low frequency: " + transaction);
      return;
    }
    if (getWeightedSum(transaction) < TRANSACTION_AMOUNT_THRESHOLD) {
      logger.info("Skipping transaction with low weighted sum: " + transaction);
      return;
    }
    if (!isWithinGeolocationRange(transaction)) {
      logger.info("Skipping transaction outside of geolocation range: " + transaction);
      return;
    }

    // Increment statistics
    transactionCount.incrementAndGet();

    // Compute MD5 hash for filtering and analytics
    String md5Hash = DigestUtils.md5Hex(transaction);

    // Filter transactions based on MD5 hash
    if (csharpFunction.isFiltered(md5Hash)) {
      logger.info("Skipping filtered transaction: " + transaction);
      return;
    }

    // Increment statistics
    filteredTransactionCount.incrementAndGet();

    // Process transaction
    long startTime = System.currentTimeMillis();
    try {
      processTransactionImpl(transaction);
      successfulProcessingTime.addAndGet(System.currentTimeMillis() - startTime);
    } catch (Exception e) {
      logger.error("Error processing transaction: " + transaction, e);
      failedProcessingTime.addAndGet(System.currentTimeMillis() - startTime);
    }
  }

  private static void processTransactionImpl(String transaction) throws Exception {
    // Deserialize transaction data based on format
    JsonObject json = null;
    XmlDocument xml = null;
    GenericData avro = null;
    switch (getFormat()) {
      case JSON_FORMAT:
        json = getJsonObject(transaction);
        break;
      case XML_FORMAT:
        xml = getXmlDocument(transaction);
        break;
      case AVRO_FORMAT:
        avro = getGenericData(transaction);
        break;
    }

    // Validate transaction data
    if (json != null) {
      validateJsonObject(json);
    } else if (xml != null) {
      validateXmlDocument(xml);
    } else if (avro != null) {
      validateGenericData(avro);
    }

    // Persist transaction data
    persistTransactionData(transaction, json, xml, avro);
  }

  private static JsonObject getJsonObject(String transaction) throws Exception {
    return new Gson().fromJson(transaction, JsonObject.class);
  }

  private static XmlDocument getXmlDocument(String transaction) throws Exception {
    // Use C# function to parse XML
    String xmlString = csharpFunction.parseXml(transaction);
    return new XmlDocument();
  }

  private static GenericData getGenericData(String transaction) throws Exception {
    // Use Avro schema to deserialize data
    BinaryDecoder decoder = null;
    try (ByteArrayOutputStream outputStream = new ByteArrayOutputStream()) {
      DatumWriter<GenericData> datumWriter = null;
      GenericData avro = null;
      try {
        // Serialize transaction data to Avro format using C# function
        csharpFunction.serializeAvro(transaction, outputStream);

        // Create decoder for Avro data
        decoder = DecoderFactory.get().binaryDecoder(outputStream.toByteArray(), null);

        // Deserialize Avro data using schema
        datumWriter = new GenericDatumWriter<>(AVRO_SCHEMA);
        avro = datumWriter.read(null, decoder);
      } catch (Exception e) {
        logger.error("Error deserializing transaction: " + transaction, e);
        throw e;
      } finally {
        // Close resources
        if (datumWriter != null) {
          datumWriter.close();
        }
        if (decoder != null) {
          decoder.close();
        }
      }
    } catch (Exception e) {
      logger.error("Error deserializing transaction: " + transaction, e);
      throw e;
    }
    return avro;
  }

  private static void validateJsonObject(JsonObject json) throws Exception {
    // Validate JSON schema using C# function
    csharpFunction.validateJsonSchema(json);
  }

  private static void validateXmlDocument(XmlDocument xml) throws Exception {
    // Validate XML schema using C# function
    csharpFunction.validateXmlSchema(xml);
  }

  private static void validateGenericData(GenericData avro) throws Exception {
    // Validate Avro schema using C# function
    csharpFunction.validateAvroSchema(avro);
  }

  private static void persistTransactionData(String transaction, JsonObject json, XmlDocument xml, GenericData avro) throws Exception {
    // Persist transaction data to database or file system using C# function
    String data = csharpFunction.persistTransactionData(transaction, json, xml, avro);
  }

  private static boolean isOldTransaction(String transaction) {
    // Check if transaction is too old based on the TRANSACTION_TIMEOUT parameter
    return System.currentTimeMillis() - getTimestamp(transaction) > TRANSACTION_TIMEOUT;
  }

  private static long getTimestamp(String transaction) throws Exception {
