#include <iostream>
#include <vector>
#include <mutex>
#include <thread>
#include <condition_variable>
#include <chrono>
#include <random>
#include <future>
#include <algorithm>
#include <numeric>
#include <memory>
#include <string>
#include <unordered_map>
#include <utility>
#include <type_traits>

// Define the data structure to store a TCP packet buffer
struct PacketBuffer {
    std::vector<char> data;
    bool is_allocated = false;
};

// Define the class for managing the pool of TCP packet buffers
class BufferPool {
private:
    // Vector of available buffer objects
    std::vector<PacketBuffer*> available_buffers_;

    // Vector of allocated but not yet used buffer objects
    std::vector<PacketBuffer*> allocated_buffers_;

    // Mutex for protecting the pool access
    std::mutex mutex_;

    // Condition variable for waiting on buffers to become available
    std::condition_variable cv_;

    // Minimum and maximum number of buffers in the pool
    size_t min_buffer_count_, max_buffer_count_;

    // Current number of buffers in use
    size_t buffer_count_;

    // Maximum allowed memory usage
    size_t max_memory_usage_;

    // Memory usage tracking
    size_t current_memory_usage_ = 0;

public:
    BufferPool(size_t min_buffer_count, size_t max_buffer_count, size_t max_memory_usage) :
        min_buffer_count_(min_buffer_count),
        max_buffer_count_(max_buffer_count),
        buffer_count_(0),
        current_memory_usage_(0),
        max_memory_usage_(max_memory_usage) {}

    ~BufferPool() {
        for (auto* buffer : available_buffers_) {
            delete buffer;
        }

        for (auto* buffer : allocated_buffers_) {
            delete buffer;
        }
    }

    // Allocate a new buffer object
    PacketBuffer* allocate() {
        std::unique_lock<std::mutex> lock(mutex_);

        while (available_buffers_.empty()) {
            cv_.wait(lock);
        }

        auto* buffer = available_buffers_.back();
        available_buffers_.pop_back();
        allocated_buffers_.push_back(buffer);
        ++buffer_count_;
        current_memory_usage_ += buffer->data.size();
        return buffer;
    }

    // Release a buffer object to the pool
    void release(PacketBuffer* buffer) {
        std::unique_lock<std::mutex> lock(mutex_);

        if (buffer->is_allocated) {
            auto it = std::find(allocated_buffers_.begin(), allocated_buffers_.end(), buffer);
            if (it != allocated_buffers_.end()) {
                *it = allocated_buffers_.back();
                allocated_buffers_.pop_back();
                --buffer_count_;
                current_memory_usage_ -= buffer->data.size();
            } else {
                // The buffer has already been released before, do nothing
                return;
            }
        }

        available_buffers_.push_back(buffer);
        cv_.notify_one();
    }

    // Return the current number of buffers in use
    size_t getBufferCount() {
        std::unique_lock<std::mutex> lock(mutex_);
        return buffer_count_;
    }

    // Return the current memory usage
    size_t getCurrentMemoryUsage() {
        std::unique_lock<std::mutex> lock(mutex_);
        return current_memory_usage_;
    }
};

// Define the class for managing a multi-cloud storage system
class MultiCloudStorageSystem {
private:
    // Vector of buffer pools, one per cloud provider
    std::vector<BufferPool> buffer_pools_;

    // Map of external service endpoints and corresponding buffer pools
    std::unordered_map<std::string, BufferPool*> service_endpoints_;

    // Vector of thread objects for serving incoming requests
    std::vector<std::thread> threads_;

    // Mutex for protecting the threads access
    std::mutex mutex_;

    // Condition variable for waiting on available buffers
    std::condition_variable cv_;

    // Minimum and maximum number of threads in the system
    size_t min_thread_count_, max_thread_count_;

    // Current number of threads in use
    size_t thread_count_;

    // Maximum allowed memory usage for all buffer pools
    size_t max_memory_usage_;

public:
    MultiCloudStorageSystem(size_t min_thread_count, size_t max_thread_count, size_t max_memory_usage) :
        min_thread_count_(min_thread_count),
        max_thread_count_(max_thread_count),
        thread_count_(0),
        max_memory_usage_(max_memory_usage) {}

    ~MultiCloudStorageSystem() {
        for (auto& buffer_pool : buffer_pools_) {
            delete &buffer_pool;
        }

        for (auto& thread : threads_) {
            if (thread.joinable()) {
                thread.join();
            }
        }
    }

    // Start the system and begin serving incoming requests
    void start() {
        std::unique_lock<std::mutex> lock(mutex_);

        while (buffer_pools_.size() < service_endpoints_.size()) {
            buffer_pools_.emplace_back(10, 1000, max_memory_usage_ / 2);
        }

        for (size_t i = 0; i < buffer_pools_.size(); ++i) {
            threads_.push_back(std::thread(&BufferPool::run, &buffer_pools_[i]));
        }
    }

    // Stop the system and end serving incoming requests
    void stop() {
        std::unique_lock<std::mutex> lock(mutex_);

        for (auto& thread : threads_) {
            if (thread.joinable()) {
                thread.join();
            }
        }

        buffer_pools_.clear();
    }

    // Register an external service endpoint with the system
    void registerServiceEndpoint(const std::string& name, const std::string& url) {
        std::unique_lock<std::mutex> lock(mutex_);

        if (service_endpoints_.find(name) != service_endpoints_.end()) {
            throw std::runtime_error("Service endpoint already registered");
        }

        auto& buffer_pool = buffer_pools_[buffer_pools_.size() - 1];
        service_endpoints_[name] = &buffer_pool;
    }

    // Unregister an external service endpoint with the system
    void unregisterServiceEndpoint(const std::string& name) {
        std::unique_lock<std::mutex> lock(mutex_);

        auto it = service_endpoints_.find(name);
        if (it == service_endpoints_.end()) {
            throw std::runtime_error("Service endpoint not registered");
        }

        service_endpoints_.erase(it);
    }

    // Submit a request to the system
    void submitRequest(const std::string& name, const std::string& data) {
        std::unique_lock<std::mutex> lock(mutex_);

        auto it = service_endpoints_.find(name);
        if (it == service_endpoints_.end()) {
            throw std::runtime_error("Service endpoint not registered");
        }

        auto* buffer_pool = it->second;
        Packet packet;
        packet.data = data;
        buffer_pool->submitRequest(packet);
    }
};

// Define a class for handling incoming requests and submitting them to the appropriate service endpoint
class RequestHandler {
private:
    MultiCloudStorageSystem& system_;

public:
    RequestHandler(MultiCloudStorageSystem& system) : system_(system) {}

    // Handle an incoming request by submitting it to the appropriate service endpoint
    void handleRequest(const std::string& name, const std::string& data) {
        std::unique_lock<std::mutex> lock(system_.mutex_);

        system_.submitRequest(name, data);
    }
};

// Define a class for handling outgoing responses and returning them to the appropriate client
class ResponseHandler {
private:
    MultiCloudStorageSystem& system_;

public:
    ResponseHandler(MultiCloudStorageSystem& system) : system_(system) {}

    // Handle an incoming response by returning it to the appropriate client
    void handleResponse(const std::string& name, const std::string& data) {
        std::unique_lock<std::mutex> lock(system_.mutex_);

        system_.releaseBuffer(name, data);
    }
};']

