import java.io.*;

public class RuntimeExecExample {
    public static void main(String[] args) {
        try {
            // Create a new process builder
            ProcessBuilder pb = new ProcessBuilder("command", "arg1", "arg2");

            // Set the working directory to /home/user
            pb.directory(new File("/home/user"));

            // Redirect output and error streams to files
            pb.redirectOutput(Redirect.appendTo(new File("output.txt")));
            pb.redirectError(Redirect.appendTo(new File("error.txt")));

            // Start the process
            Process p = pb.start();

            // Read output and error streams to variables
            InputStream outputStream = p.getInputStream();
            InputStream errorStream = p.getErrorStream();

            // Close the input streams after reading them fully
            outputStream.close();
            errorStream.close();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
