#include <iostream>
#include <string>
#include <map>
#include <set>
#include <fstream>
#include <sstream>
#include <chrono>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <cstdlib>
#include <vector>
#include <algorithm>
#include <sys/stat.h>
#include <unistd.h>

using namespace std;

// Semaphore class to manage concurrent access to website configurations
class Semaphore {
public:
    Semaphore(int initialValue) : value(initialValue) {}
    ~Semaphore() = default;

    void lock() {
        unique_lock<mutex> lck(mtx);
        while (value <= 0) {
            condVar.wait(lck);
        }
        --value;
    }

    void unlock() {
        unique_lock<mutex> lck(mtx);
        ++value;
        condVar.notify_all();
    }

private:
    int value = 0;
    mutex mtx;
    condition_variable condVar;
};

// Function to create a semaphore with the specified initial value
Semaphore* createSemaphore(int initialValue) {
    return new Semaphore(initialValue);
}

// Function to delete a semaphore
void deleteSemaphore(Semaphore* semaphore) {
    delete semaphore;
}

// Class to handle website configurations and metadata
class WebsiteConfigurations {
public:
    // Constructor
    WebsiteConfigurations() {}

    // Destructor
    ~WebsiteConfigurations() = default;

    // Adds a new website configuration with the specified version and environment
    void addWebsiteWithVersion(const string& siteName, const string& version, const string& env) {
        Semaphore* semaphore = createSemaphore(1);
        semaphore->lock();
        try {
            // Ensure the website configuration is unique and does not exist already
            if (configurations.find(siteName) != configurations.end()) {
                throw invalid_argument("Website configuration already exists");
            }

            // Generate a unique filename for the website configuration
            string filename = generateFilename(siteName, version);

            // Store the website configuration and metadata in the specified directory
            storeConfiguration(filename, siteName, version, env);

            // Add the website configuration to the map of configurations
            configurations[siteName] = {filename, env};
        } catch (const exception& e) {
            delete semaphore;
            throw e;
        }
        semaphore->unlock();
    }

    // Retrieves a website configuration by name and environment
    pair<string, string> getWebsiteConfiguration(const string& siteName, const string& env) {
        Semaphore* semaphore = createSemaphore(1);
        semaphore->lock();
        try {
            // Ensure the website configuration exists
            if (configurations.find(siteName) == configurations.end()) {
                throw invalid_argument("Website configuration does not exist");
            }

            // Get the filename and environment for the website configuration
            pair<string, string> config = configurations[siteName];

            // Return the website configuration
            return config;
        } catch (const exception& e) {
            delete semaphore;
            throw e;
        }
        semaphore->unlock();
    }

private:
    // Map of website configurations and metadata
    map<string, pair<string, string>> configurations;

    // Generates a unique filename for the website configuration
    string generateFilename(const string& siteName, const string& version) {
        // Get the current timestamp
        time_t t = chrono::system_clock::to_time_t(chrono::system_clock::now());
        struct tm tm = *localtime(&t);
        string filename = to_string(tm.tm_sec) + "-" + to_string(tm.tm_min) + "-" + to_string(tm.tm_hour) + "-" + to_string(tm.tm_mday) + "-" + to_string(tm.tm_mon) + "-" + to_string(tm.tm_year);
        filename += "-";
        if (version.empty()) {
            filename += "v1-";
        } else {
            filename += version + "-";
        }
        filename += siteName;
        return filename;
    }

    // Stores the website configuration and metadata in the specified directory
    void storeConfiguration(const string& filename, const string& siteName, const string& version, const string& env) {
        // Create a new file with the generated filename
        ofstream file(filename);

        // Write the website configuration and metadata to the file
        file << "Website: " << siteName << endl;
        file << "Version: " << version << endl;
        file << "Environment: " << env << endl;

        // Close the file
        file.close();
    }
};
