using namespace std;

// Custom allocator for memory pooling
class MemoryPool {
public:
  MemoryPool(size_t size) : size_(size), freeList_{} {}

  void* allocate() {
    if (freeList_.empty()) {
      return new char[size_];
    } else {
      auto block = freeList_.back();
      freeList_.pop_back();
      return block;
    }
  }

  void deallocate(void* block) {
    freeList_.push_back(block);
  }

private:
  size_t size_;
  vector<char*> freeList_;
};

// Custom memory pool for data processing
class DataPool : public MemoryPool {
public:
  DataPool() : MemoryPool(1024 * 1024) {}

  void* allocate(size_t size) override {
    if (freeList_.empty()) {
      return new char[size];
