        if len(self.bundles) >= MAX_ROUTE_COUNT:
            return False
        else:
            self.bundles[len(self.bundles)] = (pattern, bundle)
            return True

class MessageBroker:
    def __init__(self):
        self.router = MessageRouter()
        self.incoming_queue = []

    def send(self, message):
        if len(self.incoming_queue) >= MAX_MESSAGE_COUNT:
            return False
        else:
            self.incoming_queue.append(message)
            return True

    def receive(self):
        if len(self.incoming_queue) <= 0:
            return None
        else:
            message = self.incoming_queue[0]
            del self.incoming_queue[0]
            return message
