const fs = require('fs');
const crypto = require('crypto');
const stream = require('stream');
const { createHash } = require('crypto');

class FileProcessor {
  constructor() {
    this.hashAlgorithm = 'MD5';
    this.hashValue = null;
    this.fileStream = null;
  }

  async processFile(filePath) {
    this.fileStream = fs.createReadStream(filePath);
    this.hashValue = createHash(this.hashAlgorithm).update(this.fileStream);
    return this.hashValue.digest('hex');
  }

  async processFileWithRetry(filePath) {
    let retryCount = 0;
    while (retryCount < 3) {
      try {
        const hashValue = await this.processFile(filePath);
        return hashValue;
      } catch (error) {
        console.log(`Error processing file: ${error}`);
        retryCount++;
        await new Promise((resolve) => setTimeout(resolve, 1000));
      }
    }
    throw new Error('Maximum retries exceeded');
  }
}
