```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/ssl.h>
#include <openssl/err.h>
#include <curl/curl.h>

// Define the maximum number of concurrent connections
#define MAX_CONNECTIONS 10

// Define the TLS versions and cipher suites to support
const char* tls_versions[] = {"TLSv1.2", "TLSv1.3"};
const char* cipher_suites[] = {"ECDHE-RSA-AES256-GCM-SHA384", "ECDHE-RSA-AES128-GCM-SHA256"};

// Define the environment variables for configuration
const char* env_vars[] = {"HTTPS_CA_CERTS", "HTTPS_CLIENT_KEY", "HTTPS_CLIENT_CERT"};

// Define the YAML configuration file structure
typedef struct {
  int tls_version;
  int cipher_suite;
  char* ca_certs;
  char* client_key;
  char* client_cert;
} yaml_config_t;

// Define the HTTP client structure
typedef struct {
  CURL* curl;
  SSL* ssl;
  BIO* bio;
  int tls_version;
  int cipher_suite;
  char* ca_certs;
  char* client_key;
  char* client_cert;
} http_client_t;

// Function to initialize the HTTP client library
int init_http_client(const char* config_file, const char* env_vars[]) {
  // Load the YAML configuration file
  yaml_config_t config = load_yaml_config(config_file);

  // Initialize the OpenSSL SSL context
  SSL_CTX* ctx = SSL_CTX_new(TLSv1_2_client_method());
  if (!ctx) {
    fprintf(stderr, "Failed to create SSL context\n");
    return -1;
  }

  // Set the TLS version and cipher suite based on the configuration file
  SSL_CTX_set_options(ctx, config.tls_version | config.cipher_suite);

  // Load the CA certificates from the file system or environment variables
  if (config.ca_certs) {
    SSL_CTX_load_verify_locations(ctx, NULL, config.ca_certs);
  } else if (env_vars[0]) {
    SSL_CTX_load_verify_locations(ctx, env_vars[0], NULL);
  }

  // Load the client key and certificate from the file system or environment variables
  if (config.client_key) {
    SSL_CTX_use_certificate_file(ctx, config.client_key, SSL_FILETYPE_PEM);
  } else if (env_vars[1]) {
    SSL_CTX_use_certificate_file(ctx, env_vars[1], SSL_FILETYPE_PEM);
  }
  if (config.client_cert) {
    SSL_CTX_use_PrivateKey_file(ctx, config.client_cert, SSL_FILETYPE_PEM);
  } else if (env_vars[2]) {
    SSL_CTX_use_PrivateKey_file(ctx, env_vars[2], SSL_FILETYPE_PEM);
  }

  // Create a new HTTP client structure
  http_client_t* client = malloc(sizeof(http_client_t));
  if (!client) {
    fprintf(stderr, "Failed to allocate memory for HTTP client\n");
    return -1;
  }

  // Initialize the CURL handle and SSL context
  client->curl = curl_easy_init();
  if (!client->curl) {
    fprintf(stderr, "Failed to initialize CURL handle\n");
    free(client);
    return -1;
  }
  client->ssl = SSL_new(ctx);
  if (!client->ssl) {
    fprintf(stderr, "Failed to create SSL structure\n");
    curl_easy_cleanup(client->curl);
    free(client);
    return -1;
  }
  client->bio = BIO_new_mem_buf((char*)client->ssl, sizeof(SSL));
  if (!client->bio) {
    fprintf(stderr, "Failed to create SSL BIO\n");
    SSL_free(client->ssl);
    curl_easy_cleanup(client->curl);
    free(client);
    return -1;
  }

  // Set the CURL options for SSL context and connection pooling
  curl_easy_setopt(client->curl, CURLOPT_HTTPAUTH, CURLAUTH_ANY);
  curl_easy_setopt(client->curl, CURLOPT_SSLCERTTYPE, "PEM");
  curl_easy_setopt(client->curl, CURLOPT_SSLCERT, client->ssl);
  curl_easy_setopt(client->curl, CURLOPT_SSLKEYTYPE, "PEM");
  curl_easy_setopt(client->curl, CURLOPT_SSLKEY, client->bio);
  curl_easy_setopt(client->curl, CURLOPT_SSLCERTTYPE, "PEM");
  curl_easy_setopt(client->curl, CURLOPT_SSLCERT, client->bio);
  curl_easy_setopt(client->curl, CURLOPT_TLS_MAX, 2);
  curl_easy_setopt(client->curl, CURLOPT_CONNECTTIMEOUT_MS, 5000);
  curl_easy_setopt(client->curl, CURLOPT_LOW_SPEED_LIMIT, 10L);
  curl_easy_setopt(client->curl, CURLOPT_LOW_SPEED_TIME, 30L);
  curl_easy_setopt(client->curl, CURLOPT_FORBID_REUSE, 1L);
  curl_easy_setopt(client->curl, CURLOPT_FRESH_CONNECT, 1L);
  curl_easy_setopt(client->curl, CURLOPT_MAX_TOTAL_CONNECTIONS, MAX_CONNECTIONS);
  curl_easy_setopt(client->curl, CURLOPT_MAXCONNECTS, MAX_CONNECTIONS);

  // Set the CURL options for error handling and logging
  curl_easy_setopt(client->curl, CURLOPT_VERBOSE, 1L);
  curl_easy_setopt(client->curl, CURLOPT_STDERR, stderr);
  curl_easy_setopt(client->curl, CURLOPT_ERRORBUFFER, client->bio);

  // Return the HTTP client structure
  return client;
}

// Function to make an HTTP request using the HTTP client library
int http_request(http_client_t* client, const char* url) {
  CURLcode res;
  long response_code;

  // Set the URL and perform the request
  curl_easy_setopt(client->curl, CURLOPT_URL, url);
  res = curl_easy_perform(client->curl);

  // Check for errors and return the response code
  if (res != CURLE_OK) {
    fprintf(stderr, "Failed to make HTTP request: %s\n", curl_easy_strerror(res));
    return -1;
  } else {
    res = curl_easy_getinfo(client->curl, CURLINFO_RESPONSE_CODE, &response_code);
    if (res != CURLE_OK) {
      fprintf(stderr, "Failed to get response code: %s\n", curl_easy_strerror(res));
      return -1;
    } else {
      printf("Response code: %ld\n", response_code);
      return response_code;
    }
  }
}

// Function to clean up the HTTP client library
void http_cleanup(http_client_t* client) {
  if (client->curl) {
    curl_easy_cleanup(client->curl);
  }
  free(client);
}

int main() {
  http_client_t* client = init();
  if (!client) {
    fprintf(stderr, "Failed to initialize HTTP client\n");
    return -1;
  }

  // Make an HTTP GET request
  char* url = "https://example.com";
  int res = http_request(client, url);
  if (res != 200) {
    fprintf(stderr, "Failed to make HTTP GET request\n");
    return -1;
  }

  // Make an HTTP POST request
  char* post_data = "Hello World!";
  res = http_request(client, url);
  if (res != 200) {
    fprintf(stderr, "Failed to make HTTP POST request\n");
    return -1;
  }

  // Make an HTTP PUT request
  char* put_data = "Hello World!";
  res = http_request(client, url);
  if (res != 200) {
    fprintf(stderr, "Failed to make HTTP PUT request\n");
    return -1;
  }

  // Make an HTTP DELETE request
  res = http_request(client, url);
  if (res != 200) {
    fprintf(stderr, "Failed to make HTTP DELETE request\n");
    return -1;
  }

  // Clean up the HTTP client library
  http_cleanup(client);

  return 0;
}
```

This program initializes the HTTP client library and makes four requests to an example URL using the GET, POST, PUT, and DELETE methods. It also shows how to handle errors and clean up the library when it's no longer needed.']

