    fn commit_changes(&mut self, changes: &Vec<Change>) -> Result<(), Error> {
        for change in changes {
            match change {
                Change::Insert(key, value) => {
                    // Insert key-value pair into the cache
                    self.cache.insert(key, value);
                },
                Change::Update(key, new_value) => {
                    // Update key-value pair in the cache
                    self.cache.update(key, new_value);
                },
                Change::Delete(key) => {
                    // Delete key from the cache
                    self.cache.delete(key);
                },
            }
        }
        Ok(())
    }
}
