using System.Threading.Tasks;
using Microsoft.Extensions.Configuration;
using Newtonsoft.Json;
using RestSharp;
using Serilog;
using StackExchange.Redis;

public class FetchUserActivityStreamAsync : IAsyncRequestHandler<FetchUserActivityStreamRequest, List<UserActivity>>
{
    private readonly ILogger _logger;
    private readonly RedisClient _redisClient;
    private readonly RestClient _restClient;
    private readonly IConfiguration _configuration;

    public FetchUserActivityStreamAsync(ILogger logger, RedisClient redisClient, RestClient restClient, IConfiguration configuration)
    {
        _logger = logger;
        _redisClient = redisClient;
        _restClient = restClient;
        _configuration = configuration;
    }

    public async Task<List<UserActivity>> Handle(FetchUserActivityStreamRequest request, CancellationToken cancellationToken)
    {
        var userId = request.UserId;
        var activityType = request.ActivityType;

        // Retrieve user activity stream from cache if available
        var cachedActivities = await _redisClient.GetAsync<List<UserActivity>>($"user-activity:{userId}");
        if (cachedActivities != null)
        {
            return cachedActivities;
        }

        // Fetch user activity stream from external service if cache miss
        var activities = await GetUserActivityStreamFromExternalServiceAsync(userId, cancellationToken);

        // Cache user activity stream for future use
        await _redisClient.SetAsync($"user-activity:{userId}", activities);

        return activities;
    }

    private async Task<List<UserActivity>> GetUserActivityStreamFromExternalServiceAsync(Guid userId, CancellationToken cancellationToken)
    {
        var request = new RestRequest($"/users/{userId}/activity", Method.GET);
        var response = await _restClient.ExecuteTaskAsync(request, cancellationToken);

        if (response.IsSuccessful)
        {
            return JsonConvert.DeserializeObject<List<UserActivity>>(response.Content);
        }
        else
        {
            _logger.Error("Failed to fetch user activity stream from external service");
            throw new Exception("Failed to fetch user activity stream from external service");
        }
    }
}
```
