        [HttpGet("{tenantId}/{userId}/{key}")]
        public async Task<IActionResult> GetPreference(string tenantId, string userId, string key)
        {
            try
            {
                var preference = await _preferenceRepository.GetAsync(tenantId, userId, key);

                if (preference == null)
                    return NotFound();

                return Ok(preference);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, $"Failed to get preference for tenant {tenantId} and user {userId}: {ex.Message}");
                return StatusCode((int)HttpStatusCode.InternalServerError);
            }
