import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.LinkedBlockingQueue;
import java.util.concurrent.ThreadPoolExecutor;
import java.util.concurrent.TimeUnit;

public class NotificationService {
    private static final int CORE_POOL_SIZE = 5;
    private static final int MAX_POOL_SIZE = 10;
    private static final int QUEUE_CAPACITY = 1000;
    private static final long KEEP_ALIVE_TIME = 30;

    private ExecutorService executor;
    private LinkedBlockingQueue<Runnable> workQueue;

    public NotificationService() {
        this.executor = new ThreadPoolExecutor(CORE_POOL_SIZE, MAX_POOL_SIZE, KEEP_ALIVE_TIME, TimeUnit.SECONDS, workQueue);
    }

    public void submitNotification(Notification notification) {
        executor.submit(() -> {
            try {
                // Process notification and deliver to user
                // ...
            } catch (Exception e) {
                // Handle exception and log error message
                System.out.println("Error processing notification: " + e);
            }
        });
    }
}

class Notification {
    private String title;
    private String body;
    private int priority;
    private Date timestamp;

    public Notification(String title, String body, int priority, Date timestamp) {
        this.title = title;
        this.body = body;
        this.priority = priority;
        this.timestamp = timestamp;
    }

    // Getters and setters
}

class NotificationProcessor implements Runnable {
    private Notification notification;

