        ProductCatalog {
            products: HashMap::new(),
        }
    }

    fn add_product(&mut self, name: &str, description: &str) {
        let product = Product {
            name: name.to_string(),
            description: description.to_string()
        };
        self.products.insert(name.to_string(), product);
    }

    fn get_product(&self, name: &str) -> Option<&Product> {
        self.products.get(name)
    }
}

struct Product {
    name: String,
    description: String
}

fn main() {
    let catalog = Arc::new(Mutex::new(ProductCatalog::new()));

    // Create a new directory with the given name and set an environment variable to its path
    let dir_name = "my-dir";
    let env_var_name = "MY_DIR";
    if env::var(env_var_name).is_none() {
        fs::create_dir(dir_name).unwrap();
        env::set_var(env_var_name, dir_name);
    } else {
        let existing_dir = env::var(env_var_name).unwrap();
        if !PathBuf::from(&existing_dir).exists() {
            fs::create_dir(dir_name).unwrap();
            env::set_var(env_var_name, dir_name);
