import java.util.concurrent.*;
import org.apache.http.client.methods.HttpGet;
import org.apache.http.impl.client.CloseableHttpClient;
import org.apache.http.impl.client.HttpClients;
import com.google.gson.Gson;
import com.google.gson.JsonObject;

public class DynamicPaymentProcessor {
  private static final String BASE_URL = "https://api.paymentgateway.com";
  private static final String STRIPE_PATH = "/v1/payments/stripe";
  private static final String PAYPAL_PATH = "/v1/payments/paypal";
  private static final String BANK_TRANSFERS_PATH = "/v1/payments/bank-transfers";
  private static final String MERCHANT_ID = "merchant001";
  private static final String CARD_TOKEN = "cardtoken001";
  private static final String DIRECT_DEBIT_ACCOUNT = "account001";
  private static final String PAYPAL_EMAIL = "user@example.com";
  private static final int CONNECTION_TIMEOUT = 5000; // milliseconds
  private static final int READ_TIMEOUT = 5000; // milliseconds
  private static final int WRITE_TIMEOUT = 5000; // milliseconds
  private static final String METHOD_POST = "POST";
  private static final String METHOD_GET = "GET";
  private static final String HEADER_CONTENT_TYPE = "Content-Type";
  private static final String HEADER_ACCEPT = "Accept";
  private static final String HEADER_AUTHORIZATION = "Authorization";
  private static final String CONTENT_TYPE_JSON = "application/json";
  private static final String ACCEPT_JSON = "application/json";
  private static final String AUTH_TOKEN = "Bearer your-access-token";

  public void processPayment(String paymentType, float amount) throws IOException {
    CloseableHttpClient httpClient = HttpClients.createDefault();
    String url = BASE_URL + paymentType;
    Gson gson = new Gson();
    JsonObject json = new JsonObject();
    json.addProperty("amount", amount);

    switch (paymentType) {
      case "stripe":
        json.addProperty("cardToken", CARD_TOKEN);
        break;
      case "paypal":
        json.addProperty("email", PAYPAL_EMAIL);
        break;
      case "bank-transfers":
        json.addProperty("accountNumber", DIRECT_DEBIT_ACCOUNT);
        break;
    }

    HttpPost post = new HttpPost(url);
    post.setHeader(HEADER_CONTENT_TYPE, CONTENT_TYPE_JSON);
    post.setHeader(HEADER_ACCEPT, ACCEPT_JSON);
    post.setHeader(HEADER_AUTHORIZATION, AUTH_TOKEN);
    post.setEntity(new StringEntity(json.toString(), ContentType.APPLICATION_JSON));

    CloseableHttpResponse response = httpClient.execute(post);
    HttpEntity entity = response.getEntity();
    InputStream is = entity.getContent();
    JsonObject resultJson = gson.fromJson(is, JsonObject.class);
    String result = resultJson.get("result").toString();
    System.out.println("Payment result: " + result);
  }
}
```
