// Microservice for processing real-time data streams from IoT devices

package com.example.iot;

import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import org.apache.kafka.clients.consumer.ConsumerConfig;
import org.apache.kafka.clients.consumer.KafkaConsumer;
import org.json.JSONObject;
import com.google.protobuf.InvalidProtocolBufferException;
import com.example.iot.models.IotData;
import com.example.iot.services.DataProcessorService;
import com.example.iot.utils.KafkaUtils;

public class IoTDataProcessor {
    private static final String TOPIC_NAME = "iot-data";
    private static final String GROUP_ID = "iot-data-processor";
    private static final int CONCURRENCY = 10;

    public static void main(String[] args) throws Exception {
        ExecutorService executor = Executors.newFixedThreadPool(CONCURRENCY);
        KafkaConsumer<String, byte[]> consumer = KafkaUtils.createConsumer();
        DataProcessorService dataProcessorService = new DataProcessorService();

        consumer.subscribe(List.of(TOPIC_NAME));

        while (true) {
            ConsumerRecords<String, byte[]> records = consumer.poll(Duration.ofSeconds(1L));

            for (ConsumerRecord<String, byte[]> record : records) {
                String key = record.key();
                byte[] value = record.value();

                if (isJsonData(value)) {
                    processJsonData(dataProcessorService, key, value);
                } else if (isProtobufData(value)) {
                    processProtobufData(dataProcessorService, key, value);
                }
            }
        }
    }

    private static void processJsonData(DataProcessorService dataProcessorService, String key, byte[] value) throws Exception {
        JSONObject json = new JSONObject(new String(value));
        IotData iotData = json.toBean(IotData.class);
        dataProcessorService.processJsonData(iotData, key);
    }

    private static void processProtobufData(DataProcessorService dataProcessorService, String key, byte[] value) throws InvalidProtocolBufferException {
        IotData iotData = IotData.parseFrom(value);
        dataProcessorService.processProtobufData(iotData, key);
    }

    private static boolean isJsonData(byte[] value) {
        return value != null && value.length > 0;
    }

    private static boolean isProtobufData(byte[] value) {
        return value != null && value.length > 0;
    }
}

// DataProcessorService for processing IoT data

package com.example.iot.services;

import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.json.JSONObject;
import com.google.protobuf.InvalidProtocolBufferException;
import com.example.iot.models.IotData;
import com.example.iot.utils.ProtobufUtils;
import com.example.iot.utils.JsonUtils;

public class DataProcessorService {
    private final Map<String, IotData> dataMap = new HashMap<>();
    private final List<IotDataConsumer> consumers;

    public DataProcessorService(List<IotDataConsumer> consumers) {
        this.consumers = consumers;
    }

    public void processJsonData(IotData iotData, String key) {
        dataMap.put(key, iotData);
        notifyConsumers();
    }

    public void processProtobufData(IotData iotData, String key) throws InvalidProtocolBufferException {
        IotData parsedIotData = ProtobufUtils.parseIotData(iotData);
        dataMap.put(key, parsedIotData);
        notifyConsumers();
    }

    private void notifyConsumers() {
        consumers.forEach((consumer) -> consumer.consume(dataMap));
    }
}

// IotDataConsumer for consuming IoT data

package com.example.iot.services;

import java.util.List;
import org.json.JSONObject;
import com.google.protobuf.InvalidProtocolBufferException;
