```c++
#include <iostream>
#include <unordered_map>
#include <vector>
#include <string>
#include <fstream>
#include <chrono>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <json/json.h>
#include <curl/curl.h>
#include <pthread.h>

using namespace std;

// Define constants for API calls and configuration file
const string API_URL = "https://api.example.com";
const string CONFIG_FILE = "config.yaml";
const int MAX_RETRIES = 3;
const int RETRY_DELAY = 5000; // ms
const int MAX_CONCURRENT_REQUESTS = 10;
const int MIN_COOLDOWN = 2000; // ms
const int MAX_COOLDOWN = 60000; // ms

// Define types for API responses and configuration data
struct ApiResponse {
  string status;
  Json::Value data;
};

struct ConfigData {
  vector<string> strategies;
  unordered_map<string, int> cooldowns;
};

// Define a structure to represent the current state of the module
struct State {
  // Maintain a list of active attack strategies and their associated cooldown timestamps
  unordered_map<string, chrono::steady_clock::time_point> strategyCooldowns;

  // Maintain a vector of pending API requests and their associated response handlers
  vector<pair<ApiResponse, function<void(const ApiResponse&)>>> pendingRequests;

  // Maintain a mutex to protect concurrent access to the module's state
  std::mutex mutex;

  // Maintain a condition variable to signal when new requests are available for processing
  std::condition_variable cv;
};

// Define functions for interacting with the external API and managing the state of the module
void apiCall(const string& strategy, function<void(const ApiResponse&)> callback) {
  // Check if the strategy is currently on cooldown
  State* state = getState();
  auto it = state->strategyCooldowns.find(strategy);
  if (it != state->strategyCooldowns.end()) {
    chrono::steady_clock::time_point cooldownEnd = it->second;
    if (cooldownEnd > chrono::steady_clock::now()) {
      // Strategy is currently on cooldown, schedule a retry later
      state->pendingRequests.emplace_back(ApiResponse{}, callback);
      return;
    }
  }

  // Make the API call and handle the response
  CURL* curl = curl_easy_init();
  if (curl) {
    string url = API_URL + "/strategy/" + strategy;
    curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, writeResponse);
    curl_easy_perform(curl);
  } else {
    // Handle API call failure
  }
}

void writeResponse(const string& response) {
  ApiResponse apiResponse;
  json::parse(response, apiResponse.data);
  apiResponse.status = "ok";
  State* state = getState();
  state->pendingRequests.emplace_back(apiResponse, nullptr);
}

void handlePendingRequests() {
  State* state = getState();
  for (auto& request : state->pendingRequests) {
    if (request.second) {
      // Invoke the response handler for the pending request
      auto it = state->strategyCooldowns.find(request.first.data["strategy"].asString());
      if (it != state->strategyCooldowns.end()) {
        chrono::steady_clock::time_point cooldownEnd = it->second;
        if (cooldownEnd > chrono::steady_clock::now()) {
          // Strategy is currently on cooldown, delay handling the request further
          continue;
        } else {
          // Strategy is no longer on cooldown, handle the request immediately
          state->strategyCooldowns.erase(it);
        }
      }
    }
  }
}

void updateState() {
  State* state = getState();
  for (auto& request : state->pendingRequests) {
    if (request.second) {
      // Invoke the response handler for the pending request
      auto it = state->strategyCooldowns.find(request.first.data["strategy"].asString());
      if (it == state->strategyCooldowns.end()) {
        // Strategy is not currently on cooldown, update its cooldown timestamp
        chrono::steady_clock::time_point cooldownEnd = chrono::steady_clock::now() + MIN_COOLDOWN;
        state->strategyCooldowns[request.first.data["strategy"].asString()] = cooldownEnd;
      } else {
        // Strategy is currently on cooldown, update its cooldown timestamp
        chrono::steady_clock::time_point cooldownEnd = it->second + request.first.data["cooldown"].asInt();
        state->strategyCooldowns[request.first.data["strategy"].asString()] = cooldownEnd;
      }
    }
  }
}

void handleStrategy(const string& strategy) {
  // Handle the requested attack strategy
  State* state = getState();
  auto it = state->strategyCooldowns.find(strategy);
  if (it != state->strategyCooldowns.end()) {
    chrono::steady_clock::time_point cooldownEnd = it->second;
    if (cooldownEnd > chrono::steady_clock::now()) {
      // Strategy is currently on cooldown, schedule a retry later
      state->pendingRequests.emplace_back(ApiResponse{}, nullptr);
    } else {
      // Strategy is no longer on cooldown, handle the request immediately
      state->strategyCooldowns.erase(it);
    }
  }
}

void processRequest(const string& request) {
  // Process the received attack request
  json::parse(request, request.data["attack"].asString());
  handleStrategy(request.data["strategy"].asString());
}

// Define functions for managing the state of the module and interacting with the external API
State* getState() {
  State* state = new State;
  // Load the current state from the external API
  curl_easy_init();
  string url = API_URL + "/state";
  curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
  curl_easy_perform(curl);
  delete curl;
}

void updateModuleState() {
  State* state = getState();
  // Update the module's state based on the external API response
  json::parse(response, state->data);
  delete state;
}
```

In this example, we define a `State` struct to store the current state of the module and its interactions with the external API. We also define functions for interacting with the external API and managing the state of the module. The `apiCall` function makes a request to the external API to retrieve the latest state of the module, and the `updateModuleState` function updates the module's state based on the response from the external API.

The `handlePendingRequests` function is responsible for handling any pending requests that are waiting to be processed. It checks if each request is currently on cooldown, and schedules a retry later if it is. If the request is not currently on cooldown, it invokes the response handler for the request.

The `updateState` function updates the state of the module based on any pending requests that have been received. It checks if each strategy is currently on cooldown, and updates its cooldown timestamp accordingly. If a strategy is no longer on cooldown, it removes it from the cooldown list.

The `handleStrategy` function handles an attack request for a specific strategy. It first checks if the requested strategy is currently on cooldown. If it is, it schedules a retry later. If the strategy is not currently on cooldown, it invokes the response handler for the request and updates its cooldown timestamp accordingly.

The `processRequest` function processes an attack request by handling any pending requests that are waiting to be processed. It then updates the state of the module based on any new requests that have been received. Finally, it handles the attack request itself by invoking the response handler for the requested strategy and updating its cooldown timestamp accordingly.']

