public class DataIngestionPipeline {

private static final Logger LOGGER = LoggerFactory.getLogger(DataIngestionPipeline.class);

private static final String TOPIC_CRITICAL = "critical";
private static final String TOPIC_BATCH = "batch";

private final KafkaConsumer<String, String> consumer;
private final KafkaProducer<String, String> producer;

public DataIngestionPipeline(KafkaConsumer<String, String> consumer, KafkaProducer<String, String> producer) {
this.consumer = consumer;
this.producer = producer;
}

@Override
public void run() {
while (true) {
try {
// Consume message from Kafka topic
ConsumerRecords<String, String> records = consumer.poll(Duration.ofMillis(100));
for (ConsumerRecord<String, String> record : records) {
// Determine the event importance based on its topic
boolean isCritical = record.topic().equals(TOPIC_CRITICAL);
// Process message asynchronously with priority-based scheduling
processMessageAsync(record.value(), isCritical);
}
consumer.commitSync();
} catch (Exception e) {
LOGGER.error("Error while consuming messages from Kafka", e);
}
}
}

private void processMessageAsync(String message, boolean isCritical) {
// Create a task for processing the message asynchronously
CompletableFuture<Void> future = CompletableFuture.runAsync(() -> {
processMessage(message, isCritical);
}, executorService);

// Add the task to the priority queue based on its importance
if (isCritical) {
future.thenRunAsync(() -> processMessage(message, isCritical), criticalExecutorService);
} else {
future.whenComplete((aVoid, throwable) -> {
if (throwable != null) {
LOGGER.error("Error while processing message", throwable);
}
});
}
}

private void processMessage(String message, boolean isCritical) {
// Parse the message and extract relevant information
JsonObject json = JsonParser.parseString(message).getAsJsonObject();
String key = json.get("key").getAsString();
String value = json.get("value").getAsString();

// Transform the message into a structured format if necessary
if (isCritical) {
value = transformCriticalMessage(value);
} else {
value = transformBatchMessage(value);
}

// Produce the transformed message to Kafka topic
ProducerRecord<String, String> record = new ProducerRecord<>(TOPIC_PROCESSED, key, value);
producer.send(record, (metadata, exception) -> {
if (exception != null) {
LOGGER.error("Error while producing message to Kafka", exception);
} else {
LOGGER.info("Message produced to Kafka topic: {} with offset: {}", metadata.topic(), metadata.offset());
}
});
}

private static String transformCriticalMessage(String message) {
// Implement critical message transformation logic here
return message;
}

private static String transformBatchMessage(String message) {
// Implement batch message transformation logic here
return message;
}

public void stop() {
consumer.close();
producer.close();
executorService.shutdownNow();
criticalExecutorService.shutdownNow();
}

public static void main(String[] args) throws Exception {
// Initialize Kafka consumer and producer
KafkaConsumer<String, String> consumer = new KafkaConsumer<>(getKafkaConfig());
consumer.subscribe(Arrays.asList(TOPIC_CRITICAL, TOPIC_BATCH));

KafkaProducer<String, String> producer = new KafkaProducer<>(getKafkaConfig());

// Initialize the data ingestion pipeline with consumer and producer
DataIngestionPipeline pipeline = new DataIngestionPipeline(consumer, producer);

// Start the data ingestion pipeline
new Thread(pipeline).start();
}

private static Properties getKafkaConfig() {
Properties props = new Properties();
props.put("bootstrap.servers", "localhost:9092");
props.put("group.id", "data-ingestion-pipeline");
props.put("enable.auto.commit", "false");
props.put("auto.offset.reset", "earliest");
return props;
}

private static ExecutorService executorService = Executors.newFixedThreadPool(10);
private static ScheduledExecutorService criticalExecutorService = Executors.newScheduledThreadPool(2);
}']

