namespace MyCompany.HashLibrary
{
    public class HashProcessor : IHashProcessor
    {
        private readonly IConfiguration _config;

        public HashProcessor(IConfiguration config)
        {
            _config = config;
        }

        public async Task<string> ProcessInputAsync(string input)
        {
            var hashAlgorithm = GetHashAlgorithm(_config.GetValue<string>("HASH_ALGORITHM"));
            var inputBytes = Encoding.UTF8.GetBytes(input);
            var hash = await Task.Run(() => hashAlgorithm.ComputeHash(inputBytes));
            return BitConverter.ToString(hash).Replace("-", "").ToLowerInvariant();
        }

        private static HashAlgorithm GetHashAlgorithm(string algorithm)
        {
            switch (algorithm.ToUpper())
            {
                case "MD5":
                    return MD5.Create();
                case "SHA256":
                    return SHA256.Create();
                default:
                    throw new NotSupportedException($"Unsupported hash algorithm: {algorithm}");
            }
        }
    }
}
```
