  public void processTransaction(Transaction transaction) {
    // Check if the transaction is within the allowed time window
    if (transaction.getTimestamp() > System.currentTimeMillis() - 3000) {
      // Check if the transaction has been processed before
      if (!processedTransactions.contains(transaction)) {
        // Filter the transaction based on age, frequency, and geolocation
        boolean filterResult = filterTransaction(transaction);

        // If the transaction passes the filter, add it to the list of processed transactions
        if (filterResult) {
          processedTransactions.add(transaction);
        }
      }
    }
  }

  // Define the method to filter a single transaction
  public boolean filterTransaction(Transaction transaction) {
    // Check if the transaction is within the allowed age range
    if (transaction.getAge() <= 100) {
      // Check if the transaction has been processed too frequently in the last 3 seconds
      if (!transactions.containsKey(transaction.getId())) {
        transactions.put(transaction.getId(), transaction);

        // Calculate the weighted sum threshold based on the frequency of the transaction
        int weightedSumThreshold = calculateWeightedSumThreshold(transaction);

        // Check if the transaction meets the weighted sum threshold
        if (transaction.getAmount() > weightedSumThreshold) {
          // Check if the transaction has a valid geolocation
