  // Define the method to calculate the weighted sum threshold based on the frequency of a transaction
  public int calculateWeightedSumThreshold(Transaction transaction) {
    // Calculate the frequency of the transaction in the last 3 seconds
    long frequency = transactions.get(transaction.getId()).getFrequency();

