        } else {
            return new Date(0);
        }
    }

    // Define a method to perform a file operation asynchronously
    public Future<Object> executeFileOperationAsync(String path, String command, Object[] args) {
        FileOperation operation = new FileOperation(path, command, args);
        return executorService.submit(() -> {
            // Perform the file operation and return the result
