#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/time.h>
#include <unistd.h>
#include <curl/curl.h>

#define MAX_CONFIG_URLS 100
#define MAX_OUTPUT_FILES 256

// Structure to hold configuration URL and output file information
typedef struct config_url {
    char *url;
    FILE *output_file;
} config_url;

// Function to fetch configuration data from external API
void fetch_config(char *url, FILE *output_file) {
    CURL *curl;
    CURLcode res;

    // Initialize cURL session
    curl = curl_easy_init();

    // Set URL and output file for the request
    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, output_file);

    // Perform HTTP GET request
    res = curl_easy_perform(curl);

    // Check for errors and handle them appropriately
    if (res != CURLE_OK) {
        fprintf(stderr, "cURL error: %s\n", curl_easy_strerror(res));
    }

    // Clean up cURL session
    curl_easy_cleanup(curl);
}

// Function to parse configuration data from external API responses
void parse_config(FILE *input_file, FILE *output_file) {
    char line[1024];
    int i = 0;

    // Read each line of input file and parse it according to the desired format
    while (fgets(line, sizeof(line), input_file)) {
        // Parse line and write formatted output to output file
        fprintf(output_file, "%d: %s", i++, line);
    }
}

// Main function for the command-line tool
int main(int argc, char *argv[]) {
    int opt;
    FILE *input_file, *output_file;
    config_url urls[MAX_CONFIG_URLS];
    size_t num_urls = 0;

    // Initialize variables and parse command-line arguments
    while ((opt = getopt(argc, argv, "u:o:")) != -1) {
        switch (opt) {
            case 'u':
                urls[num_urls].url = optarg;
                num_urls++;
                break;
            case 'o':
                output_file = fopen(optarg, "w");
                break;
            case '?':
                if (isprint(optopt)) {
                    fprintf(stderr, "Unknown option -%c\n", optopt);
                } else {
                    fprintf(stderr, "Unknown option character \\x%x\n", optopt);
                }
            default:
                exit(EXIT_FAILURE);
        }
    }

    // Handle help and version options separately
    if (strcmp(argv[1], "--help") == 0) {
        printf("Usage: %s [-u <config URL>]... -o <output file>\n", argv[0]);
        return EXIT_SUCCESS;
    } else if (strcmp(argv[1], "--version") == 0) {
        printf("%s version 1.0\n", argv[0]);
        return EXIT_SUCCESS;
    }

    // Check for required command-line arguments and handle errors
    if (!output_file) {
        fprintf(stderr, "Error: no output file specified (-o option)\n");
        exit(EXIT_FAILURE);
    } else if (num_urls == 0) {
        fprintf(stderr, "Error: no configuration URLs specified (-u option)\n");
        exit(EXIT_FAILURE);
    }

    // Fetch and parse configuration data for each URL in parallel
    int i;
    pthread_t threads[num_urls];
    for (i = 0; i < num_urls; i++) {
        input_file = tmpfile();
        fetch_config(urls[i].url, input_file);
        parse_config(input_file, output_file);
        fclose(input_file);
    }

    // Print successful completion message and return
    printf("Successfully fetched and parsed %zu configuration URL%s\n", num_urls, num_urls == 1 ? "" : "s");
    return EXIT_SUCCESS;
}
