#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>

// Define the data structure for the cache
typedef struct {
    int key;
    char* value;
} CacheEntry;

// Define the cache itself as a hash map
typedef struct {
    CacheEntry** entries;
    int capacity;
} Cache;

// Define the functions for managing the cache
void cache_init(Cache* cache) {
    // Initialize the cache with a fixed size
    cache->capacity = 100;
    cache->entries = (CacheEntry**)malloc(sizeof(CacheEntry*) * cache->capacity);
}

void cache_destroy(Cache* cache) {
    // Free all the memory allocated for the cache entries
    for (int i = 0; i < cache->capacity; i++) {
        free(cache->entries[i]);
    }
    free(cache->entries);
}

void cache_put(Cache* cache, int key, char* value) {
    // Check if the key already exists in the cache
    for (int i = 0; i < cache->capacity; i++) {
        if (cache->entries[i] != NULL && cache->entries[i]->key == key) {
            free(cache->entries[i]->value);
            cache->entries[i]->value = strdup(value);
            return;
        }
    }

    // If the key does not exist, add a new entry to the cache
    CacheEntry* entry = (CacheEntry*)malloc(sizeof(CacheEntry));
    entry->key = key;
    entry->value = strdup(value);
    cache->entries[cache->capacity++] = entry;
}

char* cache_get(Cache* cache, int key) {
    // Check if the key exists in the cache
    for (int i = 0; i < cache->capacity; i++) {
        if (cache->entries[i] != NULL && cache->entries[i]->key == key) {
            return cache->entries[i]->value;
        }
    }

    // If the key does not exist, return null
    return NULL;
}

void cache_remove(Cache* cache, int key) {
    // Find the index of the entry to remove
    for (int i = 0; i < cache->capacity; i++) {
        if (cache->entries[i] != NULL && cache->entries[i]->key == key) {
            free(cache->entries[i]);
            cache->entries[i] = NULL;
            return;
        }
    }
}
