  std::mutex mutex_;
  std::condition_variable cv_;
  std::vector<std::string> addresses_;
  std::unordered_map<std::string, int> ports_;
  size_t maxConnections_;
  size_t connectionTimeout_;
  size_t timeout_;

  // Methods for managing connections
