```
// TCPConnectionPool.cpp
#include "TCPConnectionPool.h"
#include <algorithm>
#include <stdexcept>

TCPConnectionPool::TCPConnectionPool(size_t maxConnections, size_t connectionTimeout)
    : maxConnections_(maxConnections), connectionTimeout_(connectionTimeout), timeout_(std::numeric_limits<size_t>::max()) {
  if (maxConnections < 1) {
    throw std::invalid_argument("Maximum number of connections must be positive");
  }
}

TCPConnectionPool::~TCPConnectionPool() {
  // Close all open connections
  for (const auto& connection : addresses_) {
    removeConnection(connection.first, connection.second);
  }
}

void TCPConnectionPool::addConnection(const std::string& address, int port) {
  std::lock_guard<std::mutex> lock(mutex_);
  addConnectionInternal(address, port);
}

void TCPConnectionPool::removeConnection(const std::string& address, int port) {
  std::lock_guard<std::mutex> lock(mutex_);
  removeConnectionInternal(address, port);
}

bool TCPConnectionPool::hasConnection(const std::string& address, int port) const {
  std::lock_guard<std::mutex> lock(mutex_);
  return ports_.find(address) != ports_.end() && ports_.at(address) == port;
}

size_t TCPConnectionPool::getNumConnections() const {
  std::lock_guard<std::mutex> lock(mutex_);
  return addresses_.size();
}

size_t TCPConnectionPool::getMaxConnections() const {
  return maxConnections_;
}

void TCPConnectionPool::setTimeout(size_t timeout) {
  std::lock_guard<std::mutex> lock(mutex_);
  if (timeout < 1) {
    throw std::invalid_argument("Timeout must be positive");
  }
  timeout_ = timeout;
}

size_t TCPConnectionPool::getTimeout() const {
  return timeout_;
}

void TCPConnectionPool::checkConnection(const std::string& address, int port) {
  // Check if the connection is expired
  auto it = ports_.find(address);
  if (it != ports_.end()) {
    if (it->second == port) {
      // Connection is not expired, nothing to do
      return;
    } else {
      // Connection is expired, remove it
      removeConnectionInternal(address, it->second);
    }
  }
}

void TCPConnectionPool::removeExpiredConnections() {
  std::lock_guard<std::mutex> lock(mutex_);
  for (auto it = addresses_.begin(); it != addresses_.end();) {
    checkConnection(it->first, it->second);
    if (hasConnection(it->first, it->second)) {
      // Connection is not expired, move on to the next one
      ++it;
    } else {
      // Connection is expired, remove it from the pool
      it = addresses_.erase(it);
      ports_.erase(it->first);
    }
  }
}

void TCPConnectionPool::addConnectionInternal(const std::string& address, int port) {
  // Check if the connection already exists in the pool
  auto it = ports_.find(address);
  if (it != ports_.end()) {
    if (it->second == port) {
      // Connection is already in the pool, nothing to do
      return;
    } else {
      // Connection is not in the pool or has expired, replace it
      removeConnectionInternal(address, it->second);
    }
  }

  // Add the connection to the pool
  addresses_.push_back({ address, port });
  ports_.emplace(address, port);
}

void TCPConnectionPool::removeConnectionInternal(const std::string& address, int port) {
  // Remove the connection from the pool
  auto it = addresses_.begin();
  while (it != addresses_.end()) {
    if (it->first == address && it->second == port) {
      it = addresses_.erase(it);
      ports_.erase(address);
      break;
    } else {
      ++it;
    }
  }
}

void TCPConnectionPool::updateTimeouts() {
  // Update the timeout for each connection
  std::lock_guard<std::mutex> lock(mutex_);
  for (auto& connection : addresses_) {
    connection.second = getNextTimeout();
  }
}

size_t TCPConnectionPool::getNextTimeout() const {
  return timeout_;
}
