  FILE* fp = fopen(filePath, "r");
  if (fp == NULL) {
    fprintf(stderr, "Error: %s\n", strerror(errno));
    return -1;
  }

  // Allocate memory for the ResourceBundle struct and set its fields
  *bundle = malloc(sizeof(ResourceBundle));
  if (*bundle == NULL) {
    fprintf(stderr, "Error: %s\n", strerror(errno));
    return -1;
  }
  (*bundle)->numItems = 0;
  (*bundle)->items = malloc(sizeof(Item*) * 16);
  if ((*bundle)->items == NULL) {
    fprintf(stderr, "Error: %s\n", strerror(errno));
    return -1;
  }
  (*bundle)->filePath = malloc(strlen(filePath) + 1);
  if ((*bundle)->filePath == NULL) {
    fprintf(stderr, "Error: %s\n", strerror(errno));
    return -1;
  }
  strcpy((*bundle)->filePath, filePath);

  // Load the items in the bundle from the file
  while (fread(*bundle, sizeof(Item), 16, fp) == 16) {
    (*bundle)->numItems++;
    (*bundle)->items = realloc((*bundle)->items, sizeof(Item*) * (*bundle)->numItems);
    if ((*bundle)->items == NULL) {
      fprintf(stderr, "Error: %s\n", strerror(errno));
      return -1;
    }
  }

  // Close the file and return success
