// OAuth2 validation library namespace
namespace OAuth2Validation {
    // Token format version enumeration
    enum class TokenFormatVersion {
        v1,
        v2
    };

    // Token type enumeration
    enum class TokenType {
        Bearer,
        RefreshToken
    };

    // Token expiration mode enumeration
    enum class ExpirationMode {
        Absolute,
        Relative
    };

    // Token validation result
    struct ValidationResult {
        bool valid;
        std::string errorMessage;
    };

    // Token format version-specific validation function
    typedef ValidationResult (*ValidationFunction)(const std::map<std::string, std::string> &);

    // Token format version registry
    static std::map<TokenFormatVersion, ValidationFunction> tokenFormatValidators = {
        { TokenFormatVersion::v1, validateV1Token },
        { TokenFormatVersion::v2, validateV2Token }
    };

    // Token type registry
    static std::map<std::string, TokenType> tokenTypes = {
        { "Bearer", TokenType::Bearer },
        { "RefreshToken", TokenType::RefreshToken }
    };

    // Token expiration mode registry
    static std::map<std::string, ExpirationMode> expirationModes = {
        { "absolute", ExpirationMode::Absolute },
        { "relative", ExpirationMode::Relative }
    };

    // Validate OAuth2 access token using a given validation function
    static ValidationResult validateToken(const std::map<std::string, std::string> &token, TokenFormatVersion version) {
        auto validator = tokenFormatValidators[version];
        return validator(token);
    }

    // Validate OAuth2 access token (V1 format)
    static ValidationResult validateV1Token(const std::map<std::string, std::string> &token) {
        ValidationResult result;

        // Check for mandatory fields
        if (!token.count("access_token")) {
            result.valid = false;
            result.errorMessage = "Mandatory field 'access_token' is missing";
        } else {
            result.valid = true;
        }

        // Check for optional fields
        if (token.count("expires_in")) {
            auto expirationMode = expirationModes[token["expires_in"].substr(0, 1)];
            auto expirationTime = std::stoi(token["expires_in"].substr(1));

            switch (expirationMode) {
                case ExpirationMode::Absolute:
                    // Check for valid absolute expiration time
                    if (expirationTime < 0 || expirationTime > INT_MAX) {
                        result.valid = false;
                        result.errorMessage = "Invalid absolute expiration time";
                    }
                case ExpirationMode::Relative:
                    // Check for valid relative expiration time
                    if (expirationTime <= 0 || expirationTime > INT_MAX) {
                        result.valid = false;
                        result.errorMessage = "Invalid relative expiration time";
                    }
            }
        } else {
            // Check for mandatory token type
            if (!token.count("token_type")) {
                result.valid = false;
                result.errorMessage = "Mandatory field 'token_type' is missing";
            } else {
                auto tokenType = tokenTypes[token["token_type"]];
                // Check for valid token type
                if (tokenType != TokenType::Bearer) {
                    result.valid = false;
                    result.errorMessage = "Invalid token type";
                }
            }
        }

        return result;
    }

    // Validate OAuth2 access token (V2 format)
    static ValidationResult validateV2Token(const std::map<std::string, std::string> &token) {
        ValidationResult result;

        // Check for mandatory fields
        if (!token.count("access_token")) {
            result.valid = false;
            result.errorMessage = "Mandatory field 'access_token' is missing";
        } else {
            result.valid = true;
        }

        // Check for optional fields
        if (token.count("expires_in")) {
            auto expirationMode = expirationModes[token["expires_in"].substr(0, 1)];
            auto expirationTime = std::stoi(token["expires_in"].substr(1));

            switch (expirationMode) {
                case ExpirationMode::Absolute:
                    // Check for valid absolute expiration time
                    if (expirationTime < 0 || expirationTime > INT_MAX) {
                        result.valid = false;
                        result.errorMessage = "Invalid absolute expiration time";
                    }
                case ExpirationMode::Relative:
                    // Check for valid relative expiration time
                    if (expirationTime <= 0 || expirationTime > INT_MAX) {
                        result.valid = false;
                        result.errorMessage = "Invalid relative expiration time";
                    }
            }
        } else {
            // Check for mandatory token type
            if (!token.count("token_type")) {
                result.valid = false;
                result.errorMessage = "Mandatory field 'token_type' is missing";
            } else {
                auto tokenType = tokenTypes[token["token_type"]];
                // Check for valid token type
                if (tokenType != TokenType::Bearer) {
                    result.valid = false;
                    result.errorMessage = "Invalid token type";
                }
            }
        }

        return result;
    }
}
```
