// Message queue structure to store messages
class MessageQueue {
public:
    // Constructor to initialize the message queue
    MessageQueue() {
        mutex = new mutex();
        cond_var = new condition_variable();
        message_queue.reserve(1024);
    }

    // Destructor to clean up the resources
    ~MessageQueue() {
        delete mutex;
        delete cond_var;
    }

    // Enqueues a new message into the queue
    void enqueue(const string& payload, const string& topic, int priority) {
        unique_lock<mutex> lock(*mutex);
        Message message{payload, topic, priority};
        message_queue.push_back(message);
        cond_var->notify_all();
    }

    // Dequeues a message from the queue
    Message dequeue() {
        unique_lock<mutex> lock(*mutex);
        while (message_queue.empty()) {
            cond_var->wait(lock);
        }
        Message message = message_queue.front();
        message_queue.pop_front();
        return message;
    }

private:
    mutex* mutex;
    condition_variable* cond_var;
    vector<Message> message_queue;
};

