// Structure to hold the list of NFAPI_CRC_INDICATION_PDU_T structures
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* crc_ind;
    int size;
} CRC_IND_LIST;

// Structure to hold the memory usage information
typedef struct {
    long mem_usage;
    time_t last_update;
} MEM_USAGE;

// Global variables
static CRC_IND_LIST crc_ind_list;
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
static MEM_USAGE mem_usage;

// Function to initialize the list of NFAPI_CRC_INDICATION_PDU_T structures
void init_crc_ind_list(int size) {
    crc_ind_list.size = size;
    crc_ind_list.crc_ind = (NFAPI_CRC_INDICATION_PDU_T*)calloc(crc_ind_list.size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

// Function to add a new NFAPI_CRC_INDICATION_PDU_T structure to the list
void add_crc_ind(NFAPI_CRC_INDICATION_PDU_T* crc_ind) {
    pthread_mutex_lock(&lock);
    if (crc_ind_list.size == 0) {
        init_crc_ind_list(1000); // Initialize the list with a default size of 1000
    } else if (crc_ind_list.size >= crc_ind_list.size * 2) {
        realloc_crc_ind_list(); // Reallocate the list to double its current size
    }
    crc_ind_list.crc_ind[crc_ind_list.size] = *crc_ind;
    memcpy(&crc_ind_list.crc_ind[crc_ind_list.size].rx_ue_information, &crc_ind->rx_ue_information, sizeof(RX_UE_INFORMATION));
    memcpy(&crc_ind_list.crc_ind[crc_ind_list.size].crc_indication_rel8, &crc_ind->crc_indication_rel8, sizeof(CRC_INDICATION_REL8));
    crc_ind_list.size++;
    pthread_mutex_unlock(&lock);
}

// Function to reallocate the list of NFAPI_CRC_INDICATION_PDU_T structures
void realloc_crc_ind_list() {
    crc_ind_list.size *= 2;
    crc_ind_list.crc_ind = (NFAPI_CRC_INDICATION_PDU_T*)realloc(crc_ind_list.crc_ind, crc_ind_list.size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

// Function to remove a NFAPI_CRC_INDICATION_PDU_T structure from the list
void remove_crc_ind(int index) {
    pthread_mutex_lock(&lock);
    crc_ind_list.size--;
    for (int i = index; i < crc_ind_list.size; i++) {
        crc_ind_list.crc_ind[i] = crc_ind_list.crc_ind[i + 1];
    }
    pthread_mutex_unlock(&lock);
}

// Function to update the memory usage information
void update_mem_usage(long mem_usage) {
    pthread_mutex_lock(&lock);
    if (mem_usage > mem_usage.mem_usage) {
        mem_usage.last_update = time(NULL);
        mem_usage.mem_usage = mem_usage;
    }
    pthread_mutex_unlock(&lock);
}

// Function to monitor memory usage and trigger alerts if necessary
void monitor_mem_usage() {
    long max_mem_usage = 10 * 1024 * 1024; // Maximum allowed memory usage (10 MB)
    if (mem_usage.mem_usage > max_mem_usage) {
        printf("Memory usage exceeded the limit of %ld bytes!\n", max_mem_usage);
    }
}

// Function to deallocate memory when it is no longer needed
void deallocate_memory() {
    pthread_mutex_lock(&lock);
    if (crc_ind_list.size > 0) {
        free(crc_ind_list.crc_ind);
        crc_ind_list.crc_ind = NULL;
    }
    pthread_mutex_unlock(&lock);
}

// Function to safely deallocate memory when the data is no longer needed
void safe_deallocate_memory() {
    pthread_mutex_lock(&lock);
    if (crc_ind_list.size > 0) {
        for (int i = 0; i < crc_ind_list.size; i++) {
            free(crc_ind_list.crc_ind[i].rx_ue_information);
            free(crc_ind_list.crc_ind[i].crc_indication_rel8.payload);
        }
        free(crc_ind_list.crc_ind);
    }
    crc_ind_list.size = 0;
    pthread_mutex_unlock(&lock);
}

// Function to handle memory allocation errors
void error_handler(char* message) {
    printf("Error: %s\n", message);
    deallocate_memory();
    exit(-1);
}

int main() {
    init_memory_management(); // Initialize memory management functions
    while (true) {
        receive_data(); // Receive data from the network
        process_data(); // Process the received data
        update_mem_usage(get_current_mem_usage()); // Update memory usage information
        monitor_mem_usage(); // Monitor memory usage and trigger alerts if necessary
    }
}
