#define DB_PORT 3306
#define DB_USER "root"
#define DB_PASSWORD ""
#define DB_DATABASE "word_count"

// Define data structures for file and word processing
typedef struct {
    char *filepath;
    int filefd;
} FileInfo;

typedef struct {
    char *word;
    int count;
} WordInfo;

// Define function prototypes
void processFiles(char **files, int num_files);
void processFile(FileInfo *file);
void parseWords(char *text);
void analyzeWord(WordInfo *word);
void saveAnalysisResults(WordInfo *words, int num_words);
