// Main function
int main(int argc, char **argv) {
    // Check command line arguments and initialize variables
    if (argc < 2) {
        printf("Usage: %s <directory path> [minimum word length] [output format] [logging preferences]\n", argv[0]);
        return 1;
    }
    int num_files = 0;
    char **files = NULL;
    if (argc >= 2) {
        files = malloc(sizeof(char *) * (argc - 1));
        for (int i = 1; i < argc; i++) {
            files[num_files++] = argv[i];
        }
    }
    int min_word_length = 0;
    if (argc >= 3) {
        min_word_length = atoi(argv[2]);
    }
    char *output_format = "txt";
    if (argc >= 4) {
        output_format = argv[3];
    }
    bool log_errors = false;
    if (argc >= 5) {
        log_errors = true;
    }

    // Create a thread for each file to be processed
    pthread_t *threads = malloc(sizeof(pthread_t) * num_files);
    FileInfo *file_info = malloc(sizeof(FileInfo) * num_files);
    for (int i = 0; i < num_files; i++) {
        file_info[i].filepath = files[i];
        int fd = open(files[i], O_RDONLY);
        if (fd == -1) {
            logError("Failed to open file: %s", strerror(errno));
        } else {
            file_info[i].filefd = fd;
        }
    }

    // Process each file in a separate thread
    for (int i = 0; i < num_files; i++) {
        pthread_create(&threads[i], NULL, processFile, &file_info[i]);
    }

    // Wait for all threads to complete
    for (int i = 0; i < num_files; i++) {
        pthread_join(threads[i], NULL);
    }

    // Clean up resources
    free(file_info);
    free(threads);

    return 0;
}

// Process each file in a separate thread
void *processFile(void *arg) {
    FileInfo *file = (FileInfo *) arg;
    char text[1024];
    while (read(file->filefd, text, sizeof(text)) > 0) {
        parseWords(text);
    }
    close(file->filefd);
    return NULL;
}

// Parse words in the given text and analyze them
void parseWords(char *text) {
    WordInfo *words = malloc(sizeof(WordInfo) * 1024);
    int num_words = 0;
    char *word = strtok(text, " ");
    while (word != NULL) {
        if (strlen(word) >= min_word_length) {
            WordInfo word_info = {word, 1};
            analyzeWord(&word_info);
            words[num_words++] = word_info;
        }
        word = strtok(NULL, " ");
    }
    saveAnalysisResults(words, num_words);
    free(words);
}

// Analyze a single word by counting its frequency in the external database
void analyzeWord(WordInfo *word) {
    // Connect to the database and perform a query
    MYSQL *conn = mysql_init(NULL);
    if (mysql_real_connect(conn, DB_HOST, DB_USER, DB_PASSWORD, DB_DATABASE, 0, NULL, 0)) {
        char query[1024];
        sprintf(query, "SELECT COUNT(*) FROM words WHERE word = '%s'", word->word);
        if (mysql_query(conn, query) == 0) {
            MYSQL_RES *res = mysql_store_result(conn);
            int count = 0;
            while ((row = mysql_fetch_row(res))) {
                count += atoi(row[0]);
            }
            word->count = count;
        } else {
            logError("Failed to perform query: %s", mysql_error(conn));
        }
    } else {
        logError("Failed to connect to database: %s", mysql_error(conn));
    }
    // Close the connection and clean up resources
    mysql_close(conn);
}

// Save the analysis results in an external database
void saveAnalysisResults(WordInfo *words, int num_words) {
    MYSQL *conn = mysql_init(NULL);
    if (mysql_real_connect(conn, DB_HOST, DB_USER, DB_PASSWORD, DB_DATABASE, 0, NULL, 0)) {
        char query[1024];
        for (int i = 0; i < num_words; i++) {
            sprintf(query, "INSERT INTO words VALUES ('%s', %d)", words[i].word, words[i].count);
            if (mysql_query(conn, query) != 0) {
                logError("Failed to insert into database: %s", mysql_error(conn));
            }
        }
    } else {
        logError("Failed to connect to database: %s", mysql_error(conn));
    }
    // Close the connection and clean up resources
    mysql_close(conn);
}

// Log errors gracefully
void logError(const char *message, ...) {
    va_list args;
    va_start(args, message);
    vfprintf(stderr, message, args);
    fprintf(stderr, "\n");
    va_end(args);
}

// Log messages to a file or console
void logMessage(const char *message) {
    FILE *log = stdout;
    if (log_errors) {
        log = fopen("error.log", "a");
    }
    fprintf(log, "%s\n", message);
    if (log != stdout) {
        fclose(log);
    }
}
