// Function to encrypt a string using AES-256 and the specified key and initialization vector
char* encrypt(char* str, char* key, char* iv) {
    // Initialize the encryption library
    EVP_CIPHER_CTX ctx;
    EVP_EncryptInit(&ctx, EVP_aes_256_cbc(), (unsigned char*)key, (unsigned char*)iv);

    // Get the length of the input string
    int str_len = strlen(str);

    // Allocate memory for the encrypted output
    int out_len = EVP_EncryptUpdate(&ctx, NULL, 0, (unsigned char*)str, str_len);
    char* enc_out = malloc(out_len);

    // Encrypt the input string and write it to the output buffer
    EVP_EncryptUpdate(&ctx, (unsigned char*)enc_out, out_len, (unsigned char*)str, str_len);

    // Free the encryption library resources
    EVP_CIPHER_CTX_cleanup(&ctx);

    return enc_out;
}

