    struct dirent* entry;
    while ((entry = readdir(dir)) != NULL) {
        char* filename = entry->d_name;
        if (strcmp(filename, ".") == 0 || strcmp(filename, "..") == 0) {
            continue;
        }

        // Open the file for reading
        FILE* fp = fopen(entry->d_name, "r");
