    }

    return 0;
}

void parseCommandLineArguments(int argc, char* argv[]) {
    for (int i = 1; i < argc; ++i) {
        string argument(argv[i]);

        if (argument == USAGE_HELP) {
            printUsageInformation();
            exit(0);
        } else if (argument == CUSTOM_COMPRESSION_ALGORITHM && i + 1 < argc) {
            int level = atoi(argv[i + 1]);
            if (!isCustomCompressionLevelValid(level)) {
                cout << INVALID_COMPRESSION_LEVEL << endl;
                exit(INVALID_COMPRESSION_LEVEL_EXIT_CODE);
            }
        } else if (argument == OUTPUT_FILE && i + 1 < argc) {
            string outputFilePath = getOutputFilePath();
            if (!outputFilePath.empty()) {
                cout << OUTPUT_FILE_SUCCESSFUL << outputFilePath << endl;
            } else {
                cout << FILE_NOT_FOUND << endl;
                exit(FILE_NOT_FOUND_EXIT_CODE);
            }
        } else if (argument != USAGE_HELP && argument != CUSTOM_COMPRESSION_ALGORITHM && argument != OUTPUT_FILE) {
            vector<string> filePaths = getFilePathsFromCommandLineArguments(argc - i, argv + i);
            if (filePaths.empty()) {
                cout << INVALID_ARGUMENTS << endl;
                exit(INVALID_ARGUMENTS_EXIT_CODE);
            } else {
                // add file paths to vector for file data and signal main thread to process files
                lock_guard<mutex> lock(fileDataVectorMutex);
                for (const string& filePath : filePaths) {
                    FileData fileData;
                    fileData.filePath = filePath;
                    fileData.inputStream = ifstream(filePath, ios::binary);
                    fileDataVector.push_back(fileData);
                }
            }
        }
    }
}

bool isManpageRequested() {
    return !fileDataVectorMutex.try_lock();
}

bool isCustomCompressionLevelValid(int level) {
    return level >= MIN_COMPRESSION_LEVEL && level <= MAX_COMPRESSION_LEVEL;
}

string getOutputFilePath() {
    string outputFilePath = "";
    for (int i = 1; i < fileDataVector.size(); ++i) {
        const string& filePath = fileDataVector[i].filePath;
        if (filePath != fileDataVector[0].filePath) {
            cout << "All files must have the same path." << endl;
            return "";
        } else {
            outputFilePath = filePath + ".compressed";
        }
    }
    return outputFilePath;
}

vector<string> getFilePathsFromCommandLineArguments(int argc, char* argv[]) {
    vector<string> filePaths;
    for (int i = 1; i < argc; ++i) {
        string argument(argv[i]);

        if (argument == CUSTOM_COMPRESSION_ALGORITHM || argument == OUTPUT_FILE) {
            continue;
        } else {
            filePaths.push_back(argument);
        }
    }
    return filePaths;
}

void processFiles() {
    while (true) {
        // signal main thread to stop processing files if vector is empty
        lock_guard<mutex> lock(fileDataVectorMutex);
        if (fileDataVector.empty()) {
            break;
        }

        // process next file data in vector concurrently
        FileData& fileData = fileDataVector[0];
        string outputFilePath = getOutputFilePath();
        ifstream& inputStream = fileData.inputStream;
        ofstream outputStream(outputFilePath, ios::binary);
        int compressionLevel = 1;
        for (const auto& arg : vector<string>(argv + 1, argv + argc)) {
            string argument(arg);
            if (argument == CUSTOM_COMPRESSION_ALGORITHM) {
                compressionLevel = atoi(argv[i + 1]);
                if (!isCustomCompressionLevelValid(compressionLevel)) {
                    break;
                }
            } else if (argument == OUTPUT_FILE) {
                outputFilePath = getOutputFilePath();
            }
        }
        compressFileContent(inputStream, outputStream, compressionLevel);
        inputStream.close();
        outputStream.close();
        fileDataVectorConditionVariable.notify_one();
    }
}

void printUsageInformation() {
    cout << "Usage: [program name] <file path> [compression level (default 1)] [output file path]" << endl;
}

void compressFileContent(ifstream& inputStream, ofstream& outputStream, int compressionLevel) {
    if (!inputStream.is_open()) {
        cout << "Input file is not open." << endl;
        return;
    } else if (compressionLevel < MIN_COMPRESSION_LEVEL || compressionLevel > MAX_COMPRESSION_LEVEL) {
        cout << INVALID_COMPRESSION_LEVEL << endl;
        return;
    } else if (!outputStream.is_open()) {
        cout << "Output file is not open." << endl;
        return;
    }

    // Compress file content using given compression level
}
