config_t *config_versions[MAX_CONCURRENCY] = {NULL}; // For storing the versions of the configuration
config_t current_config = {.version = "v1", .dependencies = {"d1"}}; // Initial version and dependencies
int num_concurrent = 0; // Number of concurrent threads accessing the configuration

// Function to acquire semaphore
void acquire_semaphore() {
    while (semaphore != 0) {} // Spin lock until semaphore is available
    semaphore++; // Increment semaphore count
}

// Function to release semaphore
void release_semaphore() {
    semaphore--; // Decrement semaphore count
}

// Function to update the current configuration with a new version
void update_config(char *new_version, char **new_dependencies) {
    config_t new_config = {.version = new_version, .dependencies = new_dependencies}; // Create new config structure
    int i; // Iterator variable
    for (i = 0; i < num_concurrent; i++) { // Check if there are any concurrent threads accessing the configuration
        if (config_versions[i] != NULL) { // If yes, check if the versions match
            if (strcmp(config_versions[i]->version, new_config.version) == 0) { // If they match, update the dependencies
                strcpy(config_versions[i]->dependencies[0], new_config.dependencies[0]);
            }
        }
    }
}

// Function to retrieve the current configuration
void get_config() {
    pthread_mutex_lock(&semaphore); // Acquire semaphore lock
    if (num_concurrent < MAX_CONCURRENCY) { // If there are available slots in the config versions array
        num_concurrent++; // Increment number of concurrent threads
        config_versions[num_concurrent - 1] = &current_config; // Add new version to the array
    } else { // If all slots are occupied, find the oldest unused slot and update it with the latest version
        int oldest = -1; // Initialize oldest index to -1
        for (int i = 0; i < MAX_CONCURRENCY; i++) { // Find the oldest unused slot
            if (config_versions[i] == NULL) { // If a slot is found, update oldest index
                oldest = i;
                break;
            } else if (strcmp(current_config.version, config_versions[i]->version) < 0) { // Otherwise, compare current version with the versions in the array
                oldest = i;
            }
        }
        config_versions[oldest] = &current_config; // Update the oldest unused slot with the latest version
    }
    pthread_mutex_unlock(&semaphore); // Release semaphore lock
}

// Function to delete a configuration version from the array
void delete_config(char *version) {
    int i; // Iterator variable
    for (i = 0; i < num_concurrent; i++) { // Find the index of the version to be deleted
        if (strcmp(config_versions[i]->version, version) == 0) { // If found, delete the version from the array
            config_versions[i] = NULL;
            break;
        }
    }
}

// Function to perform a rollback operation on the configuration
void rollback(char *version) {
    pthread_mutex_lock(&semaphore); // Acquire semaphore lock
    delete_config(current_config.version); // Delete the current version from the array
    strcpy(current_config.version, version); // Copy the target version to the current configuration
    for (int i = 0; i < num_concurrent; i++) { // Iterate over all concurrent threads and update their versions
        if (strcmp(version, config_versions[i]->version) == 0) {
            strcpy(config_versions[i]->version, current_config.version);
        }
    }
    pthread_mutex_unlock(&semaphore); // Release semaphore lock
}

// Function to update the dependencies of a configuration version
void update_dependencies(char *version, char **dependencies) {
    int i; // Iterator variable
    for (i = 0; i < num_concurrent; i++) { // Find the index of the target version in the array
        if (strcmp(config_versions[i]->version, version) == 0) {
            break;
        }
    }
    strcpy(config_versions[i]->dependencies[0], dependencies[0]); // Update the dependencies for the target version
}

