// Structure to store configuration data
typedef struct {
    char version[MAX_VERSIONS];
    char config[MAX_CONFIG_SIZE];
} WebsiteConfig;

// Function to load the latest website configuration from disk
void loadLatestConfig(WebsiteConfig *config) {
    FILE *file = fopen(CONFIG_FILE, "r");
    if (file == NULL) {
        printf("Error: failed to open file %s\n", CONFIG_FILE);
        return;
    }

    char version[MAX_VERSIONS];
    char config[MAX_CONFIG_SIZE];
    fscanf(file, "%s%*[^ ]%s", version, config);

    // Close the file and set the latest configuration
    fclose(file);
    strcpy(config->version, version);
    strcpy(config->config, config);
}

// Function to save a new website configuration to disk
void saveConfig(WebsiteConfig *config) {
    FILE *file = fopen(CONFIG_FILE, "w");
    if (file == NULL) {
        printf("Error: failed to open file %s\n", CONFIG_FILE);
        return;
    }

    // Write the latest configuration to disk
    fprintf(file, "%s %s\n", config->version, config->config);

    // Close the file
    fclose(file);
}

// Function to update the website configuration with a new version
void updateConfig(WebsiteConfig *config) {
    char version[MAX_VERSIONS];
    char config[MAX_CONFIG_SIZE];

    // Load the latest configuration from disk
    loadLatestConfig(config);

    // Increment the version number and append a new line character to the end of the configuration
    sprintf(version, "%d", atoi(config->version) + 1);
    strcat(config->config, "\n");

    // Save the updated configuration to disk
    saveConfig(config);
}

// Function to roll back to a previous version of the website configuration
void rollbackConfig(WebsiteConfig *config, int version) {
    char new_version[MAX_VERSIONS];
    char new_config[MAX_CONFIG_SIZE];

    // Load the latest configuration from disk
    loadLatestConfig(config);

    // Check if the requested version is valid
    if (atoi(config->version) <= version) {
        printf("Error: invalid version number\n");
        return;
    }

    // Decrement the version number and remove the new line character from the end of the configuration
    sprintf(new_version, "%d", atoi(config->version) - 1);
    strncpy(new_config, config->config, MAX_CONFIG_SIZE);
    new_config[MAX_CONFIG_SIZE - 1] = '\0';

    // Save the updated configuration to disk
    saveConfig(config);
}

int main() {
