from concurrent.futures import ThreadPoolExecutor
from loguru import logger
from fastavro import writer

class DistributedLoggingFramework:
    def __init__(self):
        self.log_levels = ['DEBUG', 'INFO', 'WARNING', 'ERROR']
        self.logger = logging.getLogger('distributed_logging_framework')
        self.logger.setLevel(logging.INFO)

    def log(self, level: str, message: str):
        if level not in self.log_levels:
            raise ValueError(f'Invalid log level {level}')
        logger.bind(level=level).info(message)

    def log_to_avro(self, logs: List[Dict]) -> None:
        with ThreadPoolExecutor() as executor:
            for log in logs:
                executor.submit(self._log_to_avro, log)

    def _log_to_avro(self, log: Dict):
        try:
            message = avro.parse(schema=LOG_SCHEMA, datum=log)
            writer(f'logs/{datetime.now().strftime("%Y-%m-%d")}.avro', message, mode='a+')
