Here is an example implementation of a modular, high-performance C# library named `SecureDataProcessor` that efficiently decrypts large volumes of encrypted data using AES-CBC encryption, supporting asynchronous decryption in parallel for multiple ciphertexts:
```csharp
using System;
using System.Security.Cryptography;
using System.Threading.Tasks;

namespace SecureDataProcessor
{
    public class DataDecrypter
    {
        private readonly Aes _aes;
        private readonly byte[] _iv;
        private readonly bool _useAsynchronousDecryption;

        public DataDecrypter(byte[] key, byte[] iv, bool useAsynchronousDecryption = false)
        {
            _aes = new AesCryptoServiceProvider();
            _aes.KeySize = 256;
            _aes.BlockSize = 128;
            _aes.IV = iv;
            _useAsynchronousDecryption = useAsynchronousDecryption;
        }

        public async Task<byte[]> Decrypt(byte[] ciphertext)
        {
            if (_useAsynchronousDecryption)
            {
                return await DecryptAsync(ciphertext);
            }

            using (var cryptoStream = new CryptoStream(_aes.CreateEncryptor(), _aes.IV, CryptoStreamMode.Write))
            {
                var buffer = new byte[ciphertext.Length];
                await cryptoStream.ReadAsync(buffer, 0, ciphertext.Length);
                return buffer;
            }
        }

        public async Task<byte[]> DecryptAsync(byte[] ciphertext)
        {
            using (var cryptoStream = new CryptoStream(_aes.CreateEncryptor(), _aes.IV, CryptoStreamMode.Write))
            {
                var buffer = new byte[ciphertext.Length];
                await cryptoStream.ReadAsync(buffer, 0, ciphertext.Length);
                return buffer;
            }
        }
    }
}
```
