#[tokio::main]
async fn main() -> Result<(), Box<dyn Error>> {
    let mut user_activity_stream = HashMap::new();

    // Create a hashmap to store the user activity stream
    for i in 0..50_000 {
        let user = User { id: i, name: format!("User {}", i) };
        user_activity_stream.insert(user.id, user);
    }

    // Connect to the database and fetch the user activity stream
    let mut db = Database::new();
    let user_activity_stream = db.get_user_activity_stream(&user_activity_stream)?;

    // Process the user activity stream in real-time
    for (user, activity) in &user_activity_stream {
        process_activity(user, activity);
    }

    Ok(())
}

// Process a single user's activity stream
fn process_activity(user: &User, activity: Vec<Activity>) -> Result<(), Box<dyn Error>> {
    // Check if the activity is still valid
    let mut is_valid = true;
    for i in 0..activity.len() {
        let current_activity = activity[i];
        if !is_current_activity(current_activity) {
            is_valid = false;
            break;
        }
    }

    // If the activity is not valid, remove it from the cache
    if !is_valid {
        user_activity_stream.remove(&user);
    }

    Ok(())
}

// Check if an activity is still valid
fn is_current_activity(activity: Activity) -> bool {
    // Check if the activity is recent and not expired
    let now = Instant::now();
    let duration = now.duration_since(activity.created_at);
    return (duration < Duration::days(14)) && !activity.expired;
}
