            tiles.Add(tile.Id, tile);
        }

        public void AddEntity(int id, string type, float x, float y)
        {
            Entity entity = new Entity(id, type, x, y);
            entities.Add(entity);
        }

        public void UpdateTile(int id, int size, string materialType, int resourceCapacity)
        {
            if (tiles.ContainsKey(id))
            {
                Tile tile = tiles[id];
                tile.Size = size;
                tile.MaterialType = materialType;
                tile.ResourceCapacity = resourceCapacity;
            }
        }

        public void UpdateEntity(int id, string type, float x, float y)
        {
            if (entities.Any(e => e.Id == id))
            {
                Entity entity = entities.FirstOrDefault(e => e.Id == id);
                entity.Type = type;
                entity.X = x;
                entity.Y = y;
            }
        }

        public void RemoveTile(int id)
        {
            tiles.Remove(id);
        }

        public void RemoveEntity(int id)
