    int userId; // User ID of the session
    std::string videoId; // Video ID being played back
    DeviceType deviceType; // Type of device (e.g., desktop, mobile)
    NetworkQuality networkQuality; // Current network quality
    PlaybackState playbackState; // Current state of the playback (e.g., buffering, playing)
    std::vector<std::future<void>> bitrateSwitchThreads; // Threads for handling bitrate switching
};

// Define a struct to represent a video segment
struct VideoSegment {
    int segmentId; // Unique ID of the segment
    long startTime; // Start time of the segment in milliseconds
    long duration; // Duration of the segment in milliseconds
    std::string content; // Content of the segment (e.g., video frames)
};

// Define a struct to represent a buffer for a playback session
struct Buffer {
    int size; // Size of the buffer in bytes
    int capacity; // Capacity of the buffer in bytes
    std::vector<VideoSegment> segments; // Segments stored in the buffer
    std::mutex mutex; // Mutex for synchronizing access to the buffer
    std::condition_variable conditionVariable; // Condition variable for notifying changes to the buffer
};

// Define a struct to represent analytics data for a playback session
