    session.userId = userId;
    session.videoId = videoId;
    session.deviceType = deviceType;
    session.networkQuality = networkQuality;
    session.playbackState = PlaybackState::BUFFERING;

    // Create a new buffer object for the session
    Buffer* buffer = new Buffer();
    buffer->size = 0;
    buffer->capacity = 1024 * 1024; // Set initial capacity to 1 MB
    buffer->segments.reserve(3); // Reserve space for up to 3 video segments

    // Add the session and buffer to the library
    std::lock_guard<std::mutex> lock(PlaybackLibrary.mutex);
    PlaybackLibrary.sessions[userId] = session;
    PlaybackLibrary.buffers.push_back(buffer);
}

// Define a function to start playback for a user
