#include <stdio.h>
#include <stdlib.h>
#include <string.h>

void renameFiles(char* dirPath, char** filenames, int numFilenames) {
    // Initialize variables
    char newExtension[10];
    int i;

    // Loop through each filename and determine a new extension using sprintf
    for (i = 0; i < numFilenames; i++) {
        sprintf(newExtension, "%s.txt", filenames[i]);
        rename(dirPath, filenames[i], newExtension);
    }

    // Log all file renamings to a centralized log file
    FILE* logFile = fopen("renaming_log.txt", "a");
    for (i = 0; i < numFilenames; i++) {
        fprintf(logFile, "%s renamed to %s\n", filenames[i], newExtension);
    }
    fclose(logFile);
}
```
