    // Loop through each filename and perform resource management tasks
    for (i = 0; i < numFilenames; i++) {
        getrusage(RUSAGE_SELF, &usage);

        // Monitor system performance and resource usage to identify and mitigate bottlenecks
        if (time(NULL) - startTime > MAX_TIME_PERIOD) {
            printf("Bottleneck detected. Slowing down processing...\n");
            sleep(1);
        } else if (usage.ru_maxrss > MAX_MEMORY) {
            printf("Memory usage threshold reached. Pausing for %d seconds...\n", PAUSE_TIME);
            sleep(PAUSE_TIME);
