FileTransferManager::FileTransferManager() {
    // Initialize internal data structures
}

FileTransferManager::~FileTransferManager() {
    // Clean up any resources used by the class
}

bool FileTransferManager::startFileTransfer(const std::string& file_name, const PeerID& peer_id) {
    // Check if a file transfer is already active for this file and peer
    if (isFileTransferActive(file_name, peer_id)) {
        return false;
    }

    // Create a new FileTransfer object and add it to the list of active transfers
    std::shared_ptr<FileTransfer> file_transfer = std::make_shared<FileTransfer>();
    file_transfer->startTransfer(file_name, peer_id);
    file_transfers_.insert({ file_name, file_transfer });

    // Update the status of the connection with the given peer to "active"
    updateConnectionStatus(peer_id, true);

    return true;
}

bool FileTransferManager::stopFileTransfer(const FileID& file_id) {
    // Check if a file transfer is active for this file ID
    auto it = file_transfers_.find(file_id);
    if (it == file_transfers_.end()) {
        return false;
    }

    // Stop the file transfer and remove it from the list of active transfers
    std::shared_ptr<FileTransfer> file_transfer = it->second;
    file_transfer->stopTransfer();
    file_transfers_.erase(it);

    return true;
}

void FileTransferManager::updateFileTransferStatus(const FileID& file_id, bool is_active) {
    // Check if a file transfer is active for this file ID
    auto it = file_transfers_.find(file_id);
    if (it == file_transfers_.end()) {
        return;
    }

    // Update the status of the file transfer to "active" or "inactive"
    std::shared_ptr<FileTransfer> file_transfer = it->second;
    file_transfer->setIsActive(is_active);
}

bool FileTransferManager::addPeer(const PeerID& peer_id) {
    // Check if the given peer is already connected to this node
    auto it = peer_connections_.find(peer_id);
    if (it != peer_connections_.end()) {
        return false;
    }

    // Create a new PeerConnection object and add it to the list of active connections
    std::shared_ptr<PeerConnection> peer_connection = std::make_shared<PeerConnection>();
    peer_connection->updateStatus(true);
    peer_connections_.insert({ peer_id, peer_connection });

    return true;
}

bool FileTransferManager::stopPeer(const PeerID& peer_id) {
    // Check if the given peer is already connected to this node
    auto it = peer_connections_.find(peer_id);
    if (it == peer_connections_.end()) {
        return false;
    }

    // Stop the connection with the given peer and remove it from the list of active connections
    std::shared_ptr<PeerConnection> peer_connection = it->second;
    peer_connection->updateStatus(false);
    peer_connections_.erase(it);

    return true;
}

bool FileTransferManager::isFileTransferActive(const FileID& file_id) const {
    // Check if a file transfer is active for this file ID
    auto it = file_transfers_.find(file_id);
    if (it == file_transfers_.end()) {
        return false;
    }

    // Return true if the file transfer is active, else false
    std::shared_ptr<FileTransfer> file_transfer = it->second;
    return file_transfer->isActive();
}

