#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <errno.h>
#include <time.h>

#define NFAPI_CRC_INDICATION_PDU_T struct {
    int crc_indication;
    char* data;
}

// Thread-safe shared queue for storing CSV rows
typedef struct {
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    size_t capacity;
    int head;
    int tail;
    char** rows;
} csv_queue_t;

// Initialize a shared queue with the given capacity
csv_queue_t* init_csv_queue(size_t capacity) {
    csv_queue_t* q = malloc(sizeof(csv_queue_t));
    if (!q) return NULL;
    q->capacity = capacity;
    q->head = 0;
    q->tail = 0;
    q->rows = calloc(q->capacity, sizeof(char*));
    if (!q->rows) {
        free(q);
        return NULL;
    }
    pthread_mutex_init(&q->mutex, NULL);
    pthread_cond_init(&q->cond, NULL);
    return q;
}

// Destroy a shared queue and free its resources
void destroy_csv_queue(csv_queue_t* q) {
    if (!q) return;
    free(q->rows);
    pthread_mutex_destroy(&q->mutex);
    pthread_cond_destroy(&q->cond);
    free(q);
}

// Enqueue a new CSV row into the shared queue
void enqueue_csv_row(csv_queue_t* q, char* row) {
    if (!q || !row) return;
    pthread_mutex_lock(&q->mutex);
    while (q->tail - q->head == q->capacity) {
        pthread_cond_wait(&q->cond, &q->mutex);
    }
    int next = (q->tail + 1) % q->capacity;
    if (next == q->head) {
        // Queue is full, drop the oldest row
        free(q->rows[q->head]);
        q->head = (q->head + 1) % q->capacity;
    }
    q->rows[q->tail] = strdup(row);
    q->tail = next;
    pthread_cond_signal(&q->cond);
    pthread_mutex_unlock(&q->mutex);
}

// Dequeue a CSV row from the shared queue
char* dequeue_csv_row(csv_queue_t* q) {
    if (!q) return NULL;
    pthread_mutex_lock(&q->mutex);
    while (q->tail - q->head == 0) {
        pthread_cond_wait(&q->cond, &q->mutex);
    }
    int next = (q->head + 1) % q->capacity;
    char* row = q->rows[q->head];
    q->head = next;
    pthread_cond_signal(&q->cond);
    pthread_mutex_unlock(&q->mutex);
    return row;
}

// Read a CSV file into the shared queue
int read_csv_file(const char* filename, csv_queue_t* q) {
    FILE* fp = fopen(filename, "r");
    if (!fp) {
        perror("Error opening file");
        return -1;
    }
    int rows = 0;
    char line[4096];
    while (fgets(line, sizeof(line), fp)) {
        enqueue_csv_row(q, strdup(line));
        rows++;
    }
    fclose(fp);
    return rows;
}

// Parse a CSV row into an NFAPI_CRC_INDICATION_PDU_T structure
int parse_crc_indication_pdu(char* row, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (!row || !pdu) return -1;
    char** fields = strtok(row, ",");
    if (!fields) return -1;
    int n = 0;
    while (fields[n] != NULL) {
        switch (n) {
            case 0: pdu->crc_indication = atoi(fields[n]); break;
            case 1: pdu->data = fields[n]; break;
        }
        n++;
    }
    return n - 1; // Number of columns read, minus the header row
}

// Populate an array of NFAPI_CRC_INDICATION_PDU_T structures from a CSV file
int populate_crc_indication_pdus(const char* filename, NFAPI_CRC_INDICATION_PDU_T** pdus) {
    if (!filename || !pdus) return -1;
    csv_queue_t* q = init_csv_queue(10000); // Initial capacity of 10,000 rows
    if (!q) return -1;
    int num_rows = read_csv_file(filename, q);
    if (num_rows < 0) {
        destroy_csv_queue(q);
        return -1;
    }
    *pdus = calloc(num_rows, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*pdus) {
        destroy_csv_queue(q);
        return -1;
    }
    int i = 0;
    while (i < num_rows) {
        char* row = dequeue_csv_row(q);
        if (!row) break;
        int n = parse_crc_indication_pdu(row, (*pdus) + i);
        if (n < 0) {
            destroy_csv_queue(q);
            return -1;
        }
        i += n;
    }
    destroy_csv_queue(q);
    return i; // Number of PDUs populated
}

int main() {
    const char* filename = "example.csv";
    NFAPI_CRC_INDICATION_PDU_T** pdus = NULL;
    populate_crc_indication_pdus(filename, &pdus);
    for (int i = 0; i < num_rows; i++) {
        printf("CRC Indication PDU %d: crc_indication=%d, data=%s\n", i + 1, pdus[i]->crc_indication, pdus[i]->data);
    }
    return 0;
}
```
This code creates a shared queue to hold the CSV rows and uses `fgets` to read each row of the file into the queue. The `strtok` function is then used to split each row into fields, which are then parsed into an `NFAPI_CRC_INDICATION_PDU_T` structure using the `atoi` and `strdup` functions.

The main function creates a shared array of `NFAPI_CRC_INDICATION_PDU_T` structures to hold the populated PDUs, and passes its address to the `populate_crc_indication_pdus` function as a parameter. The function reads each row from the queue and populates an element in the array with the corresponding data.

Finally, the main function prints out information about each populated PDU using the same format used by the original code.']

