    public class DataIngestionPipeline
    {
        private readonly ILogger<DataIngestionPipeline> _logger;
        private readonly NpgsqlConnection _pgConn;
        private readonly RabbitMQ.Client.IConnection _rabbitMqConn;
        private readonly Kafka.Client.IConsumer _kafkaConsumer;
        private readonly Azure.EventHubs.EventHubClient _eventHubsClient;
        private readonly S3.Bucket.S3Client _s3Client;

        public DataIngestionPipeline(ILogger<DataIngestionPipeline> logger, NpgsqlConnection pgConn, RabbitMQ.Client.IConnection rabbitMqConn, Kafka.Client.IConsumer kafkaConsumer, Azure.EventHubs.EventHubClient eventHubsClient, S3.Bucket.S3Client s3Client)
        {
            _logger = logger;
            _pgConn = pgConn;
            _rabbitMqConn = rabbitMqConn;
            _kafkaConsumer = kafkaConsumer;
            _eventHubsClient = eventHubsClient;
            _s3Client = s3Client;
        }

        public async Task RunAsync()
        {
            while (true)
            {
                try
                {
                    // Retrieve messages from RabbitMQ queue
                    var rabbitMqMessages = await _rabbitMqConn.BasicGet(_pgConn, 10);

                    if (rabbitMqMessages.Length == 0)
                    {
                        continue;
                    }

                    // Process messages from RabbitMQ queue
                    foreach (var rabbitMqMessage in rabbitMqMessages)
                    {
                        await ProcessMessageAsync(rabbitMqMessage);
                    }
                }
                catch (Exception ex)
                {
                    Logger.LogError(ex, "Failed to retrieve messages from RabbitMQ queue");
                }

                try
                {
                    // Retrieve messages from Kafka topic
                    var kafkaMessages = await _kafkaConsumer.PollAsync();

                    if (kafkaMessages.Count == 0)
                    {
                        continue;
                    }

                    // Process messages from Kafka topic
                    foreach (var kafkaMessage in kafkaMessages)
                    {
                        await ProcessMessageAsync(kafkaMessage);
                    }
                }
                catch (Exception ex)
                {
                    Logger.LogError(ex, "Failed to retrieve messages from Kafka topic");
                }

                try
                {
                    // Retrieve messages from Azure Event Hubs
                    var eventHubMessages = await _eventHubsClient.ReceiveBatchAsync();

                    if (eventHubMessages.Count == 0)
                    {
                        continue;
                    }

                    // Process messages from Azure Event Hubs
                    foreach (var eventHubMessage in eventHubMessages)
                    {
                        await ProcessMessageAsync(eventHubMessage);
                    }
                }
                catch (Exception ex)
                {
                    Logger.LogError(ex, "Failed to retrieve messages from Azure Event Hubs");
                }

                try
                {
                    // Retrieve messages from S3 bucket
                    var s3Messages = await _s3Client.GetObjectsAsync();

                    if (s3Messages.Count == 0)
                    {
                        continue;
                    }

                    // Process messages from S3 bucket
                    foreach (var s3Message in s3Messages)
                    {
                        await ProcessMessageAsync(s3Message);
                    }
                }
                catch (Exception ex)
                {
                    Logger.LogError(ex, "Failed to retrieve messages from S3 bucket");
                }
            }
        }

        private async Task ProcessMessageAsync(byte[] message)
        {
            try
            {
                var json = Encoding.UTF8.GetString(message);
                var eventData = JsonConvert.DeserializeObject<EventData>(json);

                // Validate schema of incoming data
                if (!ValidateSchema(eventData))
                {
                    throw new Exception("Invalid schema");
                }

                // Process data transformation and enrichment
                eventData = await TransformAndEnrichAsync(eventData);

                // Store processed data in PostgreSQL database
                await _pgConn.StoreAsync(eventData);
            }
            catch (Exception ex)
            {
                Logger.LogError(ex, "Failed to process message");
            }
        }

        private bool ValidateSchema(EventData eventData)
        {
