  if (message_json["event"] == "configuration-update") {
    string url = message_json["url"];
    string config = message_json["config"];

    // Update the global configurations:
    g_mutex.lock();
    g_configs[url] = config;
    g_mutex.unlock();
  } else if (message_json["event"] == "heartbeat") {
    // Send a heartbeat response:
    json heartbeat_response = {
      {"event", "heartbeat-response"},
      {"id", message_json["id"]}
    };
    websocket_client.send(heartbeat_response.dump());
  } else if (message_json["event"] == "shutdown") {
    // Shut down the utility:
    g_mutex.lock();
    g_shutdown = true;
    g_mutex.unlock();
  }
}

void handle_file_update(const string& path, const string& content) {
