  // Update the global configurations:
  g_mutex.lock();
  g_configs[path] = file_update["config"];
  g_mutex.unlock();
}

void handle_request(const string& request_url, const string& request_body) {
  // Parse the request body:
  json request_json = json::parse(request_body);

  // Check if the request is for a configuration update:
  if (request_json["event"] == "configuration-update") {
