        }
    }

    void start() {
        // Start the ingest and storage threads
        should_stop_ = false;
        for (int i = 0; i < num_ingest_threads_; ++i) {
            ingest_threads_.push_back(std::thread(&DataProcessor::ingestThread, this));
        }
        for (int i = 0; i < num_storage_threads_; ++i) {
            storage_threads_.push_back(std::thread(&DataProcessor::storageThread, this));
        }
    }

private:
    void ingestThread() {
        std::vector<SensorReading> readings;
        while (!should_stop_) {
            // Try to pop a batch of readings from the queue
            bool success = ingest_queue_.try_pop(readings);
            if (!success) {
                continue;
            }

            // Process the readings in parallel
            std::vector<std::future<void>> futures;
            for (auto& reading : readings) {
                auto future = std::async([reading]() {
                    // Perform data ingestion tasks here
                    // ...
                });
                futures.push_back(future);
            }

            // Wait for all tasks to finish
            for (auto& future : futures) {
                future.wait();
            }
        }
    }

    void storageThread() {
        std::vector<SensorReading> readings;
        while (!should_stop_) {
            // Try to pop a batch of readings from the queue
            bool success = ingest_queue_.try_pop(readings);
            if (!success) {
                continue;
            }

            // Store the readings in the database
            std::vector<std::future<void>> futures;
            for (auto& reading : readings) {
                auto future = std::async([reading]() {
                    // Perform storage tasks here
                    // ...
                });
                futures.push_back(future);
            }

            // Wait for all tasks to finish
            for (auto& future : futures) {
                future.wait();
            }
        }
    }

private:
    std::atomic<bool> should_stop_;
    std::condition_variable cv_;
    std::mutex mutex_;
    std::queue<std::vector<SensorReading>> ingest_queue_;
    std::queue<std::vector<SensorReading>> storage_queue_;
};
