use std::process::Command;
use std::time::Instant;
use std::time::Duration;
use std::fs::File;
use std::io::BufReader;
use std::io::prelude::*;

fn measure_rustc_compile(compiler_path: &str, input_file: &str) -> i32 {
    let mut args = vec![];
    args.push("-Z".to_string()); // Custom logging hook
    args.push("--log-file=output.log");

    let start = Instant::now();
    let output = Command::new(compiler_path)
        .args(&args)
        .current_dir(input_file)
        .stdout(Stdio::inherit())
        .stderr(Stdio::inherit())
        .output()
        .unwrap();
    let end = Instant::now();

    let duration = end.duration_since(start);
    let resident_set_size = get_resident_set_size(input_file).unwrap();

    println!("Compilation took {} seconds", duration.as_secs());
    println!("Resident set size: {}", resident_set_size);

    output.status.code().unwrap()
}

fn get_resident_set_size(input_file: &str) -> Result<u64, std::io::Error> {
    let mut file = File::open(input_file)?;
    let mut buf = Vec::new();
    file.read_to_end(&mut buf)?;

    let mut resident_set_size: u64 = 0;
    for byte in buf {
        resident_set_size += (byte as u64) * 8;
    }

    Ok(resident_set_size)
}
