    public void processTransaction(String transactionId, String transactionData) {
        executor.execute(() -> {
            // Compute MD5 hash of the transaction data for filtering and analytics
            String hash = DigestUtils.md5Hex(transactionData);

            // Filter transactions based on age, frequency, and weighted sum threshold
            boolean isFiltered = filterTransaction(hash);

            if (!isFiltered) {
                // Process transaction data using a C# function for computing MD5 hashes
                String processedTransaction = processCSharpHash(transactionData);

                // Handle successful transaction processing
                handleSuccessfulTransactionProcessing(processedTransaction);
            } else {
                // Handle filtered transactions
                handleFilteredTransaction(hash);
            }
        });
    }

    private boolean filterTransaction(String hash) {
        long age = getAgeInSeconds(hash);
        int frequency = getFrequencyCount(hash);
        double weightedSumThreshold = 0.5; // Adjustable threshold for filtering

        if (age > 3 || frequency > 100) {
            return true;
        } else {
            double weightedSum = calculateWeightedSum(age, frequency);
            return weightedSum < weightedSumThreshold;
        }
    }

    private long getAgeInSeconds(String hash) {
        // Calculate age of the transaction in seconds using a C# function for computing MD5 hashes
        int age = getCSharpHashAgeInSeconds(hash);
        return (long) age;
    }

    private int getFrequencyCount(String hash) {
        // Count frequency of the transaction within the last 3 seconds using a C# function for computing MD5 hashes
        int frequency = getCSharpHashFrequencyInSeconds(hash);
        return (int) frequency;
    }

    private double calculateWeightedSum(long age, int frequency) {
        // Calculate weighted sum of the transaction age and frequency using a C# function for computing MD5 hashes
        double weightedSum = getCSharpHashWeightedSum(age, frequency);
        return (double) weightedSum;
    }

    private void handleSuccessfulTransactionProcessing(String processedTransaction) {
        // Handle successful transaction processing using a C# function for computing MD5 hashes
        String result = processCSharpHashResult(processedTransaction);
        System.out.println("Transaction processed successfully: " + result);
