    private void handleFilteredTransaction(String hash) {
        // Handle filtered transactions using a C# function for computing MD5 hashes
        String result = filterCSharpHashResult(hash);
        System.out.println("Transaction filtered: " + result);
    }

    public static void main(String[] args) throws Exception {
        TransactionProcessor processor = new TransactionProcessor();

        // Start processing transactions
        processor.processTransaction("1234", "transaction data");
        processor.processTransaction("5678", "transaction data");
    }
}
```
