#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <unistd.h>
#include <pthread.h>
#include <errno.h>

// Constants for file categories and naming convention
#define TEXT_FILE  0
#define BINARY_FILE 1
#define IMAGE_FILE  2
#define FILE_NAME_LEN 256
#define TIMESTAMP_FORMAT "%Y-%m-%d %H:%M:%S"

// Structure to hold file metadata
struct file_metadata {
    int type; // 0 for text, 1 for binary, 2 for image
    unsigned long size;
    char name[FILE_NAME_LEN];
};

// Function to categorize files based on content type and size
int categorize_file(const char* filepath) {
    struct stat sb;
    if (stat(filepath, &sb) == -1) {
        perror("cannot access file");
        return 0;
    }
    unsigned long size = sb.st_size;
    char* data = malloc(size);
    FILE* fp = fopen(filepath, "r");
    if (fp == NULL) {
        perror("cannot open file");
        free(data);
        return 0;
    }
    // Read the entire file into memory
    size_t nread = fread(data, 1, size, fp);
    fclose(fp);
    if (nread != size) {
        perror("cannot read file");
        free(data);
        return 0;
    }
    // Check the file type based on content type and size
    int type = TEXT_FILE;
    if (strstr(filepath, ".txt")) {
        type = TEXT_FILE;
    } else if (strstr(filepath, ".bin")) {
        type = BINARY_FILE;
    } else if (strstr(filepath, ".jpg") || strstr(filepath, ".jpeg") ||
               strstr(filepath, ".png") || strstr(filepath, ".gif")) {
        type = IMAGE_FILE;
    }
    // Free the memory allocated for data
    free(data);
    return type;
}

// Function to rename files based on their content type and size
void rename_files(const char* directory) {
    struct dirent** list = NULL;
    int n = scandir(directory, &list, NULL, alphasort);
    if (n == -1) {
        perror("cannot scan directory");
        return;
    }
    for (int i = 0; i < n; i++) {
        char* filepath = list[i]->d_name;
        // Skip non-files and hidden files
        if (!strcmp(filepath, ".") || !strcmp(filepath, "..")) continue;
        int type = categorize_file(filepath);
        if (type == 0) {
            // Rename text file to <filename>_<timestamp>.txt
            char* timestamp = malloc(FILE_NAME_LEN);
            time_t t = time(NULL);
            strftime(timestamp, FILE_NAME_LEN, TIMESTAMP_FORMAT, localtime(&t));
            char new_name[FILE_NAME_LEN];
            snprintf(new_name, FILE_NAME_LEN, "%s_%s.txt", filepath, timestamp);
            free(timestamp);
            rename(filepath, new_name);
        } else if (type == 1) {
            // Rename binary file to <filename>_<timestamp>.bin
            char* timestamp = malloc(FILE_NAME_LEN);
            time_t t = time(NULL);
            strftime(timestamp, FILE_NAME_LEN, TIMESTAMP_FORMAT, localtime(&t));
            char new_name[FILE_NAME_LEN];
            snprintf(new_name, FILE_NAME_LEN, "%s_%s.bin", filepath, timestamp);
            free(timestamp);
            rename(filepath, new_name);
        } else if (type == 2) {
            // Rename image file to <filename>_<timestamp>.jpg or .jpeg or .png or .gif
            char* timestamp = malloc(FILE_NAME_LEN);
            time_t t = time(NULL);
            strftime(timestamp, FILE_NAME_LEN, TIMESTAMP_FORMAT, localtime(&t));
            char new_name[FILE_NAME_LEN];
            snprintf(new_name, FILE_NAME_LEN, "%s_%s.jpg", filepath, timestamp);
            int j = 0;
            while (j < n) {
                if (!strcmp(list[j]->d_name, new_name)) break;
                j++;
            }
            if (j == n) {
                // File does not exist, rename it
                free(timestamp);
                rename(filepath, new_name);
            } else {
                // File exists, check if the same file already exists with a different extension
                char* ext = strrchr(list[j]->d_name, '.');
                if (!strcmp(ext + 1, "txt") || !strcmp(ext + 1, "bin")) {
                    // Same file already exists with a different extension, rename this one to .jpg or .jpeg or .png or .gif
                    char* ext = strrchr(filepath, '.');
                    snprintf(new_name, FILE_NAME_LEN, "%s_%s.%s", filepath, timestamp, ext + 1);
                    free(timestamp);
                    rename(filepath, new_name);
                } else {
                    // File does not exist with a different extension, rename it to .jpg or .jpeg or .png or .gif
                    free(timestamp);
                    rename(filepath, new_name);
                }
            }
        }
    }
    // Free the memory allocated for list
    for (int i = 0; i < n; i++) {
        free(list[i]);
    }
    free(list);
}

// Function to handle thread-safe file operations
void* file_handler(void* arg) {
    char* directory = (char*)arg;
    while (1) {
        // Wait for a signal to start renaming files
        int signal = wait_for_signal();
        if (signal == -1) {
            perror("cannot wait for signal");
            return NULL;
        }
        // Rename files in the directory based on their content type and size
        rename_files(directory);
    }
}

// Main function to run the program
int main() {
    char* directory = "/path/to/shared/directory";
    pthread_t thread;
    if (pthread_create(&thread, NULL, file_handler, (void*)directory) == -1) {
        perror("cannot create thread");
        return 1;
    }
    // Wait for the signal to start renaming files
    int signal = wait_for_signal();
    if (signal == -1) {
        perror("cannot wait for signal");
        return 1;
    }
    // Rename files in the directory based on their content type and size
    rename_files(directory);
    // Wait for the thread to finish
    void* status;
    if (pthread_join(thread, &status) == -1) {
        perror("cannot join thread");
        return 1;
    }
    // Print the status of the thread
    printf("Thread exited with status %d\n", (int)status);
    return 0;
}
```
This program uses a separate thread to handle file operations in the directory. The main function creates a new thread and passes the path to the shared directory as an argument. The thread function waits for a signal to start renaming files, and then it calls the `rename_files` function to rename the files based on their content type and size. The main function also waits for the thread to finish before exiting.

The program uses a separate thread because file operations can take a long time, and we don't want to block the main thread while waiting for the signal or for the thread to finish. By using a separate thread, we can perform other tasks in parallel while waiting for the signal or for the thread to finish.

The program also uses a queue to handle signals. When the main function receives a signal, it adds the signal to the queue. The thread function polls the queue to check if there are any signals available. If there is a signal available, the thread function starts renaming files in the directory based on their content type and size.

The program also uses the `time` function to get the current time and the `strftime` function to format the timestamp. The `rename_files` function uses the `snprintf` function to create a new file name for each file based on the original file name, the content type, and the timestamp.

The program also uses the `wait_for_signal` function to wait for a signal to start renaming files. The `wait_for_signal` function returns a negative value if it fails or 0 if there are no signals available. If it returns 1, then it means that there is at least one signal available and it can be removed from the queue.

The program also uses the `pthread_create` function to create a new thread and the `pthread_join` function to wait for the thread to finish before exiting. The `pthread_create` function returns a negative value if it fails or 0 if it succeeds. If it returns a positive value, then it means that the thread was created successfully, but it hasn't started running yet. The `pthread_join` function returns a negative value if it fails or 0 if it succeeds. If it returns 1, then it means that the thread has finished running and can be joined successfully.

The program also uses the `malloc` function to allocate memory for the file name and the timestamp, and the `free` function to free the allocated memory when it's no longer needed. The program uses the `strrchr` function to find the last occurrence of a character in a string. The `snprintf` function is used to create a new file name based on the original file name, the content type, and the timestamp.

The program also uses the `perror` function to print an error message if it fails or if there's a problem with the signal. The `printf` function is used to print the status of the thread when it exits.']

