        indications[i].rx_ue_information = RX_UE_INFORMATION_TAG;
        indications[i].rnti = RNTI;
        indications[i].crc_indication_rel8 = CRC_INDICATION_REL8_TAG;
    }
    for (int i = 0; i < numIndications; i++) {
        printf("CRC Indication %d: RX UE Information Tag = %u, RNTI = %u, CRC Indication REL8 Tag = %u\n",
                i+1, indications[i].rx_ue_information, indications[i].rnti, indications[i].crc_indication_rel8);
    }
}

int main() {
    int numIndications = 0;
    printf("Enter the number of CRC Indications: ");
    scanf("%d", &numIndications);
    if (numIndications > MAX_CRC_INDICATIONS) {
        printf("Maximum number of CRC Indications exceeded. Maximum allowed is %d\n", MAX_CRC_INDICATIONS);
        return 1;
    }
    createAndLogNFapiCrcIndications(numIndications);
    return 0;
}
