    // Read the input file
    ifstream infile(file_path.c_str(), ios::binary);
    if (!infile) {
        log("Failed to read input file", FILE_ERROR);
        return FILE_ERROR;
    }
    vector<char> buffer(istreambuf_iterator<char>(infile), {});
    infile.close();
    // Decrypt the data
    unsigned char* decrypted = (unsigned char*)malloc(buffer.size() + AES_BLOCK_SIZE);
    int dec_len = decryptBuffer(decrypted, buffer.data(), buffer.size());
    if (dec_len == -1) {
        log("Failed to decrypt data", ENCRYPTION_ERROR);
        return ENCRYPTION_ERROR;
    }
    // Write the output file
    ofstream outfile(output_file.c_str(), ios::binary);
    if (!outfile) {
        log("Failed to write output file", FILE_ERROR);
        return FILE_ERROR;
    }
    outfile.write((char*)decrypted, dec_len);
    outfile.close();
    // Clean up
    free(decrypted);
    return ret;
}
int encryptBuffer(unsigned char* encrypted, unsigned char* buffer, int len) {
    AES_KEY aesKey;
    if (AES_set_encrypt_key(buffer, KEY_SIZE * 8, &aesKey) == 0) {
        return -1;
    }
    AES_ctr128_encrypt(buffer, encrypted, len, &aesKey, iv, NULL, NULL);
    return AES_BLOCK_SIZE + (len % AES_BLOCK_SIZE != 0 ? AES_BLOCK_SIZE : 0);
}
int decryptBuffer(unsigned char* decrypted, unsigned char* buffer, int len) {
    AES_KEY aesKey;
    if (AES_set_decrypt_key(buffer, KEY_SIZE * 8, &aesKey) == 0) {
        return -1;
    }
    AES_ctr128_encrypt(buffer, decrypted, len, &aesKey, iv, NULL, NULL);
    return AES_BLOCK_SIZE + (len % AES_BLOCK_SIZE != 0 ? AES_BLOCK_SIZE : 0);
}

// Define the thread functions
void threadFunc(int id) {
    // Encrypt or decrypt the file data
    if (leader) {
        encrypt(file_data, id + ".enc");
    } else {
        decrypt(file_data, id + ".dec");
    }
}
void* threadWrapper(void* arg) {
    int id = (int)arg;
    threadFunc(id);
    return NULL;
}

// Define the main function
int main(int argc, char** argv) {
    // Parse the command line arguments
    if (argc != 3) {
        log("Usage: " + string(argv[0]) + " <input_file> <output_file>", FILE_ERROR);
        return -1;
    }
    file_data = argv[1];
    // Initialize the RSA key pair
    rsa_key = RSA_new();
    if (!RSA_generate_key_ex(rsa_key, KEY_SIZE, 65537, NULL)) {
        log("Failed to generate RSA key pair", ENCRYPTION_ERROR);
        return -1;
    }
    // Initialize the IV
    if (!RAND_bytes(iv, AES_BLOCK_SIZE)) {
        log("Failed to generate random IV", ENCRYPTION_ERROR);
        return -1;
    }
    // Determine whether this instance is the leader
    if (atoi(argv[2]) == 0) {
        leader = true;
    } else {
        leader = false;
    }
    // Get the total number of threads
    thread_count = atoi(argv[2]);
    // Create and start the threads
    pthread_t threads[thread_count];
    for (int i = 0; i < thread_count; ++i) {
        int rc = pthread_create(&threads[i], NULL, threadWrapper, (void*)i);
        if (rc != 0) {
            log("Failed to create thread", ENCRYPTION_ERROR);
            return -1;
        }
    }
    // Wait for the threads to finish
    for (int i = 0; i < thread_count; ++i) {
        pthread_join(threads[i], NULL);
    }
    // Clean up
    RSA_free(rsa_key);
}
```
This code defines a `main` function that initializes the RSA key pair and IV, then determines whether it is the leader instance. It then creates and starts a number of threads, each of which either encrypts or decrypts the file data based on its instance ID. The main thread waits for all of the threads to finish before cleaning up the RSA key pair and returning from `main`.

The `threadFunc` function is called by each thread in its own context, so it does not have access to any shared variables. It uses the instance ID passed to it as an argument to determine whether to encrypt or decrypt the file data. If the instance is the leader, it calls the `encrypt` function to encrypt the file data and writes it to a file with a name constructed from the instance ID. Otherwise, it calls the `decrypt` function to decrypt the file data and writes it to a file with a name constructed from the instance ID.

The `threadWrapper` function is called by each thread in its own context, so it does not have access to any shared variables. It simply calls the `threadFunc` function with the appropriate arguments and returns the result.']

