// Define the structure for the encryption key
typedef struct EncryptionKey {
    int keySize;
    char* keyMaterial;
} EncryptionKey;

// Define the structure for the encryption context
typedef struct EncryptionContext {
    EncryptionKey key;
    bool isEncrypted;
    int chunkSize;
} EncryptionContext;

// Function to generate a random encryption key
void generateRandomKey(EncryptionKey* key) {
    key->keySize = 128;
    key->keyMaterial = (char*) malloc(key->keySize);
    for (int i = 0; i < key->keySize; i++) {
        *(key->keyMaterial + i) = rand() % 256;
    }
}

// Function to initialize the encryption context
void initEncryptionContext(EncryptionContext* ctx, int chunkSize) {
    generateRandomKey(&ctx->key);
    ctx->isEncrypted = false;
    ctx->chunkSize = chunkSize;
}

// Function to encrypt a file
void encryptFile(FILE* infile, FILE* outfile, EncryptionContext* ctx) {
    // Read the input file in chunks of size ctx->chunkSize
    char buffer[ctx->chunkSize];
    while (fread(buffer, 1, ctx->chunkSize, infile) > 0) {
        // Encrypt each chunk using AES-256 with the encryption key
        for (int i = 0; i < ctx->key.keySize; i++) {
            buffer[i] ^= ctx->key.keyMaterial[i];
        }
        // Write the encrypted chunk to the output file
        fwrite(buffer, 1, ctx->chunkSize, outfile);
    }
}

// Function to decrypt a file
void decryptFile(FILE* infile, FILE* outfile, EncryptionContext* ctx) {
    // Read the input file in chunks of size ctx->chunkSize
    char buffer[ctx->chunkSize];
    while (fread(buffer, 1, ctx->chunkSize, infile) > 0) {
        // Decrypt each chunk using AES-256 with the encryption key
        for (int i = 0; i < ctx->key.keySize; i++) {
            buffer[i] ^= ctx->key.keyMaterial[i];
        }
        // Write the decrypted chunk to the output file
        fwrite(buffer, 1, ctx->chunkSize, outfile);
    }
}

// Function to encrypt a string
void encryptString(const char* input, char** output) {
    EncryptionContext ctx;
    initEncryptionContext(&ctx, strlen(input));
    *output = (char*) malloc(strlen(input));
    for (int i = 0; i < strlen(input); i++) {
        (*output)[i] = input[i] ^ ctx.key.keyMaterial[i];
    }
}

// Function to decrypt a string
void decryptString(const char* input, char** output) {
    EncryptionContext ctx;
    initEncryptionContext(&ctx, strlen(input));
    *output = (char*) malloc(strlen(input));
    for (int i = 0; i < strlen(input); i++) {
        (*output)[i] = input[i] ^ ctx.key.keyMaterial[i];
    }
}
