void populateNfarxIndications(int N) {

// 1. Create a linked list of NFAPI_CRC_INDICATION_PDU_T structures
list = (struct NFAPI_CRC_INDICATION_PDU_T*) malloc(sizeof(struct NFAPI_CRC_INDICATION_PDU_T) * N);

// 2. Initialize the linked list with default values
for (int i = 0; i < N; i++) {
    list[i] = (struct NFAPI_CRC_INDICATION_PDU_T) {
        .pdu = NULL,
        .SFN = 0,
        .timestamp = 0,
        .num_tlv = 0,
        .tlv = NULL
    };
}

// 3. Dynamically populate the linked list with CRC indications from each server node
for (int i = 0; i < num_nodes; i++) {
    struct NF_PCI_SERVER_NODE* node = &nodes[i];
    int index = node->index;

    // 3.1 Read the CRC indications from the server node
    struct NFAPI_CRC_INDICATION_PDU_T crc_indication;
    if (read_crc_indication(node, &crc_indication) < 0) {
        continue;
    }

    // 3.2 Append the CRC indications to the linked list
    list[index] = crc_indication;
}

// 4. Return the populated linked list of NFAPI_CRC_INDICATION_PDU_T structures
return list;
}

// Define helper functions for communication with the server nodes
struct NF_PCI_SERVER_NODE {
    int index; // Index of the server node in the cluster
    char* address; // IP address of the server node
};

int num_nodes = 5; // Number of server nodes in the cluster
struct NF_PCI_SERVER_NODE nodes[num_nodes];

// Initialize the server nodes and their corresponding indices
for (int i = 0; i < num_nodes; i++) {
    struct NF_PCI_SERVER_NODE* node = &nodes[i];
    node->index = i;
    node->address = "192.168.1.%d", i + 1);
}

// Define a function to read the CRC indications from a server node
int read_crc_indication(struct NF_PCI_SERVER_NODE* node, struct NFAPI_CRC_INDICATION_PDU_T* crc_indication) {
    // 1. Connect to the server node using its IP address and port number
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    struct sockaddr_in serv_addr;
    memset(&serv_addr, 0, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    inet_pton(AF_INET, node->address, &serv_addr.sin_addr);
    serv_addr.sin_port = htons(8080); // Port number of the server node's API endpoint

    // 2. Send a request to read the CRC indications from the server node
    char* request = "GET /crc-indication HTTP/1.1\r\nHost: 192.168.1.%d\r\nConnection: close\r\n\r\n";
    sprintf(request, request, node->index + 1);
    int n = sendto(sock, request, strlen(request), 0, (struct sockaddr*)&serv_addr, sizeof(serv_addr));
    if (n < 0) {
        perror("sendto");
        return -1;
    }

    // 3. Receive the response from the server node
    char* buffer = malloc(2048);
    struct sockaddr_in cli_addr;
    memset(&cli_addr, 0, sizeof(cli_addr));
    int len = recvfrom(sock, buffer, 2048, 0, (struct sockaddr*)&cli_addr, &len);
    if (len < 0) {
        perror("recvfrom");
        return -1;
    }

    // 4. Parse the response and extract the CRC indications
    char* token = strtok(buffer, "\r\n");
    while (token != NULL) {
        if (strncmp(token, "Content-Type:", 13) == 0) {
            token = strtok(NULL, "\r\n");
            continue;
        }
        char* name = token;
        token = strtok(NULL, ":");
        if (token == NULL) {
            break;
        }
        token = trim(token);
        if (strcmp(name, "crc-indication") == 0) {
            *crc_indication = parse_crc_indication(token);
        }
    }

    // 5. Close the socket and return
    close(sock);
    free(buffer);
    return 0;
}

// Define a function to parse a CRC indication from a string
struct NFAPI_CRC_INDICATION_PDU_T parse_crc_indication(char* token) {
    struct NFAPI_CRC_INDICATION_PDU_T crc_indication;
    memset(&crc_indication, 0, sizeof(crc_indication));
    char* temp = strtok(token, ",");
    while (temp != NULL) {
        if (strncmp(temp, "cell-id", 7) == 0) {
            temp = strtok(NULL, ",");
            continue;
        }
        int id = atoi(temp);
        crc_indication.cell_identity = id;
    }
    return crc_indication;
}

// Define a function to trim white spaces from a string
char* trim(char* str) {
    size_t len = strlen(str);
    size_t start = 0, end = len - 1;
    while (isspace(str[start])) start++;
    while (isspace(str[end]) || end == start) end--;
    str[end + 1] = '\0';
    return &str[start];
}']

