class PaymentGateway {
    private:
        std::unordered_map<std::string, std::string> paymentMethods;
        std::unordered_map<std::string, std::string> currencies;
        int retryAttempts;
        double exponentialBackoffFactor;
        bool circuitBreaker;
        int circuitBreakerTimeout;
        std::vector<std::string> transactionLog;

    public:
        PaymentGateway(std::unordered_map<std::string, std::string> paymentMethods, std::unordered_map<std::string, std::string> currencies) {
            this->paymentMethods = paymentMethods;
            this->currencies = currencies;
            retryAttempts = 3;
            exponentialBackoffFactor = 1.5;
            circuitBreaker = true;
            circuitBreakerTimeout = 600;
        }

    void processTransaction(std::string paymentMethod, std::string currency, double amount) {
        // Perform transaction validation
        if (amount <= 0) {
            throw "Invalid amount";
        }

        if (!paymentMethods.count(paymentMethod)) {
            throw "Unknown payment method";
        }

        if (!currencies.count(currency)) {
            throw "Unknown currency";
        }

        // Retry transaction if necessary
        for (int i = 0; i < retryAttempts; i++) {
            try {
                performTransaction(paymentMethod, currency, amount);
                break;
            } catch (std::exception& e) {
                if (i == retryAttempts - 1) {
                    throw "Failed to process transaction";
                } else {
                    std::cout << "Retrying transaction in " << exponentialBackoffFactor * i << " seconds" << std::endl;
                    std::this_thread::sleep_for(std::chrono::seconds(exponentialBackoffFactor * i));
                }
            }
        }

        // Log transaction
        transactionLog.push_back({paymentMethod, currency, amount});
    }

    private:
        void performTransaction(std::string paymentMethod, std::string currency, double amount) {
            // Implement transaction processing logic
        }
};
