        return -1;
    }
    // Check that the frequency offset is valid
    if (config->frequency_offset < -4096 || config->frequency_offset > 4095) {
        printf("Error: Invalid frequency offset (%d)\n", config->frequency_offset);
        return -1;
    }
    // Check that the pilot symbols are valid
    if (config->pilot_symbols < 0 || config->pilot_symbols > 255) {
