// Multi-threaded C library module for managing a collection of NFAPI_CRC_INDICATION_PDU_T structures
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdbool.h>

// Define the structure to hold the NFAPI CRC indication PDUs
typedef struct {
    int pdu_id;
    int pdu_length;
    unsigned char* pdu_data;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a pool allocator to manage memory allocation and deallocation
static void* nfapi_crc_indication_pool = NULL;
static int nfapi_crc_indication_pool_size = 0;

// Function to allocate memory from the pool for a new NFAPI CRC indication PDU
NFAPI_CRC_INDICATION_PDU_T* nfapi_allocate_crc_indication_pdu(int pdu_id, int pdu_length) {
    // Check if the pool is initialized
    if (nfapi_crc_indication_pool == NULL) {
        return NULL;
    }

    // Allocate memory for the new PDU from the pool
    NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pdu == NULL) {
        return NULL;
    }

    // Initialize the new PDU with the given parameters
    pdu->pdu_id = pdu_id;
    pdu->pdu_length = pdu_length;
    pdu->pdu_data = malloc(pdu_length * sizeof(unsigned char));
    if (pdu->pdu_data == NULL) {
        free(pdu);
        return NULL;
    }

    // Return the new PDU to the caller
    return pdu;
}

