import logging
import time
from collections import defaultdict
from typing import Dict, List, Union

from fastapi import FastAPI, Request
from starlette.responses import JSONResponse
from starlette.status import HTTP_200_OK, HTTP_500_INTERNAL_SERVER_ERROR

import recommendation_engine
import user_activity_tracking_api
import real_time_analytics_platform
import global_search_service

app = FastAPI()

# Cache settings
cache_ttl = 60 * 10  # 10 minutes
cache_size = 10000

# Caching layer
cached_items: Dict[str, List[Dict]] = defaultdict(list)

@app.get("/recommendations", response_model=List[Union[Dict, str]])
async def get_recommendations(request: Request):
    user_id = request.path_params["user_id"]
    session_id = f"{user_id}-{time.time()}"

    # Check cache for recommendations
    cached_recommendations = cached_items.get(session_id)
    if cached_recommendations:
        logging.info("Retrieved recommendations from cache.")
        return cached_recommendations

    # Get user activity and product information
    try:
        user_activity = await user_activity_tracking_api.get_user_activity(user_id)
        products = await global_search_service.find_similar_products(user_activity)
    except Exception as e:
        logging.exception("Failed to retrieve user activity or products.")
        return JSONResponse(status_code=HTTP_500_INTERNAL_SERVER_ERROR, content={"message": str(e)})

    # Generate recommendations using the recommendation engine
    try:
        recommendations = await recommendation_engine.generate_recommendations(products)
    except Exception as e:
        logging.exception("Failed to generate recommendations.")
        return JSONResponse(status_code=HTTP_500_INTERNAL_SERVER_ERROR, content={"message": str(e)})

    # Cache the recommendations for future use
    cached_items[session_id] = recommendations
    logging.info("Cached %d recommendations.", len(recommendations))

    return JSONResponse(status_code=HTTP_200_OK, content={"data": recommendations})

