// C header file
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <curl/curl.h>
#include <json-c/json.h>

// Struct definitions for linked list of NFAPI_CRC_INDICATION_PDU_T structures
struct NFAPI_CRC_INDICATION_PDU {
    int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned char CRCFLAG;
};
typedef struct NFAPI_CRC_INDICATION_PDU NFAPI_CRC_INDICATION_PDU_T;

// Function to initialize and populate linked list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T *init_list(int size) {
    // Allocate memory for linked list of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T *head = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * size);
    // Initialize linked list head
    head->next = NULL;

    // Initialize counter for number of elements in the linked list
    int count = 0;

    // Loop until all REST API responses are received or error occurs
    while (count < size) {
        // Retrieve UE information tags from cloud-based database using REST API
        json_object *ue_info_tags = retrieve_ue_info_tags();
        if (!ue_info_tags) {
            break;
        }

        // Loop over each UE information tag in the response
        for (int i = 0; i < json_object_array_length(ue_info_tags); i++) {
            json_object *ue_tag = json_object_array_get_idx(ue_info_tags, i);

            // Retrieve RNTI value for current UE information tag using REST API
            unsigned int rnti = retrieve_rnti(ue_tag);
            if (rnti == 0) {
                break;
            }

            // Calculate CRC flag for current UE information tag using REST API
            unsigned char crcflag = calculate_crc_flag(ue_tag, rnti);

            // Create new NFAPI_CRC_INDICATION_PDU_T structure and append to linked list
            head->next = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            head->next->RX_UE_INFORMATION_TAG = json_object_get_int(ue_tag);
            head->next->RNTI = rnti;
            head->next->CRCFLAG = crcflag;

            // Update linked list head and counter
            head = head->next;
            count++;
        }

        // Release memory for UE information tags JSON object
        json_object_put(ue_info_tags);
    }

    return head;
}

// Retrieve UE information tags from cloud-based database using REST API
json_object *retrieve_ue_info_tags() {
    // Initialize CURL handle and set URL for UE information tags
    CURL *curl = curl_easy_init();
    if (!curl) {
        return NULL;
    }
    char url[256] = "http://example.com/api/ue-info-tags";
    curl_easy_setopt(curl, CURLOPT_URL, url);

    // Set JSON response to store UE information tags in
    json_object *response = NULL;

    // Retrieve and parse UE information tags from REST API
    CURLcode res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        fprintf(stderr, "CURL failed: %s\n", curl_easy_strerror(res));
        return NULL;
    } else {
        // Get JSON response from REST API and parse into UE information tags JSON object
        curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response);
        if (json_object_get_type(response) != json_type_array) {
            fprintf(stderr, "Invalid response from REST API\n");
            return NULL;
        }
    }

    // Release memory for CURL handle
    curl_easy_cleanup(curl);

    return response;
}

// Retrieve RNTI value for current UE information tag using REST API
unsigned int retrieve_rnti(json_object *ue_tag) {
    // Initialize CURL handle and set URL for RNTI value retrieval
    CURL *curl = curl_easy_init();
    if (!curl) {
        return 0;
    }
    char url[256] = "http://example.com/api/rnti";
    curl_easy_setopt(curl, CURLOPT_URL, url);

    // Set JSON response to store RNTI value in
    json_object *response = NULL;

