    // Add items to the cache
    cache.addItem("key1", std::make_pair([&](){ std::cout << "Function 1" << std::endl; }, std::chrono::high_resolution_clock::now()));
    cache.addItem("key2", std::make_pair([&](){ std::cout << "Function 2" << std::endl; }, std::chrono::high_resolution_clock::now()));
    cache.addItem("key3", std::make_pair([&](){ std::cout << "Function 3" << std::endl; }, std::chrono::high_resolution_clock::now()));

    // Get an item from the cache
