    if (item) {
        std::cout << "Retrieved function: " << item->first << std::endl;
    } else {
        std::cout << "Key not found" << std::endl;
    }

    // Evict an item from the cache
    cache.evict();

    // Update the eviction policy of the cache
    cache.updateEvictionPolicy();

    return 0;
}']

