['```c++
#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <chrono>
#include <ctime>
#include <memory>

class HTTPRequestRecord {
public:
    // constructor and destructor
    HTTPRequestRecord(const std::string& url, const std::string& method) :
        _url(url), _method(method) {}
    ~HTTPRequestRecord() = default;

    // getters
    std::string getURL() { return _url; }
    std::string getMethod() { return _method; }

private:
    // member variables
    std::string _url;
    std::string _method;
};

class HTTPRequestManager {
public:
    // constructor and destructor
    HTTPRequestManager(const size_t capacity) :
        _capacity(capacity), _size(0), _requests() {}
    ~HTTPRequestManager() = default;

    // add request to the manager
    void addRequest(const std::string& url, const std::string& method);

    // remove request from the manager
    bool removeRequest(const size_t index);

    // get request at a given index
    HTTPRequestRecord* getRequest(const size_t index);

    // get number of requests in the manager
    size_t getSize() { return _size; }

private:
    // member variables
    const size_t _capacity;
    std::vector<std::unique_ptr<HTTPRequestRecord>> _requests;
    std::mutex _mtx;
    std::condition_variable _cv;
};

void HTTPRequestManager::addRequest(const std::string& url, const std::string& method) {
    // check if there is space to add a new request
    if (_size == _capacity) {
        return;
    }

    // create a new request record and add it to the vector
    auto request = std::make_unique<HTTPRequestRecord>(url, method);
    {
        std::lock_guard<std::mutex> lock(_mtx);
        _requests.emplace_back(std::move(request));
        ++_size;
    }
}

bool HTTPRequestManager::removeRequest(const size_t index) {
    // check if the index is valid
    if (index >= _size) {
        return false;
    }

    // remove the request at the given index and decrease the size
    std::lock_guard<std::mutex> lock(_mtx);
    _requests.erase(_requests.begin() + index);
    --_size;

    return true;
}

HTTPRequestRecord* HTTPRequestManager::getRequest(const size_t index) {
    // check if the index is valid
    if (index >= _size) {
        return nullptr;
    }

    // get the request at the given index
    std::lock_guard<std::mutex> lock(_mtx);
    return _requests[index].get();
}
