```cpp
#include <iostream>
#include <string>
#include <fstream>
#include <sstream>
#include <mutex>
#include <thread>
#include <condition_variable>
#include <chrono>
#include <unordered_map>
#include <vector>
#include <memory>

// Forward declarations
class Logger;
class LogEntry;

// Global variables
std::mutex gMutex;
std::condition_variable gCV;
std::thread* gLoggingThread = nullptr;
bool gRunning = true;
int gFrequency = 10; // ms
int gLevel = 2; // INFO level
int gMinLevel = 0; // ERROR level
int gMaxLevel = 3; // DEBUG level
std::unordered_map<std::string, Logger*> gLoggers;

// Structures and classes
struct LogEntry {
    std::string loggerName;
    int level;
    std::string message;
};

class Logger {
public:
    Logger(const std::string& name) : m_name(name) {}

    void log(int level, const std::string& message) {
        if (level >= m_minLevel && level <= m_maxLevel) {
            LogEntry entry;
            entry.loggerName = m_name;
            entry.level = level;
            entry.message = message;
            gMutex.lock();
            gLogEntries.push_back(entry);
            gCV.notify_all();
            gMutex.unlock();
        }
    }

    void setLevel(int level) { m_minLevel = level; m_maxLevel = level; }

private:
    std::string m_name;
    int m_minLevel;
    int m_maxLevel;
};

// Functions
void startLoggingThread() {
    gRunning = true;
    while (gRunning) {
        // Sleep for a certain amount of time before processing the log entries.
        std::this_thread::sleep_for(std::chrono::milliseconds(gFrequency));
        gMutex.lock();
        if (!gLogEntries.empty()) {
            // Process the log entries one by one in a thread-safe manner.
            for (auto& entry : gLogEntries) {
                if (entry.level >= gLevel && entry.level <= gMaxLevel) {
                    std::cout << "[" << entry.loggerName << "] [" << getLevelString(entry.level) << "] "
                              << entry.message << std::endl;
                }
            }
            // Clear the log entries after processing them.
            gLogEntries.clear();
        }
        gMutex.unlock();
    }
}

void stopLoggingThread() {
    gRunning = false;
    if (gLoggingThread != nullptr) {
        gCV.notify_all();
        gLoggingThread->join();
        delete gLoggingThread;
    }
}

std::string getLevelString(int level) {
    switch (level) {
        case 0: return "ERROR";
        case 1: return "WARN";
        case 2: return "INFO";
        case 3: return "DEBUG";
        default: return "UNKNOWN";
    }
}

// Usage example
int main() {
    // Initialize the logging framework.
    gFrequency = 10;
    gLevel = 2;
    gMinLevel = 0;
    gMaxLevel = 3;
    gLoggers["logger_name"] = new Logger("logger_name");

    // Start the logging thread.
    startLoggingThread();

    // Log messages using the logger.
    gLoggers["logger_name"].log(1, "This is a warning message.");
    gLoggers["logger_name"].log(2, "This is an informational message.");
    gLoggers["logger_name"].log(3, "This is a debug message.");

    // Stop the logging thread.
    stopLoggingThread();

    return 0;
}
```
Note: This code is just one possible implementation of a modular, thread-safe logging framework in C++ that integrates with an external logging system used across multiple microservices. The actual implementation may vary depending on the specific requirements and dependencies of the system being developed.']

