use crate::{UserActivityStream, User, Activity};

struct FetchUserActivityStreamAsync {
    user: Arc<User>,
    activities: Vec<Arc<Activity>>,
}

impl FetchUserActivityStreamAsync {
    pub async fn new(user: Arc<User>) -> Self {
        let mut activities = vec![];
        for activity in user.activity_stream() {
            if let Some(activity) = activity {
                activities.push(Arc::new(activity));
            }
        }
        Self { user, activities }
    }

    pub async fn fetch_activities(&mut self) -> Result<(), Error> {
        let mut connection_pool = Vec::with_capacity(10);
        for _ in 0..10 {
            connection_pool.push(Runtime::new()?);
        }
        let mut tasks = vec![];
        for runtime in &connection_pool {
            let user = self.user.clone();
            let task = runtime.spawn(async move {
                for activity in user.activity_stream() {
                    if let Some(activity) = activity {
                        return Ok(());
                    }
                }
                Err(Error::from("Failed to fetch activities"))
            });
            tasks.push(task);
        }
        select! {
            res = future::select_all(tasks) => {
                for task in &mut tasks {
                    if let Some(result) = res.next() {
                        return result;
                    }
                }
                Err(Error::from("No tasks completed"))
            }
        }
    }
}
