// StateManager.java
import java.util.*;
import java.util.concurrent.*;
import java.util.logging.*;
import java.io.*;

public class StateManager {
    private static final Logger logger = Logger.getLogger(StateManager.class.getName());
    private Map<String, MoSTState> stateCache;
    private BlockingQueue<MoSTStateUpdate> updateQueue;
    private File stateFile;

    public StateManager(String stateFilename) {
        this.stateFile = new File(stateFilename);
        this.stateCache = new ConcurrentHashMap<>();
        this.updateQueue = new LinkedBlockingDeque<>();

        // Load states from file and cache
        loadStatesFromFile();
    }

    private void loadStatesFromFile() {
        try (BufferedReader reader = new BufferedReader(new FileReader(stateFile))) {
            String line;
            while ((line = reader.readLine()) != null) {
                MoSTState state = parseMoSTState(line);
                stateCache.put(state.getId(), state);
            }
        } catch (IOException e) {
            logger.log(Level.SEVERE, "Error loading states from file", e);
        }
    }

    private MoSTState parseMoSTState(String line) {
        String[] tokens = line.split(" ");
        int id = Integer.parseInt(tokens[0]);
        int value = Integer.parseInt(tokens[1]);
        return new MoSTState(id, value);
    }

    public void updateMoSTState(int id, int value) {
        // Update state in cache and file
        MoSTState state = getMoSTState(id);
        if (state == null) {
            logger.log(Level.WARNING, "MoSTState with ID " + id + " not found");
            return;
        }
        state.setValue(value);
        updateQueue.offer(new MoSTStateUpdate(id, value));
    }

    public MoSTState getMoSTState(int id) {
        return stateCache.get(id);
    }

    public void run() {
        while (true) {
            try {
                // Get next update from queue
                MoSTStateUpdate update = updateQueue.take();
                logger.log(Level.INFO, "Received update for ID " + update.getId());

                // Update state in cache and file
                MoSTState state = getMoSTState(update.getId());
                if (state == null) {
                    logger.log(Level.WARNING, "MoSTState with ID " + update.getId() + " not found");
                    continue;
                }
                state.setValue(update.getValue());
                writeStateToFile(state);
            } catch (InterruptedException e) {
                logger.log(Level.SEVERE, "Error updating MoSTState", e);
            }
        }
    }

    private void writeStateToFile(MoSTState state) {
        try (BufferedWriter writer = new BufferedWriter(new FileWriter(stateFile))) {
            String line = state.getId() + " " + state.getValue();
            writer.write(line);
            logger.log(Level.INFO, "Wrote updated state to file");
        } catch (IOException e) {
            logger.log(Level.SEVERE, "Error writing updated state to file", e);
        }
    }
}
