  private static void processRequest(Request request) throws Exception {
    // Get the requested resource and method
    String resource = request.getResource();
    String method = request.getMethod();

    // Check if the user is authenticated
    if (!isAuthenticated()) {
      // Challenge the client for authentication
      challengeClientForAuthentication(request);
      return;
