      String mfaToken = getMfaToken(request);
      String userId = validateMfaToken(mfaToken);

      // Check if the user has permission to access the requested resource
      if (!hasPermissionToResource(userId, request.getMethod())) {
        denyAccessToResource(request);
        return;
