#include <stdio.h>
#include <stdlib.h>
#include <errno.h>
#include <string.h>
#include <assert.h>

// Function to rename file with versioning and logging
void renameWithVersion(const std::string& filename, const std::string& targetDir, int version) {
    // Initialize variables for new filename and directory path
    std::string newFilename;
    std::string newDirPath;

    // Construct new filename by appending version number to original filename
    newFilename = filename + "_v" + std::to_string(version);

    // Append unique identifier derived from file extension and incremental counter
    int i = 0;
    while (true) {
        newFilename += "_" + std::to_string(i++);
        if (newFilename.length() <= 255) break; // Maximum filename length is 255 characters
    }

    // Construct new directory path by appending version number to target directory path
    newDirPath = targetDir + "/" + std::to_string(version);

    // Create new directory if it does not exist
    if (mkdir(newDirPath.c_str(), 0755) != 0 && errno != EEXIST) {
        perror("Failed to create new directory");
        exit(1);
    }

    // Rename file in target directory to new filename
    std::string oldFilename = targetDir + "/" + filename;
    if (rename(oldFilename.c_str(), newFilename.c_str()) != 0) {
        perror("Failed to rename file");
        exit(1);
    }

    // Log all modifications in a central logging service or file
    std::string logMessage = "File renamed from '" + oldFilename + "' to '" + newFilename + "'";
    std::cout << logMessage << std::endl;
}
```
