<?php

namespace PasswordManager;

class PasswordManager {
    private $charSet;
    private $hashCostFactor;
    private $loggingService;

    public function __construct(string $charSet, int $hashCostFactor, LoggingService $loggingService) {
        $this->charSet = $charSet;
        $this->hashCostFactor = $hashCostFactor;
        $this->loggingService = $loggingService;
    }

    public function generateRandomString(int $length): string {
        $randomString = '';

        for ($i = 0; $i < $length; $i++) {
            $randomString .= $this->charSet[mt_rand(0, strlen($this->charSet) - 1)];
        }

        return $randomString;
    }

    public function hashPassword(string $password): string {
        try {
            return password_hash($password, PASSWORD_BCRYPT, ['cost' => $this->hashCostFactor]);
        } catch (Exception $e) {
            $this->loggingService->logError("Failed to hash password: {$e->getMessage()}");
            throw new PasswordManagerException("Hashing password failed", 0, $e);
        }
    }

    public function storePassword(string $password): void {
        try {
            $hashedPassword = $this->hashPassword($password);
            Database::insert('passwords', ['password' => $hashedPassword]);
        } catch (Exception $e) {
            $this->loggingService->logError("Failed to store password: {$e->getMessage()}");
            throw new PasswordManagerException("Storing password failed", 0, $e);
        }
    }

    public function retrievePassword(string $username): string|null {
        try {
            $password = Database::query('SELECT `password` FROM `passwords` WHERE `username` = ?', [$username]);

            if ($password === null) {
                return null;
            } elseif (password_verify($password, $hashedPassword)) {
                return $password;
            } else {
                throw new PasswordManagerException("Invalid password");
            }
        } catch (Exception $e) {
            $this->loggingService->logError("Failed to retrieve password: {$e->getMessage()}");
            throw new PasswordManagerException("Retrieving password failed", 0, $e);
        }
    }

    public function deletePassword(string $username): void {
        try {
            Database::delete('passwords', ['username' => $username]);
        } catch (Exception $e) {
            $this->loggingService->logError("Failed to delete password: {$e->getMessage()}");
            throw new PasswordManagerException("Deleting password failed", 0, $e);
        }
    }
}

class LoggingService {
    public function logError(string $message): void {
        // Implement error logging here
    }
}
