Here is an example of how to implement the modular application in Node.js and .NET Core that integrates local data processing with a remote relational database:

1. JavaScript Service (Node.js):
```
const { reduce } = require('lodash');
const request = require('request');

// Define function to compute summary statistics from dataset asynchronously
function asyncComputeSummaryStats(data) {
  return new Promise((resolve, reject) => {
    const totalAmount = data.reduce((acc, transaction) => acc + transaction.amount, 0);
    const averageTransaction = totalAmount / data.length;
    const countOfTransactions = data.length;
    resolve({ totalAmount, averageTransaction, countOfTransactions });
  }).catch(error => {
    console.error('Error computing summary statistics:', error);
  });
}

// Define function to handle errors gracefully and optimize for performance
function handleErrorsAndOptimizePerformance(error) {
  if (error) {
    console.error('Error processing data:', error);
    return;
  }

  const startTime = Date.now();
  asyncComputeSummaryStats(data).then(stats => {
    console.log(`Processed ${data.length} transactions in ${Date.now() - startTime}ms.`);
    console.log('Total amount:', stats.totalAmount);
    console.log('Average transaction:', stats.averageTransaction);
    console.log('Count of transactions:', stats.countOfTransactions);
  });
}

// Define function to handle memory constraints and concurrency issues
function handleMemoryConstraintsAndConcurrency(data) {
  const dataChunks = [];
  let chunkSize = 1000; // Chunk size in number of transactions
  for (let i = 0; i < data.length; i += chunkSize) {
    dataChunks.push(data.slice(i, i + chunkSize));
  }
  return dataChunks;
}

// Define function to query remote database and handle errors
function queryRemoteDatabase(query) {
  const startTime = Date.now();
  return request({
    url: 'https://mydatabase.com/api',
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(query),
    timeout: 5000 // Timeout in milliseconds
  }).then(response => {
    console.log(`Query executed in ${Date.now() - startTime}ms.`);
    return response;
  }).catch(error => {
    console.error('Error querying remote database:', error);
    throw error;
  });
}
```
