```csharp
using System;
using System.Security.Cryptography;
using System.Threading.Tasks;

namespace HashingLibrary
{
    public class Hasher
    {
        private const int BATCH_SIZE = 1024 * 1024 * 1024; // 1 GB per batch
        private readonly List<string> _hashes = new();
        private readonly Dictionary<string, string> _hashedTexts = new();

        public async Task HashBatchAsync(string[] texts)
        {
            var hashAlgorithm = MD5.Create();
            foreach (var text in texts)
            {
                var hash = Convert.ToBase64String(hashAlgorithm.ComputeHash(Encoding.UTF8.GetBytes(text)));
                _hashes.Add(hash);
                _hashedTexts[hash] = text;
            }
        }

        public string GetHashedText(string hash) => _hashedTexts[hash];
    }
}
```
