        # Set environment variables for the logging configuration path
        if not config_paths or len(config_paths) == 0:
            raise ValueError("Invalid configuration paths")
        else:
            # Validate their correctness to avoid race conditions among concurrent processes
            try:
                self.validate_environment_variables(config_paths)
            except ValueError as e:
                self.log_error("Failed to set environment variables for logging configuration path: {}".format(e))
            else:
