            logging.warning('Dropping log due to failure')
            return False

def process_fallback_log(log):
    # If we have a fallback cache entry for this log, process it instead of the original log
    logging.debug('Processing fallback cache entry for log {}'.format(log['id']))
    try:
        response = requests.post(analytics_service, json=fallback_cache[log['id']])
        if response.status_code == 200:
            return True
        else:
