    char* configuration;
} Configuration;

void manageWebsiteConfigurations(const char* environment, const char* configuration) {
    // Initialize SSL context for secure connections with the metadata service
    SSL_CTX* sslCtx = SSL_CTX_new(TLSv1_2_client_method());
    if (!sslCtx) {
        printf("Failed to create new SSL context: %s\n", ERR_error_string(ERR_get_error(), NULL));
        return;
    }

    // Initialize socket for connecting to the metadata service
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock == -1) {
        printf("Failed to create new socket: %s\n", strerror(errno));
        SSL_CTX_free(sslCtx);
        return;
    }

    // Set up connection to the metadata service
    struct sockaddr_in serverAddr;
    memset(&serverAddr, 0, sizeof(serverAddr));
    serverAddr.sin_family = AF_INET;
    serverAddr.sin_port = htons(PORT);
    if (inet_pton(AF_INET, HOST, &serverAddr.sin_addr) <= 0) {
        printf("Failed to resolve %s: %s\n", HOST, strerror(errno));
        close(sock);
        SSL_CTX_free(sslCtx);
        return;
    }

    // Connect to the metadata service
    if (connect(sock, (struct sockaddr*)&serverAddr, sizeof(serverAddr)) == -1) {
        printf("Failed to connect to %s: %s\n", HOST, strerror(errno));
        close(sock);
        SSL_CTX_free(sslCtx);
        return;
    }

    // Initialize SSL connection with the metadata service
    SSL* ssl = SSL_new(sslCtx);
    if (!ssl) {
        printf("Failed to create new SSL object: %s\n", ERR_error_string(ERR_get_error(), NULL));
        close(sock);
        SSL_CTX_free(sslCtx);
        return;
    }

    // Set up SSL connection with the metadata service
    if (SSL_set_fd(ssl, sock) == -1) {
        printf("Failed to set SSL socket: %s\n", ERR_error_string(ERR_get_error(), NULL));
        close(sock);
        SSL_free(ssl);
        SSL_CTX_free(sslCtx);
        return;
    }

    // Perform SSL handshake with the metadata service
    if (SSL_do_handshake(ssl) <= 0) {
        printf("Failed to perform SSL handshake: %s\n", ERR_error_string(ERR_get_error(), NULL));
        close(sock);
        SSL_free(ssl);
        SSL_CTX_free(sslCtx);
        return;
    }

    // Build HTTP request for fetching website configurations
    char* req = malloc(1024);
    if (!req) {
        printf("Failed to allocate memory for HTTP request: %s\n", strerror(errno));
        close(sock);
        SSL_free(ssl);
        SSL_CTX_free(sslCtx);
        return;
    }

    // Fetch website configurations from the metadata service
    snprintf(req, 1024, "GET %s HTTP/1.1\r\nHost: %s\r\nConnection: close\r\n\r\n", PATH, HOST);
    if (SSL_write(ssl, req, strlen(req)) <= 0) {
        printf("Failed to send HTTP request: %s\n", ERR_error_string(ERR_get_error(), NULL));
        close(sock);
        SSL_free(ssl);
        SSL_CTX_free(sslCtx);
        return;
    }

    // Read HTTP response from the metadata service
    char* res = malloc(1024);
    if (!res) {
        printf("Failed to allocate memory for HTTP response: %s\n", strerror(errno));
        close(sock);
        SSL_free(ssl);
        SSL_CTX_free(sslCtx);
        return;
    }

    int r = SSL_read(ssl, res, 1024);
    if (r <= 0) {
        printf("Failed to read HTTP response: %s\n", ERR_error_string(ERR_get_error(), NULL));
        close(sock);
        SSL_free(ssl);
        SSL_CTX_free(sslCtx);
        return;
    }

    // Parse JSON response from the metadata service
    JSON_Value* root = json_parse_string(res);
    if (!root) {
        printf("Failed to parse JSON response: %s\n", ERR_error_string(ERR_get_error(), NULL));
        close(sock);
        SSL_free(ssl);
        SSL_CTX_free(sslCtx);
        return;
    }

    // Fetch website configurations from the metadata service
    JSON_Object* obj = json_object_get_object(root, "configurations");
    if (!obj) {
        printf("Failed to fetch website configurations: %s\n", ERR_error_string(ERR_get_error(), NULL));
        close(sock);
        SSL_free(ssl);
        SSL_CTX_free(sslCtx);
        return;
    }

    const char* configuration = json_object_dotget_string(obj, "configuration");
    if (!configuration) {
        printf("Failed to fetch website configurations: %s\n", ERR_error_string(ERR_get_error(), NULL));
        close(sock);
        SSL_free(ssl);
        SSL_CTX_free(sslCtx);
        return;
    }

    // Free memory for HTTP request and response
    free(req);
    free(res);

    // Return fetched website configurations
    return configuration;
}']

