// Define a structure to represent a WebSocket connection
struct WebSocketConnection {
    std::string ip;
    int port;
    std::string protocol;
};

// Define a class for managing WebSocket connections
class WebSocketConnectionManager {
public:
    // Constructor
    WebSocketConnectionManager() {}

    // Destructor
    ~WebSocketConnectionManager() {}

    // Add a new WebSocket connection to the manager
    void addConnection(const std::string& ip, int port, const std::string& protocol) {
        std::lock_guard<std::mutex> lock(connectionsMutex);
        connections.emplace_back(ip, port, protocol);
    }

    // Remove a WebSocket connection from the manager
    void removeConnection(const std::string& ip, int port) {
        std::lock_guard<std::mutex> lock(connectionsMutex);
        for (auto it = connections.begin(); it != connections.end(); ++it) {
            if ((*it).ip == ip && (*it).port == port) {
                connections.erase(it);
                break;
            }
        }
    }

    // Establish a connection with the WebSocket server
    bool establishConnection(const std::string& ip, int port, const std::string& protocol) {
        std::lock_guard<std::mutex> lock(connectionsMutex);
        connections.emplace_back(ip, port, protocol);
        return true;
    }

    // Close a WebSocket connection
    void closeConnection(const std::string& ip, int port) {
        std::lock_guard<std::mutex> lock(connectionsMutex);
        for (auto it = connections.begin(); it != connections.end(); ++it) {
            if ((*it).ip == ip && (*it).port == port) {
                connections.erase(it);
                break;
            }
        }
    }

    // Handle incoming WebSocket messages
    void handleMessage(const std::string& message) {
        // Parse the message and validate its integrity
        // ...

        // Queue the message for asynchronous processing
        std::lock_guard<std::mutex> lock(messageMutex);
        queuedMessages.emplace_back(message);
    }

    // Process queued messages asynchronously
    void processQueuedMessages() {
        std::lock_guard<std::mutex> lock(messageMutex);
        for (auto& message : queuedMessages) {
            // Process the message and handle any errors that may occur
            // ...
        }
        queuedMessages.clear();
    }

private:
    // The list of active WebSocket connections
    std::vector<WebSocketConnection> connections;

    // A mutex to protect access to the connection list
    std::mutex connectionsMutex;

    // A condition variable to signal when new messages are available for processing
    std::condition_variable messageAvailableCondition;

    // The list of queued messages
    std::vector<std::string> queuedMessages;

    // A mutex to protect access to the message queue
    std::mutex messageMutex;
};
```
The `WebSocketConnectionManager` class manages a set of active WebSocket connections and provides methods for establishing, closing, and handling incoming messages. It also includes a condition variable to signal when new messages are available for processing, as well as synchronization primitives to protect access to the connection list and message queue.

To use this class, you can create an instance of it and add WebSocket connections to it using the `addConnection` method. You can then remove connections from the manager using the `removeConnection` method, and establish connections with the `establishConnection` method. When a connection is closed, the `closeConnection` method should be called to remove the connection from the manager.

To handle incoming messages, you can implement the `handleMessage` method to parse the message and validate its integrity. You can then queue the message for asynchronous processing using the `queuedMessages` list and signaling the `messageAvailableCondition`. Finally, you can process queued messages asynchronously using the `processQueuedMessages` method.

This implementation provides a modular and efficient way to manage WebSocket connections in a high-throughput, low-latency communication system. It allows for dynamic connection handling, real-time message parsing and queuing, advanced error handling and recovery, scalability and performance optimization, configurable integration points, enhanced security measures, and custom extension points.']

