// Define the configuration file format
struct Config {
  std::string name;
  int value;
};

// Define the configuration data structure
using ConfigData = std::map<std::string, Config>;

// Define the command-line options
enum class CommandLineOption {
  Help,
  Version,
  ConfigUrl,
  OutputFile,
  DryRun,
};

struct CommandLineOptions {
  bool help;
  bool version;
  std::string config_url;
  std::string output_file;
  bool dry_run;
};

// Define the data type for storing metadata
using Metadata = std::vector<std::pair<std::string, ConfigData>>;

// Define the data structure for managing tasks
struct Task {
  std::string name;
  int priority;
  bool completed;
};

// Define the task queue
using TaskQueue = std::queue<Task>;

// Define the utility class
class Utility {
 public:
  // Constructor
  explicit Utility(const CommandLineOptions& options) : options_(options) {}

  // Load configuration from file
  void loadConfiguration();

  // Save configuration to file
  void saveConfiguration();

  // Update configuration using REST API
  void updateConfiguration();

  // Process tasks in the task queue
  void processTasks();

  // Get the next task from the task queue
  Task getNextTask() {
    std::lock_guard<std::mutex> lock(task_queue_mutex_);
    if (task_queue_.empty()) {
      return {};
    }
    Task task = task_queue_.front();
    task_queue_.pop();
    return task;
  }

  // Add a task to the task queue
  void addTask(const Task& task) {
    std::lock_guard<std::mutex> lock(task_queue_mutex_);
    task_queue_.push(task);
  }

 private:
  // Options for the utility
  CommandLineOptions options_;

  // Configuration data structure
  ConfigData config_data_;

  // Metadata data structure
  Metadata metadata_;

  // Task queue
  TaskQueue task_queue_;

  // Mutex for protecting the task queue
  std::mutex task_queue_mutex_;
};
