import logging
import os
from typing import List, Dict
import boto3
from botocore.exceptions import ClientError
import json

class InfrastructureManager:
    def __init__(self, region: str = "us-east-1", profile_name: str = None):
        self.region = region
        self.profile_name = profile_name
        self.session = boto3.Session(profile_name=profile_name)
        self.cloudformation = self.session.client("cloudformation")
        self.codepipeline = self.session.client("codepipeline")

    def update_stack(self, stack_name: str, template: Dict[str, any], parameters: List[Dict[str, any]], capabilities=None) -> bool:
        try:
            response = self.cloudformation.update_stack(StackName=stack_name, TemplateBody=json.dumps(template), Parameters=parameters, Capabilities=capabilities or ["CAPABILITY_IAM"])
            logging.info(f"Updated stack {stack_name} with response: {response}")
        except ClientError as e:
            logging.error(f"Failed to update stack {stack_name}: {e}")
            return False
        else:
            return True

    def create_stack(self, stack_name: str, template: Dict[str, any], parameters: List[Dict[str, any]], capabilities=None) -> bool:
        try:
            response = self.cloudformation.create_stack(StackName=stack_name, TemplateBody=json.dumps(template), Parameters=parameters, Capabilities=capabilities or ["CAPABILITY_IAM"])
            logging.info(f"Created stack {stack_name} with response: {response}")
        except ClientError as e:
            logging.error(f"Failed to create stack {stack_name}: {e}")
            return False
        else:
            return True

    def list_stacks(self) -> List[Dict]:
        try:
            response = self.cloudformation.list_stacks()
            logging.info(f"Listed stacks with response: {response}")
            return response["StackSummaries"]
        except ClientError as e:
            logging.error(f"Failed to list stacks: {e}")
            return []

    def get_stack_status(self, stack_name: str) -> str:
        try:
            response = self.cloudformation.describe_stacks(StackName=stack_name)
            logging.info(f"Described stack {stack_name} with response: {response}")
            return response["Stacks"][0]["StackStatus"]
        except ClientError as e:
            logging.error(f"Failed to describe stack {stack_name}: {e}")
            return "FAILED"

    def get_stack_events(self, stack_name: str) -> List[Dict]:
        try:
            response = self.cloudformation.describe_stack_events(StackName=stack_name)
            logging.info(f"Described stack events for {stack_name} with response: {response}")
            return response["StackEvents"]
        except ClientError as e:
            logging.error(f"Failed to describe stack events for {stack_name}: {e}")
            return []

    def delete_stack(self, stack_name: str) -> bool:
        try:
            response = self.cloudformation.delete_stack(StackName=stack_name)
            logging.info(f"Deleted stack {stack_name} with response: {response}")
        except ClientError as e:
            logging.error(f"Failed to delete stack {stack_name}: {e}")
            return False
        else:
            return True

    def list_pipelines(self) -> List[Dict]:
        try:
            response = self.codepipeline.list_pipelines()
            logging.info(f"Listed pipelines with response: {response}")
            return response["pipelines"]
        except ClientError as e:
            logging.error(f"Failed to list pipelines: {e}")
            return []

    def get_pipeline_status(self, pipeline_name: str) -> str:
        try:
            response = self.codepipeline.get_pipeline_state(name=pipeline_name)
            logging.info(f"Got pipeline state for {pipeline_name} with response: {response}")
            return response["stageStates"][0]["latestExecution"]["status"]
        except ClientError as e:
            logging.error(f"Failed to get pipeline state for {pipeline_name}: {e}")
            return "FAILED"

    def start_pipeline(self, pipeline_name: str) -> bool:
        try:
            response = self.codepipeline.start_pipeline_execution(name=pipeline_name)
            logging.info(f"Started pipeline execution for {pipeline_name} with response: {response}")
        except ClientError as e:
            logging.error(f"Failed to start pipeline execution for {pipeline_name}: {e}")
            return False
        else:
            return True

    def stop_pipeline(self, pipeline_name: str) -> bool:
        try:
            response = self.codepipeline.stop_pipeline_execution(name=pipeline_name)
            logging.info(f"Stopped pipeline execution for {pipeline_name} with response: {response}")
        except ClientError as e:
            logging.error(f"Failed to stop pipeline execution for {pipeline_name}: {e}")
            return False
        else:
            return True

    def get_stack_outputs(self, stack_name: str) -> Dict:
        try:
            response = self.cloudformation.describe_stacks(StackName=stack_name)
            logging.info(f"Described stack {stack_name} with response: {response}")
            return {output["OutputKey"]: output["OutputValue"] for output in response["Stacks"][0]["Outputs"]}
        except ClientError as e:
            logging.error(f"Failed to describe stack outputs for {stack_name}: {e}")
            return {}

    def get_pipeline_outputs(self, pipeline_name: str) -> Dict:
        try:
            response = self.codepipeline.get_pipeline_state(name=pipeline_name)
            logging.info(f"Got pipeline state for {pipeline_name} with response: {response}")
            return {}
        except ClientError as e:
            logging.error(f"Failed to get pipeline outputs for {pipeline_name}: {e}")
            return {}

    def get_stack_parameters(self, stack_name: str) -> Dict:
        try:
            response = self.cloudformation.describe_stacks(StackName=stack_name)
            logging.info(f"Described stack {stack_name} with response: {response}")
            return {parameter["ParameterKey"]: parameter["ParameterValue"] for parameter in response["Stacks"][0]["Parameters"]}
        except ClientError as e:
            logging.error(f"Failed to describe stack parameters for {stack_name}: {e}")
            return {}

    def get_pipeline_parameters(self, pipeline_name: str) -> Dict:
        try:
            response = self.codepipeline.get_pipeline_state(name=pipeline_name)
            logging.info(f"Got pipeline state for {pipeline_name} with response: {response}")
            return {}
        except ClientError as e:
            logging.error(f"Failed to get pipeline parameters for {pipeline_name}: {e}")
            return {}

    def update_stack_parameters(self, stack_name: str, parameters: Dict) -> bool:
        try:
            response = self.cloudformation.update_stack(StackName=stack_name, Parameters=list(parameters.items()))
            logging.info(f"Updated stack parameters for {stack_name} with response: {response}")
        except ClientError as e:
            logging.error(f"Failed to update stack parameters for {stack_name}: {e}")
            return False
        else:
            return True

    def update_pipeline_parameters(self, pipeline_name: str, parameters: Dict) -> bool:
        try:
            response = self.codepipeline.update_pipeline(name=pipeline_name, Parameters=list(parameters.items()))
            logging.info(f"Updated pipeline parameters for {pipeline_name} with response: {response}")
        except ClientError as e:
            logging.error(f"Failed to update pipeline parameters for {pipeline_name}: {e}")
            return False
        else:
            return True

    def get_stack_template(self, stack_name: str) -> Dict:
        try:
            response = self.cloudformation.get_template(StackName=stack_name)
            logging.info(f"Got stack template for {stack_name} with response: {response}")
            return response["TemplateBody"]
        except ClientError as e:
            logging.error(f"Failed to get stack template for {stack_name}: {e}")
            return {}
