    std::vector<float> sensor_data;
};

struct TimeSeriesData {
    int timestamp;
    std::unordered_map<std::string, IoTDevice> devices;
};

// Global Variables
const int MAX_NUM_DEVICES = 100;
const int MAX_NUM_SENSORS = 5;
const int TIME_SERIES_WINDOW = 60; // minutes
const float LATENCY_THRESHOLD = 100.0; // milliseconds

// Function Declarations
void handle_data(std::vector<float>& data);
void process_time_series_data(std::vector<TimeSeriesData>& data);
void update_device_list(std::unordered_map<std::string, IoTDevice> devices);
void handle_disconnection(const std::string& device_id);
void handle_reconnection(const std::string& device_id);
void handle_sensor_data(IoTDevice& device, float sensor_value);

// Main Function
int main() {
    // Initialize data structures and variables
    std::vector<TimeSeriesData> time_series_data;
    std::unordered_map<std::string, IoTDevice> devices;
    std::mutex device_list_mtx;
    std::condition_variable disconnection_cv;
    std::condition_variable reconnection_cv;
    std::thread update_device_list_thread;
    std::atomic<bool> is_running = true;

    // Start data processing thread
    auto process_time_series_data_lambda = [&]() {
        while (is_running) {
            if (!time_series_data.empty()) {
                process_time_series_data(time_series_data);
                time_series_data.clear();
            }
        }
    };
    std::thread data_processing_thread(process_time_series_data_lambda);

    // Start device list update thread
    auto update_device_list_lambda = [&]() {
        while (is_running) {
            std::lock_guard<std::mutex> lock(device_list_mtx);
            if (!devices.empty()) {
                update_device_list(devices);
                devices.clear();
            }
        }
    };
    update_device_list_thread = std::thread(update_device_list_lambda);

    // Start data handling thread
    auto handle_data_lambda = [&]() {
        while (is_running) {
            std::string device_id;
            float sensor_value;
            if (!handle_sensor_data(device_id, sensor_value)) {
                break;
            }
            TimeSeriesData time_series_data{};
            IoTDevice& device = devices[device_id];
            device.sensor_data.push_back(sensor_value);
            if (device.sensor_data.size() == MAX_NUM_SENSORS) {
                time_series_data.timestamp = std::chrono::system_clock::now().time_since_epoch().count();
                time_series_data.devices[device_id] = device;
                std::lock_guard<std::mutex> lock(device_list_mtx);
                devices.erase(device_id);
            }
        }
    };
    std::thread handle_data_thread(handle_data_lambda);

    // Start disconnection handling thread
    auto handle_disconnection_lambda = [&]() {
        while (is_running) {
            std::string device_id;
            if (!handle_disconnection(device_id)) {
                break;
            }
            TimeSeriesData time_series_data{};
            IoTDevice& device = devices[device_id];
            device.sensor_data.clear();
            time_series_data.timestamp = std::chrono::system_clock::now().time_since_epoch().count();
            time_series_data.devices[device_id] = device;
            std::lock_guard<std::mutex> lock(device_list_mtx);
            devices.erase(device_id);
        }
    };
    std::thread handle_disconnection_thread(handle_disconnection_lambda);

    // Start reconnection handling thread
    auto handle_reconnection_lambda = [&]() {
        while (is_running) {
            std::string device_id;
            if (!handle_reconnection(device_id)) {
                break;
            }
            IoTDevice& device = devices[device_id];
            TimeSeriesData time_series_data{};
            device.sensor_data.clear();
            time_series_data.timestamp = std::chrono::system_clock::now().time_since_epoch().count();
            time_series_data.devices[device_id] = device;
            std::lock_guard<std::mutex> lock(device_list_mtx);
            devices.erase(device_id);
        }
    };
    std::thread handle_reconnection_thread(handle_reconnection_lambda);

    // Wait for all threads to finish
    is_running = false;
    data_processing_thread.join();
    update_device_list_thread.join();
    handle_data_thread.join();
    handle_disconnection_thread.join();
    handle_reconnection_thread.join();

    return 0;
}

// Function to handle new sensor data
bool handle_sensor_data(std::string& device_id, float& sensor_value) {
    // Check if there are any new sensor values
    if (sensor_queue.empty()) {
        return false;
    }

    // Get the next sensor value from the queue
    std::lock_guard<std::mutex> lock(sensor_mtx);
    auto iter = sensor_queue.begin();
    device_id = iter->device_id;
    sensor_value = iter->sensor_value;
    sensor_queue.erase(iter);

    return true;
}

// Function to handle new devices
void update_device_list(std::unordered_map<std::string, IoTDevice>& devices) {
    // Check if there are any new devices
    if (new_device_queue.empty()) {
        return;
    }

    // Add the new devices to the device list
    std::lock_guard<std::mutex> lock(device_list_mtx);
    for (auto& device : new_device_queue) {
        devices[device.id] = device;
    }
    new_device_queue.clear();
}

// Function to handle disconnections
void handle_disconnection(const std::string& device_id) {
    // Check if the device is connected
    if (!connected_devices.count(device_id)) {
        return;
    }

    // Remove the device from the connected list and add it to the disconnected list
    std::lock_guard<std::mutex> lock(disconnection_mtx);
    auto iter = connected_devices.find(device_id);
    if (iter != connected_devices.end()) {
        disconnected_devices[device_id] = iter->second;
        connected_devices.erase(iter);
        disconnection_cv.notify_all();
    }
}

// Function to handle reconnections
void handle_reconnection(const std::string& device_id) {
    // Check if the device is not connected
    if (connected_devices.count(device_id)) {
        return;
    }

    // Add the device to the connected list and remove it from the disconnected list
    std::lock_guard<std::mutex> lock(reconnection_mtx);
    auto iter = disconnected_devices.find(device_id);
    if (iter != disconnected_devices.end()) {
        connected_devices[device_id] = iter->second;
        disconnected_devices.erase(iter);
        reconnection_cv.notify_all();
    }
}
```

