        if (!memory_pools[i]) {
            printf("Failed to allocate memory for memory pool\n");
            return;
        }
        memory_pools[i]->total_size = i == 0 ? SMALL_MEMORY_POOL_SIZE : (i == 1 ? MEDIUM_MEMORY_POOL_SIZE : LARGE_MEMORY_POOL_SIZE);
        memory_pools[i]->used_size = 0;
        memory_pools[i]->memory_block = malloc(memory_pools[i]->total_size);
        if (!memory_pools[i]->memory_block) {
            printf("Failed to allocate memory block for memory pool\n");
            free(memory_pools[i]);
            return;
        }
    }
}

static struct MemoryPool* getAvailableMemoryPool(uint32_t allocation_size) {
    uint32_t smallest_pool = 0;
    for (uint32_t i = 1; i < MEMORY_POOL_TIERS; i++) {
        if (memory_pools[i]->used_size + allocation_size <= memory_pools[i]->total_size) {
            smallest_pool = i;
        }
    }
    return memory_pools[smallest_pool];
