using MediaProcessingPipeline;

namespace MediaProcessingPipeline
{
    public class TranscodingEngine
    {
        private readonly List<Transcoder> _transcoders = new List<Transcoder>();

        public TranscodingEngine()
        {
            // Initialize transcoders
            _transcoders.Add(new H264Transcoder());
            _transcoders.Add(new H265Transcoder());
            _transcoders.Add(new AACTranscoder());
            _transcoders.Add(new MP3Transcoder());
        }

        public async Task<TranscodedMedia> TranscodeAsync(Media media)
        {
            var transcodedMedia = new TranscodedMedia();

            foreach (var transcoder in _transcoders)
            {
                try
                {
                    transcodedMedia = await transcoder.TranscodeAsync(media);
                }
                catch (Exception ex)
                {
                    // Handle error and continue with next transcoder
                    Console.WriteLine($"Error transcoding media: {ex.Message}");
                }
            }

            return transcodedMedia;
        }
    }

    public class TranscodedMedia
    {
        public string MediaType { get; set; }
        public byte[] Data { get; set; }
    }

    public abstract class Transcoder
    {
        public abstract Task<TranscodedMedia> TranscodeAsync(Media media);
    }

