['```
import java.util.concurrent.*;
import org.apache.commons.io.FileUtils;
import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.boot.context.properties.ConfigurationProperties;
import org.springframework.context.annotation.Bean;
import org.springframework.scheduling.annotation.Async;
import org.springframework.scheduling.annotation.EnableAsync;
import org.springframework.scheduling.concurrent.ThreadPoolTaskExecutor;

@SpringBootApplication
@EnableAsync
public class RealTimeAnalyticsEngine {

    private static final Logger logger = LogManager.getLogger(RealTimeAnalyticsEngine.class);

    @Autowired
    private BatchProcessor batchProcessor;

    @ConfigurationProperties("engine")
    public void setEngineConfig(EngineConfig engineConfig) {
        this.engineConfig = engineConfig;
    }

    public EngineConfig getEngineConfig() {
        return engineConfig;
    }

    private EngineConfig engineConfig;

    @Async("taskExecutor")
    public void processBatch(String batchId, List<Object> data) {
        try {
            logger.info("Processing batch {}", batchId);
            batchProcessor.processBatch(batchId, data);
        } catch (Exception e) {
            logger.error("Error processing batch {}: {}", batchId, e);
        }
    }

    @Bean("taskExecutor")
    public ThreadPoolTaskExecutor taskExecutor() {
        ThreadPoolTaskExecutor executor = new ThreadPoolTaskExecutor();
        executor.setCorePoolSize(engineConfig.getCorePoolSize());
        executor.setMaxPoolSize(engineConfig.getMaxPoolSize());
        executor.setQueueCapacity(engineConfig.getQueueCapacity());
        executor.initialize();
        return executor;
