        algorithms_.push_back(std::make_unique<SIKEEncryptionAlgorithm>());
    }

    // Encrypt the given plaintext using the specified algorithm
    std::string encrypt(const std::string& plaintext, const std::string& algorithm) {
        for (const auto& algo : algorithms_) {
            if (algo->getName() == algorithm) {
                return algo->encrypt(plaintext);
            }
        }
        // If the specified algorithm is not found, throw an exception
        throw std::runtime_error("Invalid encryption algorithm");
    }

    // Decrypt the given ciphertext using the specified algorithm
    std::string decrypt(const std::string& ciphertext, const std::string& algorithm) {
        for (const auto& algo : algorithms_) {
            if (algo->getName() == algorithm) {
                return algo->decrypt(ciphertext);
            }
        }
        // If the specified algorithm is not found, throw an exception
        throw std::runtime_error("Invalid decryption algorithm");
    }

private:
    std::vector<std::unique_ptr<EncryptionAlgorithm>> algorithms_;
};

int main() {
