// Define the maximum size of the packet buffer pool
const int MAX_BUFFER_POOL_SIZE = 1024;

// Define a struct to represent a single packet buffer
struct PacketBuffer {
    char* data;
    int size;
};

// Define a vector to store the packet buffers
std::vector<PacketBuffer> packetBuffers;

// Define a mutex and condition variable for synchronizing access to the packet buffers
std::mutex bufferMutex;
std::condition_variable bufferCondition;

// Function to allocate a new packet buffer
PacketBuffer* allocateBuffer(int size) {
    // Lock the mutex
    std::lock_guard<std::mutex> lock(bufferMutex);

    // Check if there is enough space in the pool to allocate the requested buffer
    if (packetBuffers.size() >= MAX_BUFFER_POOL_SIZE) {
        return nullptr;
    }

    // Allocate a new packet buffer and append it to the vector
    PacketBuffer* buffer = new PacketBuffer();
    buffer->data = new char[size];
    buffer->size = size;
    packetBuffers.push_back(buffer);

    return buffer;
}

// Function to release a packet buffer
void releaseBuffer(PacketBuffer* buffer) {
    // Lock the mutex
    std::lock_guard<std::mutex> lock(bufferMutex);

    // Find the buffer in the vector and remove it
    auto it = std::find(packetBuffers.begin(), packetBuffers.end(), buffer);
    if (it != packetBuffers.end()) {
        packetBuffers.erase(it);
    }

    // Release the memory for the buffer
    delete[] buffer->data;
    delete buffer;
}

// Function to resize the packet buffer pool
void resizeBufferPool(int newSize) {
    // Lock the mutex
    std::lock_guard<std::mutex> lock(bufferMutex);

    // Check if the new size is within the bounds of the current pool size
    int maxSize = packetBuffers.size();
    if (newSize > maxSize) {
        return;
    }

    // Remove any extra buffers from the vector
    while (packetBuffers.size() > newSize) {
        auto it = std::find(packetBuffers.begin(), packetBuffers.end(), buffer);
        if (it != packetBuffers.end()) {
            packetBuffers.erase(it);
        }
    }
}

// Function to read a packet from the pool
PacketBuffer* readPacket(int size) {
    // Lock the mutex
    std::lock_guard<std::mutex> lock(bufferMutex);

    // Check if there are any buffers available for reading
    if (packetBuffers.empty()) {
        return nullptr;
    }

    // Find a buffer that is large enough to hold the requested size
    auto it = std::find_if(packetBuffers.begin(), packetBuffers.end(), [size](PacketBuffer* buffer) {
        return buffer->size >= size;
    });

    // If no buffer was found, allocate a new one
    if (it == packetBuffers.end()) {
        PacketBuffer* buffer = allocateBuffer(size);
        if (buffer != nullptr) {
            it = std::find(packetBuffers.begin(), packetBuffers.end(), buffer);
        }
    }

    // If a buffer was found, return it
    if (it != packetBuffers.end()) {
        PacketBuffer* buffer = *it;
        buffer->size -= size;
        return buffer;
    }

    return nullptr;
}

// Function to write a packet to the pool
void writePacket(PacketBuffer* buffer, int size) {
    // Lock the mutex
    std::lock_guard<std::mutex> lock(bufferMutex);

    // Check if there is enough space in the buffer for the requested size
    if (buffer->size < size) {
        return;
    }

    // Update the buffer's size and release the memory for the packet
    buffer->size -= size;
    delete[] buffer->data;
    buffer->data = new char[size];
}
