class EventLog {
public:
    // Define the different types of events that can be logged
    enum class EventType {
        ERROR,
        WARNING,
        INFO,
        DEBUG
    };

    // Define the different severity levels for events
    enum class SeverityLevel {
        CRITICAL,
        MAJOR,
        MINOR,
        TRIVIAL
    };

    // Define a structure to hold the event data
