        uint64_t timestamp;
        EventType type;
        SeverityLevel level;
        std::string id;
    };

    // Define a vector to store all the events
    std::vector<EventData> events_;

    // Define a mutex to synchronize access to the events vector
    std::mutex mutex_;

    // Define a condition variable to signal when an event is added or removed from the vector
    std::condition_variable cv_;

    // Define a function to add an event to the vector
    void addEvent(const EventData& event) {
        // Acquire the lock on the mutex
        std::lock_guard<std::mutex> lock(mutex_);

        // Add the event to the vector and signal the condition variable
        events_.push_back(event);
        cv_.notify_one();
    }

    // Define a function to remove an event from the vector
    void removeEvent(const EventData& event) {
        // Acquire the lock on the mutex
        std::lock_guard<std::mutex> lock(mutex_);

        // Remove the event from the vector and signal the condition variable
        events_.erase(std::remove(events_.begin(), events_.end(), event), events_.end());
        cv_.notify_one();
    }

    // Define a function to query the events in the vector
    std::vector<EventData> getEvents() {
        // Acquire the lock on the mutex
        std::lock_guard<std::mutex> lock(mutex_);

        // Return a copy of the events vector
        return events_;
    }

    // Define a function to clear all events from the vector
    void clearEvents() {
        // Acquire the lock on the mutex
        std::lock_guard<std::mutex> lock(mutex_);

