#include <iostream>

class TCPBufferPool {
public:
    // Constructor
    TCPBufferPool(size_t maxSize, size_t minSize) : maxSize_(maxSize), minSize_(minSize) {}

    // Destructor
    ~TCPBufferPool() {
        for (auto it = buffers_.begin(); it != buffers_.end(); ++it) {
            delete it->second;
        }
    }

    // Add a buffer to the pool
    void addBuffer(const std::string& tenant, const std::vector<char>& data) {
        auto buffer = new Buffer(data);
        buffers_.insert({tenant, buffer});

        // Update the total size of the pool
        totalSize_ += buffer->getSize();
    }

    // Get a buffer from the pool
    std::vector<char> getBuffer(const std::string& tenant) {
        auto it = buffers_.find(tenant);

        if (it == buffers_.end()) {
            return {};
        } else {
            // Remove the buffer from the pool
            auto buffer = it->second;
            buffers_.erase(it);

            // Update the total size of the pool
            totalSize_ -= buffer->getSize();

            // Return the buffer
            return buffer->getData();
        }
    }

    // Get the total size of the pool
    size_t getTotalSize() {
        return totalSize_;
    }

    // Check if the pool is empty
    bool isEmpty() {
        return buffers_.empty();
    }

private:
    struct Buffer {
        std::vector<char> data;
        size_t size;

        Buffer(const std::vector<char>& data) : data(data), size(data.size()) {}

        ~Buffer() = default;

        const std::vector<char>& getData() {
            return data;
        }

        size_t getSize() {
            return size;
        }
    };

    // Map of tenants to their corresponding buffers
    std::unordered_map<std::string, Buffer*> buffers_;

    // Maximum size of the pool
    const size_t maxSize_;

    // Minimum size of the pool
    const size_t minSize_;

    // Total size of the pool
    size_t totalSize_ = 0;
};
```
