        evictData();
    }

    // Add new data to the cache
    cache[key] = CacheData{key, value};

    // Notify waiting threads
    cv.notify_all();
}

// Function to retrieve data from the cache
string getData(string key) {
    unique_lock<mutex> ul(mtx);

    // Check if data is present in the cache
    auto it = cache.find(key);
    if (it != cache.end()) {
        return it->second;
    } else {
        return "";
    }
}

// Function to evict oldest data from the cache
void evictData() {
    // Acquire lock
    unique_lock<mutex> ul(mtx);

    // Evict oldest data
    for (auto it = cache.begin(); it != cache.end();) {
        if (it->second.last_accessed < currentTime()) {
            it = cache.erase(it);
        } else {
            ++it;
        }
    }
}

// Function to update data in the cache
void updateData(string key, string value) {
    unique_lock<mutex> ul(mtx);

    // Check if data is present in the cache
    auto it = cache.find(key);
    if (it != cache.end()) {
        it->second.value = value;
        it->second.last_accessed = currentTime();
    } else {
        addData(key, value);
    }

    // Notify waiting threads
    cv.notify_all();
}

// Function to delete data from the cache
void deleteData(string key) {
    unique_lock<mutex> ul(mtx);

    // Check if data is present in the cache
    auto it = cache.find(key);
    if (it != cache.end()) {
        cache.erase(it);
    } else {
        throw "Key not found";
    }
}

// Function to check if cache is empty
bool isEmpty() {
    unique_lock<mutex> ul(mtx);

    return cache.empty();
}

// Main function
int main() {
    // Initialize cache
    CacheType cache;

    // Create threads for reading and writing data to the cache
    thread t1([&](){
        while (true) {
            string key = getKey();
            string value = getData(key);
            if (!value.empty()) {
                cout << "Retrieved data: " << value << endl;
            } else {
                cout << "Cache miss for key: " << key << endl;
            }
        }
    });

    thread t2([&](){
        while (true) {
            string key = getKey();
            string value = getValue();
            updateData(key, value);
        }
    });

    // Join threads
    t1.join();
    t2.join();
}
```
