int main(int argc, char *argv[]) {
    // Check if input file is provided
    if (argc == 1) {
        std::cout << "Usage: ./<program_name> [options] input_file" << std::endl;
        return 0;
    }

    // Parse command line options
    bool manpage = false, cs = false, output = false;
    std::string output_file;
    for (int i = 1; i < argc; ++i) {
        if (strcmp(argv[i], "--manpage") == 0) {
            manpage = true;
        } else if (strcmp(argv[i], "-cs") == 0) {
            cs = true;
        } else if (strcmp(argv[i], "-o") == 0) {
            output = true;
            output_file = argv[++i];
        }
    }

    // Read input file line by line and print number of lines
    std::ifstream infile(argv[argc - 1]);
    if (!infile.is_open()) {
        std::cout << "Error: Could not open input file." << std::endl;
        return 1;
    }

    int line_count = 0;
    while (std::getline(infile, std::string())) {
        ++line_count;
    }
    infile.close();

    // Print usage information if no input file is provided
    if (!output) {
        std::cout << "Usage: ./<program_name> [options] input_file" << std::endl;
        return 0;
    }

    // Write output to file if specified
    if (output) {
        std::ofstream outfile(output_file);
        if (!outfile.is_open()) {
            std::cout << "Error: Could not open output file." << std::endl;
            return 1;
        }
        outfile << line_count << std::endl;
        outfile.close();
    } else {
        // Print number of lines to stdout if no output file is specified
        std::cout << "Number of lines: " << line_count << std::endl;
    }
}
