        return ugcService.create(userContent);
    }

    @GetMapping("/{id}")
    public ResponseEntity<UserContent> getUserContent(@PathVariable String id) {
        return ugcService.get(id);
    }

    @PutMapping("/{id}")
    public ResponseEntity<String> updateUserContent(@PathVariable String id, @RequestBody UserContent userContent) {
        return ugcService.update(id, userContent);
    }

    @DeleteMapping("/{id}")
    public ResponseEntity<String> deleteUserContent(@PathVariable String id) {
        return ugcService.delete(id);
    }

    @GetMapping("/analytics")
    public ResponseEntity<List<UserContent>> getAnalytics() {
        return ugcService.getAnalytics();
    }
}
