// Define the external image processing API functions used in this library
extern void *external_image_api_open(const char *filename);
extern int external_image_api_close(void *handle);
extern int external_image_api_get_metadata(void *handle, unsigned long *bitsPerSample, unsigned long *samplesPerPixel, unsigned long *extraSamplesCount, float **extraSamplesInfo);

// Define the logging function for recording actions and errors
#define LOG(format, ...) fprintf(stderr, format "\n", ##__VA_ARGS__)

// Define the function to modify and extract information from a TIFF file
void modify_and_extract_info(const char *filename) {
    // Check if the filename is valid and the file exists
    if (access(filename, R_OK) != 0) {
        LOG("Error: File %s does not exist or cannot be read", filename);
        return;
    }

    // Open the external image processing API handle for the given file
    void *handle = external_image_api_open(filename);
    if (handle == NULL) {
        LOG("Error: Failed to open file %s with the external image processing API", filename);
        return;
    }

    // Get the metadata from the handle
    unsigned long bitsPerSample = 0, samplesPerPixel = 0, extraSamplesCount = 0;
    float *extraSamplesInfo = NULL;
    if (external_image_api_get_metadata(handle, &bitsPerSample, &samplesPerPixel, &extraSamplesCount, &extraSamplesInfo) != 0) {
        LOG("Error: Failed to get metadata from file %s", filename);
        external_image_api_close(handle);
        return;
    }

    // Close the handle and free any allocated memory for extra samples information
    if (external_image_api_close(handle) != 0) {
        LOG("Error: Failed to close file %s with the external image processing API", filename);
    } else if (extraSamplesInfo != NULL) {
        free(extraSamplesInfo);
    }

    // Rename the file based on specific criteria
    char newFilename[PATH_MAX];
    strncpy(newFilename, filename, PATH_MAX - 1);
    if (strpbrk(filename, "0123456789") != NULL) { // If the file contains at least one digit, change the extension to .bin
        char *dot = strrchr(newFilename, '.');
        if (dot != NULL) {
            dot[1] = 'b';
            dot[2] = 'i';
            dot[3] = 'n';
        } else {
            LOG("Error: Failed to rename file %s due to invalid extension", filename);
            return;
        }
    } else if (strchr(filename, '.') == NULL) { // Otherwise, append a version number if it doesn't exist
        char *versionNumber = "0";
        size_t filenameLen = strlen(newFilename);
        size_t versionNumberLen = strlen(versionNumber);
        if (filenameLen + versionNumberLen + 1 > PATH_MAX) { // Check for path overflow
            LOG("Error: Failed to rename file %s due to path length limit", filename);
            return;
        } else {
            memmove(&newFilename[filenameLen - versionNumberLen], versionNumber, versionNumberLen + 1);
        }
    }

    // Rename the file and log the action
    if (rename(filename, newFilename) != 0) {
        LOG("Error: Failed to rename file %s to %s", filename, newFilename);
        return;
    } else {
        LOG("Renamed file %s to %s", filename, newFilename);
    }
}
