PokemonWeaknessService.java:
```java
package com.pokemonweaknessservice;

import org.springframework.stereotype.Service;
import org.springframework.web.client.RestTemplate;
import org.springframework.web.util.UriComponentsBuilder;

import java.net.URI;
import java.util.List;
import java.util.Map;

@Service
public class PokemonWeaknessService {
    private static final int MAX_ATTEMPTS = 5;
    private static final String POKEAPI_URL = "https://pokeapi.co/api/v2/pokemon/";
    private static final String TYPE_URL = "types";
    private static final String WEAKNESS_URL = "weaknesses";

    private RestTemplate restTemplate;
    private Map<String, PokemonType> typeMap;

    public PokemonWeaknessService(RestTemplate restTemplate, Map<String, PokemonType> typeMap) {
        this.restTemplate = restTemplate;
        this.typeMap = typeMap;
    }

    public List<PokemonType> getWeaknesses(Pokemon pokemon) {
        // Handle null or empty input
        if (pokemon == null || pokemon.getName() == null) {
            return Collections.emptyList();
        }

        // Get the Pokemon type from the API
        String typeUrl = UriComponentsBuilder.fromUriString(POKEAPI_URL).pathSegment(pokemon.getName()).build().toUriString();
        PokemonType pokemonType;
        try {
            pokemonType = restTemplate.getForObject(typeUrl, PokemonType.class);
        } catch (ResourceAccessException | HttpClientErrorException e) {
            // Log failed attempt and return empty list
            log.error("Failed to retrieve Pokemon type for {}", pokemon.getName(), e);
            return Collections.emptyList();
        }

        // Get the weaknesses from the API
        String weaknessUrl = UriComponentsBuilder.fromUriString(POKEAPI_URL).pathSegment(pokemonType.getId()).pathSegment(WEAKNESS_URL).build().toUriString();
        List<PokemonType> weaknesses;
        try {
            weaknesses = restTemplate.getForObject(weaknessUrl, new ParameterizedTypeReference<List<PokemonType>>() {});
        } catch (ResourceAccessException | HttpClientErrorException e) {
            // Log failed attempt and return empty list
            log.error("Failed to retrieve weaknesses for {}", pokemon.getName(), e);
            return Collections.emptyList();
        }

        // Compute compounded effects
        List<PokemonType> result = new ArrayList<>();
        for (PokemonType weakness : weaknesses) {
            if (weakness.getId().startsWith("weakness-")) {
                // Dual-type weakness
                String[] ids = weakness.getId().split("-");
                PokemonType primary = typeMap.get(ids[1]);
                PokemonType secondary = typeMap.get(ids[2]);
                if (primary != null && secondary != null) {
                    result.add(new PokemonType(primary.getName() + " vs. " + secondary.getName(), primary.getWeaknesses().contains(secondary) || secondary.getWeaknesses().contains(primary)));
                } else {
                    log.warn("Invalid weakness {} for Pokemon {}", weakness, pokemon);
                }
            } else if (weakness.getId().startsWith("resistance-")) {
                // Dual-type resistance
                String[] ids = weakness.getId().split("-");
                PokemonType primary = typeMap.get(ids[1]);
                PokemonType secondary = typeMap.get(ids[2]);
                if (primary != null && secondary != null) {
                    result.add(new PokemonType(primary.getName() + " vs. " + secondary.getName(), !(primary.getWeaknesses().contains(secondary) || secondary.getWeaknesses().contains(primary))));
                } else {
                    log.warn("Invalid weakness {} for Pokemon {}", weakness, pokemon);
                }
            } else if (weakness.getId().startsWith("immunity-")) {
                // Dual-type immunity
                String[] ids = weakness.getId().split("-");
                PokemonType primary = typeMap.get(ids[1]);
                PokemonType secondary = typeMap.get(ids[2]);
                if (primary != null && secondary != null) {
                    result.add(new PokemonType(primary.getName() + " vs. " + secondary.getName(), !(primary.getWeaknesses().contains(secondary) || secondary.getWeaknesses().contains(primary))));
                } else {
                    log.warn("Invalid weakness {} for Pokemon {}", weakness, pokemon);
                }
            }
        }

        return result;
    }
}
