```java
import java.util.concurrent.*;
import java.util.HashMap;
import java.util.Map;
import java.util.List;
import java.util.ArrayList;

// Third-party library for user authentication and authorization
import com.auth0.Auth0;
import com.auth0.AuthenticationManager;
import com.auth0.exceptions.AuthException;

// Local credential store for fallback mechanism
import com.localcredentials.CredentialStore;

// In-memory cache for improved performance and consistency
import java.util.concurrent.ConcurrentHashMap;

public class AuthService {
  private static final Map<String, String> CACHE = new ConcurrentHashMap<>();
  private static final int MAX_CACHE_SIZE = 10000;

  // Authentication manager for external services
  private static final AuthenticationManager AUTH_MANAGER = new Auth0();

  public static void main(String[] args) {
    System.out.println("AuthService started");

    // Initialize credential store and cache
    CredentialStore.init();
    CACHE.clear();

    // Start background thread for cache maintenance
    ExecutorService executor = Executors.newSingleThreadExecutor();
    executor.execute(new CacheMaintenanceTask());
  }

  public static boolean authenticateUser(String username, String password) {
    // Check if user is in cache
    if (CACHE.containsKey(username)) {
      return CACHE.get(username).equals(password);
    }

    // Use external authentication manager for initial authentication
    try {
      AUTH_MANAGER.authenticate(username, password);
      return true;
    } catch (AuthException e) {
      System.out.println("Authentication failed: " + e.getMessage());
      return false;
    }
  }

  public static void cacheUserCredentials(String username, String password) {
    // Add user to cache if not already present
    if (!CACHE.containsKey(username)) {
      CACHE.put(username, password);
    }

    // Evict oldest entries from cache if necessary
    if (CACHE.size() > MAX_CACHE_SIZE) {
      List<String> evictedUsers = new ArrayList<>();
      for (Map.Entry<String, String> entry : CACHE.entrySet()) {
        String user = entry.getKey();
        if (!AUTH_MANAGER.isUserAuthenticated(user)) {
          evictedUsers.add(user);
        }
      }

      for (String user : evictedUsers) {
        CACHE.remove(user);
      }
    }
  }

  public static boolean isUserAuthorized(String username, String[] permissions) {
    // Check if user is authenticated and has the required permissions
    return AUTH_MANAGER.isUserAuthenticated(username) &&
            AUTH_MANAGER.hasPermissions(username, permissions);
  }

  public static void evictUserFromCache(String username) {
    // Remove user from cache if present
    CACHE.remove(username);
  }

  private static class CacheMaintenanceTask implements Runnable {
    @Override
    public void run() {
      while (true) {
        // Evict users from cache periodically
        for (Map.Entry<String, String> entry : CACHE.entrySet()) {
          if (!AUTH_MANAGER.isUserAuthenticated(entry.getKey())) {
            CACHE.remove(entry.getKey());
          }
        }

        try {
          // Sleep for a short period to prevent busy-waiting
          Thread.sleep(1000);
        } catch (InterruptedException e) {
          System.out.println("Cache maintenance task interrupted");
        }
      }
    }
  }
}
```
