        }
        return strings;
    }

    // Benchmark the performance of the library
    void benchmark() {
        std::vector<std::thread> threads;

        // Start a new thread for each string in the cache
        for (const auto& str : generateRandomStrings(1000)) {
            threads.push_back(std::thread([str] {
                ContentManager cm;
                cm.addString(str);
                uint64_t seq = cm.getRandomSequence(str);
                std::cout << "Sequence: " << seq << std::endl;
            }));
        }

