const renderFooterScripts = async (scripts) => {
  const scriptPromises = scripts.map((script) => {
    return fetch(script.url, { method: 'GET', headers: {'X-Requested-With': 'XMLHttpRequest'} })
      .then((response) => response.text())
      .catch((error) => console.log('Error fetching script: ', error))
  });

  const cachedScripts = await Promise.all(scriptPromises);

  const scriptsToRender = [];
  for (const script of cachedScripts) {
    if (script && !scriptsToRender.includes(script)) {
      scriptsToRender.push(script);
    }
  }

  return scriptsToRender;
};
```
