    configs: HashMap<String, String>,
    version_map: HashMap<String, Vec<String>>,
    dependencies: HashMap<String, Vec<String>>,
    api_requests: HashMap<String, i64>,
    api_limits: HashMap<String, i64>,
    requests: Vec<RequestInfo>,
}

struct RequestInfo {
    id: String,
    timestamp: DateTime<Local>,
    path: String,
    query: String,
    payload: Value,
}

impl ConfigManager {
    fn new() -> Self {
        let configs = HashMap::new();
        let version_map = HashMap::new();
        let dependencies = HashMap::new();
        let api_requests = HashMap::new();
        let api_limits = HashMap::new();
        let requests = Vec::new();

        Self {
            configs,
            version_map,
            dependencies,
            api_requests,
            api_limits,
            requests,
        }
    }

    fn get_config(&mut self, path: &str) -> Result<String> {
        match self.configs.get(path) {
            Some(value) => Ok(value.clone()),
            None => Err(anyhow!("Configuration not found")),
        }
    }

    fn get_version(&mut self, path: &str) -> Result<Vec<String>> {
        match self.version_map.get(path) {
            Some(value) => Ok(value.clone()),
            None => Err(anyhow!("Version not found")),
        }
    }

    fn get_dependencies(&mut self, path: &str) -> Result<Vec<String>> {
        match self.dependencies.get(path) {
            Some(value) => Ok(value.clone()),
            None => Err(anyhow!("Dependency not found")),
        }
    }

    fn get_api_requests(&mut self, path: &str) -> Result<i64> {
        match self.api_requests.get(path) {
            Some(value) => Ok(*value),
            None => Err(anyhow!("API requests not found")),
        }
    }

    fn get_api_limits(&mut self, path: &str) -> Result<i64> {
        match self.api_limits.get(path) {
            Some(value) => Ok(*value),
            None => Err(anyhow!("API limits not found")),
        }
    }

    fn add_request(&mut self, request: RequestInfo) -> Result<()> {
        self.requests.push(request);
        Ok(())
    }

    fn handle_requests(&mut self) -> Result<()> {
        for request in &self.requests {
            match request.path.as_str() {
                "GET /configs" => {
                    let configs = self.get_configs(request)?;
                    self.send_response(request, &configs)?;
                }
                "POST /configs" => {
                    self.add_or_update_config(request)?;
                }
                "DELETE /configs" => {
                    self.delete_config(request)?;
                }
                "GET /versions" => {
                    let versions = self.get_versions(request)?;
                    self.send_response(request, &versions)?;
                }
                "POST /versions" => {
                    self.add_version(request)?;
                }
                "DELETE /versions" => {
                    self.delete_version(request)?;
                }
                "GET /dependencies" => {
                    let dependencies = self.get_dependencies(request)?;
                    self.send_response(request, &dependencies)?;
                }
                "POST /dependencies" => {
                    self.add_dependency(request)?;
                }
                "DELETE /dependencies" => {
                    self.delete_dependency(request)?;
                }
                "GET /api-requests" => {
                    let api_requests = self.get_api_requests(request)?;
                    self.send_response(request, &api_requests)?;
                }
                "POST /api-limits" => {
                    self.add_api_limit(request)?;
                }
                "DELETE /api-limits" => {
                    self.delete_api_limit(request)?;
                }
                _ => {}
            }
        }
        Ok(())
    }

    fn send_response(&mut self, request: &RequestInfo, response: &str) -> Result<()> {
        let mut headers = HeaderMap::new();
        headers.append(CONTENT_TYPE, "application/json".parse().unwrap());
        let response = Response::builder()
            .status(StatusCode::OK)
            .header("Content-Type", "application/json")
            .body(response.to_string())
            .unwrap();
        Ok(())
    }
}
