using namespace std;

const int MAX_FILENAME_LENGTH = 255; // maximum length of a filename (including path)
const int MIN_VERSION_NUMBER = 1; // minimum version number for a file
const int MAX_VERSION_NUMBER = 999; // maximum version number for a file
const int CONFLICT_TIMEOUT = 5000; // timeout in milliseconds to resolve conflicts

// function to rename a file with a version number and return the new filename
string renameWithVersion(const string& originalFilename, const string& targetDir, int versionNumber) {
    // validate input parameters
    if (originalFilename.empty() || targetDir.empty()) {
        throw invalid_argument("Invalid argument: empty filename or target directory");
    }
    if (versionNumber < MIN_VERSION_NUMBER || versionNumber > MAX_VERSION_NUMBER) {
        throw out_of_range("Version number out of range: " + to_string(versionNumber));
    }

    // construct a unique filename with the given version number
    string newFilename = targetDir;
    if (!newFilename.ends_with("/")) {
        newFilename += "/";
    }
    newFilename += originalFilename + "_v" + to_string(versionNumber);

    // ensure the new filename does not exceed the maximum length
    int maxLength = MAX_FILENAME_LENGTH - targetDir.length() - 1;
    if (newFilename.length() > maxLength) {
        throw out_of_range("New filename too long: " + newFilename);
    }

    // check for conflicts with existing files and resolve them as necessary
    int counter = 0;
    while (true) {
        ifstream file(newFilename.c_str());
        if (!file) {
            break; // no conflict found, proceed with renaming
        }

        // append a timestamp or counter to the filename to resolve conflicts
        newFilename = targetDir;
        if (!newFilename.ends_with("/")) {
            newFilename += "/";
        }
        newFilename += originalFilename + "_v" + to_string(versionNumber) + "_" + to_string(counter);

        // check for conflicts again after appending the timestamp or counter
        ifstream file2(newFilename.c_str());
        if (!file2) {
            break; // no conflict found, proceed with renaming
        }

        // wait for a short period of time and try again if there is still a conflict
        this_thread::sleep_for(chrono::milliseconds(CONFLICT_TIMEOUT));
    }

    // rename the file and log all modifications to a central logging service or file
    string originalPath = targetDir + "/" + originalFilename;
    int status = std::rename(originalPath.c_str(), newFilename.c_str());
    if (status != 0) {
        throw runtime_error("Failed to rename file: " + originalFilename);
    }
    ofstream logFile("logfile.txt", ios::app);
    logFile << "Renamed " << originalFilename << " to " << newFilename << endl;
    logFile.close();

    return newFilename;
}
