<?php

namespace PasswordManagement;

use \Exception;
use \PDO;
use \Sodium\Compat;

class PasswordManager {
  private $pdo;
  private $salt;

  public function __construct(PDO $pdo, string $salt) {
    $this->pdo = $pdo;
    $this->salt = $salt;
  }

  public function generatePasswordHash(string $password): string {
    return Compat::crypto_generichash($password, self::SALT);
  }

  public function validatePassword(string $password, string $hash): bool {
    try {
      if (Compat::crypto_generichash($password) !== $hash) {
        return false;
      }
    } catch (Exception $e) {
      throw new Exception('Invalid password.');
    }
  }
}
