// DynamicFileMetadataAggregator
// A robust and scalable Rust application for aggregating metadata from multiple cloud storage services.

use std::collections::HashMap;
use std::error::Error;
use std::io::Read;
use std::time::Duration;
use std::vec::Vec;

use anyhow::Result;
use log::info;
use redis::Commands;
use reqwest::blocking::Client;
use serde::{Deserialize, Serialize};
use tokio::sync::mpsc::Receiver;

// Configuration struct for the application.
#[derive(Clone, Debug, Deserialize, Serialize)]
pub struct Config {
    pub services: Vec<ServiceConfig>,
}

// Configuration struct for each cloud storage service.
#[derive(Clone, Debug, Deserialize, Serialize)]
pub struct ServiceConfig {
    pub name: String,
    pub endpoint: String,
    pub key: String,
}

// Metadata struct for storing metadata from multiple services.
#[derive(Clone, Debug, Deserialize, Serialize)]
pub struct Metadata {
    pub service_name: String,
    pub metadata: HashMap<String, String>,
}

// Struct for handling the Redis cache.
struct CacheHandler {
    client: redis::Client,
    connection: redis::Connection,
}

impl CacheHandler {
    fn new(client: &redis::Client) -> Result<CacheHandler> {
        let connection = client.get_connection()?;

        Ok(CacheHandler { client: client.clone(), connection })
    }

    fn get(&self, key: &str) -> Result<Option<String>> {
        match self.connection.get(key)? {
            Some(value) => Ok(Some(value)),
            None => Ok(None),
        }
    }

    fn set(&self, key: &str, value: String) -> Result<()> {
        let _ = self.connection.set_ex(key, value, Duration::from_secs(3600))?; // 1 hour expiration

        Ok(())
    }
}

fn main() -> Result<(), Box<dyn Error>> {
    let config = Config::new("config.toml")?;

    // Initialize the Redis client and connection.
    let redis_client = redis::Client::open("redis://localhost:6379/0")?;
    let mut cache_handler = CacheHandler::new(&redis_client)?;

    // Initialize the HTTP client.
    let client = Client::builder()
        .timeout(Duration::from_secs(10)) // 10-second timeout
        .build()?;

    // Channel for receiving messages from the receiver thread.
    let (tx, rx) = tokio::sync::mpsc::channel(1024);

    // Spawn a new thread for handling incoming messages.
    tokio::spawn(async move {
        // Receive messages from the channel and handle them.
        while let Some(message) = rx.recv().await {
            match message {
                Message::UpdateCache(key, value) => {
                    // Update the cache with the given key and value.
                    cache_handler.set(&key, value)?;
                }
                Message::QueryCache(key) => {
                    // Query the cache for the given key and return the result.
                    let value = cache_handler.get(&key)?;

                    if let Some(value) = value {
                        // Send the query result back to the sender thread.
                        tx.send(QueryResult::CacheHit(value)).await?;
                    } else {
                        // If the cache misses, fetch the metadata from the cloud storage service and update the cache.
                        let mut response = client.get(&key).send()?;

                        if response.status().is_success() {
                            let value = response.text()?;

                            // Update the cache with the given key and value.
                            cache_handler.set(&key, value)?;

                            // Send the fetched metadata back to the sender thread.
                            tx.send(QueryResult::Fetched(value)).await?;
                        } else {
                            // If the request fails, send an error message back to the sender thread.
                            let status = response.status();
                            let body = response.text()?;

                            tx.send(QueryResult::Error(format!("{} {}", status, body))).await?;
                        }
                    }
                }
            }
        }

        Ok::<(), Box<dyn Error>>(())
    });

    // Initialize the receiver thread for handling messages.
    let receiver = Receiver::new(rx);

    // Infinite loop for receiving and handling messages.
    while let Some(message) = receiver.recv() {
        match message {
            Message::UpdateCache(key, value) => {
                // Update the cache with the given key and value.
                cache_handler.set(&key, value)?;
            }
            Message::QueryCache(key) => {
                // Query the cache for the given key and return the result.
                let value = cache_handler.get(&key)?;

                if let Some(value) = value {
                    // Send the query result back to the sender thread.
                    tx.send(QueryResult::CacheHit(value)).await?;
                } else {
                    // If the cache misses, fetch the metadata from the cloud storage service and update the cache.
                    let mut response = client.get(&key).send()?;

                    if response.status().is_success() {
                        let value = response.text()?;

                        // Update the cache with the given key and value.
                        cache_handler.set(&key, value)?;

                        // Send the fetched metadata back to the sender thread.
                        tx.send(QueryResult::Fetched(value)).await?;
                    } else {
                        // If the request fails, send an error message back to the sender thread.
                        let status = response.status();
                        let body = response.text()?;

                        tx.send(QueryResult::Error(format!("{} {}", status, body))).await?;
                    }
                }
            }
        }
    }
}
