package com.example.streamingimageprocessor;

import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import org.apache.commons.lang3.SerializationUtils;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.cloud.client.circuitbreaker.CircuitBreaker;
import org.springframework.cloud.client.circuitbreaker.CircuitBreakerFactory;
import org.springframework.stereotype.Component;
import com.example.streamingimageprocessor.CameraClient;
import com.example.streamingimageprocessor.CameraVendorApiClient;
import com.example.streamingimageprocessor.SecurityMonitor;
import com.example.streamingimageprocessor.StreamingImageProcessorProperties;
import com.example.streamingimageprocessor.StreamingImageProcessor;

@Component
public class StreamingImageProcessor {

    @Autowired
    private CameraVendorApiClient cameraVendorApiClient;

    @Autowired
    private SecurityMonitor securityMonitor;

    @Autowired
    private ExecutorService executorService;

    @Autowired
    private StreamingImageProcessorProperties streamingImageProcessorProperties;

    public void processStreamingImages() {
        // Load camera vendors from configuration file
        List<CameraVendor> cameraVendors = loadCameraVendorsFromConfiguration();

        // Create circuit breaker for each vendor API client
        Map<String, CircuitBreaker> circuitBreakers = new HashMap<>();
        for (CameraVendor vendor : cameraVendors) {
            String apiUrl = vendor.getApiUrl();
            CircuitBreakerFactory factory = streamingImageProcessorProperties.getCircuitBreakerFactory();
            CircuitBreaker cb = factory.create(apiUrl, vendor.getTimeout());
            circuitBreakers.put(apiUrl, cb);
        }

        // Create camera client for each vendor API client
        Map<String, CameraClient> cameraClients = new HashMap<>();
        for (CameraVendor vendor : cameraVendors) {
            String apiUrl = vendor.getApiUrl();
            CircuitBreaker cb = circuitBreakers.get(apiUrl);
            CameraClient client = new CameraClient(vendor.getName(), apiUrl, cb);
            cameraClients.put(apiUrl, client);
        }

        // Create streaming image processor for each camera vendor API client
        Map<String, StreamingImageProcessor> streamingImageProcessors = new HashMap<>();
        for (CameraClient client : cameraClients.values()) {
            String apiUrl = client.getApiUrl();
            StreamingImageProcessor processor = new StreamingImageProcessor(client, executorService);
            streamingImageProcessors.put(apiUrl, processor);
        }

        // Start processing streaming images from each camera vendor API client
        for (StreamingImageProcessor processor : streamingImageProcessors.values()) {
            processor.startProcessing();
        }
    }
}

