    CommunicationManager(vector<string> serviceAddresses);
    ~CommunicationManager();

    void sendMessage(const Message& msg); // send a message to all connected services
    Message receiveMessage(); // receive a message from any of the connected services
    bool isConnected(); // check if all services are still connected
private:
    vector<string> serviceAddresses; // the addresses of the external network services
    map<string, pair<int, int>> serviceSockets; // the sockets for each service (key: service address, value: socket and port)
    set<string> connectedServices; // the services that are still connected
    mutex connectMutex; // a mutex to protect concurrent access to the connections
    vector<thread> threadPool; // a pool of worker threads for handling network I/O
};

// Define a class to manage the distribution and configuration of messages across multiple instances
class MessageManager {
public:
    MessageManager(vector<string> instanceAddresses);
    ~MessageManager();

    void sendMessage(const Message& msg); // send a message to all connected instances
    bool isInstanceConnected(const string& instanceAddress); // check if an instance is still connected
private:
    vector<string> instanceAddresses; // the addresses of the message distribution instances
    map<string, pair<int, int>> instanceSockets; // the sockets for each instance (key: instance address, value: socket and port)
    set<string> connectedInstances; // the instances that are still connected
    mutex connectMutex; // a mutex to protect concurrent access to the connections
};

// Define a class to manage the configuration of the system
class ConfigurationManager {
public:
    ConfigurationManager();
    ~ConfigurationManager();

    void updateConfiguration(const map<string, string>& newConfig); // update the system configuration with the given values
private:
    map<string, string> config; // the current system configuration
    mutex configMutex; // a mutex to protect concurrent access to the configuration
};
