#include <boost/asio.hpp>

class CommunicationManager {
public:
    void sendMessage(const Message& msg) {
        // Create a new connection to the service using boost::asio
        auto& socket = socketPool[msg.service];
        if (!socket) {
            socket = make_unique<boost::asio::ip::tcp::socket>(context);
            socket->connect(boost::asio::ip::tcp::endpoint(boost::asio::ip::address::from_string(msg.service), msg.port));
        }

        // Encode the message and send it to the service using boost::asio
        vector<uint8_t> encodedMsg;
        encodeMessage(&encodedMsg, msg);
        socket->write_some(boost::asio::buffer(encodedMsg), [this, &msg](const boost::system::error_code& ec) {
            if (ec) {
                // Handle error
            } else {
                // Handle success
            }
        });
    }

private:
    boost::asio::io_context context;
    map<string, unique_ptr<boost::asio::ip::tcp::socket>> socketPool;
};
