#include <ctime>
#include "openssl/aes.h"
#include "openssl/evp.h"
#include "openssl/rand.h"
#include "openssl/hmac.h"
#include "openssl/err.h"
#include "argon2.h"
using namespace std;
const size_t AES_BLOCK_SIZE = 16;
const size_t GCM_TAG_SIZE = 16;
const string ENCRYPTION_KEY_FILENAME = "encryption_key.txt";
const string INITIALIZATION_VECTOR_FILENAME = "initialization_vector.txt";
void generateEncryptionKey(string& key);
void generateInitializationVector(string& iv);
string encrypt(string& message, string& key, string& iv);
string decrypt(string& ciphertext, string& key, string& iv);
int main() {
    // Generate encryption and initialization vectors
    string key;
    generateEncryptionKey(key);
    string iv;
    generateInitializationVector(iv);
    // Encrypt a message
    string message = "This is a test message";
    cout << "Original message: " << message << endl;
    string ciphertext = encrypt(message, key, iv);
    cout << "Encrypted message: " << ciphertext << endl;
    // Decrypt the ciphertext
    string plaintext = decrypt(ciphertext, key, iv);
    cout << "Decrypted message: " << plaintext << endl;
}
void generateEncryptionKey(string& key) {
    // Generate a random encryption key using Argon2
    char* password = "a secret password";
    int password_len = strlen(password);
    argon2_context context = { 0 };
    context.out = (uint8_t*)key.data();
    context.outlen = AES_BLOCK_SIZE;
    context.pwd = (const uint8_t*)password;
    context.pwdlen = password_len;
    context.salt = NULL;
    context.secret = NULL;
    context.ad = NULL;
    context.adlen = 0;
    context.t_cost = 4;
    context.m_cost = 16;
    int result = argon2i_hash_raw(&context);
    if (result != ARGON2_OK) {
        cerr << "Error generating encryption key: " << result << endl;
        exit(EXIT_FAILURE);
    }
}
void generateInitializationVector(string& iv) {
    // Generate a random initialization vector using OpenSSL
    unsigned char* data = new unsigned char[AES_BLOCK_SIZE];
    RAND_bytes(data, AES_BLOCK_SIZE);
    iv = string((char*)data, AES_BLOCK_SIZE);
    delete[] data;
}
string encrypt(string& message, string& key, string& iv) {
    // Encrypt the message using AES-256-CBC with GCM tag
    unsigned char* data = (unsigned char*)message.data();
    size_t len = message.length();
    size_t block_len = (len + AES_BLOCK_SIZE - 1) / AES_BLOCK_SIZE * AES_BLOCK_SIZE;
    unsigned char* ciphertext = new unsigned char[block_len + GCM_TAG_SIZE];
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    // Set encryption parameters
    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key.data(), iv.data()) != 1) {
        cerr << "Error initializing encryption context" << endl;
        exit(EXIT_FAILURE);
    }
    // Encrypt the message
    if (EVP_EncryptUpdate(ctx, ciphertext, &block_len, data, len) != 1) {
        cerr << "Error encrypting message" << endl;
        exit(EXIT_FAILURE);
    }
    // Generate GCM tag
    if (EVP_EncryptFinal_ex(ctx, ciphertext + block_len, &block_len) != 1) {
        cerr << "Error finalizing encryption" << endl;
        exit(EXIT_FAILURE);
    }
    // Free resources and return the ciphertext
    EVP_CIPHER_CTX_free(ctx);
    string result = string((char*)ciphertext, block_len + GCM_TAG_SIZE);
    delete[] ciphertext;
    return result;
}
string decrypt(string& ciphertext, string& key, string& iv) {
    // Decrypt the ciphertext using AES-256-CBC with GCM tag
    unsigned char* data = (unsigned char*)ciphertext.data();
    size_t len = ciphertext.length();
    size_t block_len = (len - GCM_TAG_SIZE + AES_BLOCK_SIZE - 1) / AES_BLOCK_SIZE * AES_BLOCK_SIZE;
    unsigned char* plaintext = new unsigned char[block_len];
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    // Set decryption parameters
    if (EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key.data(), iv.data()) != 1) {
        cerr << "Error initializing decryption context" << endl;
        exit(EXIT_FAILURE);
    }
    // Decrypt the ciphertext
    if (EVP_DecryptUpdate(ctx, plaintext, &block_len, data, len - GCM_TAG_SIZE) != 1) {
        cerr << "Error decrypting message" << endl;
        exit(EXIT_FAILURE);
    }
    // Verify the GCM tag
    unsigned char* tag = new unsigned char[GCM_TAG_SIZE];
    memcpy(tag, data + block_len, GCM_TAG_SIZE);
    if (EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_TAG, GCM_TAG_SIZE, tag) != 1) {
        cerr << "Error setting GCM tag" << endl;
        exit(EXIT_FAILURE);
    }
    // Free resources and return the plaintext
    EVP_CIPHER_CTX_free(ctx);
    string result = string((char*)plaintext, block_len);
    delete[] plaintext;
    delete[] tag;
    return result;
}']

