#include "NFAPI_CRC_INDICATION_PDU_T.h"

// Define a structure to store the state of the CRC indication PDUs
typedef struct {
  int num_indications;
  NFAPI_CRC_INDICATION_PDU_T *indications;
} CrcIndicationState;

// Define a mutex to protect access to the state of the CRC indication PDUs
pthread_mutex_t crc_indication_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new CRC indication PDU to the pool
void add_crc_indication(NFAPI_CRC_INDICATION_PDU_T *indication) {
  pthread_mutex_lock(&crc_indication_mutex);

  // Check if there is enough memory available to store the new indication
  if (state.num_indications >= MAX_NUM_INDICATIONS) {
    // If not, release the mutex and return an error
    pthread_mutex_unlock(&crc_indication_mutex);
    printf("Error: Not enough memory to store new CRC indication\n");
    return;
  }

  // Otherwise, allocate memory for the new indication and copy its contents
  state.indications[state.num_indications++] = *indication;

  pthread_mutex_unlock(&crc_indication_mutex);
}

// Function to remove a CRC indication PDU from the pool
void remove_crc_indication(int index) {
  pthread_mutex_lock(&crc_indication_mutex);

  // Check if the specified index is valid
  if (index >= state.num_indications || index < 0) {
    // If not, release the mutex and return an error
    pthread_mutex_unlock(&crc_indication_mutex);
    printf("Error: Invalid CRC indication index\n");
    return;
  }

  // Otherwise, shift all subsequent indications to fill the gap
  for (int i = index + 1; i < state.num_indications; i++) {
    state.indications[i - 1] = state.indications[i];
  }

  // Decrement the number of indications and free the memory allocated for the removed indication
  state.num_indications--;
  pthread_mutex_unlock(&crc_indication_mutex);
}

// Function to retrieve a CRC indication PDU from the pool by its index
NFAPI_CRC_INDICATION_PDU_T* get_crc_indication(int index) {
  pthread_mutex_lock(&crc_indication_mutex);

  // Check if the specified index is valid
  if (index >= state.num_indications || index < 0) {
    // If not, release the mutex and return an error
    pthread_mutex_unlock(&crc_indication_mutex);
    printf("Error: Invalid CRC indication index\n");
    return NULL;
  }

  NFAPI_CRC_INDICATION_PDU_T *indication = &state.indications[index];
  pthread_mutex_unlock(&crc_indication_mutex);
  return indication;
}

