    int expires_in;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a pool of NFAPI_CRC_INDICATION_PDU_T structures
#define POOL_SIZE 1024
NFAPI_CRC_INDICATION_PDU_T pool[POOL_SIZE];

// Define the mutex for protecting the access to the pool
pthread_mutex_t pool_mutex = PTHREAD_MUTEX_INITIALIZER;

// Define the semaphore for waiting for available slots in the pool
semaphore_t pool_sem = SEMAPHORE_INITIALIZER(1, 0);

// Define the function to acquire a slot from the pool
int acquire_slot() {
    int ret;
    pthread_mutex_lock(&pool_mutex);
    while ((ret = semaphore_wait(&pool_sem)) != 0) {
        if (errno == EINTR || errno == EAGAIN) {
            continue;
        } else {
            break;
        }
    }
    pthread_mutex_unlock(&pool_mutex);
    return ret;
}

// Define the function to release a slot in the pool
int release_slot() {
    int ret;
    pthread_mutex_lock(&pool_mutex);
    while ((ret = semaphore_post(&pool_sem)) != 0) {
        if (errno == EINTR || errno == EAGAIN) {
            continue;
        } else {
            break;
        }
    }
    pthread_mutex_unlock(&pool_mutex);
    return ret;
}

// Define the function to add a new slot in the pool if needed
