        BlobId blobId = BlobId.of(blobInfo);
        byte[] encryptedContent = encryptFileContent(fileContent, encryptionKey);

        // Upload the file to the cloud storage.
        CompletableFuture<Void> uploadFuture = client.create(blobInfo, encryptedContent);

        // Add a callback function to track the progress of the upload and handle errors.
        uploadFuture.whenComplete((result, error) -> {
            if (error != null) {
                System.out.println("Error occurred during file upload: " + error.getMessage());
                return;
            }
            System.out.println("File uploaded successfully.");
        });

        return uploadFuture;
    }

    /**
     * Encrypts the given content using AES-256-CBC or RSA, depending on the user's preferences.
     * @param content The content to encrypt.
     * @param encryptionKey The encryption key to use for encryption.
     * @return The encrypted content.
     */
    public static byte[] encryptFileContent(byte[] content, String encryptionKey) {
        // Use AES-256-CBC encryption if the user prefers it, otherwise use RSA encryption.
        if (encryptionKey.startsWith("aes-")) {
            return encryptAes(content, encryptionKey);
        } else {
            return encryptRsa(content, encryptionKey);
        }
    }

    /**
     * Encrypts the given content using AES-256-CBC.
     * @param content The content to encrypt.
     * @param encryptionKey The encryption key to use for encryption.
     * @return The encrypted content.
     */
    public static byte[] encryptAes(byte[] content, String encryptionKey) {
        // Load the AES-256-CBC cipher from the Java Cryptography Extension (JCE) provider.
        Cipher aes = Cipher.getInstance("AES/CBC/PKCS5Padding");

        // Generate a secret key using the given encryption key and AES-256-CBC algorithm.
        SecretKeySpec secretKey = new SecretKeySpec(encryptionKey.getBytes(), "AES");
        aes.init(Cipher.ENCRYPT_MODE, secretKey);

        // Encrypt the content using AES-256-CBC and return the encrypted bytes.
        byte[] encryptedContent = aes.doFinal(content);
        return encryptedContent;
    }

    /**
     * Encrypts the given content using RSA encryption.
     * @param content The content to encrypt.
     * @param encryptionKey The encryption key to use for encryption.
     * @return The encrypted content.
     */
    public static byte[] encryptRsa(byte[] content, String encryptionKey) {
        // Load the RSA algorithm from the Java Cryptography Extension (JCE) provider.
        KeyPair rsa = KeyPair.getKeyPair("RSA", "SHA256withRSA");

        // Generate a secret key using the given encryption key and RSA algorithm.
        SecretKeySpec secretKey = new SecretKeySpec(encryptionKey.getBytes(), "RSA");
        rsa.init(Cipher.ENCRYPT_MODE, secretKey);

        // Encrypt the content using RSA encryption and return the encrypted bytes.
        byte[] encryptedContent = rsa.doFinal(content);
        return encryptedContent;
    }
