#include <fstream>
#include <iostream>
#include <vector>

int loadResourceBundle(const char* path) {
  std::ifstream file(path);
  if (!file.is_open()) {
    return -1; // error opening file
  }

  std::string line;
  std::vector<std::string> items;
  while (std::getline(file, line)) {
    items.push_back(line);
  }

  int numItems = items.size();

  // allocate memory for the bundle and its items
  char** bundle = new char*[numItems];
  for (int i = 0; i < numItems; i++) {
    bundle[i] = new char[strlen(items[i].c_str()) + 1];
    strcpy(bundle[i], items[i].c_str());
  }

  file.close();

  return numItems;
}
```
