// Define a struct to represent an SSL/TLS connection
typedef struct {
    int socket; // The file descriptor for the socket
    SSL_CTX *ctx; // The OpenSSL context object
    SSL *ssl; // The OpenSSL object representing the current connection
} ssl_conn_t;

// Initialize an SSL/TLS connection
int init_ssl(ssl_conn_t *conn, const char *hostname, int port) {
    conn->socket = socket(AF_INET, SOCK_STREAM, 0);
    if (conn->socket < 0) {
        perror("socket");
        return -1;
    }

    // Set up the SSL context object
    conn->ctx = SSL_CTX_new(TLSv1_client_method());
    if (!conn->ctx) {
        ERR_print_errors_fp(stderr);
        close(conn->socket);
        return -1;
    }

    // Set up the SSL object for this connection
    conn->ssl = SSL_new(conn->ctx);
    if (!conn->ssl) {
        ERR_print_errors_fp(stderr);
        SSL_CTX_free(conn->ctx);
        close(conn->socket);
        return -1;
    }

    // Connect to the server
    struct sockaddr_in server_addr = {0};
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(port);
    if (inet_pton(AF_INET, hostname, &server_addr.sin_addr) <= 0) {
        perror("inet_pton");
        SSL_free(conn->ssl);
        SSL_CTX_free(conn->ctx);
        close(conn->socket);
        return -1;
    }
    if (connect(conn->socket, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("connect");
        SSL_free(conn->ssl);
        SSL_CTX_free(conn->ctx);
        close(conn->socket);
        return -1;
    }

    // Perform the SSL/TLS handshake
    if (SSL_connect(conn->ssl) < 0) {
        ERR_print_errors_fp(stderr);
        SSL_free(conn->ssl);
        SSL_CTX_free(conn->ctx);
        close(conn->socket);
        return -1;
    }

    return 0;
}

// Clean up an SSL/TLS connection
void cleanup_ssl(ssl_conn_t *conn) {
    if (conn->ssl) {
        SSL_free(conn->ssl);
    }
    if (conn->ctx) {
        SSL_CTX_free(conn->ctx);
    }
    close(conn->socket);
}

// Send data over an SSL/TLS connection
int send_data(ssl_conn_t *conn, const char *data, int len) {
    if (!conn || !conn->ssl) {
        return -1;
    }

    // Write the data to the socket
    int ret = SSL_write(conn->ssl, data, len);
    if (ret < 0) {
        ERR_print_errors_fp(stderr);
        return -1;
    }

    return ret;
}

// Receive data over an SSL/TLS connection
int receive_data(ssl_conn_t *conn, char *buf, int len) {
    if (!conn || !conn->ssl) {
        return -1;
    }

    // Read the data from the socket
    int ret = SSL_read(conn->ssl, buf, len);
    if (ret < 0) {
        ERR_print_errors_fp(stderr);
        return -1;
    }

    return ret;
}
```
This code defines a struct `ssl_conn_t` to represent an SSL/TLS connection, and provides functions for initializing, cleaning up, sending, and receiving data over the connection. The `init_ssl()` function creates a new SSL/TLS connection, sets up the SSL context and object, connects to the server, performs the SSL/TLS handshake, and returns 0 on success or -1 on error. The `cleanup_ssl()` function frees the SSL object and context, closes the socket, and returns. The `send_data()` function sends data over the connection using the SSL_write() function, and returns the number of bytes sent on success or -1 on error. The `receive_data()` function receives data over the connection using the SSL_read() function, and returns the number of bytes received on success or -1 on error.

To use this library in your application, you would first need to include the header file containing the struct definition and function prototypes:
```
#include "ssl_lib.h"
```
Then, you can create an instance of `ssl_conn_t` using the `init_ssl()` function, and use the `send_data()` and `receive_data()` functions to send and receive data over the connection. For example:
```
int main() {
    // Initialize an SSL/TLS connection
    ssl_conn_t conn;
    init_ssl(&conn, "example.com", 443);

    // Send some data over the connection
    char *data = "Hello, server!";
    int ret = send_data(&conn, data, strlen(data));
    if (ret < 0) {
        perror("send");
        return -1;
    }

    // Receive some data from the connection
    char buf[256];
    ret = receive_data(&conn, buf, sizeof(buf));
    if (ret < 0) {
        perror("receive");
        return -1;
    }

    printf("Received %d bytes: %s\n", ret, buf);

    // Clean up the connection
    cleanup_ssl(&conn);

    return 0;
}
```
This code initializes an SSL/TLS connection to `example.com` on port 443 using the `init_ssl()` function, sends a string of data over the connection using the `send_data()` function, receives some data from the connection using the `receive_data()` function, and then cleans up the connection using the `cleanup_ssl()` function.']

