// Retry Mechanism with Exponential Backoff Strategies
class RetryManager {
private:
    int maxRetries = 3;
    int backoffFactor = 1000; // milliseconds
    map<string, int> retryCounts;

public:
    void reset() {
        retryCounts.clear();
    }

    bool shouldRetry(const string& key) {
        auto it = retryCounts.find(key);
        if (it == retryCounts.end()) {
            return false;
        }
        int count = it->second + 1;
        retryCounts[key] = count;
        return count <= maxRetries;
    }

    void backoff(const string& key) {
        auto it = retryCounts.find(key);
        if (it == retryCounts.end()) {
            return;
        }
        int count = it->second + 1;
        retryCounts[key] = count;
        this_thread::sleep_for(chrono::milliseconds(backoffFactor * count));
    }
};

