        packets.reserve(MAX_PACKETS);
    }

    // Add a packet to the pool
    void addPacket(std::string data, int size) {
        std::lock_guard<std::mutex> lock(mutex);
        if (packets.size() >= MAX_PACKETS || size < MIN_SIZE || size > MAX_SIZE) {
            return;
        }
        packets.emplace_back(new PacketBuffer{data, size});
        empty = false;
        cv.notify_one();
    }

    // Remove a packet from the pool
