    // A mutex to protect the thread list from concurrent access
    std::mutex mutex;

    // A condition variable to signal when a new task is available
    std::condition_variable cv;

    // A flag to indicate if there are any tasks left to be processed
    bool active = true;

public:
    ThreadPool() {
        threads.reserve(MAX_THREADS);
    }

    // Add a new task to the pool
    void addTask(std::function<void()> task) {
        std::lock_guard<std::mutex> lock(mutex);
        if (threads.size() >= MAX_THREADS || !active) {
            return;
        }
        threads.emplace_back([this, task](){
            task();
            {
                std::lock_guard<std::mutex> lock(mutex);
                active = false;
                cv.notify_one();
            }
        });
    }

    // Wait for all tasks to be processed and then shut down the pool
    void waitAndShutdown() {
        std::unique_lock<std::mutex> lock(mutex);
        while (active) {
            cv.wait(lock);
        }
        for (auto& thread : threads) {
            thread.join();
        }
    }
