using namespace std;

class HttpSession {
public:
    HttpSession(const string& region, const string& userAgent) : region(region), userAgent(userAgent) {}
    virtual ~HttpSession() = default;

    // Getters and setters for session metadata.
    const string& getRegion() const { return region; }
    void setRegion(const string& region) { this->region = region; }
    const string& getUserAgent() const { return userAgent; }
    void setUserAgent(const string& userAgent) { this->userAgent = userAgent; }

    // Virtual methods for session handling.
    virtual bool isValid() const = 0;
    virtual void startSession() = 0;
    virtual void endSession() = 0;

private:
    string region;
    string userAgent;
};

class HttpSessionPool {
public:
    HttpSessionPool(const string& region, size_t capacity) : region(region), capacity(capacity), poolSize(0), sessions(vector<HttpSession*>()) {}
    virtual ~HttpSessionPool() = default;

    // Add a new session to the pool.
    void addSession(HttpSession* session) {
        std::lock_guard<std::mutex> lock(poolMutex);
        if (sessions.size() >= capacity) {
            throw "Pool is full";
        } else {
            sessions.push_back(session);
            poolSize++;
        }
    }

    // Remove a session from the pool.
    void removeSession(HttpSession* session) {
        std::lock_guard<std::mutex> lock(poolMutex);
        for (auto it = sessions.begin(); it != sessions.end(); ++it) {
            if (*it == session) {
                sessions.erase(it);
                poolSize--;
                break;
            }
        }
    }

    // Get a session from the pool.
    HttpSession* getSession() {
        std::lock_guard<std::mutex> lock(poolMutex);
        if (sessions.empty()) {
            return nullptr;
        } else {
            auto session = sessions.front();
            sessions.erase(sessions.begin());
            poolSize--;
            return session;
        }
    }

private:
    string region;
    size_t capacity;
    size_t poolSize;
    vector<HttpSession*> sessions;
    std::mutex poolMutex;
};

class HttpSessionManager {
public:
    HttpSessionManager(const string& region, const string& userAgent) : region(region), userAgent(userAgent), sessionPool(nullptr) {}
    virtual ~HttpSessionManager() = default;

    // Start a new session.
    void startSession() {
        std::lock_guard<std::mutex> lock(sessionMutex);
        if (sessionPool == nullptr) {
            sessionPool = createSessionPool();
        }
        auto session = sessionPool->getSession();
        if (session != nullptr) {
            session->startSession();
        } else {
            throw "No sessions available";
        }
    }

    // End an existing session.
    void endSession() {
        std::lock_guard<std::mutex> lock(sessionMutex);
        if (sessionPool != nullptr) {
            auto session = getCurrentSession();
            if (session == nullptr) {
                throw "No current session";
            } else {
                session->endSession();
            }
        }
    }

private:
    string region;
    string userAgent;
    HttpSessionPool* sessionPool;
    std::mutex sessionMutex;

    // Create a new session pool.
    HttpSessionPool* createSessionPool() {
        return new HttpSessionPool(region, 10);
    }

    // Get the current session from the pool.
    HttpSession* getCurrentSession() {
        std::lock_guard<std::mutex> lock(sessionMutex);
        if (sessionPool != nullptr) {
            return sessionPool->getSession();
        } else {
            return nullptr;
        }
    }
};
