#ifndef IoTSemaphore_H
#define IoTSemaphore_H

#include <stdbool.h>
#include <stdint.h>
#include <pthread.h>

// Define the type of semaphore to be used
typedef enum {
    SEMAPHORE_TYPE_BINARY,
    SEMAPHORE_TYPE_COUNTING
} IoTSemaphoreType;

// Define the structure for a semaphore
typedef struct {
    // The type of semaphore
    IoTSemaphoreType type;

    // The value of the semaphore
    uint64_t value;

    // The mutex to protect the semaphore
    pthread_mutex_t* mutex;
} IoTSemaphore;

// Define the structure for a thread-safe semaphore
typedef struct {
    // The type of semaphore
    IoTSemaphoreType type;

    // The value of the semaphore
    uint64_t value;

    // The mutex to protect the semaphore
    pthread_mutex_t* mutex;

    // The condition variable for waiting on the semaphore
    pthread_cond_t* cond;
} IoTSemaphoreSafe;

// Define the function prototypes for the library
void IoTSemaphoreCreate(IoTSemaphore* sem, IoTSemaphoreType type, uint64_t value);
bool IoTSemaphoreWait(IoTSemaphore* sem);
bool IoTSemaphoreTimedWait(IoTSemaphore* sem, uint64_t timeout);
void IoTSemaphorePost(IoTSemaphore* sem);
bool IoTSemaphoreTryWait(IoTSemaphore* sem);
void IoTSemaphoreDestroy(IoTSemaphore* sem);

// Define the function prototypes for the thread-safe library
void IoTSemaphoreSafeCreate(IoTSemaphoreSafe* sem, IoTSemaphoreType type, uint64_t value);
bool IoTSemaphoreSafeWait(IoTSemaphoreSafe* sem);
bool IoTSemaphoreSafeTimedWait(IoTSemaphoreSafe* sem, uint64_t timeout);
void IoTSemaphoreSafePost(IoTSemaphoreSafe* sem);
bool IoTSemaphoreSafeTryWait(IoTSemaphoreSafe* sem);
void IoTSemaphoreSafeDestroy(IoTSemaphoreSafe* sem);

#endif // IoTSemaphore_H
