// configManager.c
#include <stdbool.h>
#include <stddef.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "configManager.h"

// Define a map to hold configuration data with version information
static ConfigDataWithVersion* config_map;

// Define function to initialize the configuration manager
void init_config_manager() {
    // Allocate memory for the configuration map
    config_map = (ConfigDataWithVersion*)malloc(sizeof(ConfigDataWithVersion));

    // Initialize the version number of the configuration data to 0
    config_map->version = 0;
}

// Define function to read configuration data from a file
void read_config_data_from_file(const char* filename) {
    // Open the configuration file for reading
    FILE* fp = fopen(filename, "r");
    if (fp == NULL) {
        printf("Error: unable to open configuration file '%s'\n", filename);
        return;
    }

    // Read the configuration data from the file
    char line[256];
    while (fgets(line, sizeof(line), fp) != NULL) {
        // Parse the configuration data from the line
        char* key = strtok(line, "=");
        char* value = strtok(NULL, "\n");
        if (key == NULL || value == NULL) {
            printf("Error: invalid configuration file format\n");
            break;
        }

        // Add the configuration data to the map
        ConfigDataWithVersion* config = get_config_data(key, false);
        set_config_data(config, value);
    }

    // Close the configuration file
    fclose(fp);
}

// Define function to write configuration data to a file
void write_config_data_to_file(const char* filename) {
    // Open the configuration file for writing
    FILE* fp = fopen(filename, "w");
    if (fp == NULL) {
        printf("Error: unable to open configuration file '%s'\n", filename);
        return;
    }

    // Write the configuration data to the file
    ConfigDataWithVersion* config = get_config_data(NULL, false);
    while (config != NULL) {
        fprintf(fp, "%s=%s\n", config->key, config->value);
        config = get_config_data(NULL, true);
    }

    // Close the configuration file
    fclose(fp);
}

// Define function to get a configuration data with version information
ConfigDataWithVersion* get_config_data(const char* key, bool trim) {
    if (key == NULL) {
        return config_map;
    }

    // Search for the configuration data in the map
    ConfigDataWithVersion* config = config_map;
    while (config != NULL && strcmp(config->key, key) != 0) {
        config = config->next;
    }

    // Return the configuration data if found, otherwise return NULL
    if (config == NULL) {
        return NULL;
    } else if (trim) {
        return config->next;
    } else {
        return config;
    }
}

// Define function to set a configuration data with version information
void set_config_data(ConfigDataWithVersion* config, const char* value) {
    // Update the value of the configuration data in the map
    if (config == NULL || value == NULL) {
        return;
    }
    config->version++;
    strcpy(config->value, value);
}

// Define function to handle truncate_and_format()
char* truncate_and_format(const char* input, size_t max_length, bool trim, int* api_call_count) {
    // Handle null inputs
    if (input == NULL || max_length <= 0) {
        return NULL;
    }

    // Calculate the actual maximum length based on the trim flag
    size_t actual_max_length = max_length - (trim ? 3 : 0);

    // Truncate the input string if necessary
    const char* truncated = NULL;
    if (strlen(input) > actual_max_length) {
        *api_call_count += 1;
        truncated = strndup(input, actual_max_length);
    } else {
        truncated = input;
    }

    // Format the truncated string
    char* formatted = (char*)malloc(sizeof(char) * (strlen(truncated) + 3));
    sprintf(formatted, "%s...", truncated);

    // Return the formatted string
    return formatted;
}

// Define function to free memory allocated by the configuration manager
void free_config_manager() {
    // Free the memory for the configuration map
    if (config_map != NULL) {
        ConfigDataWithVersion* config = config_map;
        while (config != NULL) {
            ConfigDataWithVersion* next = config->next;
            free(config);
            config = next;
        }
        free(config_map);
    }
}
```

