using namespace std;

// Define a semaphore struct to hold the semaphore information
struct Semaphore {
    string name;        // Name of the semaphore
    int value;          // Current value of the semaphore
    bool available;     // Indicates whether the semaphore is available
};

// Define a map to hold all the created semaphores
map<string, Semaphore> semaphores;

// Define a mutex for synchronizing access to the semaphore map
mutex semaphore_lock;

// Define a condition variable for signaling when a semaphore becomes available
condition_variable semaphore_available;

// Define a function to create a new semaphore with the given name and initial value
Semaphore* createSemaphore(string name, int initialValue) {
    // Lock the mutex before modifying the semaphore map
    lock_guard<mutex> lock(semaphore_lock);

    // Check if a semaphore with the given name already exists
    if (semaphores.find(name) != semaphores.end()) {
        throw runtime_error("Semaphore already exists");
    }

    // Create a new semaphore object and add it to the map
    Semaphore* semaphore = new Semaphore();
    semaphore->name = name;
    semaphore->value = initialValue;
    semaphore->available = true;
    semaphores[name] = *semaphore;

    // Unlock the mutex
    lock.unlock();

    return semaphore;
}

// Define a function to delete a semaphore with the given name
void deleteSemaphore(string name) {
    // Lock the mutex before modifying the semaphore map
    lock_guard<mutex> lock(semaphore_lock);

    // Check if a semaphore with the given name exists
    auto it = semaphores.find(name);
    if (it == semaphores.end()) {
        throw runtime_error("Semaphore does not exist");
    }

    // Remove the semaphore from the map and delete it
    semaphores.erase(it);

    // Unlock the mutex
    lock.unlock();
}

// Define a function to acquire a semaphore with the given name, waiting for the semaphore to become available if necessary
void acquireSemaphore(string name) {
    // Lock the mutex before modifying the semaphore map
    lock_guard<mutex> lock(semaphore_lock);

    // Check if a semaphore with the given name exists
    auto it = semaphores.find(name);
    if (it == semaphores.end()) {
        throw runtime_error("Semaphore does not exist");
    }

    // Get the semaphore object from the map
    Semaphore* semaphore = it->second;

    // Wait for the semaphore to become available if necessary
    while (!semaphore->available) {
        semaphore_available.wait(lock);
    }

    // Decrement the value of the semaphore and set it as unavailable if necessary
    int newValue = semaphore->value - 1;
    if (newValue <= 0) {
        semaphore->available = false;
    } else {
        semaphore->value = newValue;
    }

    // Unlock the mutex
    lock.unlock();
}

// Define a function to release a semaphore with the given name, setting it as available if necessary
void releaseSemaphore(string name) {
    // Lock the mutex before modifying the semaphore map
    lock_guard<mutex> lock(semaphore_lock);

    // Check if a semaphore with the given name exists
    auto it = semaphores.find(name);
    if (it == semaphores.end()) {
        throw runtime_error("Semaphore does not exist");
    }

    // Get the semaphore object from the map
    Semaphore* semaphore = it->second;

    // Increment the value of the semaphore and set it as available if necessary
    int newValue = semaphore->value + 1;
    if (newValue > 0) {
        semaphore->available = true;
    } else {
        semaphore->value = 0;
    }

    // Unlock the mutex
    lock.unlock();
}

// Define a function to return the current value of a semaphore with the given name, returning -1 if the semaphore does not exist
int getSemaphoreValue(string name) {
    // Lock the mutex before modifying the semaphore map
    lock_guard<mutex> lock(semaphore_lock);

    // Check if a semaphore with the given name exists
    auto it = semaphores.find(name);
    if (it == semaphores.end()) {
        return -1;
    }

    // Get the semaphore object from the map and return its value
    return it->second->value;
}
