// Modular C++ library for managing TCP connections
#include <iostream>
#include <vector>
#include <map>
#include <mutex>
#include <condition_variable>
#include <unordered_set>
#include <memory>
#include <string>

class ConnectionPool {
public:
    ConnectionPool(int maxConnections = 10, int minConnections = 5) : maxConnections_(maxConnections), minConnections_(minConnections) {}

    ~ConnectionPool() {
        std::unique_lock<std::mutex> lock(poolMutex_);
        for (auto it = connections_.begin(); it != connections_.end(); ++it) {
            if ((*it)->connected()) {
                (*it)->disconnect();
            }
        }
    }

    std::shared_ptr<Connection> getConnection(const std::string& serverName, int version = 1) {
        std::unique_lock<std::mutex> lock(poolMutex_);

        // Check if a connection to the requested server is available in the pool
        for (auto it = connections_.begin(); it != connections_.end(); ++it) {
            if ((*it)->connected() && (*it)->serverName == serverName && (*it)->version == version) {
                return *it;
            }
        }

        // If no available connection found, create a new one and add it to the pool
        auto newConnection = std::make_shared<Connection>(serverName, version);
        connections_.push_back(newConnection);
        return newConnection;
    }

private:
    class Connection {
    public:
        Connection(const std::string& serverName, int version) : serverName_(serverName), version_(version), connected_(false) {}

        ~Connection() {
            if (connected_) {
                disconnect();
            }
        }

        void connect() {
            // Connect to the server and establish a session
            std::cout << "Connecting to " << serverName_ << " version " << version_ << std::endl;
            connected_ = true;
        }

        void disconnect() {
            // Disconnect from the server and destroy the session
            std::cout << "Disconnecting from " << serverName_ << " version " << version_ << std::endl;
            connected_ = false;
        }

        bool connected() const { return connected_; }

    private:
        std::string serverName_;
        int version_;
        bool connected_;
    };

    // Pool of available connections
    std::vector<std::shared_ptr<Connection>> connections_;
    // Mutex to protect the pool from concurrent access
    std::mutex poolMutex_;
    // Maximum number of connections in the pool
    int maxConnections_;
    // Minimum number of connections in the pool
    int minConnections_;
};
