/*
 * process_tiff_files.c
 *
 * Implements a function that processes all TIFF files in a specified directory.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>

#define MAX_FILE_COUNT 10000
#define RETRY_DELAY_MS 500
#define EXPONENTIAL_BACKOFF_FACTOR 2

struct file_info {
    char *file_name;
    unsigned long file_size;
};

struct metadata {
    int bits_per_sample;
    int samples_per_pixel;
    int extra_samples;
    struct sample_info {
        char name[256];
        int count;
    } extra_samples[10];
};

// Processes all TIFF files in a specified directory.
void process_tiff_files(const char *directory) {
    // Initialize file processing variables.
    struct file_info *file_list = NULL;
    unsigned long file_count = 0;
    int retry_delay = RETRY_DELAY_MS;
    int concurrent_file_access = 0;
    int version = 1;

    // Initialize metadata extraction variables.
    struct metadata *metadata_list = NULL;
    unsigned long metadata_count = 0;

    // Loop through all files in the specified directory.
    while ((file_list = read_next_file(directory, file_list))) {
        // Increment concurrent file access count to prevent simultaneous access.
        concurrent_file_access++;

        // Extract metadata from TIFF file.
        struct metadata *metadata = extract_metadata(file_list->file_name);

        // Process metadata.
        process_metadata(metadata, version);

        // Free memory used by metadata.
        free(metadata);

        // Decrement concurrent file access count.
        concurrent_file_access--;
    }

    // Ensure all files have been processed before exiting.
    while (concurrent_file_access > 0) {
        // Sleep for a short period of time to allow other tasks to run.
        sleep(retry_delay / 1000);

        // Increment retry delay to prevent overwhelming system resources.
        retry_delay *= EXPONENTIAL_BACKOFF_FACTOR;
    }

    // Free memory used by file list.
    free(file_list);

    // Log completion of file processing.
    log("Completed processing %d files.", file_count);
}

// Reads the next TIFF file in a specified directory.
struct file_info *read_next_file(const char *directory, struct file_info *file_list) {
    // Initialize file list if not already initialized.
    if (!file_list) {
        file_list = (struct file_info *) malloc(sizeof(struct file_info));
        file_count = 0;
    }

    // Open directory stream.
    DIR *dir = opendir(directory);
    assert(dir != NULL);

    // Read next TIFF file from directory.
    struct dirent *entry = readdir(dir);
    while (entry) {
        // Check if entry is a TIFF file.
        if (!strcmp(entry->d_name, ".") || !strcmp(entry->d_name, "..")) {
            entry = readdir(dir);
            continue;
        } else if (ends_with(entry->d_name, ".tiff")) {
            // Add file to list.
            file_list[file_count].file_name = entry->d_name;
            file_list[file_count].file_size = get_file_size(directory, entry->d_name);
            file_count++;

            // Check if maximum number of files has been reached.
            if (file_count >= MAX_FILE_COUNT) {
                closedir(dir);
                return file_list;
            } else {
                entry = readdir(dir);
            }
        }
    }

    // Close directory stream.
    closedir(dir);

    // Return list of files.
