// Extracts metadata from a TIFF file.
struct metadata *extract_metadata(const char *file_name) {
    // Initialize metadata structure.
    struct metadata *metadata = (struct metadata *) malloc(sizeof(struct metadata));

    // Read TIFF file.
    TIFF *tiff = TIFFOpen(file_name, "r");
    assert(tiff != NULL);

    // Extract metadata from TIFF file.
    metadata->bits_per_sample = TIFFGetBitsPerSample(tiff);
    metadata->samples_per_pixel = TIFFGetSamplesPerPixel(tiff);
    metadata->extra_samples = 0;

    // Check if extra samples are present.
    if (metadata->samples_per_pixel > 4) {
        for (int i = 0; i < metadata->samples_per_pixel - 4; i++) {
            char name[256];
            TIFFGetSampleName(tiff, i + 4, name);
            metadata->extra_samples[i].name = name;
            metadata->extra_samples[i].count++;
        }
    }

    // Close TIFF file.
    TIFFClose(tiff);

    return metadata;
}

