long get_file_size(const char *directory, const char *file) {
    // Open directory stream.
    DIR *dir = opendir(directory);
    assert(dir != NULL);

    // Read next TIFF file from directory.
    struct dirent *entry = readdir(dir);
    while (entry) {
        // Check if entry is a TIFF file.
        if (!strcmp(entry->d_name, ".") || !strcmp(entry->d_name, "..")) {
            entry = readdir(dir);
            continue;
        } else if (!ends_with(entry->d_name, ".tiff")) {
            entry = readdir(dir);
            continue;
        }

        // Check if file name matches.
        if (!strcmp(file, entry->d_name)) {
            // Get file size.
            long size = get_file_size(directory, entry->d_name);

            // Close directory stream.
            closedir(dir);

