    uint8_t crc_indication_rel8_tag; // CRC indication rel8 tag
} NFAPI_CRC_INDICATION_PDU_T;

// Define a doubly-linked list for holding the received UE information
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *head;
    NFAPI_CRC_INDICATION_PDU_T *tail;
} NFAPI_CRC_INDICATION_LIST_T;

// Define a mutex for protecting the linked list
static pthread_mutex_t crc_indication_list_lock = PTHREAD_MUTEX_INITIALIZER;

// Define a semaphore for signalling when new elements are added to the linked list
static sem_t crc_indication_semaphore = SEM_INITIALIZER(0);

// Function to populate the doubly-linked list of received UE information
void populate_crc_indication_list(NFAPI_CRC_INDICATION_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Lock the mutex to prevent concurrent access to the linked list
    pthread_mutex_lock(&crc_indication_list_lock);

    // Check if the RX_UE_INFORMATION_TAG is already present in the linked list
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current != NULL) {
        if (current->rx_ue_information_tag == pdu->rx_ue_information_tag) {
            // If the RX_UE_INFORMATION_TAG is already present, return without adding a new element
            pthread_mutex_unlock(&crc_indication_list_lock);
            return;
        }
        current = current->next;
    }

    // If the RX_UE_INFORMATION_TAG is not present, add a new element to the linked list
    NFAPI_CRC_INDICATION_PDU_T *new_element = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_element == NULL) {
        // Handle memory allocation failure
        pthread_mutex_unlock(&crc_indication_list_lock);
        return;
    }
    new_element->rx_ue_information_tag = pdu->rx_ue_information_tag;
    new_element->rnti = pdu->rnti;
    new_element->crc_indication_rel8_tag = pdu->crc_indication_rel8_tag;

    // Add the new element to the linked list
    if (list->head == NULL) {
        list->head = new_element;
        list->tail = new_element;
    } else {
        list->tail->next = new_element;
        list->tail = new_element;
    }

    // Signal the semaphore to wake up any waiting threads
    if (sem_post(&crc_indication_semaphore) != 0) {
        // Handle semaphore post failure
        pthread_mutex_unlock(&crc_indication_list_lock);
        return;
    }

    pthread_mutex_unlock(&crc_indication_list_lock);
}
