    for (int i = 0; i < num_files; ++i) {
        char *filename = files[i]->d_name;
        int file_id = i + 1;

        // Check if the file is a TIFF image
        bool is_tiff = false;
        struct stat st;
        if (stat(filename, &st) == 0 && S_ISREG(st.st_mode)) {
            is_tiff = true;
        }

        // If the file is a TIFF image, create a new message in the message queue and add it to the linked list
        if (is_tiff) {
            NFAPI_CRC_INDICATION_PDU_T *message = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            message->crc = NULL; // Placeholder for CRC data
            message->file_id = file_id;

            sem_wait(sem);
            if (list.size < 1000) {
                list.head = list.tail = message;
                list.size++;
            } else {
                // If the linked list is full, add the new message to the end of the queue
                list.tail->next = message;
                list.tail = message;
                list.size++;
            }
            sem_post(sem);
        }
    }

    return 0;
}

// Define a function to handle asynchronous I/O operations and processing in the worker threads
