#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pthread.h>
#include <semaphore.h>
#include <dirent.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <sys/wait.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <iostream>
#include <fstream>
#include <vector>
#include <queue>
#include <thread>
#include <mutex>
#include <condition_variable>

using namespace std;

// Constants
const int MAX_FILES = 5000; // Maximum number of files to process per second
const int RETRY_INTERVAL = 10; // Retry interval in seconds
const int CONCURRENCY_LIMIT = 20; // Maximum number of concurrent threads for processing
const string DATABASE_URL = "mongodb://localhost:27017"; // MongoDB URL
const string REST_API_URL = "http://localhost:8080/api/v1/predict"; // REST API URL
const string ENCRYPTION_KEY = "ENCRYPTION_KEY"; // Encryption key for secure communication

// Structures
struct File {
    char *name;
    int size;
};

struct Metadata {
    char *filename;
    int width;
    int height;
};

// Functions
void process_tiff_files(const char *directory) {
    // Get all TIFF files in the directory
    vector<File> files = get_files(directory);

    // Initialize worker pool and message queue
    pthread_t workers[CONCURRENCY_LIMIT];
    semaphore_t sem;
    init_semaphore(&sem, 0);

    // Process each file in parallel
    for (int i = 0; i < files.size(); ++i) {
        File file = files[i];

        // Create a new thread to process the file
        pthread_create(&workers[i], NULL, &process_file, (void *)&file);
    }

    // Wait for all threads to complete
    for (int i = 0; i < CONCURRENCY_LIMIT; ++i) {
        pthread_join(workers[i], NULL);
    }
}

void *process_file(void *arg) {
    // Get the file to process
    File file = *((File *)arg);

    // Check if the file is valid and can be processed
    if (is_valid_tiff_file(file.name)) {
        // Extract metadata from the TIFF file
        Metadata metadata = extract_metadata(file.name);

        // Rename the file based on the extracted metadata
        char *new_filename = rename_file(metadata.filename, metadata.width, metadata.height);

        // Save the new filename to the database
        save_to_database(new_filename);
    } else {
        // File is not valid, try again with exponential backoff
        int retry_interval = RETRY_INTERVAL;
        while (retry_interval > 0) {
            // Check if the file can be processed now
            if (is_valid_tiff_file(file.name)) {
                // Extract metadata from the TIFF file
                Metadata metadata = extract_metadata(file.name);

                // Rename the file based on the extracted metadata
                char *new_filename = rename_file(metadata.filename, metadata.width, metadata.height);

                // Save the new filename to the database
                save_to_database(new_filename);

                // Break from the loop since the file is now processed successfully
                break;
            } else {
                // File cannot be processed yet, try again with exponential backoff
                retry_interval *= 2;
                sleep(retry_interval);
            }
        }
    }

    return NULL;
}

void rename_file(char *filename, int width, int height) {
    // Generate a new filename based on the extracted metadata
    char *new_filename = generate_filename(width, height);

    // Rename the file using atomic operations to ensure thread safety
    rename(filename, new_filename);

    return new_filename;
}

bool is_valid_tiff_file(char *filename) {
    // Check if the TIFF file is valid and can be processed
    bool valid = true;

    // Open the TIFF file for reading
    FILE *file = fopen(filename, "rb");

    // Read the header of the TIFF file to determine its validity
    char buffer[12];
    int read_bytes = fread(buffer, 1, 12, file);

    if (read_bytes == 12 && strncmp(buffer, "MM\x00*\x00", 4) == 0) {
        // TIFF header is valid, the file can be processed
    } else {
        // Invalid TIFF header, the file cannot be processed
        valid = false;
    }

    fclose(file);

    return valid;
}

Metadata extract_metadata(char *filename) {
    // Extract metadata from the TIFF file using the LibTIFF library
    Metadata metadata;

    // Open the TIFF file for reading
    FILE *file = fopen(filename, "rb");

    // Read the header of the TIFF file to determine its validity
    char buffer[12];
    int read_bytes = fread(buffer, 1, 12, file);

    if (read_bytes == 12 && strncmp(buffer, "MM\x00*\x00", 4) == 0) {
        // TIFF header is valid, extract the metadata
        struct tiff *tiff = tiffOpen(filename, "rb");

        // Extract width and height of the image
        int width = tiffGetField(tiff, TIFFTAG_IMAGEWIDTH);
        int height = tiffGetField(tiff, TIFFTAG_IMAGELENGTH);

        // Close the TIFF file
        tiffClose(tiff);

        metadata.filename = filename;
        metadata.width = width;
        metadata.height = height;
    } else {
        // Invalid TIFF header, cannot extract metadata
        metadata.filename = NULL;
        metadata.width = 0;
        metadata.height = 0;
    }

    fclose(file);

    return metadata;
}

void save_to_database(char *new_filename) {
    // Save the new filename to the database using the MongoDB C driver
    mongoc_client_t *client = mongoc_client_new("mongodb://localhost:27017");
    mongoc_collection_t *collection = mongoc_client_get_collection(client, "image", "metadata");

    bson_error_t error;
    if (!mongoc_collection_insert(collection, &new_filename, 1, NULL, &error)) {
        // Cannot insert document to the database
        printf("Cannot insert document to the database: %s\n", error.message);
    }

    mongoc_collection_destroy(collection);
    mongoc_client_destroy(client);
}

char *generate_filename(int width, int height) {
    // Generate a new filename based on the extracted metadata
    char *new_filename = malloc(256);

    sprintf(new_filename, "IMG_%dx%d.tiff", width, height);

    return new_filename;
}
```

This is a simple example of how to process TIFF images using the LibTIFF library and save the processed files to a MongoDB database. The code checks if a file is a valid TIFF image, extracts its metadata, renames the file based on the extracted metadata, and saves the new filename to a MongoDB database.

The code uses the `fopen()` function to open the TIFF file for reading, and the `tiffOpen()` function to read the header of the TIFF file. The `TIFFTAG_IMAGEWIDTH` and `TIFFTAG_IMAGELENGTH` tags are used to extract the width and height of the image from the metadata.

The code also uses the `mongoc` library to connect to a MongoDB database and insert a new document with the extracted metadata into the "image" collection. The `bson_error_t error` variable is used to check if there are any errors when inserting the document, and it prints an error message if there is one.

The `generate_filename()` function generates a new filename based on the extracted metadata using the `sprintf()` function. The format of the generated filename is "IMG_%dx%d.tiff".

This code can be modified to process multiple files in parallel by creating multiple threads to process each file, and using atomic operations to ensure thread safety when renaming files or saving new filenames to the database.']

