import asyncio
from typing import List

class UserProfileService:
    def __init__(self):
        self.profiles = {}
        self.data_sources = []
        self.cache = Cache()

    async def get_profile(self, user_id: str) -> Profile:
        profile = self.cache.get(user_id)
        if profile is None:
            for data_source in self.data_sources:
                try:
                    profile = await data_source.fetch_profile(user_id)
                    break
                except Exception as e:
                    print(f"Failed to fetch profile from {data_source}: {e}")
            if profile is None:
                raise ProfileNotFoundError(user_id)
        return profile

    async def update_profile(self, user_id: str, new_profile: Profile):
        self.profiles[user_id] = new_profile
        for data_source in self.data_sources:
            try:
                await data_source.update_profile(new_profile)
            except Exception as e:
                print(f"Failed to update profile in {data_source}: {e}")

    async def delete_profile(self, user_id: str):
        del self.profiles[user_id]
        for data_source in self.data_sources:
            try:
                await data_source.delete_profile(user_id)
            except Exception as e:
                print(f"Failed to delete profile in {data_source}: {e}")

    async def fetch_profiles(self, user_ids: List[str]) -> List[Profile]:
        profiles = []
        for user_id in user_ids:
            try:
                profile = await self.get_profile(user_id)
                profiles.append(profile)
            except ProfileNotFoundError as e:
                print(f"Failed to fetch profile for {user_id}: {e}")
        return profiles

    async def update_profiles(self, new_profiles: List[Profile]):
        for new_profile in new_profiles:
            try:
                await self.update_profile(new_profile.user_id, new_profile)
            except Exception as e:
                print(f"Failed to update profile {new_profile.user_id}: {e}")

    async def delete_profiles(self, user_ids: List[str]):
        for user_id in user_ids:
            try:
                await self.delete_profile(user_id)
            except Exception as e:
                print(f"Failed to delete profile {user_id}: {e}")

    def add_data_source(self, data_source):
        self.data_sources.append(data_source)

    def remove_data_source(self, data_source):
        if data_source in self.data_sources:
            self.data_sources.remove(data_source)

class Cache:
    def __init__(self):
        self.cache = {}
        self.eviction_policy = None

    def get(self, key: str) -> Profile:
