namespace TIFFProcessor {
    // Forward declaration of the TIFFProcessor class
    class TIFFProcessor;

    // Structure to represent a file in the filesystem
    struct File {
        std::string path;
        std::string name;
        std::string extension;
    };

    // Function to process a TIFF file and return the processed image as a vector of unsigned chars
    void process_tiff(const char* filename, const char* output_format, unsigned char** data, int* size);

    // Class to handle the processing of TIFF files in parallel using a worker pool and message queue
    class TIFFProcessor {
        public:
            TIFFProcessor();
            ~TIFFProcessor();

            void process_tiff(const char* filename, const char* output_format);

        private:
            std::vector<std::thread> threads_;
            std::queue<File> queue_;
            std::mutex mtx_;
            std::condition_variable cv_;
            int concurrency_limit_;
            bool shutdown_;
    };

    // Function to handle the processing of TIFF files in parallel using a worker pool and message queue
    void TIFFProcessor::process_tiff(const char* filename, const char* output_format) {
        // Add the file to the queue
        File file = {filename};
        std::lock_guard<std::mutex> lock(mtx_);
        queue_.push(file);
        cv_.notify_one();
    }
}
