    DataBuffer buffer;
    ConnectionPool pool(5); // 5 available connections at the start
    EventProcessor processor(schemaRegistry, buffer, pool);
    DataSender sender(pool);
    Scaler scaler(5000); // Batch size for scaling events

    while (true) {
        vector<Event> data = ...; // Get data from external system
