package main;

import (
	"context"
	"errors"
	"fmt"
	"sync"
	"time"
)

// Task is the representation of a task in the system
type Task struct {
	ID        string    // Unique ID for the task
	Type      string    // Type of task (e.g., "cron", "event-driven")
	Schedule  string    // Schedule for the task (e.g., "daily", "weekly")
	StartTime time.Time // Start time for the task
	EndTime   time.Time // End time for the task
	Status    int       // Status of the task (e.g., 0: pending, 1: in progress, 2: completed)
}

// TaskManager is a struct that manages tasks and worker pools
type TaskManager struct {
	Tasks      map[string]Task        // Map of task IDs to tasks
	WorkerPools map[string]*workerPool // Map of worker pool names to worker pools
	mu         sync.Mutex             // Mutex for protecting the Tasks and WorkerPools maps
}

// NewTaskManager creates a new instance of TaskManager
func NewTaskManager() *TaskManager {
	return &TaskManager{
		Tasks:      make(map[string]Task),
		WorkerPools: make(map[string]*workerPool),
	}
}

// AddTask adds a task to the system
func (tm *TaskManager) AddTask(ctx context.Context, task Task) error {
	tm.mu.Lock()
	defer tm.mu.Unlock()

	if _, ok := tm.Tasks[task.ID]; ok {
		return errors.New("task with ID already exists")
	}
	tm.Tasks[task.ID] = task
	return nil
}

// GetTask retrieves a task from the system
func (tm *TaskManager) GetTask(ctx context.Context, taskID string) (*Task, error) {
	tm.mu.Lock()
	defer tm.mu.Unlock()

	task, ok := tm.Tasks[taskID]
	if !ok {
		return nil, errors.New("task not found")
	}
	return &task, nil
}

// UpdateTaskStatus updates the status of a task in the system
func (tm *TaskManager) UpdateTaskStatus(ctx context.Context, taskID string, status int) error {
	tm.mu.Lock()
	defer tm.mu.Unlock()

	task, ok := tm.Tasks[taskID]
	if !ok {
		return errors.New("task not found")
	}
	task.Status = status
	tm.Tasks[taskID] = task
	return nil
}

// CreateWorkerPool creates a new worker pool in the system
func (tm *TaskManager) CreateWorkerPool(ctx context.Context, name string) error {
	tm.mu.Lock()
	defer tm.mu.Unlock()

	if _, ok := tm.WorkerPools[name]; ok {
		return errors.New("worker pool already exists")
	}
	tm.WorkerPools[name] = &workerPool{Name: name, Workers: make(map[string]*worker)}
	return nil
}

// GetWorkerPool retrieves a worker pool from the system
func (tm *TaskManager) GetWorkerPool(ctx context.Context, name string) (*workerPool, error) {
	tm.mu.Lock()
	defer tm.mu.Unlock()

	pool, ok := tm.WorkerPools[name]
	if !ok {
		return nil, errors.New("worker pool not found")
	}
	return pool, nil
}

// AddWorker adds a worker to a worker pool in the system
func (tm *TaskManager) AddWorker(ctx context.Context, name string, worker *worker) error {
	tm.mu.Lock()
	defer tm.mu.Unlock()

	pool, ok := tm.WorkerPools[name]
	if !ok {
		return errors.New("worker pool not found")
	}
	pool.Workers[worker.ID] = worker
	return nil
}

// GetWorker retrieves a worker from a worker pool in the system
func (tm *TaskManager) GetWorker(ctx context.Context, name string, workerID string) (*worker, error) {
	tm.mu.Lock()
	defer tm.mu.Unlock()

	pool, ok := tm.WorkerPools[name]
	if !ok {
		return nil, errors.New("worker pool not found")
	}
	worker, ok := pool.Workers[workerID]
	if !ok {
		return nil, errors.New("worker not found")
	}
	return worker, nil
}

// TaskScheduler is a struct that schedules tasks for workers
type TaskScheduler struct {
	TaskManager *TaskManager // Reference to the task manager
}

// NewTaskScheduler creates a new instance of TaskScheduler
func NewTaskScheduler(tm *TaskManager) *TaskScheduler {
	return &TaskScheduler{
		TaskManager: tm,
	}
}

// ScheduleTask schedules a task for a worker in the system
func (ts *TaskScheduler) ScheduleTask(ctx context.Context, name string, taskID string, workerID string) error {
	tm := ts.TaskManager
	tm.mu.Lock()
	defer tm.mu.Unlock()

	task, ok := tm.Tasks[taskID]
	if !ok {
		return errors.New("task not found")
	}
	worker, ok := tm.WorkerPools[name].Workers[workerID]
	if !ok {
		return errors.New("worker not found")
	}
	worker.Tasks = append(worker.Tasks, task)
	return nil
}

// Worker is a struct that represents a worker in the system
type worker struct {
	ID       string
	Name     string
	Tasks    []Task
	Active   bool
	Busy     bool
	LastSeen time.Time
}

// Task is a struct that represents a task in the system
type Task struct {
	ID         string
