// Struct to hold the state of a resource allocation request
struct ResourceRequest {
    char* deviceID;
    int serviceType;
    int requestPriority;
};

// Struct to hold the state of a resource allocation policy
struct ResourceAllocationPolicy {
    int serviceType;
    int priorityClass;
    float weight;
    int minAvailableInstances;
    int maxAvailableInstances;
    int minRequiredInstances;
    int maxRequiredInstances;
};

// Struct to hold the state of a network interface
struct NetworkInterface {
    char* name;
    char* ipAddress;
    int port;
};

// Global variables for the dynamic resource allocator
int numOfRequests = 0;
int maxNumOfRequests = 1000;
struct ResourceRequest* requestQueue;
struct ResourceAllocationPolicy* allocationPolicies;
struct NetworkInterface* networkInterfaces;
sem_t requestQueueSemaphore;
sem_t allocationPolicySemaphore;
sem_t networkInterfaceSemaphore;
pthread_mutex_t lock;

// Function to initialize the dynamic resource allocator
void initializeDynamicResourceAllocator() {
    // Initialize the queue for storing requests
    requestQueue = (struct ResourceRequest*)malloc(sizeof(struct ResourceRequest) * maxNumOfRequests);
    if (!requestQueue) {
        printf("Failed to allocate memory for request queue\n");
        exit(1);
    }

    // Initialize the semaphore for accessing the request queue
    sem_init(&requestQueueSemaphore, 0, maxNumOfRequests);
    if (sem_init(&requestQueueSemaphore, 0, maxNumOfRequests) == -1) {
        printf("Failed to initialize request queue semaphore\n");
        exit(1);
    }

    // Initialize the array of allocation policies
    allocationPolicies = (struct ResourceAllocationPolicy*)malloc(sizeof(struct ResourceAllocationPolicy) * 5);
    if (!allocationPolicies) {
        printf("Failed to allocate memory for allocation policies\n");
        exit(1);
    }

    // Initialize the semaphore for accessing the allocation policies
    sem_init(&allocationPolicySemaphore, 0, 5);
    if (sem_init(&allocationPolicySemaphore, 0, 5) == -1) {
        printf("Failed to initialize allocation policy semaphore\n");
        exit(1);
    }

    // Initialize the array of network interfaces
    networkInterfaces = (struct NetworkInterface*)malloc(sizeof(struct NetworkInterface) * 3);
    if (!networkInterfaces) {
        printf("Failed to allocate memory for network interfaces\n");
        exit(1);
    }

    // Initialize the semaphore for accessing the network interfaces
    sem_init(&networkInterfaceSemaphore, 0, 3);
    if (sem_init(&networkInterfaceSemaphore, 0, 3) == -1) {
        printf("Failed to initialize network interface semaphore\n");
        exit(1);
    }

    // Initialize the mutex for protecting critical sections
    pthread_mutex_init(&lock, NULL);
}

// Function to add a new request to the queue
void addRequestToQueue(struct ResourceRequest* request) {
    int ret = sem_wait(&requestQueueSemaphore);
    if (ret == -1) {
        printf("Failed to wait for request queue semaphore\n");
        exit(1);
    }

    // Add the new request to the queue
    requestQueue[numOfRequests] = *request;
    numOfRequests++;

    ret = sem_post(&requestQueueSemaphore);
    if (ret == -1) {
        printf("Failed to post request queue semaphore\n");
        exit(1);
    }
}

// Function to retrieve the next request from the queue
struct ResourceRequest* getNextRequestFromQueue() {
    int ret = sem_wait(&requestQueueSemaphore);
    if (ret == -1) {
        printf("Failed to wait for request queue semaphore\n");
        exit(1);
    }

    // Retrieve the next request from the queue
    struct ResourceRequest* request = &requestQueue[0];
    numOfRequests--;
    memmove(&requestQueue, &requestQueue[1], sizeof(struct ResourceRequest) * (numOfRequests - 1));

    ret = sem_post(&requestQueueSemaphore);
    if (ret == -1) {
        printf("Failed to post request queue semaphore\n");
        exit(1);
    }

    return request;
}

// Function to add a new allocation policy to the array
void addAllocationPolicy(struct ResourceAllocationPolicy* policy) {
    int ret = sem_wait(&allocationPolicySemaphore);
    if (ret == -1) {
        printf("Failed to wait for allocation policy semaphore\n");
        exit(1);
    }

    // Add the new allocation policy to the array
    allocationPolicies[0] = *policy;
    numOfAllocationPolicies++;

    ret = sem_post(&allocationPolicySemaphore);
    if (ret == -1) {
        printf("Failed to post allocation policy semaphore\n");
        exit(1);
    }
}

// Function to retrieve the next allocation policy from the array
struct ResourceAllocationPolicy* getNextAllocationPolicy() {
    int ret = sem_wait(&allocationPolicySemaphore);
    if (ret == -1) {
        printf("Failed to wait for allocation policy semaphore\n");
        exit(1);
    }

