  }

  // Get the payment transaction result for a given configuration
  PAYMENT_TRANSACTION_RESULT get(const PAYMENT_TRANSACTION_CONFIG& config) {
    std::lock_guard<std::mutex> lock(_mutex);
    auto it = _cache.find(config);
    if (it != _cache.end()) {
      return it->second;
    } else {
      throw std::runtime_error("Cache miss");
    }
  }

private:
  std::mutex _mutex; // Mutex for protecting the cache data structure
  std::map<PAYMENT_TRANSACTION_CONFIG, PAYMENT_TRANSACTION_RESULT> _cache; // Cache data structure
};

// Define a thread-safe queue class for managing payment transaction requests
class PaymentQueue {
public:
  // Add a new payment transaction request to the queue
  void add(const PAYMENT_TRANSACTION_CONFIG& config) {
    std::lock_guard<std::mutex> lock(_mutex);
    _queue.push_back(config);
  }

  // Get the next payment transaction request from the queue, if available
  bool getNext(PAYMENT_TRANSACTION_CONFIG& config) {
    std::lock_guard<std::mutex> lock(_mutex);
    if (_queue.empty()) {
      return false;
    } else {
      config = _queue.front();
      _queue.pop_front();
      return true;
    }
  }

private:
  std::mutex _mutex; // Mutex for protecting the queue data structure
  std::list<PAYMENT_TRANSACTION_CONFIG> _queue; // Queue data structure
};

// Define a thread-safe class for managing payment transaction results and configs
class PaymentManager {
public:
  // Add a new payment transaction result to the manager
  void add(const PAYMENT_TRANSACTION_CONFIG& config, const PAYMENT_TRANSACTION_RESULT& result) {
    std::lock_guard<std::mutex> lock(_mutex);
    _results[config] = result;
  }

  // Get the payment transaction result for a given configuration
  PAYMENT_TRANSACTION_RESULT get(const PAYMENT_TRANSACTION_CONFIG& config) {
    std::lock_guard<std::mutex> lock(_mutex);
    auto it = _results.find(config);
    if (it != _results.end()) {
      return it->second;
    } else {
      throw std::runtime_error("Manager miss");
    }
  }

private:
  std::mutex _mutex; // Mutex for protecting the results data structure
  std::map<PAYMENT_TRANSACTION_CONFIG, PAYMENT_TRANSACTION_RESULT> _results; // Results data structure
};

// Define a payment processor class that manages payment transactions and integrates with external services
class PaymentProcessor {
public:
  // Initialize the payment processor with a payment manager and a cache
  PaymentProcessor(PaymentManager& manager, PaymentCache& cache) : _manager(manager), _cache(cache) {}

  // Process a payment transaction using the given configuration
  PAYMENT_TRANSACTION_RESULT processTransaction(const PAYMENT_TRANSACTION_CONFIG& config) {
    std::string gateway = config.gateway;
    int amount = config.amount;
    bool promo = config.promo;

    // Check if the transaction is already in the cache, and return it if so
    PAYMENT_TRANSACTION_RESULT result;
    try {
      result = _cache.get(config);
    } catch (std::runtime_error& e) {
      // If not in the cache, fetch the transaction from an external payment gateway API
      std::string apiUrl = "https://example.com/payment-gateway";
      std::string jsonPayload = "{\"gateway\": \"" + gateway + "\", \"amount\": " + std::to_string(amount) + ", \"promo\": " + (promo ? "true" : "false") + "}";
      auto response = sendRequest(apiUrl, jsonPayload);
      if (response.success()) {
        result = response.json();
        _cache.add(config, result); // Add the transaction to the cache for future use
      } else {
        throw std::runtime_error("Failed to fetch payment transaction from external API");
      }
    }

    // Add the transaction to the payment manager for further processing
    _manager.add(config, result);

    return result;
  }

private:
  PaymentManager& _manager; // Reference to the payment manager
  PaymentCache& _cache; // Reference to the cache
};

// Define a class that manages payment transactions and integrates with external services
class PaymentSystem {
public:
  // Initialize the payment system with a payment processor and a queue
  PaymentSystem(PaymentProcessor& processor, PaymentQueue& queue) : _processor(processor), _queue(queue) {}

  // Process a payment transaction using the given configuration
  PAYMENT_TRANSACTION_RESULT processTransaction(const PAYMENT_TRANSACTION_CONFIG& config) {
    return _processor.processTransaction(config);
  }

  // Get the next payment transaction request from the queue, if available
  bool getNext(PAYMENT_TRANSACTION_CONFIG& config) {
    return _queue.getNext(config);
  }

private:
  PaymentProcessor& _processor; // Reference to the payment processor
  PaymentQueue& _queue; // Reference to the queue
};

int main() {
  // Initialize a payment manager, cache, and queue
  PaymentManager manager;
  PaymentCache cache;
  PaymentQueue queue;

  // Initialize a payment system with the manager and queue
  PaymentSystem system(manager, queue);

  // Process a payment transaction using the system
  PAYMENT_TRANSACTION_CONFIG config;
  config.gateway = "ExampleGateway";
  config.amount = 100;
  config.promo = false;
  PAYMENT_TRANSACTION_RESULT result = system.processTransaction(config);
  std::cout << "Result: " << result << "\n";

  return 0;
}
```

This program demonstrates how to use a payment manager, cache, and queue to process payments in a multi-threaded environment. The `PaymentManager` class manages the results of processed transactions and integrates with external services. The `PaymentCache` class maintains a cache of previously processed transactions for faster lookups. The `PaymentQueue` class manages a queue of payment transaction requests and provides methods to add, remove, and retrieve requests from the queue. The `PaymentSystem` class is responsible for integrating these components together to process payments.

The program first initializes a payment manager, cache, and queue. Then it creates an instance of the `PaymentProcessor` class with the manager and cache, and uses this instance to process a payment transaction using the `processTransaction()` method. The result of the transaction is then printed to the console.

This program demonstrates how to use a multi-threaded design pattern in C++ to process payments efficiently and effectively. By using a payment manager, cache, and queue, this program can process payments quickly and efficiently, while also maintaining data consistency and preventing duplicate requests from being processed.']

