#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <unistd.h>
#include <pthread.h>
#include <semaphore.h>
#include "resourceLoader.h"

/* Define the structure for the resource bundle */
struct ResourceBundle {
    char *name;
    void *data;
    size_t size;
};

/* Define the structure for the file format parser */
struct FileFormatParser {
    const char *format;
    bool (*parse)(const char *path, struct ResourceBundle *bundle);
};

/* Define the structure for the resource loader configuration */
struct ResourceLoaderConfig {
    const char *encodings[];
    size_t numEncodings;
    struct FileFormatParser formatParsers[];
    size_t numFormatParsers;
    sem_t *semaphore;
};

/* Define the structure for the resource loader */
struct ResourceLoader {
    const char *path;
    struct ResourceBundle bundle;
    struct ResourceLoaderConfig config;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
};

/* Initialize the resource loader configuration */
void initResourceLoaderConfig(struct ResourceLoaderConfig *config, const char **encodings, size_t numEncodings) {
    config->numEncodings = numEncodings;
    for (size_t i = 0; i < numEncodings; ++i) {
        config->encodings[i] = encodings[i];
    }
}

/* Initialize the resource loader */
void initResourceLoader(struct ResourceLoader *loader, const char *path, struct ResourceLoaderConfig config) {
    loader->path = path;
    loader->config = config;
    pthread_mutex_init(&loader->mutex, NULL);
    pthread_cond_init(&loader->cond, NULL);
}

/* Destroy the resource loader */
void destroyResourceLoader(struct ResourceLoader *loader) {
    pthread_mutex_destroy(&loader->mutex);
    pthread_cond_destroy(&loader->cond);
}

/* Load a resource bundle from disk */
bool loadResourceBundle(struct ResourceLoader *loader, struct ResourceBundle *bundle) {
    /* Acquire the mutex to protect the shared data */
    pthread_mutex_lock(&loader->mutex);

    /* Check if the resource is already loaded */
    if (loader->bundle.data != NULL) {
        bundle->data = loader->bundle.data;
        bundle->size = loader->bundle.size;
        return true;
    }

    /* Open the file and read its contents */
    FILE *file = fopen(loader->path, "r");
    if (file == NULL) {
        pthread_mutex_unlock(&loader->mutex);
        return false;
    }
    char *buffer = malloc(1024);
    size_t size = 0;
    while ((size += fread(buffer + size, 1, 1024, file)) > 0) {
        buffer = realloc(buffer, size);
    }
    fclose(file);

    /* Check if the file is empty */
    if (size == 0) {
        free(buffer);
        pthread_mutex_unlock(&loader->mutex);
        return false;
    }

    /* Parse the file contents */
    struct FileFormatParser *parser = NULL;
    for (size_t i = 0; i < loader->config.numFormatParsers; ++i) {
        if (strcmp(loader->config.formatParsers[i].format, "json") == 0) {
            parser = &loader->config.formatParsers[i];
            break;
        }
    }
    if (parser == NULL) {
        free(buffer);
        pthread_mutex_unlock(&loader->mutex);
        return false;
    }
    bool parsed = parser->parse(buffer, bundle);
    free(buffer);
    if (!parsed) {
        pthread_mutex_unlock(&loader->mutex);
        return false;
    }

    /* Save the resource bundle */
    loader->bundle.data = malloc(bundle->size);
    memcpy(loader->bundle.data, bundle->data, bundle->size);
    loader->bundle.size = bundle->size;

    /* Release the mutex and return success */
    pthread_mutex_unlock(&loader->mutex);
    return true;
}

/* Unload a resource bundle from memory */
void unloadResourceBundle(struct ResourceLoader *loader, struct ResourceBundle *bundle) {
    /* Acquire the mutex to protect the shared data */
    pthread_mutex_lock(&loader->mutex);

    /* Release the resource bundle */
    if (loader->bundle.data == bundle->data) {
        free(loader->bundle.data);
        loader->bundle.data = NULL;
    }

    /* Release the mutex and return success */
    pthread_mutex_unlock(&loader->mutex);
}
