    std::string sourceName;
    std::string targetName;
    std::vector<std::string> fields;
    std::vector<std::pair<std::string, std::string>> transformations;
};

// Define a struct to represent a data pipeline
struct Pipeline {
    std::string name;
    std::vector<Plugin*> plugins;
    std::vector<TransformationRule> rules;
};

// Define a class to manage the data processing platform
