// Define a structure to represent an IP address
typedef struct {
    unsigned char bytes[4];
} ip_address;

int resolve_hostname(const char* hostname, ip_address* ip) {
    // Initialize the resolver context
    int res = 0;
    struct addrinfo hints, *result;
    memset(&hints, 0, sizeof(struct addrinfo));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;

    // Perform the DNS resolution
    if ((res = getaddrinfo(hostname, NULL, &hints, &result)) != 0) {
        fprintf(stderr, "Failed to resolve hostname: %s\n", gai_strerror(res));
        return -1;
    }

    // Copy the IP address into the output structure
    memcpy(ip->bytes, result->ai_addr->sa_data + 2, 4);

    // Free the resolver context
    freeaddrinfo(result);

    return 0;
}
```
