use std::str::FromStr;

struct BuildMetrics {
    cpu_usage: f64,
    memory_consumption: usize,
    phase_specific_durations: HashMap<String, u64>,
    disk_io: usize,
    network_bandwidth_usage: usize,
    power_consumption: f64,
}

struct BuildConfig {
    target_arch: String,
    release_mode: String,
}

impl FromStr for BuildConfig {
    type Err = ParseIntError;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        let mut iter = s.split(',');
        Ok(BuildConfig {
            target_arch: iter.next().ok_or(ParseIntError::InvalidInput)?.to_string(),
            release_mode: iter.next().ok_or(ParseIntError::InvalidInput)?.to_string(),
        })
    }
}

impl BuildMetrics {
    fn new() -> Self {
        BuildMetrics {
            cpu_usage: 0.0,
            memory_consumption: 0,
            phase_specific_durations: HashMap::new(),
            disk_io: 0,
            network_bandwidth_usage: 0,
            power_consumption: 0.0,
        }
    }

    fn add_metric(&mut self, metric: &str) -> Result<(), ParseIntError> {
        let mut iter = metric.split('=');
        let key = iter.next().ok_or(ParseIntError::InvalidInput)?;
        let value = iter.next().ok_or(ParseIntError::InvalidInput)?;
        match key {
            "cpu_usage" => self.cpu_usage = value.parse()?,
            "memory_consumption" => self.memory_consumption = value.parse()?,
            "phase_specific_durations" => self.phase_specific_durations.insert(value.to_string(), 0),
            "disk_io" => self.disk_io = value.parse()?,
            "network_bandwidth_usage" => self.network_bandwidth_usage = value.parse()?,
            "power_consumption" => self.power_consumption = value.parse()?,
            _ => (),
        }
        Ok(())
    }
}

fn main() {
    let config = BuildConfig::from_str("x86,release").unwrap();

    let mut metrics = BuildMetrics::new();
    metrics.add_metric("cpu_usage=0.5").unwrap();
    metrics.add_metric("memory_consumption=1024").unwrap();
    metrics.add_metric("phase_specific_durations=build=100").unwrap();
    metrics.add_metric("disk_io=1024").unwrap();
    metrics.add_metric("network_bandwidth_usage=512").unwrap();
    metrics.add_metric("power_consumption=0.25").unwrap();

    println!("Metrics: {:?}", metrics);
}
```
This code block defines a `BuildMetrics` struct that contains the build metrics as fields, and an `add_metric` method to add a new metric to the struct. The `main` function creates a `BuildConfig` struct and uses it to create a `BuildMetrics` instance, then adds some sample metrics using the `add_metric` method. Finally, it prints out the build metrics using the `println!` macro.

Note that this is just one possible implementation of the given programming task, and there are many other ways to design and implement such an application in Rust.']

